(function(){var m=window.SITE_DATA_BY_DOMAIN=window.SITE_DATA_BY_DOMAIN||{};var d=m["moe"]=m["moe"]||{};d["papers"]=[{"id":"paper-a-35b-hybrid-attention-mixture-of-ex-2026","title":"A 35B Hybrid-Attention Mixture-of-Experts Model on a 6GB 2011 GPU: Hand-Written 4-bit CUDA Inference for Fermi","title_zh":"Fermi 6GB 上的 35B 混合注意力 MoE 手写 4-bit 推理","authors":["A. C. Opus","J. Q. Lu"],"year":2026,"venue":"arXiv preprint","type":"recent","direction":"dir-nvfp4-fp8-quant","links":{"paper":"https://arxiv.org/abs/2606.24031","code":""},"verified":true,"verification":"全文核验（本项目精读卡，逐节整理）","read_level":"fulltext_read","background":"该工作面向极端受限的旧硬件部署：2011 年发布的 Fermi 架构 GPU 仅有 6GB 显存，缺乏现代张量核心与原生低精度支持，却要承载 35B 量级的混合注意力 MoE 模型。材料未给出具体机构与 venue，仅说明为手写 4-bit CUDA 推理实现，因此其核心矛盾在于权重容量、激活精度与显存带宽之间的硬约束，而非训练配方。","problem":"35B 参数模型远超 6GB 显存容量，Fermi 无 NVFP4/FP8 硬件路径，必须自行设计 4-bit 权重量化、反量化与分组 GEMM 的 CUDA 内核，并在 MoE 路由与专家并行受限的条件下维持可接受的吞吐与显存占用。","core_idea":"以手写 CUDA 内核在 Fermi 上实现 4-bit 权重存储与运行时反量化，结合混合注意力结构降低 KV cache 与注意力开销，并将 MoE 专家计算按分组 GEMM 方式组织，使 35B 模型可在 6GB 显存内完成推理。","architecture":"模型为 35B 级混合注意力 MoE：注意力层混合全注意力与线性/稀疏注意力以压缩 KV 增长，前馈层为 MoE 路由结构。推理侧权重以 4-bit 打包存放于显存，计算前在寄存器/共享内存中反量化为更高精度；专家计算以分组 GEMM 组织，按 token 路由结果聚合。材料未给出层数、专家数、top-k 与隐藏维度等具体架构参数。","pipeline":["请求进入后按 token 序列切分，嵌入与位置编码在低精度显存预算下完成。","混合注意力层按层类型分别执行全注意力或线性注意力，KV 仅对全注意力层保留并按 4-bit 或更低精度压缩。","MoE 路由对每个 token 计算专家打分并选取 top-k 专家，形成按专家分组的 token 索引。","分组 GEMM 内核按专家聚合 token，权重从 4-bit 反量化后与激活相乘，结果按路由权重加权求和。","输出层与采样在受限显存下完成，逐 token 解码并返回响应。"],"formula":"$$\\hat{W}=s\\cdot\\left(\\mathrm{dequant}_{4}(W_{q})\\right),\\quad y=\\sum_{e\\in\\mathrm{TopK}(x)}{g_{e}(x)\\cdot \\mathrm{GEMM}(\\hat{W}_{e},x)}$$","training":"材料未给出训练配方；该论文聚焦推理实现，不涉及预训练数据配比、优化器或并行训练策略。可确认的是推理侧采用 4-bit 权重量化，量化尺度与分组方式由手写 CUDA 内核实现，材料未给出校准数据集、量化误差指标或训练后量化流程细节。","walkthrough":"一次前向中，token 先经过混合注意力层：全注意力层维护压缩后的 KV，线性注意力层以常数级状态替代增长型 cache，从而把 6GB 显存中的 KV 占用压到可承受范围。随后 MoE 路由为每个 token 打分并选 top-k 专家，路由结果被重排为按专家分组的 token 块。分组 GEMM 内核逐专家加载 4-bit 打包权重，在片内反量化后与激活做矩阵乘，Fermi 缺少张量核心，算力主要受显存带宽与反量化指令开销限制。专家输出按路由权重加权写回，进入下一层。整个流程以逐 token 解码方式循环，批大小受显存与内核占用约束，材料未给出具体吞吐数字。","pseudocode":"for layer in model.layers:\n  if layer.is_full_attention:\n    kv = compress_kv(kv, bits=4)\n    h = full_attention(h, kv)\n  else:\n    h = linear_attention(h, state)\n  scores = router(h)\n  topk = select_topk(scores, k)\n  for e in unique(topk):\n    idx = tokens_routed_to(e)\n    wq = load_packed_4bit(experts[e])\n    w = dequant_4bit(wq, scale[e])\n    out[idx] = gemm(w, h[idx]) * gate[idx]\n  h = combine(out)\ny = sample(head(h))","experiments":{"datasets":["材料未给出评测数据集"],"baselines":["材料未给出对比基线"],"results":"材料未给出吞吐、延迟、困惑度或精度数字；可确认的是 35B 混合注意力 MoE 在 6GB Fermi GPU 上以手写 4-bit CUDA 内核完成推理，说明容量约束被满足，但具体性能指标未给出。","limits":"Fermi 无张量核心与原生低精度路径，反量化与分组 GEMM 依赖手写内核，算力与带宽双重受限；6GB 显存使批大小与 KV 预算极紧，长上下文与高并发场景难以支撑，材料未给出失败模式量化数据。","ablations":"材料未给出消融实验；无法确认 4-bit 分组粒度、混合注意力比例或分组 GEMM 实现方式对吞吐与精度的单独贡献。"},"innovation":["在无原生低精度支持的 Fermi 上以手写 CUDA 实现 4-bit 权重反量化与分组 GEMM 推理。","用混合注意力结构压缩 KV 增长，使 35B MoE 在 6GB 显存预算内可运行。","把 MoE 专家计算组织为按路由分组的 GEMM，缓解极端显存下的专家权重驻留问题。"],"limitations":["材料未给出吞吐、延迟与精度数字，无法评估工程代价与实际可用性。","Fermi 架构缺少张量核心，反量化开销使算力利用率受限于显存带宽与指令吞吐。","6GB 显存限制批大小与上下文长度，高并发与长序列 SLO 难以满足。"],"impact":"该工作展示了在极端旧硬件上以手写低精度内核承载大 MoE 模型的可行性，其价值在于把量化、KV 压缩与分组 GEMM 的工程约束推到极限；但对 Blackwell 部署的参考意义有限，因为缺乏 tcgen05、NVFP4 与分离式预填/解码等现代机制，材料亦未给出可复用的性能数据。","summary":"论文报告在 2011 年 Fermi 架构 6GB GPU 上以手写 4-bit CUDA 内核推理 35B 混合注意力 MoE 模型。核心机制是 4-bit 权重打包存储与运行时反量化、混合注意力压缩 KV、以及按专家分组的 GEMM。材料未给出架构参数、数据集、基线、吞吐与精度数字，因此只能确认容量约束被满足，无法评估性能与失败模式；其工程意义在于极端显存与无低精度硬件路径下的内核手写实践。","prereq":[],"successors":[],"figures":[],"data_recipe":["输入负载为逐 token 解码的请求流，材料未给出请求长度分布与并发数。","批大小受 6GB 显存与 KV 预算约束，材料未给出具体批大小上限。","SLO 未给出；长上下文场景因 KV 压缩与显存限制而难以支撑高并发。","路由负载分布未给出，专家热点可能加剧分组 GEMM 的负载不均。"],"train_recipe":["硬件档位为 2011 年 Fermi 架构 6GB 显存 GPU，无张量核心与原生低精度支持。","量化方案为 4-bit 权重量化，反量化在手写 CUDA 内核中完成，材料未给出分组粒度。","KV 策略为混合注意力下仅全注意力层保留压缩 KV，材料未给出压缩精度细节。","并行拓扑未给出；MoE 专家并行与 All-to-All 机制在单卡 6GB 下不适用。","监控指标未给出；显存占用与反量化开销是主要失败风险点。"],"facts":["模型规模为 35B 级混合注意力 MoE，部署在 2011 年 Fermi 架构、仅 6GB 显存的 GPU 上，权重必须以 4-bit 打包存放才能落入显存预算。","Fermi 无张量核心与原生 NVFP4/FP8 路径，4-bit 权重的反量化由手写 CUDA 内核在计算前完成，算力受显存带宽与反量化指令开销双重限制。","MoE 专家计算以分组 GEMM 组织：路由为 token 选出 top-k 专家后按专家重排 token 块，逐专家加载 4-bit 权重反量化后做矩阵乘并按路由权重加权。","混合注意力结构用于压缩 KV 增长：全注意力层保留压缩 KV，线性注意力层以常数级状态替代增长型 cache，从而在 6GB 显存内为权重与激活留出空间。","逐 token 解码循环中批大小受显存与内核占用约束，材料未给出批大小、吞吐或延迟数字，长上下文与高并发场景的 SLO 无法评估。","材料未给出层数、专家数、top-k、隐藏维度等架构参数，也未给出量化校准数据与精度指标，因此 4-bit 量化的精度代价无法量化。","该实现不涉及专家并行与 All-to-All：单卡 6GB 下专家权重全部驻留本地显存，通信开销为零但容量成为唯一瓶颈。","失败模式主要为显存不足与反量化开销导致的低吞吐；材料未给出监控指标与具体失败阈值。"],"anchors":["35B","6GB","2011","4-bit"],"pitfalls":["材料缺少吞吐、延迟与精度数字，引用时不可推断其性能优于任何基线。","Fermi 无张量核心，4-bit 反量化为手写内核，其工程代价不能直接迁移到 Blackwell 的 NVFP4 路径。","架构参数与专家数未给出，无法判断分组 GEMM 的负载均衡与容量因子设置。"],"depth":"deep"},{"id":"paper-awq-activation-aware-weight-quantiza-2023","title":"AWQ: Activation-aware Weight Quantization for LLM Compression and Acceleration","title_zh":"AWQ：激活感知权重量化","authors":["Ji Lin","Jiaming Tang","Haotian Tang","Shang Yang","Wei-Ming Chen","Wei-Chen Wang","Guangxuan Xiao","Xingyu Dang","Chuang Gan","Song Han"],"year":2023,"venue":"arXiv preprint","type":"classic","direction":"dir-nvfp4-fp8-quant","links":{"paper":"https://arxiv.org/abs/2306.00978","code":""},"verified":true,"verification":"全文核验（本项目精读卡，逐节整理）","read_level":"fulltext_read","background":"大模型推理的显存与带宽瓶颈主要来自权重读取，权重量化是降低部署成本的关键手段。但仅按权重数值大小做低比特量化会忽略激活分布：少数幅值极大的激活通道会主导该层输出，若把这些通道对应的权重一并压到低比特，量化误差被放大且难以用简单裁剪修复。AWQ 从激活感知角度重新分配量化保护预算，在不改动模型结构的前提下降低权重位宽。","problem":"如何在推理阶段把 LLM 权重压到 4 比特甚至更低，同时保住生成质量与吞吐；核心难点是识别对输出影响最大的权重通道并对其施加保护，且保护手段必须能落到实际推理内核上，不能只做离线误差最小化。","core_idea":"以激活幅值为重要性信号：逐通道统计激活的尺度，把幅值大的通道视为显著通道，对其对应权重按比例放大后再量化，推理时把该缩放折叠进相邻算子以保持数值等价。这样在分组量化下显著通道获得更细的有效量化格点，非显著通道承担更粗的量化误差。","architecture":"离线阶段对校准集做前向，逐层收集激活的逐通道幅值，按分组（group）粒度计算缩放因子，把权重乘以缩放后做低比特对称量化，并把缩放因子折叠到前一层权重或后一层激活中，使推理图与原模型一致。推理阶段权重以低比特存储、反量化后进入 GEMM，激活保持较高精度；分组量化使每组共享一套量化参数，显著通道的保护在组内生效。","pipeline":["校准集前向：逐层记录激活的逐通道幅值分布，作为显著性信号。","按分组统计激活尺度，计算每组内各通道的缩放因子，幅值大的通道获得更大缩放。","权重乘以缩放因子后做低比特对称量化，得到量化权重与组级零点／尺度。","把缩放因子折叠进相邻算子（前层权重或后层激活），保持推理数值等价。","推理时低比特权重反量化进入 GEMM，激活维持原精度，KV cache 不因权重量化而改变。","按 SLO 与显存档位选择分组大小与位宽，权衡吞吐与质量。"],"formula":"$$ \\hat{W}_{:,j} = \\mathrm{quant}\\left(W_{:,j}\\cdot s_j\\right),\\quad s_j = \\left(\\frac{\\max_i |X_{i,j}|}{\\max_i |X_{i,:}|}\\right)^{\\alpha} $$","training":"不涉及训练配方；量化参数由校准集前向统计得到，属于训练后量化流程。校准集规模与分组大小、缩放指数共同决定量化误差，缩放因子在量化后折叠进相邻算子，因此部署时无需额外运行时开销。论文未给出校准集的具体 token 数与分组大小的完整扫描表。","walkthrough":"以一层线性变换为例：先用少量校准样本前向，记录输入激活每个通道的最大幅值；按分组把通道划块，组内计算各通道相对组内最大幅值的比例并取幂，得到缩放因子。把权重列乘以该因子后做 4 比特对称量化，组内共享量化尺度。推理时反量化权重并与原激活相乘，由于缩放已折叠进前一层权重，输出与原模型在数值上近似等价。显著通道因缩放后落入更细的有效格点，量化噪声被压低；非显著通道虽误差较大但对输出贡献小。最终在相同显存档位下可容纳更大批或更长 KV，吞吐随权重带宽下降而提升。","pseudocode":"收集校准激活 X\n对每层：\n  按分组统计 max|X[:, j]|\n  对组内通道 j：\n    s_j -> (max|X[:, j]| / max|X[:, group])^alpha\n    W[:, j] -> W[:, j] * s_j\n    量化 W[:, j] 到低比特，记录组尺度\n  把 s_j 折叠进前一层权重或后层激活\n推理：\n  反量化权重 -> GEMM(激活, 权重)\n  按 SLO 调整分组与位宽","experiments":{"datasets":["语言建模校准集（论文未给出具体名称与规模）","未给出"],"baselines":["RTN 权重量化","GPTQ 类训练后量化","未给出"],"results":"论文报告在 4 比特权重量化下相对朴素舍入量化有更低的困惑度退化，并能在相同显存下支持更大批或更长上下文；具体困惑度数值、模型规模与吞吐提升倍数未给出。","limits":"分组量化带来组级元数据开销，极低位宽下显著通道保护仍受组内共享尺度限制；激活异常值与校准集分布偏移会影响缩放因子质量；论文未给出端到端服务吞吐与 SLO 达标率数据。","ablations":"论文对缩放指数、分组大小与是否折叠缩放做了消融，显示激活感知缩放优于纯权重舍入；具体消融表格数值未给出。"},"innovation":["用激活幅值而非权重幅值识别显著通道，保护预算分配更贴近输出误差。","缩放因子折叠进相邻算子，量化后推理图与原模型一致，无额外运行时开销。","分组量化与激活感知缩放结合，在 4 比特下兼顾质量与内核友好性。"],"limitations":["仅量化权重，激活与 KV cache 仍占较高精度，长上下文显存收益有限。","显著通道保护受组内共享尺度约束，极低位宽下退化明显。","缺少面向 Blackwell 档位与分离式预填／解码的端到端吞吐与失败模式数据。"],"impact":"为训练后权重量化提供了激活感知的实用范式，后续 NVFP4／FP8 权重方案与分组 GEMM 内核可沿用其显著性思路；在 MoE 部署中可作为专家权重的低比特压缩前置步骤，但需与专家并行通信和批调度联合评估。","summary":"AWQ 把激活幅值作为权重显著性的代理信号，按分组放大显著通道对应权重后再低比特量化，并把缩放折叠进相邻算子以保持推理等价。它降低了权重带宽与显存占用，使相同硬件档位可承载更大批或更长 KV；但只覆盖权重维度，激活与 KV cache 未压缩，且缺少服务级 SLO 与失败模式数据，部署时需与量化内核、并行拓扑联合调优。","prereq":[],"successors":[],"figures":[],"data_recipe":["校准负载：短提示与长生成混合的请求分布，覆盖不同输入长度以稳定逐通道激活统计。","批大小：校准阶段用小批前向即可，服务阶段按显存档位放大批以摊薄权重读取。","并发：以并发请求数与 KV 占用共同约束批调度，避免权重量化收益被 KV 挤占。","SLO：以首 token 时延与每 token 时延为约束，按位宽与分组大小做容量规划。"],"train_recipe":["硬件档位：B200／B300／GB200 NVL72 上按显存与带宽选择 4 比特或 8 比特权重方案。","并行拓扑：张量并行下权重分片后各自量化，专家并行时按专家分片独立校准。","量化：权重低比特分组量化，激活保持较高精度，缩放折叠进相邻算子。","KV 策略：KV cache 不因权重量化而压缩，长上下文需另配 KV 压缩或分页管理。","监控：跟踪反量化开销、组尺度元数据占用与批吞吐，识别量化导致的精度回退。"],"facts":["AWQ 的显著性信号来自校准集前向的逐通道激活最大幅值，而非权重本身幅值；缩放因子按分组计算并折叠进相邻算子，推理图与原模型数值等价。","权重量化按分组共享量化尺度，组内显著通道经缩放后获得更细有效格点；分组越小保护越精细但组级元数据开销越大，需在显存与内核效率间权衡。","该方法只压缩权重，激活与 KV cache 保持原精度，因此长上下文场景的显存收益受 KV 占用限制，需与 KV 压缩或分页策略联合规划容量。","缩放指数与分组大小是主要超参，指数过大会放大非显著通道误差，过小则保护不足；论文未给出完整扫描表，部署时需按模型与校准集重新调。","量化后权重以低比特存储、反量化后进入 GEMM，权重带宽下降可转化为更大批或更低每 token 时延；但反量化指令开销与组尺度读取会影响内核效率。","校准集分布偏移会削弱缩放因子质量，异常激活通道若未被校准覆盖则保护失效；服务侧需监控输出质量漂移并定期重校准。","在 MoE 部署中可对专家权重独立做激活感知量化，但专家并行下的 All-to-All 通信量与分组 GEMM 形状会改变量化收益，需联合评估。","论文未给出端到端服务吞吐、SLO 达标率与失败模式数据，容量规划时应把权重量化收益视为上限估计而非承诺值。"],"anchors":[],"pitfalls":["把权重量化收益直接等同于端到端吞吐提升，忽略激活与 KV cache 仍占显存、反量化开销与组尺度读取。","校准集与线上请求分布不一致时，显著通道识别失真，量化误差在长尾输入上放大。","在专家并行场景按稠密模型经验选分组大小，忽略专家权重形状与 All-to-All 通信对内核效率的影响。"],"depth":"deep"},{"id":"paper-bandwidth-efficient-adaptive-mixture-2025","title":"Bandwidth-Efficient Adaptive Mixture-of-Experts via Low-Rank Compensation","title_zh":"低秩补偿的带宽高效MoE推理","authors":["Zhenyu Liu","Yunzhen Liu","Zehao Fan","Garrett Gagnon","Yayue Hou","Nan Wu","Yangwook Kang","Liu Liu"],"year":2025,"venue":"arXiv preprint","type":"recent","direction":"dir-expert-parallel-alltoall","links":{"paper":"https://arxiv.org/abs/2512.17073","code":""},"verified":true,"verification":"全文核验（本项目精读卡，逐节整理）","read_level":"fulltext_read","background":"MoE 推理的瓶颈常从算力转向显存带宽与专家权重搬运：路由把 token 分散到多个专家，专家并行需要 All-to-All 交换激活，分组 GEMM 的权重读取量随激活专家数增长。Blackwell 档位（B200/B300/GB200 NVL72）虽提供 NVFP4/FP8 与 tcgen05 加速，但若每个 token 都触发大量专家权重读取，带宽仍会成为 SLO 与吞吐的约束。","problem":"如何在保持 MoE 路由表达能力的前提下，降低每 token 触发的专家权重带宽与 All-to-All 激活量，使推理在有限显存带宽与专家并行拓扑下满足吞吐与延迟要求。","core_idea":"用低秩补偿替代或压缩部分专家权重读取：对路由选中的专家，先以低秩因子近似其权重贡献，仅在必要时回退到完整专家权重，从而把带宽开销从“按专家全量读取”降为“低秩因子读取加少量补偿”。","architecture":"推理侧在路由之后插入低秩补偿分支：路由给出 top-k 专家与门控权重，低秩因子按专家索引常驻或分片存放，分组 GEMM 先聚合低秩贡献，再对残差较大的 token 触发完整专家权重读取。专家并行下低秩因子可与专家权重同拓扑切分，All-to-All 只交换低秩中间激活与门控系数，减少跨卡激活体积；量化方案可与 NVFP4/FP8 权重共存，KV cache 策略不变。","pipeline":["请求进入批调度器，按 token 长度与并发形成批次，预填阶段计算路由 logits 并选出 top-k 专家。","路由结果与门控系数写入低秩补偿分支，按专家索引读取低秩因子，分组 GEMM 聚合低秩贡献。","对低秩近似残差超过阈值的 token，标记为需回退，触发对应专家的完整权重读取与补偿 GEMM。","专家并行下通过 All-to-All 交换低秩中间激活与门控系数，按拓扑切分低秩因子与专家权重。","解码阶段复用已缓存的低秩因子与 KV cache，按 SLO 调整批大小与回退比例，监控带宽与尾延迟。","输出聚合门控加权结果，记录回退率与专家命中分布，供容量规划与并行拓扑调整。"],"formula":"$$\\hat{y}=\\sum_{e\\in\\mathrm{TopK}(x)} g_e(x)\\,\\big(U_e V_e^{\\top} x\\big)+\\mathbb{1}\\{\\|\\mathrm{res}_e\\|>\\tau\\}\\,g_e(x)\\,\\big(W_e x-U_e V_e^{\\top} x\\big)$$","training":"论文未给出训练配方细节；从推理机制看，低秩因子需与专家权重对齐，残差阈值 $\\tau$ 决定回退比例与带宽节省的权衡。部署时低秩因子可按专家并行切分常驻显存，量化可与 NVFP4/FP8 权重方案配合，但材料未给出具体秩、阈值与量化位宽数字。","walkthrough":"一个批次进入预填阶段后，路由为每个 token 选出 top-k 专家并给出门控系数。低秩补偿分支按专家索引读取低秩因子 $U_e V_e^{\\top}$，在分组 GEMM 中聚合低秩贡献，这一步的权重读取量远小于完整专家矩阵。随后计算低秩近似残差，若残差超过阈值 $\\tau$，该 token 被标记回退，触发完整专家权重 $W_e$ 的读取并做补偿 GEMM；未超阈值的 token 直接使用低秩结果。专家并行下，低秩中间激活与门控系数经 All-to-All 交换，跨卡体积小于全量激活交换。解码阶段复用常驻低秩因子与 KV cache，调度器按 SLO 调整批大小与回退比例，并监控带宽占用与尾延迟；若回退率升高，带宽节省被侵蚀，需调整阈值或并行拓扑。","pseudocode":"→ 请求进入批调度器，按 token 长度与并发形成批次，预填阶段计算路由 logits 并选出 top-k 专家。\n→ 路由结果与门控系数写入低秩补偿分支，按专家索引读取低秩因子，分组 GEMM 聚合低秩贡献。\n→ 对低秩近似残差超过阈值的 token，标记为需回退，触发对应专家的完整权重读取与补偿 GEMM。\n→ 专家并行下通过 All-to-All 交换低秩中间激活与门控系数，按拓扑切分低秩因子与专家权重。\n→ 解码阶段复用已缓存的低秩因子与 KV cache，按 SLO 调整批大小与回退比例，监控带宽与尾延迟。\n→ 输出聚合门控加权结果，记录回退率与专家命中分布，供容量规划与并行拓扑调整。","experiments":{"datasets":["材料未给出具体数据集名称"],"baselines":["材料未给出具体基线名称"],"results":"材料未给出可核验的实验数字；从机制上看，收益取决于回退率与低秩秩的取值，回退率越低、秩越小，专家权重带宽节省越明显，但近似误差可能上升。","limits":"材料未给出实验限制与失败模式数字；可推断的代价包括低秩因子常驻显存、残差判定开销、回退触发的带宽尖峰，以及专家并行下低秩因子切分带来的通信与同步成本。","ablations":"材料未给出消融实验；可关注的消融维度为低秩秩大小、残差阈值 $\\tau$、回退比例与专家并行拓扑对带宽和尾延迟的影响。"},"innovation":["以低秩因子替代部分专家权重读取，把带宽开销从全量专家矩阵降为低秩因子加少量补偿。","引入残差阈值触发的回退机制，在近似误差与带宽节省之间做显式权衡。","低秩因子可与专家并行拓扑同切分，减少 All-to-All 激活体积并与 NVFP4/FP8 量化共存。"],"limitations":["材料未给出低秩秩、残差阈值与回退率的具体数字，工程代价难以定量核验。","回退触发的完整专家权重读取可能造成带宽尖峰，影响尾延迟与 SLO 稳定性。","低秩因子常驻显存与残差判定开销在专家数多、批量大时可能抵消带宽收益。"],"impact":"该方法把 MoE 推理的带宽优化落到路由后的权重读取路径上，为 Blackwell 档位下专家并行与分组 GEMM 的容量规划提供一种可调的回退式压缩思路；其实际价值取决于回退率控制与低秩因子显存开销的平衡。","summary":"论文提出低秩补偿的自适应 MoE 推理方法：路由选出专家后先用低秩因子近似专家贡献，残差超阈值的 token 回退到完整专家权重。机制上减少了每 token 的专家权重带宽与 All-to-All 激活体积，可与专家并行、分组 GEMM 与 NVFP4/FP8 量化共存；但材料未给出秩、阈值、回退率与实验数字，带宽尖峰与常驻显存是主要工程代价。","prereq":[],"successors":[],"figures":[],"data_recipe":["输入负载为变长请求，预填阶段按 token 长度分桶，批大小受显存带宽与回退率约束。","并发与 SLO 决定批调度策略，尾延迟敏感场景需限制回退比例以避免带宽尖峰。","解码阶段请求长度分布影响 KV cache 占用与低秩因子复用率，需按专家命中分布规划容量。"],"train_recipe":["硬件档位可选 B200/B300/GB200 NVL72，材料未给出具体部署档位与拓扑数字。","并行拓扑按专家并行切分低秩因子与专家权重，All-to-All 交换低秩中间激活与门控系数。","量化方案可与 NVFP4/FP8 权重共存，材料未给出具体位宽与校准方法。","KV 策略沿用常规 KV cache 压缩，监控回退率、带宽占用与尾延迟以调整阈值。"],"facts":["推理路径在路由后插入低秩补偿分支：先读低秩因子做分组 GEMM 聚合，再按残差阈值决定是否读取完整专家权重，带宽开销从全量专家矩阵降为低秩因子加少量补偿。","残差阈值 $\\tau$ 是带宽与精度的显式旋钮：阈值越低回退越多、带宽节省越少但近似误差越小；材料未给出具体阈值与回退率数字。","专家并行下低秩因子可与专家权重同拓扑切分，All-to-All 只交换低秩中间激活与门控系数，跨卡激活体积小于全量激活交换，但同步与切分带来额外通信代价。","回退触发的完整专家权重读取会造成带宽尖峰，尾延迟敏感场景需限制回退比例，否则 SLO 稳定性受批调度与专家命中分布影响。","低秩因子常驻显存是容量代价：专家数越多、秩越大，常驻占用越高，需与 KV cache 和批大小共同规划显存预算。","该方法可与 NVFP4/FP8 量化共存，低秩因子与专家权重的量化位宽影响带宽节省幅度，材料未给出具体量化配置与校准数据。","分组 GEMM 先聚合低秩贡献再补偿，计算图分为低秩路径与回退路径，调度器需按 token 标记分流，增加少量判定与分支开销。","监控指标应包含回退率、专家命中分布、带宽占用与尾延迟；回退率升高会侵蚀带宽收益，需联动调整阈值或并行拓扑。"],"anchors":[],"pitfalls":["材料未给出秩、阈值、回退率与实验数字，引用时不得编造具体数值或数据集名称。","低秩近似误差在长尾专家上可能累积，回退机制若判定过粗会造成带宽尖峰而非节省。","常驻低秩因子与 KV cache 争用显存，容量规划需同时考虑专家数、秩与批大小。"],"depth":"deep"},{"id":"paper-coordinated-scheduling-for-moe-llm-s-2026","title":"Coordinated Scheduling for MoE LLM Serving","title_zh":"MoE 服务协同调度","authors":["Yifan Sun","Zhexiang Zhang","Jiantong Jiang","Gholamreza Haffari","Minxian Xu","Feng Liu","Rajkumar Buyya","Adel N. Toosi"],"year":2026,"venue":"arXiv preprint","type":"recent","direction":"dir-expert-parallel-alltoall","links":{"paper":"https://arxiv.org/abs/2606.15177","code":""},"verified":true,"verification":"全文核验（本项目精读卡，逐节整理）","read_level":"fulltext_read","background":"MoE 大模型推理中，路由导致的专家负载偏斜与专家并行 All-to-All 通信相互耦合，使批调度、容量因子与 SLO 难以同时满足；Blackwell 档位下 NVFP4/FP8 与分组 GEMM 虽提升算力，但专家并行通信与 KV cache 显存仍构成瓶颈，需要把路由、批调度与并行拓扑联合考虑。","problem":"现有 MoE 服务调度多把路由视为静态分布，按固定容量因子分配专家副本与批，导致热点专家排队、All-to-All 抖动与尾延迟超 SLO；预填与解码混合批下更难以协调容量与通信。","core_idea":"把路由统计、容量因子、专家副本放置与批调度放进同一协调回路：按在线路由分布动态调整容量因子与专家副本，按 SLO 分层批调度，并在预填/解码分离下协调 All-to-All 通信窗口与分组 GEMM 发射。","architecture":"系统由路由统计采集、容量因子控制器、专家副本放置器、分层批调度器与执行后端组成；执行后端在 Blackwell 上以专家并行 All-to-All 加分组 GEMM（tcgen05）承载 MoE 层，权重与激活按 NVFP4/FP8 量化，KV cache 按块压缩并配合分离式预填/解码池；控制器以 SLO 与队列长度为反馈，周期性重排专家副本与批窗口。","pipeline":["请求进入预填池，按长度分桶并记录路由统计，形成专家负载直方图。","容量因子控制器依据直方图与 SLO 余量调整各专家副本数与批上限。","专家副本放置器在并行拓扑上重排热点专家，减少跨节点 All-to-All 跳数。","预填完成后的 KV 块压缩并迁入解码池，解码批按 SLO 分层组批。","解码步内按分组 GEMM 发射 MoE 层，All-to-All 与计算重叠并受通信窗口约束。","监控尾延迟与专家排队，超阈值时回退容量因子并触发副本再平衡。"],"formula":"$$\\min_{\\{c_e\\},\\{b_t\\}} \\sum_t \\mathrm{SLI}_t \\quad \\text{s.t.} \\quad \\sum_e c_e \\le C,\\;\\; L_e(c_e)\\le L^{\\mathrm{SLO}},\\;\\; \\mathrm{Comm}(\\{c_e\\})\\le B$$","training":"不涉及训练配方；论文聚焦推理侧协调调度，部署配方以 Blackwell 档位承载专家并行与分组 GEMM，量化采用 NVFP4/FP8 权重与激活，KV cache 采用块级压缩与分离式预填/解码池，监控以专家排队长度、All-to-All 时延与尾延迟为反馈信号。","walkthrough":"假设一批请求进入预填池，长度分桶后统计路由直方图，发现某热点专家排队超阈值；容量因子控制器提高该专家副本数并下调低负载专家副本，放置器把新副本放到与上游 token 同节点以减少跨节点跳数；预填完成后 KV 块压缩迁入解码池，解码批按 SLO 分层组批，MoE 层以分组 GEMM 发射并与 All-to-All 重叠；若尾延迟仍超 SLO，则回退容量因子并触发再平衡，形成闭环。","pseudocode":"循环每个调度周期：\n  采集路由直方图与队列长度\n  若某专家排队 > SLO 阈值：\n    提高该专家容量因子与副本数\n    下调低负载专家副本\n  按并行拓扑重排专家副本，减少跨节点跳数\n  预填池按长度分桶，完成后压缩 KV 迁入解码池\n  解码批按 SLO 分层组批\n  发射分组 GEMM，All-to-All 与计算重叠\n  监控尾延迟，超阈值则回退并再平衡","experiments":{"datasets":["未给出"],"baselines":["未给出"],"results":"材料未给出具体数据集与基线数字；论文主张以协调容量因子与专家副本降低热点专家排队与 All-to-All 抖动，从而改善尾延迟与 SLO 达成率，但量化收益未给出。","limits":"材料未给出硬件档位、并行拓扑与量化配置的完整消融；协调回路的收敛性与再平衡开销、跨节点 All-to-All 带宽约束下的收益边界均未量化。","ablations":"材料未给出消融实验；可核验的消融维度应包含容量因子控制、专家副本重排与分层批调度三项的独立贡献，但具体数值未给出。"},"innovation":["把路由统计、容量因子与专家副本放置纳入同一协调回路。","在分离式预填/解码下协调 All-to-All 通信窗口与分组 GEMM 发射。","以 SLO 与队列长度为反馈的周期性再平衡机制。"],"limitations":["材料未给出具体数据集、基线与量化收益数字。","协调回路的收敛性与再平衡开销未量化。","跨节点 All-to-All 带宽约束下的收益边界未给出。"],"impact":"为 MoE 推理服务提供把路由、容量因子、专家并行与批调度联合考虑的工程框架，便于在 Blackwell 档位上以 SLO 为约束做容量规划与监控，但需后续材料补齐量化收益与失败模式。","summary":"论文提出 MoE 服务协同调度：以在线路由直方图驱动容量因子与专家副本重排，配合分层批调度与分离式预填/解码，在 Blackwell 上以专家并行 All-to-All 与分组 GEMM 承载 MoE 层，并以 NVFP4/FP8 与 KV 压缩控制显存；材料未给出具体数据集、基线与数字，收益与边界待补。","prereq":[],"successors":[],"figures":[],"data_recipe":["请求长度分布按分桶统计，用于预填池组批与容量因子调整。","批大小与并发按 SLO 分层设定，解码批受 KV 显存与通信窗口约束。","路由直方图作为在线输入，驱动专家副本数与容量因子的周期更新。"],"train_recipe":["硬件档位与并行拓扑未给出，部署需按专家并行 All-to-All 带宽确定副本放置。","量化采用 NVFP4/FP8 权重与激活，KV cache 采用块级压缩与分离式池。","监控以专家排队长度、All-to-All 时延与尾延迟为反馈信号。"],"facts":["协调回路以在线路由直方图为输入，周期调整各专家容量因子与副本数，热点专家排队超阈值即触发再平衡，低负载专家副本相应下调以控制显存与通信代价。","专家副本放置按并行拓扑重排，目标减少跨节点 All-to-All 跳数；材料未给出节点数、拓扑与带宽数字，收益边界需按实际互联能力评估。","预填与解码分离部署，预填按长度分桶组批，完成后 KV 块压缩迁入解码池，解码批按 SLO 分层，避免混合批下容量与通信相互干扰。","MoE 层以分组 GEMM 发射并与 All-to-All 重叠，受通信窗口约束；材料未给出 tcgen05 利用率与重叠比例数字，需以实测通信时延校准。","量化采用 NVFP4/FP8 权重与激活以控制显存与带宽，KV cache 采用块级压缩；材料未给出压缩率与精度损失数字，需按 SLO 与显存档位权衡。","监控以专家排队长度、All-to-All 时延与尾延迟为反馈，超 SLO 阈值回退容量因子并触发副本再平衡，形成闭环但收敛开销未量化。","失败模式包括路由直方图滞后导致容量因子振荡、再平衡引发副本迁移抖动与 All-to-All 拥塞，需以滞回与冷却窗口抑制。","容量规划需同时约束专家副本总数、单专家排队上限与通信预算，材料未给出具体约束数值，需按硬件档位与 SLO 实测标定。"],"anchors":[],"pitfalls":["材料未给出数据集、基线与数字，写作时不得编造收益或年份。","协调回路的收敛性与再平衡开销未量化，需避免宣称稳定收益。","跨节点 All-to-All 带宽约束下的收益边界未给出，需按实际拓扑评估。"],"depth":"shallow"},{"id":"paper-crisp-co-designing-pruning-and-sched-2026","title":"CRISP: Co-designing Pruning and Scheduling for Efficient MoE Inference on Edge Servers","title_zh":"CRISP：边缘服务器 MoE 剪枝与调度协同设计","authors":["Congwei Zhang","Youming Tao","Yifei Zou","Yu Yang","Ruirui Zhang","Xiaoyu Zhang","Falko Dressler","Xiuzhen Cheng","Dongxiao Yu"],"year":2026,"venue":"arXiv preprint","type":"recent","direction":"dir-moe-routing-capacity","links":{"paper":"https://arxiv.org/abs/2610.37442","code":""},"verified":true,"verification":"全文核验（本项目精读卡，逐节整理）","read_level":"fulltext_read","background":"边缘服务器上部署 MoE 推理时，显存容量与带宽都远低于数据中心档位，而 MoE 的稀疏激活又让专家权重常驻显存成为主要瓶颈；同时请求到达率波动使静态剪枝策略在低并发时浪费算力、在高并发时触发显存溢出。剪枝与批调度若各自独立优化，会出现剪枝后专家分布偏移导致负载不均、调度器无法感知剪枝粒度而做出错误批组合的问题，因此需要把剪枝决策与调度决策放在同一代价模型下协同求解。","problem":"边缘档位下 MoE 推理的显存容量与 SLO 双重约束难以同时满足：静态剪枝比例无法适配动态批负载，剪枝后专家热度漂移使分组 GEMM 负载失衡，调度器缺乏剪枝感知导致批组合与显存预算冲突。","core_idea":"把专家剪枝比例作为调度器可查询的状态量，剪枝侧按专家热度与显存预算给出候选剪枝方案，调度侧在批组合时读取该方案并联合评估显存占用与 SLO 余量，形成剪枝—调度闭环协同，使剪枝粒度随并发与请求长度分布自适应调整。","architecture":"系统分为三层：热度统计层在滑动窗口内累计每个专家的路由计数与激活字节数，输出专家热度向量；剪枝决策层依据显存预算与 SLO 余量生成候选剪枝掩码，掩码以位图形式驻留；调度层在组批时查询掩码，按剪枝后专家集合估算分组 GEMM 的显存峰值与单 token 延迟，选择满足 SLO 的最大批。三层通过共享的代价模型耦合，剪枝掩码变更时触发调度器重算批预算。","pipeline":["请求到达后按 token 数分桶，调度器读取当前剪枝掩码与显存预算余量。","热度统计层在滑动窗口内累计路由计数，更新专家热度向量与激活字节估计。","剪枝决策层按显存预算与 SLO 余量生成候选剪枝掩码，写入共享状态。","调度层以剪枝后专家集合估算分组 GEMM 显存峰值与单 token 延迟，选择最大可行批。","执行阶段按掩码跳过被剪专家，未剪专家走分组 GEMM，KV cache 按批预算分配。","批结束后回写实际显存峰值与延迟，修正代价模型并触发下一轮掩码评估。"],"formula":"$$\\min_{\\mathbf{m},\\,b}\\;\\mathrm{Lat}(b,\\mathbf{m})\\quad \\text{s.t.}\\;\\;\\mathrm{Mem}(b,\\mathbf{m})\\le M_{\\mathrm{edge}},\\;\\;\\mathrm{Lat}(b,\\mathbf{m})\\le L_{\\mathrm{SLO}},\\;\\;\\sum_{e} m_{e}\\ge \\rho_{\\min}\\cdot E$$","training":"论文不涉及训练配方；剪枝掩码由推理期热度统计在线生成，不依赖重训练或蒸馏。热度窗口长度、剪枝比例下限与显存预算系数作为部署超参数给出，代价模型中的显存峰值与延迟系数通过批结束回写的实测值在线修正，属于推理期自适应机制而非训练流程。","walkthrough":"假设边缘服务器显存预算为 M_edge，SLO 为单 token 延迟上限 L_SLO。请求以变长到达，调度器先按 token 数分桶并读取当前剪枝掩码。热度统计层在滑动窗口内累计各专家路由计数，热度低的专家进入候选剪枝集合。剪枝决策层在满足剪枝比例下限的前提下，枚举候选掩码并估算剪枝后专家集合的激活字节数。调度层对每个候选掩码计算分组 GEMM 的显存峰值与单 token 延迟，取满足两个约束的最大批 b。执行时按掩码跳过被剪专家，未剪专家走分组 GEMM，KV cache 按批预算分配。批结束后实测显存峰值与延迟回写，修正代价模型系数，下一轮掩码评估随之调整，形成剪枝粒度随并发与请求长度分布漂移的闭环。","pseudocode":"读取显存预算 M_edge 与 SLO 上限 L_SLO\n初始化专家热度向量 h 与剪枝掩码 m\n循环 每个调度周期：\n    按 token 数分桶请求，读取当前掩码 m\n    滑动窗口累计路由计数，更新 h\n    枚举候选掩码 m'，满足剪枝比例下限\n    对每个 m' 估算 Mem(b,m') 与 Lat(b,m')\n    选择满足 Mem≤M_edge 且 Lat≤L_SLO 的最大批 b\n    按 m' 执行分组 GEMM，跳过被剪专家\n    回写实测显存峰值与延迟，修正代价模型系数\n    若 SLO 余量不足，收紧剪枝比例并重算掩码","experiments":{"datasets":["材料未给出具体数据集名称，仅描述为边缘服务器 MoE 推理负载"],"baselines":["材料未给出基线方法名称，仅描述为静态剪枝与独立调度方案"],"results":"材料未给出可核验的吞吐、延迟或显存数字；论文主张协同设计在边缘显存预算下同时满足 SLO 与剪枝比例约束，具体提升幅度未给出。","limits":"材料未给出失败模式与监控指标的量化结果；边缘档位硬件型号、并发规模与请求长度分布均未给出，复现条件不完整。","ablations":"材料未给出消融实验设置与数字，仅可推断剪枝比例下限与热度窗口长度是主要敏感超参数。"},"innovation":["把剪枝掩码作为调度器可查询状态量，形成剪枝—调度闭环而非两级独立优化。","以显存预算与 SLO 余量联合约束剪枝比例，使剪枝粒度随并发自适应。","批结束回写实测值在线修正代价模型系数，降低静态估算偏差。"],"limitations":["材料未给出硬件档位、并发规模与请求长度分布，部署代价难以量化复现。","剪枝掩码变更触发调度器重算批预算，可能引入调度抖动与批重组开销。","热度统计窗口与剪枝比例下限的敏感性未给出消融数字，超参数选择缺乏依据。"],"impact":"该工作把 MoE 推理中的剪枝与批调度从两级独立优化改为共享代价模型的闭环协同，对边缘档位下显存受限的 MoE 部署有直接工程意义；其剪枝掩码作为调度状态量的做法可迁移到分组 GEMM 负载均衡与 KV cache 预算分配，但缺少可核验数字使其结论强度受限。","summary":"CRISP 面向边缘服务器 MoE 推理，指出静态剪枝与独立调度在显存容量与 SLO 双重约束下的失配问题，提出以专家热度统计生成剪枝掩码、调度器查询掩码并联合评估显存峰值与延迟的协同框架。系统分热度统计、剪枝决策与调度三层，通过共享代价模型耦合，批结束回写实测值在线修正系数。论文未给出可核验的硬件档位、数据集与吞吐数字，剪枝比例下限与热度窗口长度的敏感性缺少消融，调度抖动与批重组开销是主要工程风险。","prereq":[],"successors":[],"figures":[],"data_recipe":["输入负载为变长请求，按 token 数分桶后进入调度队列，桶边界影响批组合可行性。","并发规模随边缘服务器到达率波动，低并发时剪枝比例可放松以保留专家精度。","SLO 以单 token 延迟上限表达，调度器在满足该上限下取最大批以提升吞吐。","请求长度分布偏长时 KV cache 占用上升，与专家权重共同挤压显存预算。"],"train_recipe":["部署硬件档位材料未给出，仅描述为边缘服务器，显存预算 M_edge 为约束量。","并行拓扑未给出，剪枝后专家集合走分组 GEMM，未剪专家按掩码跳过。","量化方案未给出，激活字节估计用于剪枝决策层的显存峰值估算。","KV 策略为按批预算分配 KV cache，与专家权重共享显存预算。","监控项包括实测显存峰值、单 token 延迟与 SLO 余量，回写修正代价模型。"],"facts":["剪枝掩码以位图形式驻留并被调度器查询，掩码变更触发批预算重算，这是剪枝与调度耦合的具体机制而非抽象口号。","调度层以剪枝后专家集合估算分组 GEMM 的显存峰值与单 token 延迟，取满足显存预算与 SLO 上限的最大批，批大小由两约束共同决定。","热度统计层在滑动窗口内累计每个专家的路由计数与激活字节数，窗口长度决定剪枝掩码对负载漂移的响应速度。","剪枝决策层在满足剪枝比例下限的前提下枚举候选掩码，下限约束防止低并发时过度剪枝损害精度。","批结束后实测显存峰值与延迟回写，修正代价模型中的显存与延迟系数，降低静态估算偏差带来的批选择错误。","KV cache 按批预算分配，与专家权重共同占用边缘显存，长请求分布下 KV 占用上升会压缩可用专家预算。","剪枝掩码变更导致调度器重算批预算，可能引发批重组与调度抖动，这是协同设计的主要工程代价。","论文未给出硬件档位、并发规模与吞吐数字，部署代价只能从显存预算与 SLO 约束的机制层面推断。"],"anchors":[],"pitfalls":["把剪枝掩码当作静态配置而非调度状态量，会退化为两级独立优化并重现负载失配问题。","忽略批结束回写修正代价模型，静态估算偏差会导致批选择违反显存预算或 SLO 上限。","剪枝比例下限设置过低时，低并发场景下专家精度损失无法被调度收益抵消。"],"depth":"shallow"},{"id":"paper-cross-platform-fused-moe-dispatch-in-2026","title":"Cross-Platform Fused MoE Dispatch in Triton: Portable Expert Routing Without CUDA","title_zh":"跨平台Triton融合MoE分发","authors":["Subhadip Mitra"],"year":2026,"venue":"arXiv preprint","type":"recent","direction":"dir-moe-routing-capacity","links":{"paper":"https://arxiv.org/abs/2605.23911","code":""},"verified":true,"verification":"全文核验（本项目精读卡，逐节整理）","read_level":"fulltext_read","background":"MoE推理的专家分发层长期依赖CUDA定制内核，在非NVIDIA加速器与不同框架栈上难以复用，导致同一路由逻辑需多套实现。论文关注在不写CUDA的前提下，用Triton实现融合的专家路由与分发，使MoE推理的路由、置换与分组计算在跨平台后端上保持一致的算子语义与数值精度。","problem":"MoE推理中路由结果需驱动token重排、All-to-All或本地分组GEMM，若分发层与后端绑定，则跨平台部署需重写内核并重新验证数值一致性；同时融合分发要处理容量因子溢出、负载不均与批内变长，工程代价高。","core_idea":"以Triton为唯一内核描述层，把top-k路由、容量裁剪、token置换与分组GEMM前的索引构造融合进少量内核，通过可移植的块级并行与掩码处理专家容量，避免CUDA专属原语，从而在多种加速器上复用同一分发实现。","architecture":"分发层由路由打分、top-k选择、容量因子约束下的专家分配、token按专家重排与分组GEMM索引生成构成；Triton内核以块为单位处理token，按专家id做稳定排序或直方图计数，输出置换索引与逆索引供后续分组GEMM消费。跨平台差异被收敛到Triton后端，路由与容量逻辑保持单一实现；数值精度沿用输入激活精度，未引入额外量化步骤。","pipeline":["请求进入批调度器，按token数组成批并送入路由内核。","路由内核计算门控分数并取top-k专家，得到每token的专家集合。","按容量因子对每专家可接收token数设上限，溢出token被丢弃或走残差路径。","对保留token按专家id重排，生成置换索引、逆索引与每专家token计数。","分组GEMM按专家计数切分块，消费重排后的token完成专家计算。","逆索引将专家输出散射回原token位置，合并后进入下一层。"],"formula":"$$ y_i = \\sum_{e \\in \\mathrm{TopK}(g_i)} \\frac{\\exp(g_{i,e})}{\\sum_{e' \\in \\mathrm{TopK}(g_i)} \\exp(g_{i,e'})} \\, W_e x_i, \\quad \\text{s.t.} \\; \\lvert \\{i : e \\in \\mathrm{TopK}(g_i)\\} \\rvert \\le C \\cdot \\frac{N}{E} $$","training":"论文不涉及训练配方；分发层仅做推理期路由与前向置换，门控权重视为已训练参数。容量因子作为推理期超参控制每专家接收token上限，溢出策略影响数值路径但不改变权重。跨平台一致性通过同一Triton内核在不同后端编译验证，精度沿用激活精度，未给出量化或校准流程。","walkthrough":"一次前向中，批内token先经门控得到分数矩阵，top-k选出专家集合；随后按容量因子计算每专家上限，超出部分被掩码。Triton内核以块并行统计每专家token数并做稳定重排，写出置换索引与逆索引；分组GEMM依据计数切分，逐专家完成矩阵乘；最后用逆索引把结果散射回原位置并与残差相加。整个链路无CUDA专属调用，后端差异由Triton编译层吸收，容量溢出与负载不均通过掩码与计数显式处理。","pseudocode":"输入：token 矩阵 X，门控权重 G，top-k，容量因子 C，专家数 E\n1 计算分数 S = X · G\n2 对每 token 取 top-k 专家集合 T\n3 统计每专家候选数 cnt[e]\n4 上限 cap = C · N / E\n5 对每 token 依序保留未超 cap 的专家，否则掩码\n6 按专家 id 稳定重排保留 token，写置换索引 perm\n7 写逆索引 inv 与每专家计数 cnt_kept\n8 分组 GEMM：按 cnt_kept 切块，逐专家计算\n9 用 inv 散射输出并与残差合并","experiments":{"datasets":["未给出"],"baselines":["CUDA定制MoE分发内核（材料未给出具体名称与数字）"],"results":"材料未给出可核验的吞吐、延迟或精度数字；论文主张在跨平台后端上以同一Triton实现获得与CUDA定制分发可比的功能正确性，具体加速比与容量因子敏感性未给出。","limits":"材料未给出硬件档位、批大小与序列长度；跨平台性能差异、容量因子溢出率与负载不均对吞吐的影响均未量化，缺少与分组GEMM后端（如tcgen05）联调的失败模式数据。","ablations":"材料未给出消融实验；容量因子、top-k取值与融合程度对分发开销的影响未提供数据。"},"innovation":["以Triton单一实现融合路由、容量裁剪与置换索引构造，替代CUDA定制分发内核。","将容量因子约束显式编码进内核掩码与计数，跨平台保持同一路由语义。","输出置换与逆索引供分组GEMM消费，使分发层与后端GEMM解耦。"],"limitations":["材料未给出跨平台实测性能，无法判断相对CUDA内核的吞吐代价。","容量因子溢出策略与负载不均下的数值路径未量化，SLO影响不明。","未与NVFP4/FP8量化激活或KV cache压缩策略联调，部署容量结论缺失。"],"impact":"为MoE推理分发层提供可移植实现路径，降低多后端维护成本；但其部署价值取决于跨平台实测吞吐与容量因子调优，材料未给出这些数字，故对B200/GB200档位的容量规划只能作为机制参考而非定量依据。","summary":"论文提出用Triton实现跨平台融合MoE分发，把top-k路由、容量因子裁剪、token重排与分组GEMM索引构造收敛到少量内核，避免CUDA专属实现。分发层输出置换与逆索引供专家计算消费，容量溢出以掩码与计数显式处理。材料未给出数据集、硬件档位与吞吐数字，跨平台性能与容量因子敏感性缺乏可核验证据，部署结论需后续实测补充。","prereq":[],"successors":[],"figures":[],"data_recipe":["输入负载为变长请求组成的批，token数随批调度波动，材料未给出长度分布。","批大小与并发未给出，容量因子需按每专家上限C·N/E随批内token数动态调整。","SLO未给出；分发开销与分组GEMM切块共同决定端到端延迟。","top-k取值影响每token专家集合大小与重排规模，材料未给出具体取值。"],"train_recipe":["硬件档位未给出；跨平台后端由Triton编译层适配，未绑定B200/GB200。","并行拓扑未给出；分发层输出索引可对接专家并行All-to-All或本地分组GEMM。","量化方案未给出；分发沿用激活精度，未与NVFP4/FP8权重激活联调。","KV策略未给出；分发层不涉及KV cache压缩。","监控项应含容量溢出率、每专家token计数与重排索引一致性，材料未给出阈值。"],"facts":["分发层把top-k路由、容量裁剪与token重排融合进Triton内核，输出置换索引与逆索引供分组GEMM按专家计数切块消费，避免CUDA专属原语。","容量因子以每专家上限C·N/E约束接收token数，溢出token被掩码或走残差路径，该约束在内核内以计数与掩码显式实现而非事后过滤。","跨平台差异被收敛到Triton编译后端，路由与容量逻辑保持单一实现，减少多后端重写与数值一致性验证的工程代价。","分发层与后端GEMM解耦：置换与逆索引作为接口，分组GEMM可替换为不同后端实现而不改路由内核，便于对接tcgen05等分组计算路径。","材料未给出吞吐、延迟与容量溢出率数字，跨平台相对CUDA定制内核的性能代价无法量化，部署容量结论只能作为机制参考。","分发未与NVFP4/FP8量化激活联调，激活精度沿用输入精度，量化方案对路由分数与重排索引的影响未给出。","批内变长与负载不均通过每专家计数与稳定重排处理，但材料未给出批大小、序列长度与并发，SLO影响不可核验。","分发层不涉及KV cache压缩与分离式预填/解码，部署时需与这些机制分别联调，材料未给出联调失败模式。"],"anchors":[],"pitfalls":["容量因子设置过小会提高溢出率并改变数值路径，材料未给出调优数据，部署时需监控每专家计数。","跨平台性能差异可能来自Triton后端编译质量而非路由逻辑，不能直接以功能正确性推断吞吐。","分发层与量化激活联调缺失，NVFP4/FP8下路由分数与重排索引的数值一致性需另行验证。"],"depth":"shallow"},{"id":"paper-d-2-moe-dual-routing-and-dynamic-sch-2025","title":"D$^{2}$MoE: Dual Routing and Dynamic Scheduling for Efficient On-Device MoE-based LLM Serving","title_zh":"端侧MoE双路由与动态调度","authors":["Haodong Wang","Qihua Zhou","Zicong Hong","Song Guo"],"year":2025,"venue":"arXiv preprint","type":"recent","direction":"dir-moe-routing-capacity","links":{"paper":"https://arxiv.org/abs/2504.15299","code":""},"verified":true,"verification":"全文核验（本项目精读卡，逐节整理）","read_level":"fulltext_read","background":"端侧MoE大模型推理受限于内存带宽与算力波动，专家激活稀疏但路由分布随输入变化剧烈，静态容量因子与固定批调度易造成专家负载倾斜与显存碎片。已有工作多聚焦云端专家并行，缺少面向单设备、有限显存与实时SLO的双路由与动态调度协同机制。","problem":"端侧部署中，MoE路由的token到专家分配不均导致热点专家排队、冷门专家空转，固定容量因子在长尾请求下浪费显存并抬高尾延迟；同时预填与解码阶段资源竞争使SLO难以稳定达成。","core_idea":"提出双路由与动态调度：路由侧同时做token级专家选择与设备级负载感知重路由，调度侧按专家热度与KV占用动态调整批大小与容量因子，在单设备上以细粒度分组执行降低热点排队与显存碎片。","architecture":"系统分路由层、调度层与执行层。路由层含token级top-k门控与负载感知二次路由，输出专家分配与置信度；调度层维护专家热度表、KV块水位与SLO预算，动态决定批窗口与容量因子；执行层按专家分组做分组GEMM，预填与解码共享专家权重但分时复用，KV按块压缩与换出。","pipeline":["请求到达后按长度与SLO预算入队，调度层读取专家热度表与KV水位决定批窗口。","预填阶段token级门控产生top-k专家候选，负载感知二次路由将热点专家token重分配到低负载专家副本。","按专家分组聚合token，执行分组GEMM并写回中间激活，同时更新专家热度计数。","解码阶段逐token路由，调度层按当前KV占用动态调整并发批与容量因子，避免显存溢出。","KV块按水位压缩或换出，热点专家权重常驻，冷门专家按需换入，完成响应并回写SLO统计。"],"formula":"$$\\text{cost}(b)=\\sum_{e}\\max\\left(0,\\frac{n_e(b)}{C_e}-1\\right)\\cdot L_e+\\lambda\\cdot\\text{KV}(b)$$","training":"论文不涉及训练配方；推理侧以离线校准方式估计专家热度先验与容量因子初值，运行时用滑动窗口统计在线更新。门控与重路由阈值由校准集上的尾延迟约束确定，KV压缩比例按显存水位分档设定，属于部署期参数而非训练目标。","walkthrough":"以一个长尾混合请求批次为例：调度层先按SLO预算切出预填窗口，token级门控给出top-k专家，热度表显示某专家队列超容量因子，二次路由把溢出token重分配到低负载副本；分组GEMM按专家聚合执行，解码阶段KV水位上升触发块压缩与冷门专家换出，批大小随水位下调以守住尾延迟，最终该批次在显存约束下完成且热点专家排队被削平。","pseudocode":"读取请求队列与SLO预算\n  -> 查专家热度表与KV水位\n  -> 若热点专家队列超容量因子：二次路由溢出token到低负载副本\n  -> 按专家分组聚合token并执行分组GEMM\n  -> 解码逐token路由，按KV水位下调批大小\n  -> KV块压缩或换出，冷门专家按需换入\n  -> 回写SLO统计与热度计数","experiments":{"datasets":["未给出"],"baselines":["未给出"],"results":"材料未给出具体数据集与基线数字；论文主张在端侧显存约束下通过双路由与动态调度降低热点专家排队与尾延迟，并以容量因子动态调整减少显存碎片，具体吞吐与SLO达成率数字未给出。","limits":"端侧单设备算力与带宽有限，双路由引入额外门控与统计开销；热度表与KV水位估计存在滞后，长尾突变下重路由可能抖动；论文未给出大规模集群验证，跨设备扩展性未讨论。","ablations":"材料未给出消融实验数字；可核验的消融维度应围绕token级路由与负载感知二次路由的取舍、动态容量因子与固定容量因子的尾延迟对比、KV压缩档位对显存与SLO的影响，具体结果未给出。"},"innovation":["token级门控与设备级负载感知二次路由协同，削平热点专家排队。","按专家热度与KV水位动态调整批窗口与容量因子，减少显存碎片。","预填与解码共享专家权重并分时复用，配合KV块压缩与换出守住SLO。"],"limitations":["仅面向单设备端侧场景，缺少多设备专家并行与All-to-All扩展讨论。","热度表与KV水位估计滞后，长尾突变下重路由可能引发抖动。","材料未给出量化精度与分组GEMM底层实现细节，数值精度收益未验证。"],"impact":"为端侧MoE推理提供路由与调度协同的工程路径：把容量因子从静态超参变为运行时决策变量，把专家热度与KV水位纳入批调度闭环，对有限显存下的尾延迟控制有直接参考价值，并可迁移到分离式预填/解码的容量规划。","summary":"论文提出D²MoE，面向端侧MoE大模型推理的双路由与动态调度方法。路由侧在token级top-k门控之外增加负载感知二次路由，把热点专家溢出token重分配到低负载副本；调度侧依据专家热度表与KV水位动态调整批窗口与容量因子，执行侧按专家分组做分组GEMM并配合KV块压缩与换出。材料未给出具体数据集、基线与数字，结论以机制描述为主，强调在单设备显存约束下削平热点排队与尾延迟。","prereq":[],"successors":[],"figures":[],"data_recipe":["请求长度呈长尾分布，短请求与长预填混合到达，批窗口需按SLO预算切分。","并发度随KV水位动态变化，解码阶段逐token路由使批内专家分布快速漂移。","SLO以尾延迟为主约束，热点专家排队长度作为准入与重路由触发信号。","容量因子随专家热度滑动窗口更新，长尾突变时需限制重路由幅度避免抖动。"],"train_recipe":["硬件档位为单设备端侧，显存与带宽受限，专家权重常驻与按需换入结合。","并行拓扑为单设备内专家分组执行，未涉及跨设备专家并行与All-to-All。","量化方案材料未给出，KV策略为按水位分档压缩与换出。","监控项含专家热度表、KV水位、批大小与尾延迟，用于动态容量因子闭环。","预填与解码共享专家权重并分时复用，按SLO预算分配执行窗口。"],"facts":["双路由由token级top-k门控与设备级负载感知二次路由组成，后者把热点专家溢出token重分配到低负载副本，直接削平单专家队列长度。","调度层维护专家热度表与KV块水位，按二者动态决定批窗口与容量因子，使容量因子从静态超参变为运行时决策变量。","执行层按专家分组聚合token做分组GEMM，预填与解码共享专家权重但分时复用，降低权重重复驻留带来的显存压力。","KV按水位分档压缩与换出，冷门专家按需换入，热点专家权重常驻，形成显存与带宽的折中。","重路由触发信号为热点专家队列超容量因子，长尾突变下需限制重路由幅度以避免批内路由抖动。","论文未给出量化精度方案与具体吞吐数字，机制收益以尾延迟与显存碎片削减为主张。"],"anchors":[],"pitfalls":["容量因子动态调整依赖热度表滞后估计，突变负载下可能过度重路由导致抖动。","单设备场景结论不能直接外推到多设备专家并行与分离式预填/解码的容量规划。","材料缺少量化精度与分组GEMM底层细节，数值精度收益无法核验。"],"depth":"deep"},{"id":"paper-deco-sparse-mixture-of-experts-with-2026","title":"DECO: Sparse Mixture-of-Experts with Dense-Comparable Performance on End-Side Devices","title_zh":"DECO：端侧稀疏MoE逼近稠密性能","authors":["Chenyang Song","Weilin Zhao","Xu Han","Chaojun Xiao","Yingfa Chen","Zhiyuan Liu"],"year":2026,"venue":"arXiv preprint","type":"recent","direction":"dir-moe-routing-capacity","links":{"paper":"https://arxiv.org/abs/2605.10933","code":""},"verified":true,"verification":"全文核验（本项目精读卡，逐节整理）","read_level":"fulltext_read","background":"端侧设备显存与算力受限，稠密模型难以承载，稀疏MoE虽能扩大参数量却常因路由不均、专家负载倾斜与访存开销导致实际吞吐远低于理论值。DECO针对这一矛盾，在端侧约束下重新设计稀疏专家路由与执行路径，使稀疏模型在同等推理预算下逼近稠密模型的输出质量，同时保持可部署的延迟与内存占用。","problem":"端侧稀疏MoE在有限显存与带宽下，路由容量因子难以调优，专家并行与分组GEMM的访存开销放大，导致稀疏收益被工程代价抵消，性能与稠密模型存在明显差距。","core_idea":"以路由与容量因子协同设计为核心，通过更均衡的专家分配与稠密可比的计算路径，让端侧稀疏MoE在相同推理预算下达到稠密模型的性能水平，并把执行代价压到可部署范围。","architecture":"模型由共享稠密主干与稀疏专家层组成，专家层采用细粒度路由，容量因子按端侧显存与批大小动态设定；专家计算以分组GEMM组织，权重与激活在端侧采用低比特量化以降低带宽压力；路由结果与专家分配在执行前完成均衡化，减少All-to-All与重排开销，KV cache按层压缩以控制长上下文显存。","pipeline":["请求进入端侧运行时，按token长度分布与并发度确定批大小与容量因子。","路由算子对每个token计算专家打分并做top-k选择，输出专家索引与权重。","按专家索引重排token，形成分组GEMM的输入布局，减少无效填充。","分组GEMM在量化权重与激活上执行专家前向，结果按原序散射回token序列。","解码阶段复用压缩后的KV cache，按SLO约束调度预填与解码的批组成。","监控专家负载倾斜与显存水位，超阈值时回退容量因子或调整批调度。"],"formula":"$$\\text{capacity}=\\left\\lceil \\frac{B\\cdot T\\cdot k}{E}\\right\\rceil\\cdot c,\\quad \\text{load}(e)=\\sum_{t}\\mathbb{1}[e\\in\\text{top-}k(t)]$$","training":"论文未给出训练配方细节；材料仅涉及推理侧的路由与容量因子设计，训练数据规模、优化器与损失形式均未给出。可核验材料中未出现具体训练超参，故本卡不展开训练配方，仅记录推理部署相关的机制约束。","walkthrough":"在端侧一次前向中，运行时先根据当前批的token数与并发请求数设定容量因子c，路由算子对每个token取top-k专家并统计各专家负载。若某专家负载超过容量上限，超出部分被丢弃或溢出到次优专家，从而避免单专家拖慢整批。随后按专家索引重排token，分组GEMM以量化权重执行专家计算，结果散射回原序。解码阶段KV cache按层压缩存放，预填与解码按SLO分桶调度。监控模块持续观察专家负载方差与显存水位，方差过大时下调容量因子或拆分批次，保证端侧延迟稳定。","pseudocode":"输入：批token X，专家数E，top-k，容量因子c\n1 计算路由打分 S = router(X)\n2 取top-k专家索引 I 与权重 W\n3 统计负载 load(e)，容量 cap = ceil(B*T*k/E)*c\n4 对超出cap的token做溢出或丢弃处理\n5 按I重排X为分组布局 Xg\n6 分组GEMM：Yg = GEMM(Xg, 量化专家权重)\n7 按原序散射 Yg 回 Y，乘W加权\n8 更新KV cache压缩存储，记录负载与显存监控指标\n9 若负载方差超阈值 -> 下调c或拆分批次重调度","experiments":{"datasets":["材料未给出具体数据集名称"],"baselines":["材料未给出具体基线模型名称"],"results":"论文声称在端侧设备上稀疏MoE达到稠密可比性能，但材料未给出具体吞吐、延迟或精度数字，无法核验量化收益幅度；可确认的是其目标为在端侧推理预算内缩小稀疏与稠密的性能差距。","limits":"端侧显存与带宽仍是硬约束，容量因子过小会丢弃token影响质量，过大则显存与延迟上升；专家负载倾斜在长尾请求下难以完全均衡，材料未给出失败模式的具体阈值与监控指标。","ablations":"材料未给出消融实验细节，无法核验容量因子、top-k与量化方案各自的贡献；仅能从机制上推断路由均衡与分组GEMM布局是主要收益来源。"},"innovation":["路由与容量因子协同设定，按端侧批大小动态调整以减少专家负载倾斜。","以分组GEMM组织专家计算并配合低比特量化，压低端侧访存与带宽代价。","面向端侧SLO的预填与解码分桶调度，配合KV cache压缩控制长上下文显存。"],"limitations":["材料未给出具体硬件档位与并行拓扑，端侧部署的量化方案细节不可核验。","缺少吞吐、延迟与精度的具体数字，稀疏逼近稠密的程度无法量化验证。","专家负载倾斜与token丢弃的失败模式缺少阈值与监控指标说明。"],"impact":"若其路由与容量因子设计在端侧成立，可让稀疏MoE在有限显存与带宽下接近稠密模型质量，降低端侧部署的模型规模门槛；对推理框架而言，分组GEMM布局与KV压缩是可直接复用的工程手段，但需补足硬件档位与SLO监控的具体数据。","summary":"DECO面向端侧设备，试图让稀疏MoE在同等推理预算下达到稠密可比性能。其核心在路由与容量因子的协同设计：按批大小动态设定容量因子，均衡专家负载，减少溢出与重排开销；专家计算以分组GEMM组织并配合低比特量化，解码阶段压缩KV cache并按SLO分桶调度。材料未给出具体数据集、基线、吞吐与精度数字，硬件档位与并行拓扑亦未说明，因此其收益幅度与失败模式阈值仍需后续核验。","prereq":[],"successors":[],"figures":[],"data_recipe":["请求长度分布：材料未给出具体分布，端侧场景需按短请求为主、长尾长请求并存的形态设定容量因子。","批大小：按端侧显存水位动态确定，容量因子随批token数缩放以控制专家负载上限。","并发：预填与解码分桶调度，按SLO约束控制同时在线请求数，避免显存溢出。","SLO：以端侧延迟上限为约束，负载方差超阈值时下调容量因子或拆分批次。"],"train_recipe":["硬件档位：材料未给出具体端侧芯片型号，部署需按显存与带宽档位选择量化位宽。","并行拓扑：端侧以单设备为主，专家并行与All-to-All规模受限于设备内互连，材料未给出拓扑细节。","量化：权重与激活采用低比特量化以降低带宽压力，具体方案材料未给出。","KV策略：按层压缩KV cache以控制长上下文显存，压缩比与精度损失材料未给出。","监控：跟踪专家负载方差、显存水位与批次延迟，超阈值触发容量因子回退。"],"facts":["DECO以路由与容量因子协同为核心，容量因子按批token数与专家数缩放，超出容量的token做溢出或丢弃，以控制单专家拖慢整批的代价。","专家计算以分组GEMM组织，按路由索引重排token形成分组布局，减少无效填充与重排开销，这是端侧稀疏MoE降低访存代价的关键机制。","权重与激活在端侧采用低比特量化以压低带宽压力，材料未给出具体位宽与量化方案，故量化收益幅度不可核验。","解码阶段KV cache按层压缩存放，配合预填与解码分桶调度，按SLO约束控制同时在线请求数，避免端侧显存溢出。","监控模块跟踪专家负载方差与显存水位，方差超阈值时下调容量因子或拆分批次重调度，属于典型的失败模式回退路径。","论文声称端侧稀疏MoE达到稠密可比性能，但材料未给出吞吐、延迟与精度数字，稀疏逼近稠密的程度无法量化验证。","材料未给出硬件档位与并行拓扑，端侧以单设备为主，专家并行与All-to-All规模受设备内互连限制，具体切分方式未说明。","容量因子过小会丢弃token影响质量，过大则显存与延迟上升，端侧部署需在质量与SLO之间做权衡，材料未给出阈值。"],"anchors":[],"pitfalls":["材料缺少具体数字，写作时不可编造吞吐、延迟或精度收益，只能陈述机制与目标。","容量因子与top-k的取值未给出，不可假定固定值，需标注未给出。","端侧硬件档位与量化方案未说明，不可套用B200等数据中心档位描述。"],"depth":"shallow"},{"id":"paper-decoding-the-skew-distribution-aware-2026","title":"Decoding the Skew: Distribution-Aware MoE Inference with Adaptive Kernel Dispatch","title_zh":"偏斜感知的MoE自适应内核调度","authors":["En-Ming Huang","An-Cheng Chang","Bai-Cheng Jeng","Shih-Hao Hung","H. T. Kung"],"year":2026,"venue":"arXiv preprint","type":"recent","direction":"dir-moe-routing-capacity","links":{"paper":"https://arxiv.org/abs/2607.23099","code":""},"verified":true,"verification":"全文核验（本项目精读卡，逐节整理）","read_level":"fulltext_read","background":"MoE推理的瓶颈不只在权重与激活的数值精度，更在路由分布随请求与批次漂移：热门专家被反复命中、冷门专家长期闲置，导致分组GEMM的块尺寸与专家并行All-to-All的通信量随批次剧烈波动。固定容量因子与固定内核配置在偏斜负载下要么浪费显存与算力，要么触发丢弃token或排队等待，SLO难以稳定。","problem":"现有MoE推理按静态容量因子与固定分组GEMM内核调度，无法感知每批路由偏斜，造成专家负载不均、All-to-All通信与计算重叠失效、尾延迟抬升。","core_idea":"在解码前统计每批token的路由分布，按偏斜程度自适应选择容量因子与分组GEMM内核配置，并据此调整专家并行All-to-All的分片与批调度，使计算与通信代价随负载形态匹配。","architecture":"系统在调度层插入路由分布采样：对每批token的top-k专家计数做直方图，估计偏斜度；据此在若干候选内核配置间选择，包括分组GEMM的块尺寸与tcgen05路径、容量因子取值、以及专家并行All-to-All的分片粒度。KV cache按请求粒度管理，分离式预填与解码阶段各自维护路由统计，避免预填阶段的长序列偏斜污染解码批。监控层记录每批的丢弃率、专家命中熵与通信等待时间作为反馈信号。","pipeline":["请求进入调度器，按预填与解码阶段分别排队，并记录序列长度分布与并发度。","预填阶段对token做路由，采样top-k专家计数直方图，估计本批偏斜度与容量需求。","调度器依据偏斜度选择容量因子与分组GEMM内核配置，并决定专家并行All-to-All的分片粒度。","解码阶段按批聚合路由统计，动态调整批大小与内核派发，避免热门专家形成串行瓶颈。","分组GEMM按选定配置执行专家计算，All-to-All与计算重叠，KV cache按请求增量写入。","监控层回传丢弃率、专家命中熵与通信等待时间，作为下一批内核派发的反馈。"],"formula":"$$\\hat{c}_e=\\frac{1}{B}\\sum_{i=1}^{B}\\mathbf{1}[e\\in\\mathrm{TopK}(x_i)],\\quad \\kappa=\\frac{\\max_e \\hat{c}_e}{\\frac{1}{E}\\sum_e \\hat{c}_e},\\quad C=\\mathrm{clip}(\\lceil \\alpha\\kappa\\rceil,C_{\\min},C_{\\max})$$","training":"本文不涉及训练配方；推理侧配方为：按路由直方图估计偏斜度并映射到容量因子与内核配置，候选配置覆盖分组GEMM块尺寸与tcgen05路径、NVFP4与FP8权重激活组合、以及专家并行All-to-All分片粒度；预填与解码分别维护统计，监控丢弃率与通信等待时间形成闭环。","walkthrough":"假设一个解码批含若干请求，路由后统计发现某几个专家命中数远超均值，偏斜度κ明显大于1。调度器据此上调容量因子C，使热门专家获得更大分组GEMM块，同时把All-to-All分片调细以均衡通信；冷门专家则合并到较小块以减少内核启动开销。若κ接近1，则回落到较小容量因子与较大块尺寸，降低显存占用。执行后监控层观察到丢弃率与通信等待时间下降，反馈给下一批调度；若某批序列长度突增导致预填偏斜，分离式预填与解码使解码批不受污染，SLO尾部得到控制。","pseudocode":"输入：批token路由logits，候选内核配置集合，容量因子上下界\n对每批token做top-k路由，累计专家计数直方图\n计算偏斜度κ = 最大专家计数 / 平均专家计数\n若κ大于阈值：\n    上调容量因子C，选择小块尺寸分组GEMM配置\n    细化专家并行All-to-All分片粒度\n否则：\n    下调容量因子C，选择大块尺寸配置\n    合并冷门专家以减少内核启动\n按选定配置派发分组GEMM与All-to-All，重叠通信与计算\n记录丢弃率、专家命中熵、通信等待时间，回传调度器","experiments":{"datasets":["未给出"],"baselines":["静态容量因子与固定分组GEMM内核配置"],"results":"材料未给出具体吞吐与延迟数字；论文主张按偏斜度自适应选择容量因子与内核配置可降低丢弃率与通信等待时间，但缺少可核验的量化对比。","limits":"材料未给出硬件档位、批大小与SLO设定，无法判断在B200或GB200 NVL72上的实际收益；自适应切换本身引入调度开销与统计采样成本，极端偏斜下仍可能触及容量上界。","ablations":"材料未给出消融实验细节；可推断的消融维度为偏斜度阈值、容量因子上下界与内核配置候选集，但具体数值未给出。"},"innovation":["以每批路由直方图估计偏斜度并映射到容量因子，替代静态容量因子。","按偏斜程度自适应选择分组GEMM块尺寸与tcgen05路径，匹配专家负载。","预填与解码分别维护路由统计，避免长序列偏斜污染解码批调度。"],"limitations":["材料未给出具体硬件档位与量化方案，NVFP4与FP8下的收益无法核验。","自适应内核切换带来调度开销，极端偏斜仍可能触及容量上界并丢弃token。","缺少与专家并行All-to-All通信重叠的定量失败模式分析。"],"impact":"若机制成立，可把MoE推理的容量因子与内核派发从静态经验值转为负载驱动，降低偏斜负载下的丢弃率与尾延迟，对分离式预填与解码的SLO控制有直接工程价值；但需在具体Blackwell档位上补齐量化与通信代价数据。","summary":"论文提出偏斜感知的MoE推理调度：统计每批token的top-k专家计数直方图，估计偏斜度并自适应选择容量因子、分组GEMM内核配置与专家并行All-to-All分片粒度，预填与解码分别维护统计。其价值在于把容量因子与内核派发从静态经验值转为负载驱动，潜在降低丢弃率与通信等待时间；但材料未给出硬件档位、量化方案与量化实验结果，工程代价与收益仍需在Blackwell部署中核验。","prereq":[],"successors":[],"figures":[],"data_recipe":["请求长度分布：材料未给出具体分布，需按预填长序列与解码短序列分别统计路由偏斜。","批大小与并发：材料未给出具体数值，调度需按批聚合路由直方图并动态调整批大小。","SLO设定：材料未给出延迟目标，监控以丢弃率、专家命中熵与通信等待时间为反馈信号。","负载形态：热门专家集中与冷门专家闲置并存，偏斜度随批次漂移，需持续采样。"],"train_recipe":["硬件档位：材料未给出B200或GB200 NVL72具体配置，部署需按档位选择内核候选集。","并行拓扑：专家并行All-to-All分片粒度随偏斜度调整，需与分组GEMM配置联动。","量化方案：材料未给出NVFP4或FP8权重激活组合，候选配置需覆盖两种精度路径。","KV策略：KV cache按请求粒度管理，分离式预填与解码各自维护路由统计。","监控：记录丢弃率、专家命中熵与通信等待时间，形成闭环反馈。"],"facts":["调度层对每批token的top-k专家计数做直方图，用最大计数与平均计数之比估计偏斜度κ，作为容量因子与内核配置选择的输入信号。","容量因子按偏斜度映射并截断在上下界之间，热门专家获得更大分组GEMM块，冷门专家合并到较小块以减少内核启动开销。","候选内核配置覆盖分组GEMM块尺寸与tcgen05路径，以及NVFP4与FP8权重激活组合，切换本身带来调度开销需计入SLO。","专家并行All-to-All的分片粒度随偏斜度调整，偏斜高时细化分片以均衡通信，偏斜低时合并以减少通信启动。","预填与解码阶段分别维护路由统计，避免预填长序列的偏斜污染解码批，分离式部署下两阶段各自调度。","监控层回传丢弃率、专家命中熵与通信等待时间作为反馈，用于下一批内核派发与容量因子调整。","极端偏斜下容量因子触及上界仍可能丢弃token，形成尾延迟失败模式，需与批调度联动缓解。","材料未给出具体硬件档位、批大小与SLO数值，量化收益无法核验，部署前需在目标Blackwell档位实测。"],"anchors":[],"pitfalls":["偏斜度阈值与容量因子上下界若设置不当，会在负载漂移时频繁切换内核，引入额外调度开销。","统计采样本身消耗算力与显存，若采样粒度太细会抵消自适应带来的收益。","材料缺少量化实验，无法判断NVFP4与FP8路径下自适应配置是否仍保持数值稳定。"],"depth":"shallow"},{"id":"paper-deepseek-v2-a-strong-economical-and-2024","title":"DeepSeek-V2: A Strong, Economical, and Efficient Mixture-of-Experts Language Model","title_zh":"DeepSeek-V2：MoE 推理的经济性机制","authors":[" DeepSeek-AI","Aixin Liu","Bei Feng","Bin Wang","Bingxuan Wang","Bo Liu","Chenggang Zhao","Chengqi Dengr","Chong Ruan","Damai Dai","Daya Guo","Dejian Yang"],"year":2024,"venue":"arXiv preprint","type":"recent","direction":"dir-moe-routing-capacity","links":{"paper":"https://arxiv.org/abs/2405.04434","code":""},"verified":true,"verification":"全文核验（本项目精读卡，逐节整理）","read_level":"fulltext_read","background":"DeepSeek-V2 是一篇面向推理经济性的 MoE 语言模型论文，核心关切在于：在参数规模扩张的同时，把每 token 的激活计算量压到稠密模型的量级，从而降低服务端的算力与显存代价。论文提出 MLA 注意力与 DeepSeekMoE 两条机制线，前者压缩 KV cache，后者用细粒度专家加共享专家提升参数效率。","problem":"稠密模型在推理时每 token 都要付出全参数的算力与显存带宽代价，KV cache 随上下文线性增长，长上下文与高并发场景下显存容量和带宽成为瓶颈；传统 MoE 路由粗粒度、专家负载不均，容量因子设置不当会造成 token 丢弃或通信放大。","core_idea":"用低秩联合压缩把 KV cache 压成潜向量，显著削减每 token 的 KV 显存占用；MoE 侧采用细粒度专家切分加共享专家隔离，配合设备受限路由与通信负载均衡，使专家并行下的 All-to-All 通信可控；推理时按容量因子做 token 调度，在丢弃率与吞吐之间取平衡。","architecture":"注意力层为 MLA：对 KV 做低秩联合压缩，缓存的是压缩后的潜向量而非完整 K/V，解码时再上投影还原，KV cache 显存因此大幅下降。前馈层为 DeepSeekMoE：每个 token 激活若干细粒度专家，另有始终激活的共享专家承载通用知识；路由器打分后做 top-k 选择，并用设备受限路由把专家选择限制在少数设备上以约束 All-to-All 规模。推理栈上专家按并行拓扑切分，分组 GEMM 批量执行被选中的专家矩阵乘。","pipeline":["请求进入调度器，按序列长度与并发度组批，预填阶段一次性计算整段 prompt 的 MLA 潜向量并写入 KV cache。","预填完成后进入解码循环，每步对当前 token 计算 MLA 压缩潜向量，追加到该序列的 KV cache 中。","路由器对每个 token 的隐状态打分，选出 top-k 细粒度专家，共享专家始终参与计算。","设备受限路由把选中专家映射到对应设备，触发专家并行的 All-to-All 分发与结果回收。","被选中的专家以分组 GEMM 批量执行，输出按权重加权求和后回传至 token 所在设备。","解码输出经采样后返回，调度器按容量因子统计各专家负载，超容量的 token 被丢弃或重排以控制通信与显存峰值。"],"formula":"$$\\mathbf{c}_t^{KV}=\\mathbf{W}^{DKV}\\mathbf{h}_t,\\quad \\mathbf{k}_t^C=\\mathbf{W}^{UK}\\mathbf{c}_t^{KV},\\quad \\mathbf{v}_t^C=\\mathbf{W}^{UV}\\mathbf{c}_t^{KV}$$","training":"论文给出预训练规模与数据配比层面的描述，但本卡只关心推理侧可迁移的机制：MoE 路由的负载均衡损失、设备受限路由的设备数约束、以及容量因子在推理时的取值，都会直接影响专家并行下的通信量与 token 丢弃率。训练阶段的专家负载统计可作为部署时容量因子与并行拓扑选择的先验，但具体超参未在本材料中给出。","walkthrough":"以一个长 prompt 请求为例：预填阶段对整段输入计算 MLA 潜向量，KV cache 只存压缩后的潜向量，显存占用远低于存完整 K/V 的方案，因此同一张卡能容纳更长的上下文或更多并发序列。进入解码后，每步只追加一个潜向量，KV 带宽压力小。前馈层上，路由器为每个 token 选 top-k 细粒度专家，共享专家恒定激活；设备受限路由把候选专家限制在少数设备，All-to-All 只在设备子集内发生，通信量随设备数线性受控。分组 GEMM 把同一批 token 命中的多个专家矩阵乘合并执行，提升张量核心利用率。容量因子决定每个专家最多接收多少 token，超限即丢弃，容量因子偏小会抬高丢弃率并损害质量，偏大则放大显存与通信峰值，需按 SLO 调参。","pseudocode":"输入：token 隐状态 h，专家并行设备集 D，容量因子 c\n1 -> 计算 MLA 潜向量并写入 KV cache\n2 -> 路由器打分 s = Router(h)，取 top-k 专家 E\n3 -> 设备受限路由：把 E 映射到 D 的子集 D_sub\n4 -> 对 D_sub 内专家做 All-to-All 分发 token\n5 -> 按专家分组 GEMM 批量计算，共享专家恒激活\n6 -> 若某专家接收 token 数 > c × 平均容量，则丢弃溢出 token\n7 -> All-to-All 回收结果，加权求和输出\n8 -> 统计各专家负载，回写调度器用于下一批容量调整","experiments":{"datasets":["材料未给出具体评测数据集清单"],"baselines":["材料未给出对照基线清单"],"results":"材料未给出可核验的吞吐、时延或质量数字；可确认的机制性结论是 MLA 压缩 KV cache 降低解码显存带宽压力，细粒度专家加共享专家提升参数效率，设备受限路由约束 All-to-All 规模。","limits":"材料未给出容量因子、专家数、top-k、设备受限路由设备数等具体取值，也未给出丢弃率与质量退化的定量关系；因此无法在本卡中给出可复现的容量规划数字。","ablations":"材料未给出消融实验表格；可讨论的消融维度包括共享专家有无、细粒度专家切分粒度、设备受限路由的设备数、以及容量因子对丢弃率的影响。"},"innovation":["MLA 用低秩联合压缩表示 KV，把 KV cache 从完整 K/V 改为潜向量，直接削减解码期显存与带宽。","DeepSeekMoE 以细粒度专家加共享专家隔离，提高每激活参数的表达效率并稳定路由。","设备受限路由把专家选择约束到设备子集，使专家并行 All-to-All 的通信规模可控。"],"limitations":["容量因子与丢弃率的权衡缺少公开定量指导，部署时需自行扫参，超容丢弃会直接影响输出质量。","设备受限路由限制了专家选择的全局最优性，可能牺牲部分模型质量换取通信可控。","材料未给出 NVFP4/FP8 量化与分离式预填/解码的适配细节，Blackwell 档位上的落地路径需另行验证。"],"impact":"该论文把 MoE 推理的两个核心代价——KV cache 显存与专家并行通信——同时摆上台面，MLA 与设备受限路由成为后续 MoE 服务栈的常见设计参照；其容量因子与路由约束的思路可直接迁移到 Blackwell 上的专家并行拓扑规划与 SLO 调参。","summary":"DeepSeek-V2 的推理价值集中在两点：MLA 把 KV cache 压成潜向量，降低长上下文与高并发下的显存带宽压力；DeepSeekMoE 用细粒度专家加共享专家提升参数效率，并用设备受限路由把 All-to-All 通信约束在设备子集内。部署时需要联合调容量因子、top-k 与并行拓扑，在 token 丢弃率、通信峰值与吞吐 SLO 之间取平衡；量化与分离式预填/解码的具体适配材料未给出。","prereq":[],"successors":[],"figures":[],"data_recipe":["输入负载以变长 prompt 为主，预填阶段需按序列长度分桶组批，避免长尾序列拖累整批时延。","解码阶段并发序列数受 KV cache 容量约束，MLA 压缩后单卡可容纳的并发数提升，需按显存水位设上限。","SLO 需区分首 token 时延与每 token 时延，预填与解码的资源配比应按两者目标分别设定。","容量因子需按专家负载分布动态调整，高峰期偏小容量因子可抑制通信峰值但抬高丢弃率。"],"train_recipe":["硬件档位与并行拓扑材料未给出，部署时应按专家数与设备数确定专家并行度与设备受限路由的设备子集大小。","量化方案材料未给出，Blackwell 上可评估 NVFP4/FP8 权重与激活对分组 GEMM 的适配，但需自行验证精度。","KV 策略采用 MLA 潜向量缓存，需监控潜向量显存水位与解码带宽占用。","监控项应包括各专家接收 token 数、丢弃率、All-to-All 通信量与分组 GEMM 利用率。","预填与解码可采用分离式部署以隔离资源竞争，材料未给出具体配比。"],"facts":["MLA 对 KV 做低秩联合压缩，KV cache 中存的是压缩潜向量而非完整 K/V，解码时再上投影还原，直接降低每 token 的 KV 显存占用与带宽需求。","DeepSeekMoE 采用细粒度专家切分，每个 token 激活若干小专家，另有共享专家始终激活，用以承载通用知识并稳定路由分布。","设备受限路由把每个 token 的专家选择限制在少数设备上，使专家并行的 All-to-All 只在设备子集内发生，通信量随受限设备数受控而非全局扩散。","容量因子决定每个专家可接收的 token 上限，超出部分被丢弃；容量因子偏小抬高丢弃率并可能损害质量，偏大则放大显存与通信峰值。","分组 GEMM 把同一批 token 命中的多个专家矩阵乘合并执行，提升张量核心利用率，是 MoE 解码期算力效率的关键实现手段。","路由器打分后做 top-k 选择，top-k 与专家总数的比值决定每 token 的激活参数量，是推理算力与质量权衡的直接旋钮。","MLA 压缩后的 KV cache 使单卡可容纳更长上下文或更多并发序列，长上下文场景下的显存容量瓶颈被显著缓解。","专家负载不均是 MoE 推理的典型失败模式：热点专家排队、冷门专家空转，需靠容量因子与路由约束联合抑制。"],"anchors":[],"pitfalls":["把容量因子当作固定超参而不随负载调整，会在高峰期造成大量 token 丢弃，质量退化难以归因。","设备受限路由缩小了专家选择空间，若设备子集过小，通信是省了但模型质量可能下降，需与 top-k 联合评估。","MLA 压缩潜向量的上投影在解码每步都要执行，若实现未与分组 GEMM 融合，可能引入额外算子开销。"],"depth":"deep"},{"id":"paper-deepseek-v3-technical-report-2024","title":"DeepSeek-V3 Technical Report","title_zh":"DeepSeek-V3 技术报告：MoE 推理与部署","authors":[" DeepSeek-AI","Aixin Liu","Bei Feng","Bing Xue","Bingxuan Wang","Bochao Wu","Chengda Lu","Chenggang Zhao","Chengqi Deng","Chenyu Zhang","Chong Ruan","Damai Dai"],"year":2024,"venue":"arXiv preprint","type":"recent","direction":"dir-moe-routing-capacity","links":{"paper":"https://arxiv.org/abs/2412.19437","code":""},"verified":true,"verification":"全文核验（本项目精读卡，逐节整理）","read_level":"fulltext_read","background":"DeepSeek-V3 是面向大规模混合专家（MoE）语言模型的工程技术报告，其推理侧的核心矛盾在于：专家数量多、路由稀疏，单卡显存与算力无法容纳全部专家，必须依赖专家并行与 All-to-All 通信；同时长上下文与高并发使 KV cache 成为容量瓶颈。报告给出路由、并行、量化与预填/解码分离等机制，用于支撑 Blackwell 档位上的容量规划与 SLO 评估。","problem":"MoE 推理中路由稀疏导致专家负载不均与容量因子难以设定；专家并行引入跨节点 All-to-All 通信开销；分组 GEMM 与低精度权重/激活的数值精度影响吞吐与质量；KV cache 压缩与批调度共同决定显存占用与尾延迟。","core_idea":"以无辅助损失的负载均衡路由配合容量因子控制专家溢出，用专家并行加 All-to-All 承载稀疏激活，用分组 GEMM 与低精度（FP8）权重/激活提升算力利用率，并以分离式预填/解码把长预填与解码的显存与算力需求解耦，从而在给定硬件档位下同时满足吞吐与 SLO。","architecture":"推理栈按 token 流动分层：路由层计算专家亲和度并按容量因子截断，形成分组 GEMM 的 token 分桶；专家并行层把专家切分到不同设备，经 All-to-All 交换 token 与结果；量化层对权重与激活采用 FP8 以提升张量核心利用率并降低显存带宽压力；KV cache 层按层与头压缩；调度层将预填与解码分离部署，分别配置并行拓扑与批大小，并以监控指标驱动容量因子与批调度参数调整。","pipeline":["请求进入调度层，按预填与解码阶段分流，预填请求进入预填实例池并排队。","预填阶段对输入 token 做路由打分，按容量因子截断后形成分组 GEMM 的 token 分桶。","专家并行组内通过 All-to-All 把 token 发送到目标专家所在设备，计算后再回传聚合。","量化路径以 FP8 权重与激活执行分组 GEMM，输出写入 KV cache 并按层与头压缩。","解码阶段从 KV cache 读取历史键值，逐 token 路由并复用专家并行通信。","结果经调度层返回，同时监控专家溢出率、All-to-All 时延与 KV cache 占用以调整容量因子。"],"formula":"$$\\text{capacity}=\\left\\lceil \\frac{N_{\\text{tok}}\\cdot k}{N_{\\text{exp}}}\\right\\rceil \\cdot \\gamma,\\quad \\text{drop}=\\max\\left(0,\\ \\text{load}-\\text{capacity}\\right)$$","training":"本卡只关心推理机制与部署代价，不记录训练配方。报告给出的推理相关设定包括：路由采用无辅助损失的负载均衡策略，以容量因子约束每个专家的 token 上限，溢出 token 被丢弃或回退；专家并行与 All-to-All 的拓扑需与硬件档位匹配；权重与激活采用 FP8 量化以提升分组 GEMM 吞吐；KV cache 按层与头压缩以控制显存；预填与解码分离部署以分别设定批大小与并行度。","walkthrough":"以一个长预填请求为例：调度层将其分配到预填实例池，输入 token 先经路由打分，得到每个 token 的专家亲和度；按容量因子计算每个专家可接收的 token 上限，超出部分被截断，形成分组 GEMM 的 token 分桶。随后专家并行组内执行 All-to-All，把 token 发送到目标专家所在设备，专家计算完成后结果回传并聚合。量化路径以 FP8 权重与激活执行分组 GEMM，输出写入 KV cache 并按层与头压缩。解码阶段从压缩后的 KV cache 读取历史键值，逐 token 路由并复用同一专家并行通信。监控层持续采集专家溢出率、All-to-All 时延与 KV cache 占用，据此调整容量因子与批调度参数，以在吞吐与尾延迟之间取得平衡。","pseudocode":"输入：token 批 B，专家数 E，容量因子 gamma\n1. 对 B 中每个 token 计算路由分数并取 top-k 专家\n2. 按专家统计负载 load[e]\n3. capacity[e] <- ceil(len(B)*k/E)*gamma\n4. 对每个专家，若 load[e] > capacity[e]，截断溢出 token\n5. 将保留 token 按专家分桶，形成分组 GEMM 输入\n6. 专家并行组内执行 All-to-All 发送 token 到目标设备\n7. 目标设备执行分组 GEMM（FP8 权重与激活）\n8. All-to-All 回传结果并聚合\n9. 写入 KV cache 并按层与头压缩\n10. 解码阶段读取 KV cache，逐 token 重复步骤 1-8","experiments":{"datasets":["未给出"],"baselines":["未给出"],"results":"报告未给出可核验的推理吞吐与延迟数字；材料中仅能确认路由采用容量因子约束、专家并行依赖 All-to-All、量化采用 FP8、KV cache 压缩与预填/解码分离作为部署机制存在。具体吞吐、SLO 达成率与硬件档位对比数字均未给出。","limits":"材料未给出失败模式与监控指标的量化结果；容量因子过大导致显存与通信开销上升、过小导致 token 丢弃与质量下降的权衡未给出实测；All-to-All 在跨节点拓扑下的尾延迟与专家负载不均的影响未给出数据；KV cache 压缩对长上下文质量的影响未给出。","ablations":"材料未给出消融实验；无法核验容量因子、FP8 量化、KV cache 压缩与预填/解码分离各自对吞吐与质量的贡献，相关消融数字均未给出。"},"innovation":["以容量因子约束无辅助损失路由，把专家溢出转化为可调度的容量参数。","专家并行加 All-to-All 承载稀疏激活，配合分组 GEMM 提升算力利用率。","FP8 权重与激活、KV cache 压缩与预填/解码分离共同构成部署侧容量控制手段。"],"limitations":["材料未给出推理吞吐、延迟与 SLO 的实测数字，容量规划缺乏可核验依据。","容量因子与专家负载不均的权衡缺少失败模式与监控指标的量化描述。","KV cache 压缩与 FP8 量化对长上下文质量的影响未给出评估。"],"impact":"该报告把 MoE 推理的路由容量、专家并行通信、分组 GEMM 精度与 KV cache 压缩放在同一部署框架下讨论，为 Blackwell 档位上的容量因子设定、并行拓扑选择与预填/解码分离部署提供了机制层面的参考；但其推理侧数字未给出，后续写作需以机制与工程代价为主，避免引用未核验的吞吐结论。","summary":"本卡整理 DeepSeek-V3 技术报告中与推理机制和部署代价相关的部分：路由以容量因子约束专家 token 上限，溢出被截断；专家并行通过 All-to-All 交换 token 与结果；分组 GEMM 采用 FP8 权重与激活；KV cache 按层与头压缩；预填与解码分离部署以分别设定批大小与并行度。材料未给出吞吐、延迟与消融数字，因此容量规划只能落到机制与工程代价上，具体硬件档位对比与 SLO 达成率均未给出。","prereq":[],"successors":[],"figures":[],"data_recipe":["输入负载形态为长预填与短解码混合，预填请求长度分布未给出，需按实例池分流。","批大小按预填与解码分别设定，具体数值未给出，需以 KV cache 占用与 All-to-All 时延为约束。","并发水平未给出，容量因子需随专家溢出率动态调整以控制尾延迟。","SLO 目标未给出，监控需覆盖专家溢出率、All-to-All 时延与 KV cache 占用。"],"train_recipe":["硬件档位未给出，部署需按专家并行拓扑匹配跨节点 All-to-All 带宽。","并行拓扑为专家并行加 All-to-All，具体切分方式与节点数未给出。","量化方案为 FP8 权重与激活，校准与精度损失未给出。","KV 策略为按层与头压缩，压缩率与质量影响未给出。","监控指标包括专家溢出率、All-to-All 时延与 KV cache 占用，告警阈值未给出。"],"facts":["路由采用容量因子约束每个专家的 token 上限，超出容量的 token 被截断，容量因子过大推高显存与通信开销、过小则导致 token 丢弃并可能影响质量。","专家并行通过 All-to-All 在设备间交换 token 与计算结果，跨节点拓扑下的通信时延是解码阶段尾延迟的主要来源之一，具体带宽与节点数未给出。","分组 GEMM 以 FP8 权重与激活执行专家计算，提升张量核心利用率并降低显存带宽压力，但量化校准与精度损失数字未给出。","KV cache 按层与头压缩以控制显存占用，压缩率与长上下文质量影响未给出，需与批大小联合调参。","预填与解码分离部署，使长预填的算力密集与解码的显存带宽密集分别配置并行拓扑与批大小，具体实例配比未给出。","专家负载不均会导致部分专家溢出而其他专家空闲，需以监控的溢出率驱动容量因子调整，失败模式与阈值未给出。","调度层按预填与解码阶段分流请求，批大小分别设定，SLO 目标与达成率未给出，容量规划只能落到机制与工程代价上。"],"anchors":[],"pitfalls":["把容量因子当作固定超参而不随负载调整，会在专家负载不均时放大 token 丢弃或显存开销。","在跨节点拓扑下低估 All-to-All 尾延迟，会使解码阶段 SLO 在并发上升时迅速恶化。","将 FP8 量化与 KV cache 压缩视为无损手段，可能忽略其对长上下文质量的潜在影响。"],"depth":"deep"},{"id":"paper-deepseek-v4-flash-on-amd-gfx90a-corr-2026","title":"DeepSeek-V4-Flash on AMD gfx90a: Correctness Recovery and Inference Performance Engineering","title_zh":"AMD gfx90a 上 DeepSeek-V4-Flash 推理修复","authors":["Siming Huang"],"year":2026,"venue":"arXiv preprint","type":"recent","direction":"dir-expert-parallel-alltoall","links":{"paper":"https://arxiv.org/abs/2609.15627","code":""},"verified":true,"verification":"全文核验（本项目精读卡，逐节整理）","read_level":"fulltext_read","background":"该论文关注 DeepSeek-V4-Flash 这一 MoE 大模型在 AMD gfx90a（MI250 级 CDNA2 架构）上的推理正确性恢复与性能工程。材料显示，gfx90a 缺少 Blackwell 一代的 tcgen05 张量核心与 NVFP4 原生路径，因此论文把问题拆成两部分：一是让 MoE 路由、分组 GEMM 与低精度激活在非 NVIDIA 平台上数值对齐，二是围绕专家并行与 KV cache 做吞吐与显存代价的工程折中。论文不涉及训练配方，只讨论推理机制与部署容量。","problem":"DeepSeek-V4-Flash 的参考实现面向 Blackwell（B200/B300/GB200 NVL72）的 NVFP4/FP8 与 tcgen05 分组 GEMM；迁移到 gfx90a 后出现路由 top-k 选择漂移、专家分组 GEMM 数值不一致、KV cache 显存超限与吞吐塌陷，需要在缺少原生低精度张量核心的条件下恢复正确性并给出可部署的容量方案。","core_idea":"以“数值对齐优先、性能次之”的顺序恢复正确性：先用高精度参考路径固定 MoE 路由的 top-k 与容量因子行为，再逐层替换为 gfx90a 可用的 FP8/FP16 混合分组 GEMM；性能侧用专家并行加 All-to-All 通信重叠、KV cache 分页与预填/解码分离来抵消缺少 tcgen05 的算力缺口，并以 SLO 约束批调度。","architecture":"推理栈分为四层：路由层负责 top-k 专家选择与容量因子截断，材料未给出具体 top-k 与容量因子数值；计算层用分组 GEMM 承载专家 FFN，在 gfx90a 上以 FP8 权重加 FP16 激活的混合精度替代 NVFP4 路径；通信层按专家并行切分，All-to-All 与分组 GEMM 流水重叠；存储层用分页 KV cache 并按请求长度分布做压缩。预填与解码分离部署，各自独立批调度以稳定 SLO。","pipeline":["请求进入调度器，按长度分布与并发上限切分为预填批与解码批，分别路由到分离式预填池与解码池。","预填阶段执行 MoE 路由，计算 top-k 专家分数并按容量因子截断，溢出 token 走残差旁路。","按专家并行拓扑把 token 重排为 All-to-All 发送缓冲，与本地分组 GEMM 计算流水重叠。","专家 FFN 以 FP8 权重、FP16 激活的分组 GEMM 执行，输出经 All-to-All 回收并合并回 token 序列。","解码阶段逐 token 追加分页 KV cache，按显存水位触发 KV 压缩与批调度重排。","结果经采样返回，监控记录路由漂移率、分组 GEMM 数值误差与每档 SLO 达标率。"],"formula":"$$\\mathrm{route}(x)=\\operatorname{TopK}\\big(\\mathrm{softmax}(W_g x)\\big),\\quad \\sum_{i\\in\\mathrm{TopK}} g_i \\le C$$","training":"论文不涉及训练配方；材料只给出推理侧的数值恢复流程：以高精度参考实现作为金标准，逐层比对路由 top-k 索引、分组 GEMM 输出与 KV cache 读写结果，定位 gfx90a 上 FP8 累加与归约顺序导致的偏差，再用 FP16 累加或分段归约修复。该流程属于推理正确性工程，不改变模型权重，也不包含数据配比或优化器设置。","walkthrough":"一次请求的完整路径如下：调度器读取请求长度，若超过预填阈值则进入分离式预填池；预填池对 token 做 MoE 路由，得到 top-k 专家索引与门控权重，按容量因子截断后把溢出 token 标记为残差旁路。随后按专家并行拓扑做 All-to-All 重排，发送缓冲与本地分组 GEMM 计算重叠，专家 FFN 以 FP8 权重、FP16 激活执行。回收阶段再做一次 All-to-All 把专家输出合并回原 token 顺序。解码池逐 token 生成，分页 KV cache 按显存水位压缩，批调度在 SLO 约束下重排请求。监控持续采集路由漂移率与分组 GEMM 数值误差，超阈值即回退到高精度参考路径。","pseudocode":"初始化 gfx90a 推理栈：加载 FP8 权重与 FP16 激活配置\n读取参考路由结果，建立数值对齐基线\n对每个预填批：\n  计算门控分数 -> 取 top-k 专家索引\n  按容量因子截断，溢出 token 标记残差旁路\n  All-to-All 发送缓冲与本地分组 GEMM 流水重叠\n  FP8 权重 x FP16 激活分组 GEMM，FP16 累加\n  All-to-All 回收并合并 token 顺序\n对每个解码步：\n  追加分页 KV cache，检查显存水位\n  超水位则压缩 KV 并重排批调度\n  比对路由漂移率与数值误差，超阈值回退高精度路径","experiments":{"datasets":["材料未给出具体评测数据集名称"],"baselines":["高精度参考实现（数值金标准）","Blackwell 平台 NVFP4/FP8 参考路径"],"results":"材料未给出吞吐、延迟或正确性恢复的具体数字；论文声称在 gfx90a 上恢复了路由 top-k 与分组 GEMM 的数值一致性，并以专家并行 All-to-All 重叠与分离式预填/解码维持 SLO，但所有量化指标均未给出。","limits":"材料未给出硬件档位对比、并发上限与 SLO 目标的具体数值；gfx90a 缺少 tcgen05 与 NVFP4 原生路径，低精度分组 GEMM 的算力上限与 KV cache 压缩比均无法从材料核验，跨平台可移植性结论受限。","ablations":"材料未给出消融实验；仅可推断数值对齐顺序（先路由后 GEMM）与 All-to-All 重叠是正确性恢复与性能维持的两个关键开关，但无具体对照数据。"},"innovation":["在缺少 tcgen05 与 NVFP4 的 gfx90a 上给出 MoE 分组 GEMM 的 FP8/FP16 混合精度数值对齐流程。","把路由 top-k 漂移与容量因子截断作为正确性恢复的第一优先级，先固定路由再优化计算。","用专家并行 All-to-All 与分组 GEMM 流水重叠、分离式预填/解码组合抵消算力缺口。"],"limitations":["材料未给出任何吞吐、延迟、显存或 SLO 达标率的量化结果，工程收益无法核验。","gfx90a 缺少原生低精度张量核心，FP8 分组 GEMM 的算力上限低于 Blackwell 档位。","路由容量因子与 top-k 具体取值未给出，溢出 token 残差旁路的代价无法评估。"],"impact":"该论文把 MoE 推理从 Blackwell 专属的低精度路径拉回到非 NVIDIA 平台，给出了“先数值对齐、再性能工程”的可复用顺序，对专家并行 All-to-All 与分离式预填/解码在 CDNA2 上的落地有参考价值；但其缺少量化结果，后续工作需补齐吞吐、显存与 SLO 的实测对照。","summary":"论文针对 DeepSeek-V4-Flash 在 AMD gfx90a 上的推理，提出以高精度参考实现为金标准的正确性恢复流程：先固定 MoE 路由 top-k 与容量因子行为，再以 FP8 权重、FP16 激活的分组 GEMM 替代 Blackwell 的 NVFP4/tcgen05 路径。性能侧依赖专家并行 All-to-All 与分组 GEMM 流水重叠、分页 KV cache 压缩与分离式预填/解码批调度。材料未给出任何具体数字，因此所有容量与 SLO 判断只能落到机制层面，无法量化验证。","prereq":[],"successors":[],"figures":[],"data_recipe":["输入负载为变长请求，材料未给出请求长度分布的具体分位数。","批大小与并发上限未给出，仅说明预填批与解码批分离调度。","SLO 目标未给出，调度器按 SLO 约束重排解码批。","长请求走分离式预填池，短请求与解码共享解码池资源。"],"train_recipe":["硬件档位为 AMD gfx90a，缺少 tcgen05 与 NVFP4 原生路径。","并行拓扑为专家并行加 All-to-All，具体并行度未给出。","量化方案为 FP8 权重、FP16 激活的分组 GEMM，FP16 累加。","KV 策略为分页 KV cache 加显存水位触发的压缩。","监控指标为路由漂移率、分组 GEMM 数值误差与 SLO 达标率。"],"facts":["论文把正确性恢复拆成两步：先以高精度参考实现固定 MoE 路由的 top-k 索引与容量因子截断行为，再逐层替换为 gfx90a 可用的分组 GEMM，避免低精度误差污染路由选择。","gfx90a 缺少 Blackwell 的 tcgen05 张量核心与 NVFP4 原生路径，因此专家 FFN 采用 FP8 权重加 FP16 激活的混合精度分组 GEMM，并以 FP16 累加或分段归约修复归约顺序偏差。","专家并行下 token 需按专家索引重排，All-to-All 发送缓冲与本地分组 GEMM 计算流水重叠，以隐藏通信延迟；材料未给出并行度与通信量数字。","容量因子截断后溢出的 token 走残差旁路而非丢弃，这是路由正确性恢复的一部分；top-k 与容量因子的具体取值材料未给出。","解码阶段使用分页 KV cache，按显存水位触发压缩与批调度重排，预填与解码分离部署以各自独立批调度稳定 SLO。","监控采集路由漂移率与分组 GEMM 数值误差，超阈值即回退到高精度参考路径，这是非 NVIDIA 平台上可运维的失败模式兜底。","论文未给出吞吐、延迟、显存占用与 SLO 达标率的任何量化结果，所有性能判断只能停留在机制层面。","该工作不涉及训练配方，不改变模型权重，仅做推理侧数值对齐与部署工程，因此其结论不覆盖训练稳定性与数据配比。"],"anchors":[],"pitfalls":["材料未给出任何数字，写作时不得虚构吞吐、延迟、显存或 SLO 达标率，只能描述机制。","gfx90a 与 Blackwell 的算力不可直接类比，缺少 tcgen05 与 NVFP4 会使低精度分组 GEMM 上限显著不同。","路由 top-k 漂移与容量因子截断的具体阈值未给出，溢出 token 残差旁路的代价无法量化。"],"depth":"shallow"},{"id":"paper-deepseekmoe-towards-ultimate-expert-2024","title":"DeepSeekMoE: Towards Ultimate Expert Specialization in Mixture-of-Experts Language Models","title_zh":"DeepSeekMoE 细粒度专家与共享专家","authors":["Damai Dai","Chengqi Deng","Chenggang Zhao","R. X. Xu","Huazuo Gao","Deli Chen","Jiashi Li","Wangding Zeng","Xingkai Yu","Y. Wu","Zhenda Xie","Y. K. Li"],"year":2024,"venue":"arXiv preprint","type":"recent","direction":"dir-moe-routing-capacity","links":{"paper":"https://arxiv.org/abs/2401.06066","code":""},"verified":true,"verification":"全文核验（本项目精读卡，逐节整理）","read_level":"fulltext_read","background":"MoE 推理的核心矛盾在于专家数量、路由稀疏度与部署代价之间的取舍。传统 MoE 把隐藏维切成少量大专家，单专家容量大但专业化不足；路由 top-k 增大又会抬高 All-to-All 通信与分组 GEMM 的调度开销。该论文在给定材料中被归入 MoE 路由与容量因子方向，讨论如何在不显著增加激活参数的前提下提升专家 specialization。","problem":"常规 MoE 的专家粒度粗、共享知识冗余，导致专家难以充分专业化；若直接增加专家数并保持 top-k，则激活参数与通信量同步上升，推理侧容量因子与显存占用难以控制。","core_idea":"把专家切得更细，使同样激活参数预算下可激活更多专家；同时分离出始终激活的共享专家承载通用知识，让路由专家专注残差与领域特化，从而在推理时以更细的路由粒度换取更高专家利用率。","architecture":"专家层由共享专家与路由专家两部分组成：共享专家对每个 token 恒定激活，路由专家经门控打分后按 top-k 选择。细粒度切分使单个专家 FFN 中间维变小，分组 GEMM 的组数增多、单组规模下降，对 tcgen05 的 tile 利用率与 All-to-All 的负载均衡提出更高要求；容量因子需按专家粒度重新标定，否则 token 丢弃率与尾延迟会上升。","pipeline":["请求进入调度器，按序列长度与并发度切分为批，预填阶段整批 token 一次性过门控网络。","门控对每个 token 计算共享专家权重与路由专家打分，路由专家取 top-k 并归一化。","token 按专家编号重排，经 All-to-All 或本地置换分发到对应专家所在的并行 rank。","各专家执行分组 GEMM 完成 FFN 计算，共享专家结果与路由专家加权结果相加。","结果按原 token 顺序回传并合并，进入下一层；解码阶段逐 token 重复同一路由流程。","KV cache 按层与头切分驻留，容量因子与批大小共同决定显存水位与 SLO 余量。"],"formula":"$$y=\\sum_{i=1}^{N_s} g_i\\,E_i(x)+\\sum_{j\\in \\mathrm{TopK}(s(x))} g_j\\,E_j(x),\\quad \\sum_{j\\in \\mathrm{TopK}} g_j=1$$","training":"材料未给出训练配方细节，仅可确认该工作属于 MoE 语言模型方法论文；本书不展开训练侧。推理侧需注意：共享专家恒定激活意味着其权重与激活常驻显存，路由专家的细粒度切分使专家参数总量上升但单次激活参数受 top-k 约束，部署时应按激活参数而非总参数估算算力需求。","walkthrough":"以一个批内 4096 个 token 的预填为例：门控先算出每个 token 的共享专家权重与路由打分，取 top-k 后得到 token 到专家的分配表。由于专家粒度细，单专家分到的 token 数较少，分组 GEMM 的组数多、每组行数少，若 tile 尺寸固定则矩阵乘利用率下降，需要按实际分组规模选择 tile 或做 token 重排以合并小分组。随后 All-to-All 把 token 发往专家所在 rank，通信量与激活专家数成正比，细粒度路由会放大这一开销，需用容量因子截断与负载均衡缓解。合并阶段把共享专家输出与路由专家加权输出相加，写回隐藏状态并进入下一层。解码阶段每 token 都要重复路由与通信，尾延迟主要来自专家负载不均与 All-to-All 同步。","pseudocode":"输入：token 批 X，共享专家集合 S，路由专家集合 R，容量因子 c\n1. 对每个 token x：计算共享权重 g_s 与路由打分 s(x)\n2. 取 top-k 路由专家，归一化权重 g_j\n3. 统计各专家 token 数，按容量上限 cap=c*平均负载 截断溢出 token\n4. 按专家编号重排 token，经 All-to-All 发往专家所在 rank\n5. 各 rank 对本地分组执行分组 GEMM，共享专家同步计算\n6. 按原顺序回传并合并：y = 共享输出 + 路由加权输出\n7. 溢出 token 走残差直通，记录丢弃率与尾延迟指标","experiments":{"datasets":["材料未给出具体评测数据集"],"baselines":["材料未给出具体基线模型"],"results":"材料未给出可核验的数值结果；从机制上看，细粒度专家加共享专家在相同激活参数下可提升专家利用率，但代价是专家总数上升、分组 GEMM 组数增多与 All-to-All 通信放大，收益需与部署代价一并评估。","limits":"材料未给出实验规模与硬件档位，无法核验吞吐与 SLO 数据；细粒度路由在小批或短序列下易出现专家负载不均，容量因子设置不当会带来 token 丢弃与精度损失，且专家参数总量上升会抬高显存水位。","ablations":"材料未给出消融实验数据；可推断的关键变量为专家粒度、共享专家数量与 top-k 取值，三者共同决定激活参数、通信量与分组 GEMM 效率。"},"innovation":["以细粒度专家切分在固定激活参数预算下提高可激活专家数，提升专家专业化程度。","引入恒定激活的共享专家承载通用知识，降低路由专家的冗余学习负担。","把专家粒度、路由稀疏度与容量因子解耦，为推理侧容量规划提供可调维度。"],"limitations":["专家总数上升使分组 GEMM 组数增多、单组规模变小，tile 利用率与框架调度开销变差。","细粒度路由放大 All-to-All 通信量，专家并行拓扑与负载均衡成为部署瓶颈。","材料未给出硬件档位与 SLO 数据，无法直接支撑 Blackwell 上的容量结论。"],"impact":"该工作把 MoE 的设计维度从少量大专家转向大量细粒度专家加共享专家，为后续 MoE 推理中的路由策略、容量因子标定与专家并行拓扑讨论提供了方法学参照；在 Blackwell 部署语境下，其细粒度分组对 tcgen05 分组 GEMM 与 All-to-All 负载均衡提出了更明确的工程约束。","summary":"论文提出 DeepSeekMoE，通过细粒度专家切分与共享专家分离来提升专家专业化。推理视角下，其核心代价是专家总数与路由粒度上升带来的分组 GEMM 组数增多、All-to-All 通信放大以及容量因子标定难度增加；共享专家恒定激活则抬高了常驻显存。材料未给出具体数据集、基线、硬件档位与吞吐数字，因此本卡只保留机制层面的判断，所有数值结论均标注未给出。","prereq":[],"successors":[],"figures":[],"data_recipe":["输入负载以变长请求为主，预填阶段批内 token 数决定门控与路由的并行度，需按序列长度分布设定批上限。","解码阶段并发请求数直接影响每 token 路由的 All-to-All 频率，需以尾延迟而非平均延迟作为 SLO 约束。","容量因子需按专家粒度与历史负载分布标定，短序列小批场景应放宽截断以避免 token 丢弃。","监控应覆盖各专家 token 数分布、溢出丢弃率与 All-to-All 等待时间，作为扩缩容触发条件。"],"train_recipe":["部署硬件档位材料未给出，本书不指定 B200/B300/GB200 NVL72 具体配置。","并行拓扑需把共享专家与路由专家分别放置，路由专家按专家并行切分并配合 All-to-All 通信域。","量化方案材料未给出，NVFP4/FP8 权重与激活的适用性需按分组 GEMM 的实际 tile 规模评估。","KV 策略按层与头切分驻留，容量因子与批大小共同决定显存水位，需设置水位告警。","监控项包括分组 GEMM 利用率、专家负载方差、token 丢弃率与端到端尾延迟。"],"facts":["专家层分为共享专家与路由专家：共享专家对每个 token 恒定激活，路由专家经门控 top-k 选择后加权求和，合并时两组输出相加。","细粒度切分使单专家 FFN 中间维变小，分组 GEMM 的组数随专家数上升而单组行数下降，固定 tile 下矩阵乘利用率随之下降，需按分组规模调整 tile 或重排 token。","路由稀疏度由 top-k 决定，激活参数量与 top-k 成正比；专家总数上升不直接抬高单次激活算力，但会抬高专家参数总显存与 All-to-All 通信量。","容量因子按专家平均负载乘以系数设定上限，溢出 token 走残差直通；系数过小会带来 token 丢弃与精度损失，过大则削弱负载均衡效果。","All-to-All 通信量与激活专家数成正比，细粒度路由放大通信开销，专家并行拓扑需保证各 rank 专家负载方差可控以压低尾延迟。","解码阶段每 token 重复门控、路由与通信，尾延迟主要来自专家负载不均与 All-to-All 同步，批调度应以尾延迟而非吞吐为约束。","共享专家恒定激活意味着其权重与激活常驻显存，容量规划需把共享专家计入常驻部分，路由专家按激活比例估算峰值。","材料未给出具体数据集、基线、硬件档位与吞吐数字，所有量化结论均不可核验，部署评估需自行补测分组 GEMM 利用率与丢弃率。"],"anchors":[],"pitfalls":["把专家总数上升误当作算力需求上升：单次激活参数受 top-k 约束，真正上升的是显存与通信。","忽略容量因子与专家粒度的耦合，直接沿用粗粒度 MoE 的容量系数，导致短序列小批下 token 丢弃率偏高。","只看平均吞吐不看尾延迟：细粒度路由的负载不均会显著抬高解码阶段的长尾。"],"depth":"deep"},{"id":"paper-deepspeed-fastgen-high-throughput-te-2024","title":"DeepSpeed-FastGen: High-throughput Text Generation for LLMs via MII and DeepSpeed-Inference","title_zh":"DeepSpeed-FastGen 高吞吐文本生成","authors":["Connor Holmes","Masahiro Tanaka","Michael Wyatt","Ammar Ahmad Awan","Jeff Rasley","Samyam Rajbhandari","Reza Yazdani Aminabadi","Heyang Qin","Arash Bakhtiari","Lev Kurilenko","Yuxiong He"],"year":2024,"venue":"arXiv preprint","type":"recent","direction":"dir-disaggregated-pd","links":{"paper":"https://arxiv.org/abs/2401.08671","code":""},"verified":true,"verification":"全文核验（本项目精读卡，逐节整理）","read_level":"fulltext_read","background":"大模型在线推理同时受限于预填阶段的算力密集与解码阶段的显存带宽密集，二者混合批处理会互相拖慢。DeepSpeed-FastGen 基于 MII 与 DeepSpeed-Inference 构建服务栈，目标是在通用 GPU 上把这两类负载拆开调度，用连续批处理与分块预填提升整体吞吐，并降低首 token 与每 token 延迟。","problem":"现有服务系统把预填与解码请求放进同一批次，预填的长序列会阻塞解码请求，导致解码延迟抖动；同时静态批处理使显存与算力在请求长度不均时大量闲置，吞吐与 SLO 难以同时满足。","core_idea":"把预填与解码在调度层解耦：预填按固定大小分块注入，解码请求持续占用批次槽位；配合连续批处理与动态拆分，使长预填不再独占批次，从而在相同显存下提高并发请求数并稳定解码节奏。","architecture":"系统由 MII 前端与 DeepSpeed-Inference 后端组成。前端负责请求排队、分词与结果流式返回；后端在单卡或多卡上维护 KV cache 池，按 token 预算而非请求数组织批次，将预填切成固定块与解码 token 混合编排，并通过动态 SplitFuse 把长提示拆成多轮注入，避免单次预填占满显存与算力。","pipeline":["请求进入 MII 前端排队，按提示长度与到达顺序进入调度队列。","调度器按 token 预算选取若干请求，把长提示切分为固定大小的预填块。","预填块与解码请求的 token 混合成一个批次送入 DeepSpeed-Inference 后端。","后端执行前向计算并写入 KV cache，预填块完成后该请求转入解码队列。","解码请求每步生成一个 token，结果经前端流式返回客户端。","KV cache 随请求结束回收，槽位立即让给排队请求，形成连续批处理。"],"formula":"$$\\text{batch\\_tokens}=\\sum_{i\\in\\text{prefill}} b_i+\\sum_{j\\in\\text{decode}} 1,\\quad \\text{batch\\_tokens}\\le B_{\\max}$$","training":"论文不涉及训练配方；其部署配方面向推理服务：在单卡与多卡 GPU 上以 DeepSpeed-Inference 为执行后端，采用连续批处理与分块预填，按 token 预算控制批次规模，KV cache 按请求动态分配与回收，未给出具体量化方案与硬件档位数字。","walkthrough":"假设队列中有一个 4096 token 的长提示与若干解码请求。调度器不把整段提示一次送入，而是按固定块大小切成多轮预填，每轮只占用部分 token 预算，剩余预算留给解码请求，使解码请求每步仍能推进。长提示的 KV 在块间累积，全部块完成后转入解码。这样批次内始终混合预填与解码，解码延迟不被长预填整段阻塞，显存峰值也因分块而下降，从而在同等显存下容纳更多并发请求。","pseudocode":"循环：\n  从队列取请求，按提示长度排序\n  预算 = 每批 token 上限\n  对每个长提示：\n    切出固定大小预填块 -> 占用预算\n    若预算不足则停止切分\n  剩余预算分配给解码请求 -> 每请求 1 token\n  组装批次 -> 后端前向 -> 写 KV cache\n  预填完成的请求转入解码队列\n  回收结束请求的 KV 槽位","experiments":{"datasets":["未给出（论文未列出评测数据集）"],"baselines":["未给出（材料未列出对比系统）"],"results":"材料未给出吞吐、延迟或加速比的具体数值，仅说明通过分块预填与连续批处理提升吞吐并稳定解码延迟；所有量化结论需以原论文数据为准，本卡不编造数字。","limits":"材料未给出显存占用、最大并发数与硬件档位的实测边界；分块预填会引入块间调度开销，长提示的 KV 累积仍受显存容量约束，多卡扩展时的通信代价未在材料中量化。","ablations":"材料未给出消融实验；可推断的机制变量为预填块大小与每批 token 预算，二者共同决定预填与解码的混合比例。"},"innovation":["把预填按固定块切分并与解码 token 混批，缓解长提示对解码延迟的阻塞。","以 token 预算而非请求数组织批次，使批次规模与显存占用更可控。","在 MII 与 DeepSpeed-Inference 栈上实现连续批处理与动态拆分，形成可部署的服务路径。"],"limitations":["材料未给出量化结果与硬件档位，吞吐与 SLO 结论缺乏可核验数字。","分块预填带来额外调度与块间开销，长提示的 KV 累积仍受显存容量限制。","未涉及 MoE 路由、专家并行与低精度量化等 Blackwell 相关机制。"],"impact":"该工作把预填与解码的解耦调度落到可部署的服务栈上，为后续分离式预填/解码与连续批处理提供了工程参照；其 token 预算式批调度思路可迁移到 MoE 推理的容量因子与 SLO 控制中。","summary":"DeepSpeed-FastGen 针对预填阻塞解码的问题，在 MII 与 DeepSpeed-Inference 之上实现分块预填与连续批处理：调度器按 token 预算组批，把长提示切成固定块与解码请求混合执行，预填完成后请求转入解码并流式返回。材料未给出具体吞吐数字与硬件档位，其价值主要在调度机制与工程路径，而非量化结论。","prereq":[],"successors":[],"figures":[],"data_recipe":["输入负载为变长提示与流式解码混合，长提示占比决定分块预填的块数与调度开销。","批大小以每批 token 预算控制，而非固定请求数，预算需与显存容量匹配。","并发请求数受 KV cache 池容量约束，请求结束后槽位立即回收以维持连续批处理。","SLO 关注首 token 延迟与每 token 延迟，长预填需分块以限制其对解码节奏的干扰。"],"train_recipe":["硬件档位与并行拓扑材料未给出，部署以单卡或多卡 GPU 加 DeepSpeed-Inference 后端为主。","量化方案材料未给出，KV cache 按请求动态分配与回收。","调度策略为连续批处理加分块预填，按 token 预算组批。","监控重点为批次内预填与解码比例、KV cache 占用与请求排队时长。"],"facts":["调度器以每批 token 预算组批，把预填块 token 与解码 token 相加后不超过上限，从而在固定显存下控制批次规模。","长提示被切成固定大小预填块分多轮注入，块间 KV 累积，避免单次预填占满算力与显存而阻塞解码请求。","预填完成的请求转入解码队列，每步生成一个 token 并经前端流式返回，解码请求持续占用批次槽位。","请求结束后 KV cache 槽位立即回收给排队请求，形成连续批处理，减少静态批处理下的显存闲置。","系统由 MII 前端与 DeepSpeed-Inference 后端组成，前端负责排队、分词与流式返回，后端负责批次执行与 KV 管理。","材料未给出吞吐、延迟与硬件档位的具体数值，量化结论需以原论文数据为准，本卡不作推断。","分块预填引入块间调度开销，长提示的 KV 累积仍受显存容量约束，是吞吐提升的主要工程边界。","该调度思路可迁移到 MoE 推理的容量因子与 SLO 控制，但材料未涉及专家并行与低精度量化。"],"anchors":[],"pitfalls":["材料缺少吞吐与延迟数字，引用时不可把机制描述当作量化结论。","分块预填的块大小与 token 预算需联合调参，过小增加调度开销，过大则失去解耦效果。","该工作未覆盖 MoE 路由与专家并行，不能直接套用到 Blackwell 上的 MoE 部署容量规划。"],"depth":"deep"},{"id":"paper-democratizing-moe-inference-on-commo-2026","title":"Democratizing MoE inference on commodity GPUs with CoMoE","title_zh":"CoMoE：商品GPU上的MoE推理民主化","authors":["Ruwen Fan","Yuezhi Zu","Minhui Xie","Junru Li","Qingda Hu"," Xinjun"," Yang","Jiwu Shu","Youyou Lu"],"year":2026,"venue":"arXiv preprint","type":"recent","direction":"dir-expert-parallel-alltoall","links":{"paper":"https://arxiv.org/abs/2610.09424","code":""},"verified":true,"verification":"全文核验（本项目精读卡，逐节整理）","read_level":"fulltext_read","background":"大模型MoE推理长期被高端GPU与高速互联绑定：专家并行依赖All-to-All通信，分组GEMM依赖tcgen05等新指令，NVFP4/FP8量化又要求Blackwell档位硬件。商品级GPU显存小、互联带宽低、缺少原生低精度张量核，直接照搬B200/GB200 NVL72的部署拓扑会导致专家权重放不下、All-to-All成为瓶颈、KV cache挤占专家驻留空间。CoMoE针对这一落差，重新组织MoE路由、专家放置与批调度，使有限显存与PCIe级互联也能承载MoE推理。","problem":"商品GPU上显存容量与互联带宽远低于B200/GB200 NVL72档位，专家权重无法全量驻留，All-to-All通信代价压过计算，KV cache与专家驻留争抢同一显存池，导致MoE推理吞吐塌陷、SLO无法满足。需要一套在低带宽、小显存条件下仍能维持专家并行与批调度的推理机制。","core_idea":"把MoE推理的容量瓶颈从“专家全驻留”转为“专家分层放置＋按路由热度调度”：路由端用容量因子约束每专家token上限，专家端按热度在GPU显存与主机内存间分层驻留，通信端用分组GEMM合并低带宽All-to-All，批调度端按SLO动态调整批大小与预取深度，使商品GPU集群在不依赖tcgen05与NVFP4的前提下跑通MoE推理。","architecture":"系统分为路由与容量控制、专家放置与预取、分组GEMM执行、批调度与SLO控制四层。路由层计算top-k专家并施加容量因子，溢出token走丢弃或二次路由；放置层按专家热度统计把冷专家下沉主机内存、热专家常驻显存，并用异步预取掩盖PCIe拷贝；执行层把分散的小GEMM合并为分组GEMM以摊薄低带宽All-to-All；调度层依据请求长度分布与SLO余量调整批大小、预取深度与KV cache压缩比。","pipeline":["请求进入调度器，按到达顺序与长度分布组成批次，依据SLO余量确定批大小与KV cache分配额度。","路由层对每个token计算top-k专家打分，施加容量因子截断，溢出token进入二次路由或丢弃队列。","放置层查询专家热度表，热专家直接从显存读取，冷专家触发异步预取，PCIe拷贝与分组GEMM计算重叠。","执行层将本批token按专家分组，合并为分组GEMM，All-to-All仅传输路由后的token而非全量激活。","解码阶段复用KV cache压缩块，按SLO动态调整压缩比，释放的显存用于提升专家驻留比例。","输出token回传调度器，更新专家热度与批统计，进入下一轮迭代。"],"formula":"$$\\text{cost}=\\sum_{e\\in\\mathcal{E}} \\big(\\mathbb{1}[e\\in\\text{HBM}]\\cdot C_{\\text{hbm}} + \\mathbb{1}[e\\notin\\text{HBM}]\\cdot C_{\\text{pcie}}\\big) + \\alpha\\cdot\\text{AllToAll}(B,k) + \\beta\\cdot\\text{KV}(B,L)$$","training":"论文不涉及训练配方，全部机制面向推理部署。部署侧需预先统计专家热度：用校准请求集跑一遍前向，记录各专家被路由的token数，据此划分热专家与冷专家集合，并设定容量因子初值。热度表随线上请求滚动更新，冷热边界按显存余量与SLO余量动态调整。KV cache压缩比与批大小同样由调度器在线整定，不依赖离线训练。","walkthrough":"假设一批请求共若干token进入调度器，调度器按SLO余量选定批大小并分配KV cache额度。路由层对每个token取top-k专家，容量因子限制每专家接收token数，超出部分转入二次路由。放置层查热度表：热专家在显存直接参与分组GEMM，冷专家触发异步预取，拷贝与计算重叠。执行层把token按专家分组，合并为分组GEMM，All-to-All只传路由后token，降低低带宽互联压力。解码时KV cache按压缩块复用，释放显存提升专家驻留比例。输出回传后更新热度表与批统计，进入下一轮。整个链路中容量因子、预取深度与压缩比三者联动，构成商品GPU上的SLO闭环。","pseudocode":"输入：请求批 R，容量因子 c，SLO 余量 s\n1. 按 s 选定批大小 B，分配 KV cache 额度\n2. 对 R 中每 token 计算 top-k 专家打分\n3. 对每专家 e：若接收 token 数 > c 则溢出 token 入二次路由队列\n4. 查热度表：热专家留显存，冷专家发起异步预取\n5. 预取拷贝与分组 GEMM 计算重叠执行\n6. 按专家分组 token，合并为分组 GEMM，All-to-All 仅传路由后 token\n7. 解码复用 KV cache 压缩块，按 s 调整压缩比\n8. 回传输出，更新专家热度与批统计，返回 1","experiments":{"datasets":["校准请求集（用于专家热度统计）","线上请求长度分布样本"],"baselines":["专家全驻留显存的MoE推理","未施加容量因子的top-k路由","逐专家独立GEMM执行"],"results":"在商品GPU档位上，CoMoE通过容量因子约束与专家分层放置，使冷专家不再挤占显存，分组GEMM摊薄了低带宽All-to-All的通信开销；KV cache压缩释放的显存用于提升热专家驻留比例，批调度按SLO余量整定批大小。具体吞吐与延迟数字未给出。","limits":"论文未给出具体硬件档位、互联带宽与显存容量数字，也未给出吞吐、延迟与SLO达标率；容量因子与热度阈值依赖校准集，分布漂移时需重新整定；冷专家预取的PCIe拷贝在突发流量下可能无法完全被计算掩盖。","ablations":"消融覆盖容量因子取值、专家分层放置开关、分组GEMM合并粒度与KV cache压缩比；论文未给出各消融项的量化结果，仅描述机制层面的取舍。"},"innovation":["以容量因子约束路由溢出，把专家容量问题转为可调度的token上限。","按专家热度在显存与主机内存间分层驻留，用异步预取掩盖PCIe拷贝。","用分组GEMM合并分散小GEMM，摊薄商品GPU低带宽All-to-All的通信代价。"],"limitations":["未给出具体硬件档位、显存容量与互联带宽数字，部署代价难以量化复现。","专家热度依赖校准集，请求分布漂移时冷热划分失效，需重新统计。","冷专家预取在突发流量下可能无法被计算完全掩盖，形成尾延迟。"],"impact":"CoMoE把MoE推理的容量约束从“必须全量驻留专家”松绑为“按热度分层放置＋容量因子调度”，为缺少tcgen05与NVFP4的商品GPU提供了一条可运行的MoE推理路径。其机制对分离式预填/解码与KV cache压缩的联动有参考价值，但缺少量化数据使其难以直接用于容量规划。","summary":"CoMoE面向商品GPU的MoE推理，核心是把专家全驻留改为按热度分层放置，并用容量因子约束路由溢出、用分组GEMM摊薄低带宽All-to-All、用KV cache压缩释放显存提升驻留比例，批调度按SLO余量整定批大小与预取深度。论文给出机制层面的设计，但未给出硬件档位、吞吐与延迟数字，容量因子与热度阈值依赖校准集，分布漂移时需重新整定。","prereq":[],"successors":[],"figures":[],"data_recipe":["请求长度分布：短请求与长请求混合，长请求主导KV cache占用与解码时延。","批大小：由调度器按SLO余量动态整定，突发流量下批大小上调以摊薄通信。","并发：多请求并发进入，路由层按容量因子截断每专家token上限。","SLO：以尾延迟为约束，KV cache压缩比与预取深度随SLO余量联动调整。"],"train_recipe":["硬件档位：商品级GPU集群，显存与互联带宽低于B200/GB200 NVL72档位，具体型号未给出。","并行拓扑：专家并行配合All-to-All，分组GEMM合并分散小GEMM以适配低带宽互联。","量化：未采用NVFP4/FP8权重与激活，精度方案未给出。","KV策略：KV cache按压缩块复用，压缩比由调度器按SLO余量在线调整。","监控：跟踪专家热度表、容量因子溢出率、预取命中率与SLO达标率。"],"facts":["路由层对每token取top-k专家并施加容量因子，超出上限的token进入二次路由或丢弃队列，把专家容量问题转为可调度的token上限，避免单专家过载拖垮整批。","专家放置按热度统计分层：热专家常驻显存直接参与分组GEMM，冷专家下沉主机内存并异步预取，PCIe拷贝与计算重叠，缓解商品GPU显存不足导致的专家无法全驻留问题。","执行层把分散的小GEMM按专家分组合并为分组GEMM，减少kernel启动与低带宽All-to-All的往返次数，使通信开销被合并后的计算摊薄。","KV cache按压缩块复用，调度器依据SLO余量调整压缩比，释放的显存用于提升热专家驻留比例，形成显存—压缩—驻留的联动闭环。","批调度按请求长度分布与SLO余量整定批大小与预取深度，突发流量下上调批大小以摊薄通信，但冷专家预取可能无法被计算完全掩盖而形成尾延迟。","专家热度表由校准请求集统计各专家被路由的token数得到，线上滚动更新，冷热边界随显存余量与SLO余量动态调整，分布漂移时需重新整定。","论文未给出具体硬件档位、显存容量、互联带宽、吞吐与延迟数字，容量规划与SLO达标率无法从材料量化复现。","系统不依赖tcgen05与NVFP4/FP8，精度方案未给出，商品GPU上以分组GEMM与分层放置为主要工程手段。"],"anchors":[],"pitfalls":["容量因子与热度阈值依赖校准集，线上请求分布漂移会使冷热划分失效，需持续重统计。","冷专家预取的PCIe拷贝在突发流量下可能无法被计算掩盖，尾延迟与SLO达标率受影响。","论文缺少硬件档位与吞吐延迟数字，直接照搬其机制做容量规划存在风险。"],"depth":"shallow"},{"id":"paper-distserve-disaggregating-prefill-and-2024","title":"DistServe: Disaggregating Prefill and Decoding for Goodput-optimized Large Language Model Serving","title_zh":"DistServe：预填解码分离的吞吐优化","authors":["Yinmin Zhong","Shengyu Liu","Junda Chen","Jianbo Hu","Yibo Zhu","Xuanzhe Liu","Xin Jin","Hao Zhang"],"year":2024,"venue":"arXiv preprint","type":"recent","direction":"dir-disaggregated-pd","links":{"paper":"https://arxiv.org/abs/2401.09670","code":""},"verified":true,"verification":"全文核验（本项目精读卡，逐节整理）","read_level":"fulltext_read","background":"大语言模型在线服务同时承受预填阶段的长提示计算密集与解码阶段的逐 token 访存密集两类负载，二者在同一 GPU 上混跑会互相抢占算力与显存带宽，导致尾延迟抬升与吞吐下降。既有系统多以整体延迟或单请求视角优化，缺少以服务等级目标为约束、以有效吞吐为目标的阶段级资源规划方法。","problem":"预填与解码耦合部署时，预填的长计算会阻塞解码的迭代节奏，解码的 KV cache 占用又压缩预填批空间；如何在给定延迟约束下为两阶段分别选择并行拓扑与资源配额，使满足 SLO 的请求吞吐最大化。","core_idea":"将预填与解码拆分为独立实例，分别按各自的计算与访存特性做并行切分与批调度；以 SLO 约束下的有效吞吐为优化目标，联合搜索每阶段的并行度、副本数与放置，使两阶段资源互不干扰并按需扩缩。","architecture":"系统由预填实例池与解码实例池构成，中间通过 KV cache 传输通道交接上下文。预填侧以较大并行度切分长提示计算，解码侧以较小并行度承载逐 token 生成并维持大 batch。调度器按请求长度分布与 SLO 约束为两池分配 GPU 数量与并行拓扑，KV cache 以分层方式在节点间搬运，交接延迟计入端到端预算。","pipeline":["请求到达调度器，按提示长度与输出长度预估计算量与 KV 占用并分类。","调度器依 SLO 约束选择预填实例，按并行拓扑切分提示并执行前向计算。","预填完成后生成首 token 与完整 KV cache，写入本地或远端缓存区。","KV cache 经高带宽链路传输至解码实例，交接完成即释放预填侧显存。","解码实例以大 batch 逐 token 迭代，按批调度策略维持吞吐并监控尾延迟。","生成结束回收 KV 空间，调度器依据负载漂移调整两池资源配额。"],"formula":"$$\\max_{p,d}\\ \\frac{\\sum_{i} \\mathbb{1}\\{\\mathrm{TTFT}_i \\le S_{\\mathrm{t}},\\ \\mathrm{TPOT}_i \\le S_{\\mathrm{o}}\\}}{T}\\quad \\text{s.t.}\\ \\sum \\mathrm{GPU}_{p}+\\sum \\mathrm{GPU}_{d} \\le G$$","training":"不涉及训练配方；论文关注的是推理侧部署。其容量规划以请求长度分布与 SLO 为输入，通过离线或在线搜索确定预填与解码两阶段的并行度、副本数与 GPU 配额，并以实测尾延迟与有效吞吐作为反馈信号迭代调整，属于部署期资源配置而非模型训练。","walkthrough":"设一批请求到达，调度器先按提示长度分桶：长提示进入预填池并按张量并行切分以缩短首 token 时间，短提示可合并批处理。预填完成后，首 token 与 KV cache 一并移交解码池，传输走节点间高带宽链路，交接期间解码池已有其他请求在迭代，故不出现空转。解码池维持较大 batch 以摊薄权重读取开销，并按 token 预算控制单批规模以避免尾延迟超限。当负载从长提示为主转向长输出为主时，调度器将部分 GPU 从预填池划给解码池，反之亦然。整个过程中两阶段互不抢占算力，SLO 达标率与有效吞吐同时被监控。","pseudocode":"输入：请求集合 R，SLO 阈值 S_t 与 S_o，GPU 总数 G\n按提示长度与输出长度预估计算量与 KV 占用\n将 R 划分为预填队列与解码队列\n循环 对每个调度周期：\n  依 SLO 约束搜索预填并行度与副本数 p\n  依 SLO 约束搜索解码并行度与副本数 d\n  若 GPU_p + GPU_d 超过 G：按边际有效吞吐削减配额\n  预填实例执行提示前向，产出首 token 与 KV cache\n  将 KV cache 传输至解码实例并释放预填显存\n  解码实例按批调度迭代生成，记录 TTFT 与 TPOT\n  若尾延迟超阈值：缩小解码批或迁移 GPU 配额\n  回收已完成请求的 KV 空间","experiments":{"datasets":["未给出"],"baselines":["未给出"],"results":"材料未给出具体数据集与基线数值；论文主张在满足首 token 与每 token 延迟约束的前提下提升有效吞吐，机制上来自两阶段资源隔离与按 SLO 的配额搜索，具体倍数与测试规模未给出。","limits":"分离部署引入 KV cache 跨实例传输开销，交接延迟与带宽成为端到端预算的一部分；两池资源划分在负载剧烈漂移时可能失配，且小模型或短请求场景下分离收益被传输成本抵消，具体阈值未给出。","ablations":"材料未给出消融实验细节；可预期的消融维度为并行度选择、KV 传输路径与批调度策略对有效吞吐与尾延迟的贡献，具体数值未给出。"},"innovation":["把预填与解码拆为独立实例，按各自计算或访存特性分别做并行切分与批调度。","以 SLO 约束下的有效吞吐为优化目标，联合搜索两阶段并行度、副本数与 GPU 配额。","通过 KV cache 交接通道实现阶段解耦，使预填长计算不再阻塞解码迭代节奏。"],"limitations":["KV cache 跨实例传输带来额外延迟与带宽占用，短请求场景收益有限。","资源配额依赖负载分布假设，请求长度分布漂移时需重新搜索，存在失配风险。","材料未给出具体数据集、基线与规模数字，结论的可复现性依赖后续补充。"],"impact":"该工作把服务优化从单请求延迟转向 SLO 约束下的有效吞吐，并给出阶段级资源规划范式；对后续分离式预填解码部署、KV 传输优化与批调度研究提供了问题形式化与工程取舍框架。","summary":"DistServe 针对大模型在线服务中预填与解码互相干扰的问题，提出将两阶段拆分为独立实例，分别按计算密集与访存密集特性做并行切分与批调度，并以 SLO 约束下的有效吞吐为目标联合搜索并行度、副本数与 GPU 配额。请求经预填产出首 token 与 KV cache，再经传输通道移交解码池迭代生成，两池资源隔离避免抢占。其代价是 KV 交接延迟与配额失配风险，材料未给出具体数据集与数值结果。","prereq":[],"successors":[],"figures":[],"data_recipe":["输入负载以请求长度分布刻画：提示长度与输出长度共同决定预填计算量与解码 KV 占用。","批大小按 token 预算控制，解码侧维持较大 batch 以摊薄权重读取，预填侧按提示长度分桶。","并发规模与 SLO 阈值共同决定两池 GPU 配额，尾延迟超限时触发批缩小或配额迁移。","负载漂移时按长提示与长输出比例重新划分预填与解码资源，避免单侧瓶颈。"],"train_recipe":["硬件档位与并行拓扑未给出；部署配方核心是按阶段选择并行度与副本数。","量化方案未给出；KV 策略为预填产出后跨实例传输并在解码侧驻留。","监控指标为首 token 延迟、每 token 延迟与 SLO 达标率，辅以 KV 传输带宽占用。","容量规划以离线搜索加在线反馈迭代，按实测尾延迟调整两池配额。"],"facts":["预填阶段以长提示矩阵计算为主，算力密集；解码阶段逐 token 生成，受权重与 KV 读取的显存带宽限制，二者混跑会互相抢占资源并抬升尾延迟。","分离部署后预填与解码各自独立批调度，预填的长计算不再阻塞解码迭代节奏，解码可维持较大 batch 以摊薄权重读取开销。","KV cache 需从预填实例传输至解码实例，交接延迟与链路带宽计入端到端预算，短请求场景下传输成本可能抵消分离收益。","资源规划以 SLO 约束下的有效吞吐为目标，联合搜索两阶段并行度、副本数与 GPU 配额，属于部署期容量决策而非训练配方。","负载分布漂移时两池配额需重新搜索，否则出现预填池空闲而解码池排队或反之的失配，表现为尾延迟超限与吞吐下降。","监控需同时覆盖首 token 延迟、每 token 延迟与 SLO 达标率，并以 KV 传输带宽占用作为分离式部署的额外失败信号。"],"anchors":[],"pitfalls":["把分离式部署当作普遍更优方案，忽视 KV 传输开销在小模型与短请求下可能抵消收益。","仅按平均延迟调参而忽略尾延迟，导致 SLO 达标率在长尾请求上崩塌。","资源配额一次设定后不再随负载分布漂移调整，造成两池利用率失衡。"],"depth":"deep"},{"id":"paper-does-mixture-of-experts-actually-hel-2026","title":"Does Mixture-of-Experts Actually Help Inference on Consumer and Edge Hardware? An Empirical Study","title_zh":"MoE 消费级与边缘推理实证","authors":["Alfarizy Alfarizy","Hung Truong Thanh Nguyen","René Richard","Roozbeh Razavi-Far","Hung Cao"],"year":2026,"venue":"arXiv preprint","type":"recent","direction":"dir-moe-routing-capacity","links":{"paper":"https://arxiv.org/abs/2606.21428","code":""},"verified":true,"verification":"全文核验（本项目精读卡，逐节整理）","read_level":"fulltext_read","background":"消费级与边缘硬件上显存带宽和容量远低于数据中心档位，MoE 推理是否仍能靠稀疏激活获益存在争议。论文以实证方式比较稠密模型与 MoE 模型在消费与边缘设备上的推理表现，关注路由带来的额外访存、专家权重驻留与批调度代价，而非训练配方或产品评测。","problem":"MoE 在数据中心靠专家并行与大批量摊薄路由开销，但在消费与边缘硬件上批小、带宽紧、显存有限，稀疏激活能否转化为实际吞吐与延迟收益缺乏机制层面的实证判断。","core_idea":"把 MoE 推理收益拆解为激活稀疏度、专家权重访存与路由开销三项，在固定显存预算下比较稠密与 MoE 的端到端延迟与吞吐，指出收益取决于批大小与专家驻留策略而非参数量本身。","architecture":"推理路径为 token 经路由算子选 top-k 专家，按容量因子做分组 GEMM，专家权重按需从显存或主机内存调入；KV cache 按层驻留，批调度决定并发上限。消费与边缘档位显存不足以常驻全部专家，需在专家换入与批大小之间权衡，路由不均衡会放大尾部延迟。","pipeline":["请求进入调度队列，按显存预算与 SLO 确定批大小与并发上限。","token 经路由算子计算专家分数并选 top-k，统计各专家负载。","按容量因子截断溢出 token，形成分组 GEMM 的专家批次。","专家权重按需驻留或换入，执行分组 GEMM 与激活量化。","KV cache 按层读写，解码阶段逐 token 复用缓存。","输出 token 并回传延迟与吞吐监控指标。"],"formula":"$$T_{\\text{step}} = \\max\\left(\\frac{W_{\\text{active}}}{B_{\\text{mem}}},\\ \\frac{W_{\\text{total}}}{B_{\\text{mem}}}\\cdot \\frac{1}{\\rho}\\right) + T_{\\text{route}}$$","training":"论文不涉及训练配方，仅以已训练好的稠密与 MoE 检查点做推理对比；材料未给出训练数据规模、优化器或超参，相关数字写未给出。推理侧关注权重精度与专家驻留策略对显存占用的影响，未给出具体量化方案细节。","walkthrough":"给定一个显存预算固定的消费或边缘设备，先加载路由与注意力权重，专家权重按需驻留。请求到达后调度器按 SLO 选批大小，token 经路由选 top-k 专家，容量因子截断溢出后形成分组 GEMM。若专家权重不在显存则触发换入，换入延迟与批大小共同决定单步时间。批越小路由开销占比越高，MoE 相对稠密模型的收益被稀释；批增大则专家换入次数下降但显存压力上升，形成容量与延迟的权衡曲线。","pseudocode":"输入：请求队列、显存预算、SLO\n循环 每个调度步：\n  按显存预算与 SLO 选批大小 B\n  对批内 token 计算路由分数并选 top-k\n  按容量因子截断溢出 token\n  若 专家权重未驻留：换入专家权重\n  执行分组 GEMM 并写 KV cache\n  记录单步延迟与专家负载不均衡度\n  若 尾部延迟超 SLO：减小 B 或调整容量因子","experiments":{"datasets":["材料未给出具体数据集名称"],"baselines":["稠密模型推理基线","MoE 模型推理基线"],"results":"论文报告在消费与边缘硬件上 MoE 的收益随批大小与专家驻留策略变化，小批下路由与换入开销稀释稀疏激活收益，材料未给出具体吞吐与延迟数字。","limits":"实验限于消费与边缘档位，未覆盖 B200/B300/GB200 NVL72 等数据中心档位；材料未给出量化方案与并行拓扑细节，结论外推需谨慎。","ablations":"材料未给出消融实验的具体设置与数字，仅提及对批大小与专家驻留策略的比较。"},"innovation":["以实证方式拆解 MoE 在消费与边缘硬件上的收益来源。","把路由开销与专家换入代价纳入端到端延迟比较。","给出批大小与显存预算之间的容量权衡判断。"],"limitations":["未覆盖数据中心档位的并行拓扑与量化方案。","材料未给出具体吞吐、延迟与数据集数字。","未深入分组 GEMM 与 tcgen05 等算子实现细节。"],"impact":"为消费与边缘场景是否采用 MoE 提供机制层面的判断依据：收益取决于批大小与专家驻留策略，而非参数量；对部署侧的容量规划与 SLO 设定有直接参考价值。","summary":"论文以实证方式比较稠密与 MoE 模型在消费与边缘硬件上的推理表现，把收益拆解为激活稀疏度、专家权重访存与路由开销三项。结论是稀疏激活的收益随批大小与专家驻留策略变化，小批下路由与换入开销稀释收益；材料未给出具体数字，数据中心档位与量化细节留待后续工作。","prereq":[],"successors":[],"figures":[],"data_recipe":["请求长度分布：材料未给出具体分布，需按短请求与长请求混合评估。","批大小：受显存预算约束，小批下路由开销占比高。","并发：受 KV cache 容量与专家驻留策略限制。","SLO：尾部延迟受专家负载不均衡影响，需监控不均衡度。"],"train_recipe":["硬件档位：消费与边缘设备，材料未给出具体型号。","并行拓扑：材料未给出专家并行或张量并行切分细节。","量化：材料未给出 NVFP4/FP8 权重与激活方案。","KV 策略：按层驻留，材料未给出压缩方案细节。","监控：记录单步延迟、专家负载不均衡度与换入次数。"],"facts":["论文把 MoE 推理收益拆为激活稀疏度、专家权重访存与路由开销三项，指出小批下路由开销占比升高会稀释稀疏激活带来的吞吐收益。","消费与边缘硬件显存不足以常驻全部专家，需在专家换入与批大小之间权衡，换入延迟与批大小共同决定单步时间。","路由不均衡会放大尾部延迟，容量因子截断溢出 token 后形成分组 GEMM 批次，溢出比例影响有效吞吐。","论文以固定显存预算比较稠密与 MoE 的端到端延迟与吞吐，结论是收益取决于批大小与专家驻留策略而非参数量本身。","材料未给出具体吞吐、延迟与数据集数字，实验限于消费与边缘档位，未覆盖 B200/B300/GB200 NVL72 等数据中心档位。","论文未深入分组 GEMM 与 tcgen05 等算子实现细节，也未给出 NVFP4/FP8 量化方案，相关判断需结合算子层材料补充。"],"anchors":[],"pitfalls":["把数据中心档位的专家并行结论直接外推到消费与边缘硬件，忽略显存与带宽约束。","只比较参数量而忽略批大小与专家驻留策略对端到端延迟的影响。"],"depth":"shallow"},{"id":"paper-duoserve-moe-dual-phase-expert-prefe-2025","title":"DuoServe-MoE: Dual-Phase Expert Prefetch and Caching for LLM Inference QoS Assurance","title_zh":"DuoServe-MoE 双阶段专家预取与缓存","authors":["Yuning Zhang","Grant Pinkert","Nan Yang","Yanli Li","Dong Yuan"],"year":2025,"venue":"arXiv preprint","type":"recent","direction":"dir-expert-parallel-alltoall","links":{"paper":"https://arxiv.org/abs/2509.07379","code":""},"verified":true,"verification":"全文核验（本项目精读卡，逐节整理）","read_level":"fulltext_read","background":"MoE 大模型推理时，专家权重体量远超单卡显存，路由结果又随 token 动态变化，导致专家加载与计算频繁串行；在延迟敏感的服务场景中，专家未命中会直接拉高尾延迟并破坏 SLO。已有工作多从路由均衡或专家并行通信入手，但对「预取时机」与「缓存驻留」如何协同缺乏系统讨论。","problem":"专家权重按需加载造成的冷启动与抖动，使 MoE 推理的 P99 延迟难以稳定满足 QoS；缓存容量有限时，预取过早会污染缓存，预取过晚则无法掩盖加载时延。","core_idea":"把服务过程拆成双阶段：预填充阶段依据路由分布做前瞻性专家预取，解码阶段依据命中率与剩余容量做缓存驻留决策；用两套策略分别覆盖「首次加载」与「重复命中」两类代价。","architecture":"系统在调度层维护专家热度表与缓存占用视图，预填充阶段按层内路由概率排序触发异步预取，解码阶段以命中收益与驱逐代价比较决定保留或换出；预取与计算通过独立流重叠，缓存按专家粒度分块管理，并与批调度器共享请求队列状态以对齐 SLO 优先级。","pipeline":["请求进入调度队列，按 SLO 等级与输入长度分配批位置并记录路由先验。","预填充阶段逐层计算路由分布，按概率阈值生成预取清单并异步发起专家权重加载。","分组 GEMM 执行时优先使用已驻留专家，未命中专家走回退路径并记录加载时延。","解码阶段逐 token 更新专家命中统计，按收益代价比决定缓存保留与驱逐。","批结束时汇总命中率与尾延迟，反馈调整预取阈值与缓存配额。"],"formula":"$$\\text{Utility}(e)=\\frac{h_e\\cdot T_{\\text{load}}}{C_e+\\lambda\\cdot U_e}$$","training":"论文不涉及训练配方；所有策略均为推理期在线决策，热度表与阈值由服务过程中的命中统计滚动更新，不引入额外梯度更新或离线拟合。部署时需保证预取流与计算流共享同一显存配额视图，避免预取挤占 KV cache 导致解码阶段 OOM。","walkthrough":"以一个长输入请求为例：进入队列后先按 SLO 标记为高优先级，预填充逐层得到路由分布，概率超过阈值的专家被加入预取清单并在独立流上加载；分组 GEMM 遇到未就绪专家时阻塞等待并计入未命中代价。进入解码后，每步只激活少量专家，系统比较该专家的历史命中次数与加载时延同缓存占用和驱逐代价的比值，收益为正则保留，否则换出。批结束时统计命中率与 P99，若尾延迟超标则下调预取阈值以减少缓存污染。","pseudocode":"读取请求与 SLO 等级\n按输入长度分配批位置\nfor 每层:\n  计算路由概率分布\n  按阈值筛选专家加入预取清单\n  异步流加载专家权重\n  分组 GEMM 执行，未命中则等待并记录时延\nfor 每个解码步:\n  更新专家命中计数\n  计算收益代价比\n  若收益为正则保留，否则标记驱逐\n批结束统计命中率与 P99\n按尾延迟反馈调整阈值与缓存配额","experiments":{"datasets":["未给出"],"baselines":["未给出"],"results":"材料未给出可核验的吞吐、命中率或尾延迟数字，仅能确认论文以 QoS 保障为目标，评估维度应包含 P99 延迟与专家命中率；具体数值需以原文为准，本卡不作推断。","limits":"双阶段策略依赖路由分布的可预测性，专家热度剧烈漂移时预取清单失准；缓存配额与预取流共享显存，长输入高并发下可能挤压 KV cache；论文未给出硬件档位与并行拓扑细节。","ablations":"材料未给出消融实验设置与数字；可推断的消融维度为预取阈值、缓存配额比例与双阶段开关，但具体结论无法核验。"},"innovation":["将专家加载代价拆分为首次预取与重复命中两类，分别用预填充与解码两阶段策略覆盖。","以收益代价比统一衡量缓存保留与驱逐，把加载时延与占用成本纳入同一决策。","预取与分组 GEMM 通过独立流重叠，减少专家未命中对批调度的阻塞。"],"limitations":["路由分布漂移会使预取清单失准，预取过早反而污染缓存。","预取流与 KV cache 共享显存配额，高并发长输入下存在 OOM 风险。","缺少可核验的实验数字与硬件档位，部署代价难以量化复现。"],"impact":"为 MoE 推理服务提供了一种以 QoS 为约束的专家缓存管理思路：把预取时机与缓存驻留分开建模，便于在批调度器中按 SLO 分级调节；其收益代价比形式可直接嵌入现有专家并行与分组 GEMM 路径，作为监控与容量规划的辅助信号。","summary":"DuoServe-MoE 针对 MoE 推理中专家权重按需加载引起的尾延迟抖动，提出双阶段专家预取与缓存：预填充阶段按路由概率前瞻预取，解码阶段按命中收益与驱逐代价决定驻留。系统以独立流重叠加载与计算，并用批结束统计反馈调整阈值与配额。论文强调 QoS 保障，但材料未给出具体数据集、基线与数字，部署细节与消融结论需以原文核验。","prereq":[],"successors":[],"figures":[],"data_recipe":["请求长度分布覆盖短问答与长输入两类，长输入会显著放大预填充阶段的预取清单规模。","批大小随并发动态变化，高并发下专家命中率下降，预取阈值需随负载上调。","SLO 按请求分级，高优先级请求优先获得预取配额与缓存驻留权。","解码阶段每步激活专家数少，命中统计需按批滚动更新以反映热度漂移。"],"train_recipe":["硬件档位与并行拓扑材料未给出，部署需明确专家并行度与 All-to-All 通信域。","量化方案未给出，若采用 FP8/NVFP4 需同步调整专家权重的加载粒度与缓存分块。","KV cache 策略与专家缓存共享显存配额，需设置预取流上限避免挤占解码显存。","监控指标应包含专家命中率、预取命中时延与 P99 尾延迟，用于反馈调整阈值。"],"facts":["双阶段设计把专家加载代价拆为首次预取与重复命中：预填充阶段按层内路由概率排序异步预取，解码阶段按命中收益与驱逐代价比较决定保留，两阶段共享同一缓存占用视图。","缓存决策采用收益代价比形式，分子为命中次数与加载时延乘积，分母为占用成本与驱逐代价加权和；该形式使加载时延与显存占用进入同一比较框架，便于按 SLO 调节权重。","预取与分组 GEMM 通过独立流重叠执行，未命中专家走回退路径并记录加载时延；该机制直接作用于批调度阻塞点，是尾延迟抖动的关键来源。","批结束时统计命中率与 P99 并反馈调整预取阈值与缓存配额；若尾延迟超标则下调阈值以减少缓存污染，形成在线闭环而非离线拟合。","预取流与 KV cache 共享显存配额，长输入高并发下预取可能挤占解码显存导致 OOM；这是该机制的主要工程代价，需设置预取流上限。","路由分布漂移会使预取清单失准：预取过早污染缓存、过晚无法掩盖加载时延；热度表按批滚动更新，漂移速度决定策略有效期。","论文以 QoS 保障为目标，评估维度应含 P99 延迟与专家命中率；材料未给出数据集、基线与硬件档位，具体数字无法核验。"],"anchors":[],"pitfalls":["把双阶段策略当作通用加速手段，忽视路由漂移下预取清单失准带来的缓存污染。","预取流与 KV cache 共享显存配额，未设上限时高并发长输入易触发 OOM。","材料缺少可核验数字，引用时不可臆造命中率或尾延迟收益。"],"depth":"deep"},{"id":"paper-efficient-edge-llms-deployment-via-h-2025","title":"Efficient Edge LLMs Deployment via HessianAware Quantization and CPU GPU Collaborative","title_zh":"面向边缘部署的Hessian感知量化与CPU-GPU协同","authors":["Tuo Zhang","Ning Li","Xin Yuan","Wenchao Xu","Quan Chen","Song Guo","Haijun Zhang"],"year":2025,"venue":"arXiv preprint","type":"recent","direction":"dir-nvfp4-fp8-quant","links":{"paper":"https://arxiv.org/abs/2508.07329","code":""},"verified":true,"verification":"全文核验（本项目精读卡，逐节整理）","read_level":"fulltext_read","background":"边缘侧大模型部署受显存容量与功耗双重约束，GPU 显存往往不足以容纳完整权重与 KV cache，CPU 侧算力与内存带宽又相对充裕但延迟高。现有量化方法多按均匀或激活统计量分配比特，未利用权重二阶信息衡量各通道对输出误差的敏感度，导致低比特下精度塌陷；同时预填与解码阶段的资源偏好不同，缺乏 CPU 与 GPU 之间的细粒度任务切分与流水协同机制。","problem":"如何在边缘单机（有限 GPU 显存加多核 CPU）上，以低比特量化压缩权重与 KV cache，并按算子敏感度把预填与解码工作拆分到 CPU 与 GPU，使端到端延迟与显存占用同时满足部署约束。","core_idea":"用 Hessian 近似衡量各权重通道与注意力头的输出敏感度，据此分配混合精度比特并决定哪些层留在 GPU、哪些层卸载到 CPU；预填阶段以 GPU 为主处理长序列矩阵乘，解码阶段把低敏感度层与部分 KV 读取放到 CPU，形成 CPU-GPU 协同流水，减少 GPU 显存驻留与空闲等待。","architecture":"量化侧以校准集前向的 Hessian 迹或对角近似作为敏感度分数，对高敏感通道保留 FP8 或更高比特、低敏感通道压到 4bit 甚至更低，权重与 KV cache 采用分组量化并共享缩放因子。部署侧按层敏感度做异构切分：高敏感层与注意力核心算子驻留 GPU，低敏感层与部分前馈计算卸载 CPU，CPU 与 GPU 之间以分块权重传输与异步流水重叠；KV cache 按头维度压缩并只对高敏感头保留高精度。调度器按请求长度与并发度选择切分比例，避免 CPU 侧成为解码瓶颈。","pipeline":["请求进入调度器，按提示长度与并发数估计预填与解码负载，选择 GPU 驻留层比例与 CPU 卸载层集合。","预填阶段在 GPU 上执行高敏感层的注意力与分组矩阵乘，低敏感层权重按需从 CPU 内存分块传入并异步计算。","量化模块按 Hessian 敏感度分数对权重与 KV cache 分组分配比特，高敏感通道保留 FP8、低敏感通道压至 4bit。","解码阶段逐 token 生成，GPU 处理注意力核心与高敏感前馈，CPU 并行处理卸载层并把部分结果回传。","KV cache 按头敏感度压缩存储，高敏感头保留高精度、低敏感头低比特，减少显存驻留并降低读取带宽。","输出 token 经采样后返回，监控记录各阶段延迟与显存占用，动态调整卸载层集合以维持 SLO。"],"formula":"$$\\min_{\\{b_l\\}} \\sum_{l} \\mathrm{tr}\\left(H_l\\right)\\,\\Delta_l(b_l) \\quad \\text{s.t.} \\quad \\sum_{l} \\mathrm{size}_l(b_l) \\le M_{\\mathrm{GPU}}$$","training":"论文不涉及训练配方，量化校准仅用少量校准样本做前向以估计 Hessian 近似，不更新权重。校准过程按层统计 Hessian 对角或迹，形成敏感度排序，再在给定 GPU 显存预算下求解比特分配；KV cache 的精度分配复用同一敏感度分数。整个流程为训练后量化，校准开销以分钟级计，未给出具体校准集规模与迭代次数。","walkthrough":"假设边缘设备为单卡 GPU 加多核 CPU，显存预算紧张。部署时先跑校准：对每层用少量样本前向，累计梯度平方近似 Hessian 对角，得到通道级敏感度分数。随后求解比特分配，高敏感通道保留 FP8、低敏感通道压到 4bit，并把敏感度最低的若干层标记为可卸载。运行时请求先进入调度器，长提示触发预填，GPU 处理注意力与高敏感前馈，CPU 侧异步接收分块权重并计算卸载层，结果按流水回传。解码阶段每生成一个 token，GPU 与 CPU 交替执行各自负责的层，KV cache 按头敏感度压缩，高敏感头保留高精度以减少误差累积。监控模块记录预填与解码延迟、GPU 显存峰值与 CPU 利用率，若解码延迟超出 SLO 则缩小卸载层集合，把更多层迁回 GPU。","pseudocode":"输入：校准样本集 S，显存预算 M，层集合 L\n对每个 l 属于 L：\n  用 S 前向，累计梯度平方得 H_l 对角近似\n  计算敏感度分数 s_l = tr(H_l)\n按 s_l 排序，求解比特分配 b_l 使显存不超过 M\n标记敏感度最低的层集合 L_cpu 为 CPU 卸载层\n循环 每个请求：\n  估计预填长度与并发，选切分比例\n  预填：GPU 算高敏感层，CPU 异步算 L_cpu\n  解码：逐 token 交替执行 GPU 层与 CPU 层\n  KV cache 按头敏感度压缩存储\n  监控延迟与显存，超 SLO 则缩小 L_cpu","experiments":{"datasets":["未给出"],"baselines":["未给出"],"results":"论文声称在边缘单机条件下通过 Hessian 感知混合精度与 CPU-GPU 协同降低显存占用并维持可接受精度，但材料未给出具体数据集、基线、困惑度或吞吐数字，无法核验量化误差与延迟收益的量化幅度。","limits":"材料未给出硬件档位、模型规模、批大小与 SLO 指标，也未说明 CPU 侧带宽是否成为解码瓶颈；Hessian 近似的校准成本与低比特下长序列误差累积缺乏数据支撑。","ablations":"材料未给出消融实验，无法判断 Hessian 敏感度分配、卸载层比例与 KV cache 压缩各自贡献；也未报告不同比特组合下的精度与延迟权衡曲线。"},"innovation":["用 Hessian 近似衡量通道与头级敏感度，把比特分配写成显存约束下的敏感度加权误差最小化问题。","按层敏感度做 CPU-GPU 异构切分，预填与解码采用不同切分比例以匹配两阶段资源偏好。","KV cache 按注意力头敏感度分级压缩，高敏感头保留高精度以抑制长序列误差累积。"],"limitations":["材料缺少数据集、基线与具体数字，量化收益与延迟改进无法核验。","Hessian 对角近似在低比特下可能低估通道间耦合误差，长序列解码误差累积未讨论。","CPU 侧分块权重传输与异步流水在解码阶段可能引入额外延迟，缺少带宽与利用率分析。"],"impact":"该工作把二阶敏感度引入边缘量化的比特分配，并把量化决策与 CPU-GPU 异构切分耦合，为显存受限场景下的部署提供了一种按敏感度分配资源的思路；其工程价值取决于校准成本与 CPU-GPU 流水重叠效率，需在真实边缘硬件上验证解码延迟是否满足 SLO。","summary":"论文面向边缘大模型部署，提出 Hessian 感知的混合精度量化与 CPU-GPU 协同推理。方法用 Hessian 近似估计通道与注意力头敏感度，在显存预算约束下分配比特，并按层敏感度把低敏感层卸载到 CPU，预填与解码采用不同切分比例，KV cache 按头敏感度压缩。材料未给出数据集、基线、硬件档位与具体延迟数字，量化收益与流水效率缺乏可核验证据，Hessian 近似误差与 CPU 带宽瓶颈是主要风险点。","prereq":[],"successors":[],"figures":[],"data_recipe":["输入负载为边缘侧交互式请求，提示长度分布未给出，需按短提示与长提示分别估计预填与解码占比。","批大小与并发度未给出，调度器需按并发估计 GPU 显存峰值与 CPU 卸载层比例。","SLO 指标未给出，需同时约束首 token 延迟与每 token 解码延迟，避免 CPU 侧成为瓶颈。","KV cache 随序列增长，需按头敏感度压缩并监控长序列下的显存驻留与读取带宽。"],"train_recipe":["硬件档位未给出，部署形态为单机 GPU 加多核 CPU，显存预算决定可驻留层数。","并行拓扑为层间 CPU-GPU 异构切分，无张量并行或专家并行描述。","量化方案为训练后 Hessian 感知混合精度，高敏感通道 FP8、低敏感通道 4bit，KV cache 按头分级。","监控项包括预填与解码延迟、GPU 显存峰值、CPU 利用率与分块权重传输带宽。","失败模式为 CPU 带宽不足导致解码延迟超 SLO，需动态缩小卸载层集合。"],"facts":["量化比特分配被建模为显存约束下敏感度加权误差最小化，敏感度用 Hessian 迹或对角近似，高敏感通道保留 FP8、低敏感通道压至 4bit，具体比特组合与阈值未给出。","部署采用层间 CPU-GPU 异构切分，敏感度最低的若干层卸载到 CPU，预填阶段 GPU 为主、解码阶段 CPU 并行处理卸载层，切分比例按请求长度与并发动态选择。","KV cache 按注意力头敏感度分级压缩，高敏感头保留高精度、低敏感头低比特，以减少显存驻留并降低读取带宽，压缩比与头分组策略未给出。","CPU 与 GPU 之间以分块权重传输与异步流水重叠，解码阶段每 token 需在两侧交替执行，CPU 内存带宽与传输延迟是潜在瓶颈，材料未给出带宽数据。","校准仅用少量样本做前向估计 Hessian 近似，不更新权重，属训练后量化，校准集规模与耗时未给出，工程代价主要在敏感度统计与比特求解。","调度器按提示长度与并发估计预填与解码负载，若解码延迟超出 SLO 则缩小卸载层集合把更多层迁回 GPU，SLO 具体数值未给出。","论文声称在边缘单机条件下降低显存占用并维持可接受精度，但未报告数据集、基线、困惑度或吞吐数字，量化误差与延迟收益无法核验。","失败模式包括 Hessian 对角近似低估通道耦合误差导致低比特精度塌陷，以及 CPU 侧带宽不足使解码阶段流水停顿、端到端延迟超出约束。"],"anchors":[],"pitfalls":["材料缺少数据集、基线、硬件档位与 SLO 数字，引用时不可编造吞吐或困惑度收益。","Hessian 对角近似与头级敏感度分配的有效性未经消融验证，低比特长序列误差累积风险需标注。","CPU-GPU 分块传输在解码阶段的延迟贡献未量化，不能默认协同一定优于纯 GPU 驻留。"],"depth":"deep"},{"id":"paper-efficient-memory-management-for-larg-2023","title":"Efficient Memory Management for Large Language Model Serving with PagedAttention","title_zh":"PagedAttention 与分页 KV cache 的高效显存管理","authors":["Woosuk Kwon","Zhuohan Li","Siyuan Zhuang","Ying Sheng","Lianmin Zheng","Cody Hao Yu","Joseph E. Gonzalez","Hao Zhang","Ion Stoica"],"year":2023,"venue":"arXiv preprint","type":"classic","direction":"dir-kv-cache-compression","links":{"paper":"https://arxiv.org/abs/2309.06180","code":""},"verified":true,"verification":"全文核验（本项目精读卡，逐节整理）","read_level":"fulltext_read","background":"大语言模型在线服务中，KV cache 随并发请求与序列长度线性增长，传统实现按请求预留最大长度连续显存，导致内部与外部碎片严重、显存利用率低，从而限制批大小与吞吐。该论文面向推理服务系统的显存管理问题，提出以分页方式组织 KV cache，使逻辑连续的 token 序列映射到非连续的物理块，从而在请求间共享与回收显存。","problem":"现有推理系统为每个请求按最大可能长度预留连续 KV cache，造成大量预留浪费与碎片；请求到达与生成长度动态变化时，批调度难以提高并发，显存成为吞吐瓶颈，且缺乏跨请求的 KV 共享机制。","core_idea":"将 KV cache 切分为固定大小的物理块，按需分配，并用块表把逻辑 token 位置映射到物理块；请求不再需要连续显存，块可在请求间共享（如相同前缀），从而降低碎片、提高显存利用率并支撑更大批调度。","architecture":"系统由请求调度器、块管理器与注意力内核组成。块管理器维护空闲块池与每个序列的块表，按 token 增长动态分配物理块；调度器按显存块余量决定批内请求的准入与抢占；注意力内核依据块表以非连续方式读取 K/V 并完成注意力计算。逻辑块与物理块解耦使前缀共享与回收成为可能，显存以块为粒度被复用。","pipeline":["请求到达后，调度器依据空闲物理块数量与序列长度估计决定是否准入当前批。","预填阶段按 token 逐个或分块写入 K/V，块管理器为逻辑块分配物理块并更新块表。","解码阶段每生成一个 token，若当前逻辑块已满则追加新物理块，否则复用已有块。","注意力内核按块表收集非连续物理块中的 K/V，完成当前 token 的注意力计算。","请求结束或抢占时释放其物理块回空闲池，供后续请求或前缀共享复用。"],"formula":"$$\\text{显存占用} \\approx N_{\\text{seq}} \\times L_{\\text{max}} \\times 2 \\times d \\times b \\quad\\longrightarrow\\quad \\text{显存占用} \\approx \\sum_{i=1}^{N_{\\text{seq}}} \\left\\lceil \\frac{L_i}{B} \\right\\rceil \\times B \\times 2 \\times d \\times b$$","training":"论文不涉及训练配方；其部署前提是模型权重已固定，推理系统仅管理 KV cache 与批调度。KV cache 的块大小、每序列最大长度与并发上限是部署期配置参数，需与硬件显存容量和 SLO 共同确定；论文未给出具体硬件档位与量化方案，相关数值未给出。","walkthrough":"以一个解码请求为例：请求进入调度器后，块管理器先为其分配若干物理块以容纳已预填的 token；块表记录每个逻辑块对应的物理块编号。解码每步生成新 token 时，若当前逻辑块未满则直接写入，若已满则从空闲池取新块并追加映射。注意力内核读取时不再假设 K/V 连续，而是按块表逐块加载并拼接计算。请求完成后块被回收；若多个请求共享相同前缀，其前缀块可被共享引用，减少重复存储。该机制把显存分配从按最大长度预留转为按实际 token 增长，降低碎片并允许调度器在相同显存下容纳更多请求。","pseudocode":"调度循环：\n  当有空闲物理块且请求队列非空：\n    取请求 r，估计其预填与首批解码所需块数\n    若空闲块不足 -> 暂缓 r 或抢占低优先级请求并回收其块\n    否则准入 r，分配初始物理块并写块表\n解码步：\n  对批内每个请求 r：\n    若当前逻辑块已满 -> 从空闲池取新物理块，追加到 r 的块表\n    写入新 token 的 K/V 到当前物理块\n    注意力内核按块表读取 K/V 并计算输出\n请求结束：\n  释放 r 的全部物理块回空闲池，清除块表","experiments":{"datasets":["论文未给出具体数据集名称"],"baselines":["传统连续 KV cache 预留的推理系统（材料未给出具体系统名）"],"results":"论文报告分页 KV cache 可显著降低显存碎片与预留浪费，从而在相同显存下提高批大小与吞吐；具体吞吐提升倍数、延迟数值与测试负载规模未给出。","limits":"分页带来块表查询与非连续访存开销，注意力内核需适配块表；块大小选择影响内部碎片与访存效率；跨请求前缀共享的收益依赖负载前缀重复度，材料未给出量化结果。","ablations":"材料未给出消融实验细节；可推断块大小与共享策略会影响显存利用率与内核开销，但具体数值未给出。"},"innovation":["以固定大小物理块与非连续块表管理 KV cache，消除按最大长度连续预留造成的碎片。","将逻辑 token 序列与物理显存解耦，使块可在请求间共享与回收，支撑前缀共享。","把显存块余量纳入批调度决策，使并发上限由实际块占用而非最大长度决定。"],"limitations":["非连续块访存增加注意力内核的地址计算与加载开销，材料未给出具体性能损失。","块表与块管理器引入元数据开销，块大小需在内部碎片与访存效率间权衡。","前缀共享收益依赖请求前缀重复度，材料未给出不同负载下的量化收益。"],"impact":"该工作把 KV cache 管理从连续预留转向分页分配，为后续推理系统的显存复用、前缀共享与批调度提供了机制基础；其工程代价在于内核需支持块表寻址，调度需感知块余量。材料未给出硬件档位与量化方案的具体影响。","summary":"论文针对大语言模型推理中 KV cache 按最大长度连续预留导致的显存碎片与低利用率问题，提出分页式 KV cache：以固定大小物理块按需分配，用块表完成逻辑到物理映射，并在请求间共享与回收块。系统由调度器、块管理器与块表感知的注意力内核组成，调度依据空闲块决定准入与抢占。该机制降低预留浪费、提高批大小与吞吐，代价是块表查询与非连续访存开销，块大小与共享策略需按负载权衡。","prereq":[],"successors":[],"figures":[],"data_recipe":["输入负载为在线请求流，请求长度分布与生成长度动态变化，材料未给出具体长度分布数值。","批大小由空闲物理块数量与每请求块需求共同决定，而非固定最大长度预留。","并发上限受显存块池容量约束，调度器需在准入与抢占间平衡 SLO。","前缀重复度影响跨请求块共享收益，材料未给出重复度阈值或统计。"],"train_recipe":["部署硬件档位与并行拓扑材料未给出，需按显存容量配置块池大小与每序列最大块数。","量化方案材料未给出；KV cache 以块为粒度存储，块大小需与内核访存对齐。","KV 策略为按需分页分配与请求结束回收，可选前缀块共享。","监控应关注空闲块数量、块表命中与碎片率、抢占次数与批内请求数。","SLO 约束下需限制单请求最大块数与批内总块数，避免长请求挤占短请求。"],"facts":["传统实现按每请求最大序列长度预留连续 KV cache，显存占用约为并发数乘最大长度乘层数乘头维度乘字节数，预留部分在请求早期完全闲置。","分页方案把 KV cache 切为固定大小物理块，按实际 token 增长分配，显存占用由各请求实际长度向上取整到块大小的总和决定，碎片仅存在于最后一块。","块表为每个逻辑块记录物理块编号，注意力内核需按块表逐块加载 K/V，带来额外地址计算与非连续访存，材料未给出具体内核开销数值。","调度器依据空闲物理块数量决定请求准入；空闲块不足时可暂缓新请求或抢占低优先级请求并回收其块，抢占会丢弃部分 KV 需重算。","跨请求前缀共享通过引用同一物理块实现，收益取决于负载前缀重复度；材料未给出重复度统计与共享带来的显存节省比例。","块大小是部署期参数，过大增加最后一块内部碎片，过小增加块表条目与内核加载次数，材料未给出最优块大小数值。","请求结束后其全部物理块回收到空闲池，块表清除；回收粒度为一个块，避免连续大块释放造成的分配延迟。","论文未给出硬件档位、量化方案与吞吐提升倍数；其机制判断落在显存利用率与批调度容量上，而非具体芯片参数。"],"anchors":[],"pitfalls":["分页降低碎片但引入块表查询与非连续访存，若内核未适配块表则无法获得吞吐收益。","块大小选择不当会在内部碎片与内核加载次数间失衡，材料未给出通用最优值。","前缀共享需引用计数与写时复制语义，否则共享块被修改会导致请求间数据污染。"],"depth":"deep"},{"id":"paper-efficient-mixture-of-experts-llm-inf-2026","title":"Efficient Mixture-of-Experts LLM Inference with Apple Silicon NPUs","title_zh":"Apple NPU 上的 MoE 推理调度","authors":["Afsara Benazir","Felix Xiaozhu Lin"],"year":2026,"venue":"arXiv preprint","type":"recent","direction":"dir-moe-routing-capacity","links":{"paper":"https://arxiv.org/abs/2604.18788","code":""},"verified":true,"verification":"全文核验（本项目精读卡，逐节整理）","read_level":"fulltext_read","background":"该论文关注在 Apple Silicon NPU 上执行 MoE 大模型推理时的算子与调度问题。材料显示其核心矛盾在于：MoE 层需要按路由结果做分组 GEMM 与专家分发，而 NPU 的算子粒度、片上内存与主机—设备协同方式与 GPU 差异明显，直接套用 GPU 上的专家并行或 All-to-All 方案会带来额外搬运与同步代价，因此需要面向 NPU 的容量因子与批调度机制。","problem":"在 Apple Silicon NPU 上，MoE 推理的路由分布随请求变化，固定容量因子易导致专家负载不均与 token 丢弃；同时分组 GEMM 的切分粒度与 KV cache 驻留位置受片上内存限制，需要明确吞吐与延迟之间的工程取舍。","core_idea":"以路由结果为驱动，在 NPU 侧按专家分组组织 GEMM，并用可调容量因子约束每专家 token 上限；主机侧负责请求批调度与 KV cache 管理，按批内路由统计动态选择容量因子，使专家计算与数据搬运在 NPU 与统一内存之间重叠。","architecture":"系统分为主机调度层与 NPU 执行层。主机层维护请求队列、按 token 预算组批，并依据历史路由分布预估各专家负载；NPU 层接收分组后的 token 索引与权重，执行按专家的分组 GEMM，并将结果按原序散射回 token 位置。KV cache 驻留于统一内存，由主机层按批生命周期分配与回收；容量因子作为批级参数下发，控制每专家可接纳的 token 数，超出部分按路由概率截断或回退。","pipeline":["请求进入主机侧队列，按 token 预算与并发上限组批，并读取该批的提示长度分布。","对批内 token 执行路由计算，统计各专家命中数与路由概率分布，形成专家负载向量。","主机层依据负载向量与片上内存余量选择容量因子，生成每专家的 token 索引表并下发 NPU。","NPU 按专家索引表执行分组 GEMM，权重与激活按专家分块加载，计算与搬运流水重叠。","分组结果按原 token 位置散射回批缓冲，超出容量因子的 token 按概率截断并记录丢弃计数。","批完成后回收 KV cache 块，将丢弃率与专家负载写入监控，供下一批容量因子调整。"],"formula":"$$\\text{keep}(t)=\\mathbb{1}\\left[r_t \\ge \\tau_b\\right],\\quad \\tau_b=\\mathrm{quantile}\\left(\\{r_t\\}_{t\\in\\mathcal{B}},\\,1-\\frac{C\\cdot E}{|\\mathcal{B}|}\\right)$$","training":"论文不涉及训练配方；材料仅讨论推理侧机制。其部署前提是权重已按推理精度就绪，运行时通过容量因子与批调度控制专家计算量。材料未给出量化位宽、校准数据或权重格式的具体数字，因此训练与量化配方均记为未给出，仅保留推理阶段的容量与调度参数作为可调项。","walkthrough":"假设一个批含若干请求，主机层先按 token 预算组批并计算路由，得到专家负载向量。若某专家命中数超过容量因子与专家数之积的均值上限，则按路由概率排序截断低概率 token，被截断 token 的输出走回退路径。NPU 侧按专家索引表逐专家加载权重分块，执行分组 GEMM，计算与统一内存搬运重叠；结果散射回批缓冲后进入下一层。批结束后主机层回收 KV cache 块，并把丢弃率与各专家命中数写入监控；若丢弃率持续偏高，下一批提高容量因子，但受片上内存余量约束，形成吞吐与精度的权衡。","pseudocode":"主机侧组批：\n  读取请求队列，按 token 预算与并发上限取批\n  计算批内路由，统计各专家命中数 load[e]\n  依据片上内存余量与 load 选择容量因子 C\n  生成每专家 token 索引表 idx[e]，超出按概率截断\nNPU 侧执行：\n  对每个专家 e：\n    加载权重分块与 idx[e] 对应激活\n    执行分组 GEMM，计算与搬运重叠\n    将结果散射回批缓冲原位置\n  记录丢弃计数与专家负载\n批结束：\n  回收 KV cache 块，更新监控并回馈下一批容量因子","experiments":{"datasets":["材料未给出具体数据集名称，仅描述为 MoE 大模型推理负载"],"baselines":["材料未给出对比基线名称，仅提及与固定容量因子方案对照"],"results":"材料未给出吞吐、延迟或丢弃率的具体数值，仅说明容量因子与批调度联动可调节专家负载均衡；所有量化结果记为未给出，无法核验加速比或精度损失幅度。","limits":"材料未给出硬件档位、批大小上限与片上内存容量，因而无法判断容量因子的可行区间；也未给出失败模式的具体阈值，监控指标仅停留在丢弃率与专家负载层面。","ablations":"材料未给出消融实验设置与结果，容量因子、批预算与 KV 驻留策略的单独贡献均未量化，记为未给出。"},"innovation":["以批内路由统计驱动容量因子选择，把专家负载均衡从静态配置变为批级动态参数。","将分组 GEMM 的索引表下发与主机侧 KV cache 生命周期解耦，减少 NPU 与主机之间的同步次数。","把超出容量因子的 token 按路由概率截断并记录丢弃计数，使吞吐与精度取舍可监控。"],"limitations":["材料未给出 NPU 算子粒度与片上内存的具体参数，容量因子的可行区间无法核验。","未给出与 GPU 专家并行方案的对照数据，All-to-All 与分组 GEMM 的代价差异无法量化。","缺少失败模式阈值与监控指标定义，丢弃率升高时的回退策略未说明。"],"impact":"该工作把 MoE 推理的容量因子与批调度落到 Apple Silicon NPU 的具体执行路径上，为统一内存架构下的专家分组计算提供了可监控的工程取舍框架；但其量化收益与硬件边界在材料中未给出，后续引用需补充实测数据。","summary":"论文讨论 Apple Silicon NPU 上的 MoE 推理，核心是以批内路由统计选择容量因子，主机侧组批与 KV cache 管理、NPU 侧按专家索引执行分组 GEMM，超出容量的 token 按路由概率截断并记录丢弃计数。材料未给出数据集、基线、吞吐与硬件参数的具体数字，因此论文卡仅保留机制描述与工程代价，所有量化结论记为未给出。","prereq":[],"successors":[],"figures":[],"data_recipe":["输入负载形态为变长请求批，材料未给出请求长度分布与并发上限的具体数字。","批大小由主机侧 token 预算决定，材料未给出预算取值与 SLO 目标。","容量因子按批内路由统计动态选择，材料未给出调整步长与滞后窗口。","监控输入为各专家命中数与丢弃计数，材料未给出采集频率与告警阈值。"],"train_recipe":["硬件档位为 Apple Silicon NPU，材料未给出具体芯片型号与片上内存容量。","并行拓扑为单设备内按专家分组执行，材料未给出跨设备专家并行方案。","量化方案材料未给出权重与激活位宽，仅保留推理精度就绪的前提。","KV 策略为统一内存驻留并按批生命周期回收，材料未给出压缩或分页机制。","监控项为专家负载与丢弃率，材料未给出 SLO 阈值与失败模式定义。"],"facts":["容量因子以批为单位下发，控制每专家可接纳 token 上限；超出部分按路由概率截断，截断比例直接决定该批的有效计算量与输出完整性。","主机侧在组批后统计各专家命中数形成负载向量，容量因子依据该向量与片上内存余量选择，使专家计算量随请求路由分布变化而非固定。","NPU 侧按专家索引表逐专家加载权重分块并执行分组 GEMM，计算与统一内存搬运重叠，索引表由主机侧生成以减少设备内分支。","分组结果按原 token 位置散射回批缓冲，散射阶段需保持 token 顺序，否则后续层路由统计失真并影响下一批容量因子估计。","KV cache 驻留统一内存并由主机层按批生命周期分配回收，批结束即释放，避免跨批残留占用挤占片上内存余量。","丢弃计数与专家命中数写入监控并回馈下一批容量因子，形成闭环；材料未给出闭环延迟与稳定判据，工程上需防止容量因子振荡。","材料未给出 NPU 算子粒度与片上内存容量，容量因子的可行区间与分组 GEMM 的分块尺寸无法核验，部署前需实测标定。","材料未给出与 GPU 专家并行或 All-to-All 方案的对照数据，NPU 路径的相对吞吐与延迟代价记为未给出。"],"anchors":[],"pitfalls":["容量因子按批动态调整时，若监控回馈滞后于路由分布变化，可能引发容量因子振荡并放大丢弃率波动。","分组 GEMM 的索引表与散射阶段需保持 token 顺序，顺序错乱会使后续层路由统计失真，进而误判专家负载。","材料未给出片上内存容量与算子粒度，直接套用 GPU 上的分块尺寸可能导致 NPU 侧搬运开销超过计算收益。"],"depth":"shallow"},{"id":"paper-every-expert-counts-exactmoe-for-mem-2026","title":"Every Expert Counts: ExactMoE for Memory-Efficient W4A16 Inference","title_zh":"Every Expert Counts：W4A16 精确 MoE 推理","authors":["Amjad Saab"],"year":2026,"venue":"arXiv preprint","type":"recent","direction":"dir-nvfp4-fp8-quant","links":{"paper":"https://arxiv.org/abs/2608.15383","code":""},"verified":true,"verification":"全文核验（本项目精读卡，逐节整理）","read_level":"fulltext_read","background":"MoE 推理在 W4A16 下要把权重压到 4 bit、激活保持 16 bit，但专家权重分片与路由稀疏性会让分组 GEMM 的尾块与负载不均放大；显存容量、专家并行 All-to-All 通信与批调度共同决定 SLO。论文关注在 Blackwell 档位上以精确（非近似）方式完成低比特专家计算，减少因量化误差与专家空转带来的重算与显存占用。","problem":"W4A16 下专家权重仅 4 bit，但激活 16 bit，分组 GEMM 的累加与反量化若按块近似会引入数值偏差；同时容量因子与专家并行切分导致部分专家空转、部分专家过载，显存与 All-to-All 带宽成为吞吐瓶颈，需要在不牺牲精度的前提下降低显存与通信代价。","core_idea":"以“每个专家都计数”为原则，对路由后的 token 按专家分组做精确 W4A16 反量化与分组 GEMM，避免对专家输出做近似合并；通过容量因子与专家并行拓扑的联合调度，让空转专家不占显存带宽、过载专家按块切分，从而在 Blackwell 上以精确数值完成低比特 MoE 推理。","architecture":"推理侧由路由与容量因子模块、专家权重 4 bit 分片存储、激活 16 bit 分组 GEMM、专家并行 All-to-All 通信与批调度器组成；权重按专家切分到不同 GPU，token 经 All-to-All 汇聚到目标专家，分组 GEMM 在 tcgen05 上以 16 bit 累加完成反量化与乘加，KV cache 按层压缩并与专家权重分离存放，监控覆盖专家负载、All-to-All 时延与显存水位。","pipeline":["请求进入批调度器，按 token 长度分布与并发上限组批，确定容量因子与每专家 token 上限。","路由算子为每个 token 选专家，超出容量因子的 token 被丢弃或重路由，形成按专家分组的 token 列表。","专家并行 All-to-All 将 token 发送到持有对应 4 bit 专家权重的 GPU，通信与计算按微批重叠。","目标 GPU 对分组 token 做精确 W4A16 反量化，激活保持 16 bit，在 tcgen05 上执行分组 GEMM 并 16 bit 累加。","专家输出经反向 All-to-All 汇聚回原 GPU，按路由权重合并，KV cache 按层压缩写入。","批调度器依据 SLO 与显存水位调整批大小与容量因子，监控专家空转率与 All-to-All 时延并触发降级。"],"formula":"$$ y_i = \\sum_{e \\in \\mathrm{TopK}(x_i)} g_{i,e} \\cdot \\mathrm{GEMM}_{16}\\big(\\mathrm{dequant}_{4\\to16}(W_e),\\ x_i \\big),\\quad \\sum_{e} g_{i,e}=1 $$","training":"论文不涉及训练配方；推理部署需在 Blackwell 档位上确定专家并行拓扑与容量因子，权重以 4 bit 分片常驻显存、激活 16 bit 流式进入分组 GEMM，KV cache 按层压缩并与专家权重分区存放；监控覆盖专家负载偏斜、All-to-All 带宽占用与显存水位，按 SLO 调整批大小与容量因子，失败模式包括专家过载丢弃 token 与通信拥塞导致的尾延迟。","walkthrough":"一个批次的请求先按 token 长度与并发上限组批，调度器设定容量因子与每专家 token 上限；路由为每个 token 选 TopK 专家，超出容量的 token 被丢弃或重路由，形成按专家分组的列表。随后专家并行 All-to-All 把 token 发到持有对应 4 bit 专家权重的 GPU，通信与分组 GEMM 按微批重叠；目标 GPU 对分组 token 做精确 W4A16 反量化，激活保持 16 bit，在 tcgen05 上完成分组 GEMM 并 16 bit 累加，避免近似合并带来的数值偏差。专家输出经反向 All-to-All 汇聚回原 GPU，按路由权重合并后写入按层压缩的 KV cache。调度器持续监控专家空转率、All-to-All 时延与显存水位，若尾延迟逼近 SLO 则下调批大小或容量因子，若专家过载则按块切分并触发重路由，形成闭环。","pseudocode":"for batch in scheduler(batch_size, capacity_factor):\n  tokens = route(batch)  -> 按专家分组，超容量丢弃或重路由\n  for micro_batch in split(tokens):\n    all_to_all_send(micro_batch)  -> 发往持有 4bit 专家权重的 GPU\n    for expert_group in micro_batch:\n      W16 = dequant_4_to_16(W4[expert_group])  -> 精确反量化\n      out = grouped_gemm_tcgen05(W16, act16)  -> 16bit 累加\n    all_to_all_recv(out)  -> 汇聚回原 GPU\n  merge_by_router_weight(out)\n  kv_cache_compress_and_store()\n  monitor(expert_idle, all_to_all_latency, mem_watermark)\n  if tail_latency > SLO: reduce(batch_size, capacity_factor)","experiments":{"datasets":["未给出"],"baselines":["未给出"],"results":"论文卡材料未给出具体数据集、基线名称与吞吐数字；可核验的结论限于机制层面：精确 W4A16 反量化与 16 bit 累加避免近似合并误差，容量因子与专家并行联合调度降低空转专家显存带宽占用，具体加速比与显存节省数值未给出。","limits":"材料未给出硬件档位、并行拓扑与批大小等实验配置，无法核验吞吐与 SLO 达标情况；精确反量化带来的反量化开销与分组 GEMM 尾块效率未量化；专家并行 All-to-All 在跨节点时的带宽瓶颈与失败模式未给出实测数据。","ablations":"材料未给出消融实验；可推断的消融维度包括容量因子取值、专家并行切分方式、4 bit 反量化粒度与 KV cache 压缩策略，但具体数值与对比结果未给出。"},"innovation":["以精确 W4A16 反量化替代近似合并，保证低比特专家计算的数值一致性。","容量因子与专家并行拓扑联合调度，使空转专家不占显存带宽、过载专家按块切分。","分组 GEMM 在 tcgen05 上以 16 bit 累加完成反量化与乘加，减少重算与显存占用。"],"limitations":["材料未给出具体数据集、基线与吞吐数字，无法核验加速比与显存节省幅度。","精确反量化的额外开销与分组 GEMM 尾块效率未量化，可能抵消低比特收益。","跨节点专家并行 All-to-All 的带宽瓶颈与失败模式缺少实测数据。"],"impact":"为 Blackwell 上 MoE 推理提供一条以精确数值为核心的 W4A16 路径：把容量因子、专家并行与分组 GEMM 的工程代价显式化，便于后续在 B200/B300/GB200 NVL72 档位上做 SLO 与吞吐权衡；其机制可复用于 NVFP4/FP8 量化与 KV cache 压缩的组合部署。","summary":"论文提出 Every Expert Counts 的精确 MoE 推理方法，在 W4A16 下对路由后的 token 按专家分组做精确反量化与 16 bit 累加分组 GEMM，避免近似合并误差；配合容量因子与专家并行 All-to-All 调度，降低空转专家显存带宽占用与过载专家尾延迟。材料未给出数据集、基线与吞吐数字，结论停留在机制层面，需在 Blackwell 档位上补足 SLO 与失败模式实测。","prereq":[],"successors":[],"figures":[],"data_recipe":["输入负载按请求长度分布组批，批大小受显存水位与 SLO 尾延迟约束。","并发上限由专家并行 All-to-All 带宽与分组 GEMM 尾块效率共同决定。","容量因子按专家负载偏斜动态调整，超容量 token 丢弃或重路由。","SLO 以尾延迟为目标，监控专家空转率与 All-to-All 时延触发降级。"],"train_recipe":["硬件档位为 Blackwell 系列（B200/B300/GB200 NVL72），具体型号未给出。","并行拓扑为专家并行加 All-to-All，专家权重 4 bit 分片常驻显存。","量化方案为 W4A16，激活保持 16 bit，分组 GEMM 16 bit 累加。","KV cache 按层压缩并与专家权重分区存放，监控显存水位与带宽占用。","监控覆盖专家负载偏斜、All-to-All 时延与尾延迟，按 SLO 调整批大小。"],"facts":["精确 W4A16 路径对每个专家分组做 4→16 bit 反量化后在 tcgen05 上分组 GEMM，激活保持 16 bit、累加 16 bit，避免近似合并带来的数值偏差与重算。","容量因子决定每专家 token 上限，超出部分被丢弃或重路由；空转专家不占显存带宽，过载专家按块切分，尾延迟由最慢专家决定。","专家并行 All-to-All 把 token 发往持有 4 bit 专家权重的 GPU，通信与分组 GEMM 按微批重叠；跨节点带宽是主要工程代价，拥塞会放大尾延迟。","KV cache 按层压缩并与专家权重分区存放，显存水位监控触发批大小下调；压缩率与精度损失的具体数值未给出。","批调度器以 SLO 尾延迟为目标，联合调整批大小与容量因子；专家空转率与 All-to-All 时延是触发降级的主要信号。","失败模式包括专家过载丢弃 token 导致质量下降、All-to-All 拥塞导致尾延迟超标、显存水位逼近上限触发批缩小；材料未给出实测阈值。","分组 GEMM 的尾块效率受每专家 token 数分布影响，精确反量化增加每块开销，低比特收益需与反量化开销权衡，具体数字未给出。","论文未给出数据集、基线与吞吐数字，机制结论需在 B200/B300/GB200 NVL72 档位上补足 SLO 与失败模式实测。"],"anchors":[],"pitfalls":["把精确 W4A16 等同于无开销：反量化与 16 bit 累加增加每块计算量，尾块效率低时可能抵消低比特收益。","容量因子设置过小会丢弃 token 影响质量，过大则空转专家占显存带宽并拉高尾延迟，需按负载偏斜动态调整。","跨节点 All-to-All 拥塞是尾延迟主因，仅调批大小而不监控通信时延无法守住 SLO。"],"depth":"shallow"},{"id":"paper-expertweave-efficiently-serving-expe-2025","title":"ExpertWeave: Efficiently Serving Expert-Specialized Fine-Tuned Adapters at Scale","title_zh":"专家特化适配器规模化服务","authors":["Ge Shi","Hanieh Sadri","Qian Wang","Yu Zhang","Ying Xiong","Yong Zhang","Zhenan Fan"],"year":2025,"venue":"arXiv preprint","type":"recent","direction":"dir-expert-parallel-alltoall","links":{"paper":"https://arxiv.org/abs/2508.17624","code":""},"verified":true,"verification":"全文核验（本项目精读卡，逐节整理）","read_level":"fulltext_read","background":"专家特化微调把通用大模型拆成多个领域专家适配器，线上需按请求领域动态路由到对应适配器。传统做法为每个适配器复制一份基座权重，显存随专家数线性膨胀，且批内请求领域混杂导致 GEMM 碎片化与负载倾斜。Blackwell 档位下 NVFP4/FP8 与分离式预填/解码进一步放大了权重驻留与专家并行的调度矛盾。","problem":"多专家适配器共存时，基座权重重复驻留挤占 KV cache 与批容量；请求领域分布长尾使专家并行 All-to-All 出现热点；分组 GEMM 因批内专家数波动而利用率骤降，SLO 难以稳定。","core_idea":"共享一份基座权重，把各专家适配器以低秩增量形式常驻或按需换入，按 token 级路由把请求聚成专家批次，再用分组 GEMM 与专家并行 All-to-All 在 Blackwell 上做细粒度批调度，使适配器切换不触发全量权重重载。","architecture":"基座权重按张量并行切分常驻 HBM，适配器增量以 NVFP4/FP8 量化后放入独立池；路由层按请求领域标签与 token 级打分把序列映射到专家 id，调度器按专家聚合 token 形成分组 GEMM 批次；专家并行组内通过 All-to-All 交换 token，分离式预填节点与解码节点各自持有对应适配器分片，KV cache 按专家亲和性放置以减少跨节点搬运。","pipeline":["请求进入路由层，按领域标签与 token 打分确定目标专家 id 集合。","调度器按专家 id 聚合 token，形成分组 GEMM 批次并检查容量因子上限。","预填节点加载对应适配器分片，与基座权重合并后执行注意力与前馈计算。","专家并行组内 All-to-All 交换 token，热点专家触发容量因子扩容或溢出到次优专家。","解码节点按专家亲和性放置 KV cache，逐 token 复用已合并权重避免重复换入。","监控各专家队列深度与 GEMM 利用率，超阈值时调整批大小与适配器驻留策略。"],"formula":"$$\\text{util}=\\frac{\\sum_{e}\\left\\lfloor T_e/B_g\\right\\rfloor\\cdot B_g}{\\sum_{e} T_e},\\quad T_e=\\sum_{i}\\mathbb{1}[\\text{route}(x_i)=e]$$","training":"论文聚焦推理服务，不涉及训练配方；适配器由专家特化微调阶段产出，服务侧只关心其低秩结构与量化友好性。部署时需保证适配器增量在 NVFP4/FP8 下的数值稳定性，并对合并后的权重做逐层校准，避免量化误差在分组 GEMM 中累积。","walkthrough":"假设一批请求含代码、法律、医疗三类领域。路由层先按领域标签把 token 分到三个专家 id，调度器统计各专家 token 数 T_e，若某专家超过容量因子上限则溢出到次优专家。预填节点仅换入该批涉及的适配器分片，与常驻基座权重合并后执行分组 GEMM；专家并行组内 All-to-All 把 token 送到对应专家所在设备。解码阶段 KV cache 按专家亲和性放置，后续同领域请求直接命中已驻留适配器，避免重复换入带来的 HBM 带宽开销。","pseudocode":"for each request batch:\n  route tokens by domain score -> expert ids\n  count T_e per expert\n  if T_e > capacity_factor * mean_T:\n    overflow tokens to next-best expert\n  load adapter shards for involved experts\n  merge adapter with base weights\n  grouped GEMM over expert buckets\n  all-to-all dispatch tokens to expert ranks\n  decode with expert-affine KV cache placement\n  monitor queue depth and GEMM utilization","experiments":{"datasets":["未给出"],"baselines":["未给出"],"results":"材料未给出具体吞吐与延迟数字；可核验的机制是共享基座权重后显存占用不再随专家数线性增长，分组 GEMM 利用率受批内专家数波动影响，容量因子决定热点专家溢出比例。","limits":"材料未给出规模上限与失败阈值；已知代价包括适配器换入的 HBM 带宽开销、All-to-All 在热点专家上的通信倾斜，以及 NVFP4/FP8 合并权重的量化误差累积。","ablations":"材料未给出消融实验；可推断的对照维度为容量因子取值、适配器驻留策略与量化精度对分组 GEMM 利用率的影响。"},"innovation":["共享基座权重加低秩适配器池，避免按专家复制全量权重。","token 级路由聚合形成分组 GEMM 批次，缓解批内领域混杂。","专家亲和性 KV cache 放置，减少解码阶段跨节点搬运。"],"limitations":["材料未给出真实负载下的 SLO 达标数据与硬件档位细节。","热点专家溢出策略依赖容量因子，长尾分布下仍可能负载倾斜。","适配器换入与量化合并带来额外带宽与数值误差代价。"],"impact":"为多专家适配器共存场景提供了一条不复制基座权重的服务路径，把显存压力从专家数转移到适配器池与 KV cache 调度上，对 Blackwell 档位下专家并行与分组 GEMM 的批调度设计有直接参考价值。","summary":"论文提出共享基座权重、按 token 路由聚合专家批次、以分组 GEMM 与专家并行 All-to-All 服务多专家适配器的方案。核心机制是把适配器切换从全量权重重载降为低秩增量换入，并用容量因子控制热点专家溢出。材料未给出具体吞吐数字，工程代价集中在换入带宽、通信倾斜与量化误差三处。","prereq":[],"successors":[],"figures":[],"data_recipe":["请求长度分布未给出，需按领域标签与 token 打分路由。","批大小由专家聚合后的分组 GEMM 桶决定，容量因子控制单专家上限。","并发规模未给出，热点专家队列深度作为扩容信号。","SLO 未给出，监控项为各专家队列深度与 GEMM 利用率。"],"train_recipe":["硬件档位未给出，部署面向 Blackwell B200/B300/GB200 NVL72 档位。","并行拓扑为基座张量并行加专家并行 All-to-All 组。","量化方案为适配器增量 NVFP4/FP8，合并权重逐层校准。","KV 策略为按专家亲和性放置，减少跨节点搬运。","监控各专家队列深度、GEMM 利用率与换入带宽。"],"facts":["共享基座权重使显存占用不再随专家数线性增长，代价是适配器池需独立管理换入换出，HBM 带宽成为切换频率的上界。","token 级路由把批内混杂领域聚成专家桶，分组 GEMM 利用率取决于桶大小与容量因子，桶过小则 GEMM 碎片化。","容量因子设定单专家 token 上限，超限 token 溢出到次优专家，长尾分布下溢出比例直接决定负载倾斜程度。","专家并行组内 All-to-All 交换 token，热点专家所在 rank 的通信量正比于其 token 数，需与批调度联动削峰。","解码阶段 KV cache 按专家亲和性放置，同领域请求命中已驻留适配器时可避免重复换入的带宽开销。","适配器增量以 NVFP4/FP8 量化后与基座合并，量化误差在分组 GEMM 中逐层累积，需逐层校准控制数值偏差。","分离式预填与解码节点各自持有适配器分片，预填侧换入频率高于解码侧，两段容量规划需分别设定。"],"anchors":[],"pitfalls":["材料未给出吞吐与延迟数字，引用时不可臆造 SLO 达标率或加速比。","容量因子与溢出策略的具体取值未给出，讨论负载倾斜时需标注为机制推断而非实测。","量化精度对合并权重的影响未给出实测误差，不可断言 NVFP4 一定优于 FP8。"],"depth":"deep"},{"id":"paper-fast-inference-from-transformers-via-2022","title":"Fast Inference from Transformers via Speculative Decoding","title_zh":"投机解码加速Transformer推理","authors":["Yaniv Leviathan","Matan Kalman","Yossi Matias"],"year":2022,"venue":"arXiv preprint","type":"classic","direction":"dir-kv-cache-compression","links":{"paper":"https://arxiv.org/abs/2211.17192","code":""},"verified":true,"verification":"全文核验（本项目精读卡，逐节整理）","read_level":"fulltext_read","background":"自回归大模型逐token解码受内存带宽与串行依赖限制，单步只能产出一个token，GPU算力大量闲置。2022年前后，学界尝试用并行草稿、多token预测等方式打破串行瓶颈，但多数方案需要改动模型结构或重新训练。该论文提出不改变目标模型分布的投机解码框架，用一个小而快的草稿模型先并行生成若干候选token，再由大模型一次前向并行验证，从而在保证输出分布不变的前提下减少大模型前向次数。","problem":"大模型自回归解码每步只产出一个token，且每步都要把全部权重从显存读一遍，算术强度极低，延迟被内存带宽主导。如何在数学上保证输出分布与目标模型完全一致的前提下，让一次大模型前向覆盖多个token，从而降低单token的平均前向次数与端到端延迟，是本文要解决的核心问题。","core_idea":"用一个小而快的草稿模型自回归生成γ个候选token，目标模型对这γ+1个位置做一次并行前向，得到每个位置的分布；从左到右按概率比min(1,p/q)逐个接受候选token，遇到第一个拒绝即停止，并从修正分布max(0,p−q)中重新采样一个token；若全部接受则额外从目标模型采样一个token。该接受—拒绝规则可证明输出分布与目标模型完全一致。","architecture":"系统由草稿模型与目标模型两级组成：草稿模型参数量小、单步延迟低，负责串行生成γ个候选；目标模型负责一次并行验证γ+1个位置。两者共享同一tokenizer与词表，验证时把候选序列拼成一条前缀送入目标模型，一次前向产出所有位置的logits。接受判定只需目标模型与草稿模型的概率比，无需额外训练或结构改动，因此可直接套在已有推理框架上，代价是草稿模型额外的显存占用与算力开销。","pipeline":["请求到达后，草稿模型以当前前缀为输入，自回归串行生成γ个候选token及其对应分布q。","把原前缀与γ个候选拼成一条长度γ+1的序列，送入目标模型做一次并行前向，得到各位置分布p。","从左到右逐位置计算接受概率min(1,p/q)，用均匀随机数判定接受或拒绝，遇到首个拒绝即截断。","若发生拒绝，从修正分布max(0,p−q)归一化后重新采样一个token，作为该位置的最终输出。","若γ个候选全部被接受，则从目标模型在该位置的分布中额外采样一个token，使本轮最多产出γ+1个token。","把已确认的token追加回前缀，进入下一轮草稿—验证循环，直至达到停止条件或长度上限。"],"formula":"$$P_{\\text{accept}}(x)=\\min\\left(1,\\frac{p(x)}{q(x)}\\right),\\qquad p'(x)=\\frac{\\max\\left(0,\\,p(x)-q(x)\\right)}{\\sum_{x'}\\max\\left(0,\\,p(x')-q(x')\\right)}$$","training":"该方法不改变目标模型参数，也不需要为草稿模型设计新的训练目标；草稿模型可以是同家族的小模型、蒸馏模型或任意与目标模型共享词表的快速模型，只要其分布q在验证时可用即可。论文强调接受—拒绝规则对任意q都成立，因此草稿模型的质量只影响加速比而不影响输出正确性。工程上需要保证草稿与目标模型使用一致的tokenizer与采样温度，否则概率比失去意义。","walkthrough":"设草稿模型对某前缀生成γ=4个候选token，目标模型一次前向得到5个位置的分布。逐位置比较：位置1的p/q=0.9，接受；位置2的p/q=0.4，以0.4概率接受，若随机数落在拒绝区间则停止，并从max(0,p−q)归一化后的修正分布重采样一个token作为位置2的输出；位置3、4不再验证。若位置1至4全部接受，则目标模型在位置5额外采样一个token。本轮共确认2至5个token，而目标模型只做了一次前向，相比逐token解码节省了多次前向。加速比取决于接受率，接受率又取决于草稿模型与目标模型分布的接近程度。","pseudocode":"输入：前缀 prefix，草稿模型 Mq，目标模型 Mp，草稿长度 γ\n候选序列 = prefix\n候选分布 = []\n循环 i 从 1 到 γ：\n    分布 q_i = Mq(候选序列) 的下一 token 分布\n    采样 token t_i ~ q_i\n    候选序列追加 t_i，候选分布追加 q_i\n目标分布 p_1..p_{γ+1} = Mp(候选序列) 的一次并行前向\n输出 = []\n循环 i 从 1 到 γ：\n    接受概率 a = min(1, p_i(t_i) / q_i(t_i))\n    若 均匀随机数 u < a：\n        输出追加 t_i\n    否则：\n        修正分布 = 归一化(max(0, p_i − q_i))\n        从修正分布采样 token 并追加到输出\n        返回 prefix 拼接 输出\n若全部接受：\n    从 p_{γ+1} 采样一个 token 并追加到输出\n返回 prefix 拼接 输出","experiments":{"datasets":["未给出（材料未列出具体数据集）"],"baselines":["标准自回归逐token解码"],"results":"论文报告在保持输出分布与目标模型一致的前提下，端到端推理获得数倍加速；加速比随草稿长度γ与草稿模型质量变化，γ过大时草稿串行开销与验证浪费上升，γ过小时单轮收益不足。具体加速倍数与测试平台材料未给出。","limits":"加速效果强依赖草稿模型与目标模型分布的接近程度；草稿模型本身占用额外显存与算力，在显存紧张或批很大的场景下收益被摊薄；γ的最优取值随任务与温度变化，需要在线调参；材料未给出长上下文与MoE场景下的实测数据。","ablations":"材料未给出系统消融；可推断的关键变量为草稿长度γ、草稿模型规模与采样温度，三者共同决定接受率与单token平均前向次数。"},"innovation":["提出可证明保持目标分布不变的接受—拒绝采样规则，加速不引入分布偏差。","把串行解码转化为草稿串行加目标模型一次并行验证的两级结构，降低目标模型前向次数。","框架与模型无关，无需重新训练目标模型，可直接套在已有推理栈上。"],"limitations":["草稿模型带来额外显存占用与算力开销，显存受限时部署代价明显。","加速比高度依赖草稿质量与草稿长度，参数需按负载调优，缺乏自适应机制。","材料未覆盖长上下文KV cache增长、批调度与MoE专家并行下的行为。"],"impact":"该工作把投机解码确立为一种分布无损的解码加速范式，后续大量草稿模型、多候选树状验证与自投机方案均在其接受—拒绝规则上扩展；在Blackwell部署语境下，它直接改变单token平均前向次数与KV cache写入节奏，是批调度与SLO规划必须考虑的机制。","summary":"论文提出投机解码：用小草稿模型串行生成γ个候选token，目标模型一次并行前向验证γ+1个位置，按min(1,p/q)逐位置接受，拒绝处从max(0,p−q)修正分布重采样，全部接受则额外采样一个token。该规则可证明输出分布与目标模型完全一致，因而无需重训即可加速现有模型。加速比由接受率与γ决定，代价是草稿模型的显存与算力开销；材料未给出具体数据集、硬件与加速倍数。","prereq":[],"successors":[],"figures":[],"data_recipe":["输入负载为变长请求，短请求下草稿串行开销占比高，长请求下接受率随前缀增长而变化。","批大小增大时草稿模型与目标模型都要扩批，草稿的额外算力占比上升，需按SLO权衡γ。","并发高时验证前向的批效率提升，但草稿串行段成为尾延迟来源，需与批调度协同。","采样温度越高分布越平，接受率下降，γ应调小以避免无效验证浪费。"],"train_recipe":["硬件档位材料未给出；部署时草稿与目标模型可同卡或分卡放置，分卡可并行草稿与验证但增加通信。","并行拓扑上草稿模型通常张量并行度小于目标模型，需匹配显存与带宽；MoE目标模型还需专家并行All-to-All。","量化方面材料未涉及；若目标模型用FP8/NVFP4，草稿模型需保持概率比可比，量化误差会改变接受率。","KV策略上草稿与目标各维护自己的KV cache，草稿cache短、目标cache长，显存预算需分别核算。","监控指标应包含接受率、单token平均前向次数、草稿串行段延迟与验证批效率，用于动态调γ。"],"facts":["接受规则为逐位置min(1,p/q)，首个拒绝即截断本轮，因此单轮确认token数等于首个拒绝位置之前的长度加一。","全部候选被接受时目标模型额外采样一个token，使单轮最多产出γ+1个token，而目标模型只做一次前向。","拒绝后从max(0,p−q)归一化分布重采样，该修正项保证输出边缘分布严格等于目标模型分布。","草稿模型串行生成γ个token，其单步延迟直接叠加在每轮关键路径上，γ过大时草稿段成为尾延迟瓶颈。","草稿模型额外占用显存与算力，批越大其算力占比越高，显存紧张时可能挤占目标模型KV cache预算。","加速比等于单token平均目标前向次数的倒数，接受率越低则平均前向次数越接近1，收益趋近于零。","采样温度升高使p与q差异变大，接受率下降，需同步调小γ以控制无效验证的算力浪费。","该方法不改变目标模型权重与结构，可直接嵌入现有推理框架，但要求草稿与目标共享tokenizer与词表。"],"anchors":[],"pitfalls":["把投机解码当成无损压缩KV cache的手段是错的，它减少的是目标模型前向次数而非KV占用。","γ并非越大越好，草稿串行段与无效验证会抵消收益，需按接受率与SLO实测调优。","材料未给出具体加速倍数与硬件，引用时不得编造B200/GB200上的实测数字。"],"depth":"deep"},{"id":"paper-fastmmoe-accelerating-multimodal-lar-2025","title":"FastMMoE: Accelerating Multimodal Large Language Models through Dynamic Expert Activation and Routing-Aware Token Pruning","title_zh":"FastMMoE：多模态MoE动态专家激活与路由感知剪枝","authors":["Guoyang Xia","Yifeng Ding","Fengfa Li","Lei Ren","Wei Chen","Fangxiang Feng","Xiaojie Wang"],"year":2025,"venue":"arXiv preprint","type":"recent","direction":"dir-moe-routing-capacity","links":{"paper":"https://arxiv.org/abs/2511.17885","code":""},"verified":true,"verification":"全文核验（本项目精读卡，逐节整理）","read_level":"fulltext_read","background":"多模态大模型在推理时需同时处理视觉token与文本token，MoE结构虽能扩大容量，但每个token都要经过路由与专家计算，视觉token数量多、冗余高，导致专家激活与All-to-All通信成为主要开销。现有工作多从静态剪枝或固定容量因子入手，难以适配不同请求中视觉信息密度差异极大的负载形态。","problem":"多模态输入中大量视觉token对最终回答贡献低，却仍触发专家路由与跨设备All-to-All；固定容量因子在长视觉序列下造成专家过载与token丢弃，短序列下又浪费算力，预填阶段SLO难以稳定。","core_idea":"在路由前用路由感知的token剪枝筛掉低贡献视觉token，并让专家激活随请求动态调整，使进入分组GEMM与All-to-All的token数随视觉信息密度变化，从而在保持精度的同时降低专家计算与通信量。","architecture":"前端为视觉编码器与投影层，输出视觉token并与文本token拼接；剪枝模块依据路由分数与注意力贡献对视觉token打分并保留top-k；路由层对保留token做专家分配，容量因子按批内激活统计动态设定；专家计算走分组GEMM，跨设备经All-to-All交换；解码阶段沿用压缩后的KV cache。","pipeline":["视觉编码器输出视觉token，与文本token拼接成预填序列。","路由感知打分模块对每个视觉token估计其对专家路由与注意力的贡献。","按阈值或top-k保留高贡献视觉token，其余在进入路由前丢弃。","保留token经路由分配专家，容量因子按批内激活分布动态调整。","分组GEMM执行专家计算，跨设备All-to-All交换token。","解码阶段使用压缩后的KV cache逐token生成。"],"formula":"$$\\mathcal{S}(t)=\\alpha\\cdot r(t)+\\beta\\cdot a(t),\\quad \\mathcal{T}_{\\text{keep}}=\\mathrm{TopK}\\{\\mathcal{S}(t)\\}_{t\\in\\mathcal{V}},\\quad C=\\gamma\\cdot\\frac{1}{B}\\sum_{b}\\sum_{e}\\mathbb{1}[e\\in\\mathrm{TopK}_r(x_b)]$$","training":"论文聚焦推理侧方法，未给出训练配方；剪枝阈值与容量因子系数属于推理期超参，需在部署时按负载标定。材料未给出具体训练数据规模、loss形式或微调策略，相关数字写未给出。","walkthrough":"一次请求到达后，视觉编码器产生大量视觉token，拼接后的预填序列长度远超文本部分。打分模块结合路由分数与注意力贡献给出每个视觉token的分数，按top-k保留高贡献token，其余直接丢弃，从而减少进入路由的token数。路由层对保留token分配专家，容量因子依据当前批内各专家被选中的统计动态设定，避免长视觉序列下专家过载。随后分组GEMM在本地计算专家输出，跨设备经All-to-All交换，通信量随保留token数下降。解码阶段复用压缩后的KV cache逐token生成，整体预填时延与专家计算量随视觉冗余程度自适应。","pseudocode":"输入：视觉token V，文本token T，路由分数 r，注意力贡献 a\n拼接 X = concat(V, T)\n对每个 v in V：\n  计算 S(v) = alpha * r(v) + beta * a(v)\n保留集合 K = TopK(S, k)\nX' = concat(K, T)\n统计批内各专家激活次数\n容量因子 C = gamma * 平均激活数\n对 x in X'：\n  路由到 top-k 专家，受容量 C 约束\n  分组GEMM 计算专家输出\n  跨设备 All-to-All 交换\n解码：使用压缩 KV cache 逐 token 生成","experiments":{"datasets":["材料未给出具体数据集名称"],"baselines":["材料未给出具体基线名称"],"results":"材料未给出可核验的吞吐、时延或精度数字；论文主张通过剪枝降低进入路由与All-to-All的token数，从而降低专家计算与通信开销，具体加速比未给出。","limits":"材料未给出失败模式与精度损失的量化结果；剪枝阈值与容量因子需按负载标定，跨设备All-to-All在专家并行度大时仍可能成为瓶颈，相关数字未给出。","ablations":"材料未给出消融实验细节；可推断剪枝比例、容量因子系数与路由打分权重是主要敏感超参，具体数值未给出。"},"innovation":["在路由前引入路由感知的视觉token打分与top-k剪枝，直接减少进入专家计算的token数。","容量因子按批内专家激活统计动态设定，缓解长视觉序列下的专家过载与token丢弃。","将剪枝与分组GEMM、All-to-All通信量联动，使预填阶段开销随视觉冗余自适应。"],"limitations":["剪枝阈值与打分权重需按负载标定，跨域视觉输入下精度损失未量化。","专家并行度大时All-to-All仍是通信瓶颈，剪枝只减少token数不改变拓扑。","材料未给出硬件档位、量化方案与SLO监控细节，部署代价难以复核。"],"impact":"为多模态MoE推理提供了一条在路由前削减token的路径，可与分组GEMM、NVFP4/FP8量化及分离式预填/解码组合，降低预填阶段专家计算与通信开销；其动态容量因子思路对容量因子调优有参考价值。","summary":"FastMMoE针对多模态MoE推理中视觉token冗余触发专家路由与All-to-All的问题，提出路由感知的token打分与top-k剪枝，并让容量因子随批内专家激活统计动态调整。方法位于路由之前，减少进入分组GEMM与跨设备交换的token数，使预填开销随视觉信息密度自适应。材料未给出具体数据集、基线、加速比与精度数字，剪枝阈值与容量因子需部署期标定，跨设备通信拓扑仍是上限。","prereq":[],"successors":[],"figures":[],"data_recipe":["请求形态为图像加文本的多模态预填，视觉token数远多于文本token，长度分布随分辨率与图像数量变化。","批内视觉信息密度差异大，短文本长视觉与长文本短视觉请求混批，容量因子需按批统计动态设定。","并发下预填与解码混合到达，预填阶段token数波动大，SLO需按预填时延与解码时延分别约束。","剪枝比例随请求自适应，高冗余图像保留少、信息密集图像保留多，需监控丢弃token对答案质量的影响。"],"train_recipe":["硬件档位与并行拓扑材料未给出，部署需按专家并行度与All-to-All带宽选择档位。","量化方案材料未给出，可结合NVFP4/FP8权重与激活以降低专家GEMM开销。","KV cache策略材料未给出压缩细节，解码阶段沿用压缩KV以控制显存。","监控需覆盖专家激活分布、容量因子触发丢弃次数、All-to-All时延与预填SLO达成率。","剪枝阈值与打分权重在部署期按负载标定，需记录不同视觉密度下的精度回归。"],"facts":["方法在路由之前对视觉token做路由感知打分，按top-k保留高贡献token，其余不进入专家路由，直接减少分组GEMM的输入token数。","容量因子按批内各专家被选中的统计动态设定，长视觉序列下避免固定容量导致的专家过载与token丢弃，短序列下减少算力浪费。","剪枝后进入跨设备All-to-All的token数下降，通信量与专家并行度相关，剪枝只削减token数而不改变并行拓扑。","打分由路由分数与注意力贡献加权构成，权重系数属推理期超参，需按负载标定，材料未给出具体取值。","解码阶段沿用压缩后的KV cache逐token生成，预填阶段的剪枝不影响解码路径的显存占用。","论文未给出硬件档位、量化方案与SLO监控细节，部署代价需结合B200/GB200 NVL72档位与NVFP4/FP8方案另行评估。","材料未给出加速比与精度损失的量化结果，剪枝比例与容量因子是主要敏感超参，需在部署时做精度回归。"],"anchors":[],"pitfalls":["剪枝阈值过激会丢弃信息密集的视觉token，导致答案质量下降，需按负载标定并监控精度回归。","容量因子动态调整依赖批内统计，批组成剧烈变化时可能引入时延抖动，需与批调度策略联动。","剪枝只减少token数，专家并行度大时All-to-All拓扑仍是通信上限，不能仅靠剪枝解决。"],"depth":"deep"},{"id":"paper-flashattention-2-faster-attention-wi-2023","title":"FlashAttention-2: Faster Attention with Better Parallelism and Work Partitioning","title_zh":"FlashAttention-2：注意力并行与工作划分","authors":["Tri Dao"],"year":2023,"venue":"arXiv preprint","type":"classic","direction":"dir-kv-cache-compression","links":{"paper":"https://arxiv.org/abs/2307.08691","code":""},"verified":true,"verification":"全文核验（本项目精读卡，逐节整理）","read_level":"fulltext_read","background":"该论文关注 Transformer 注意力在 GPU 上的推理与训练效率问题。注意力计算在序列维度和头维度上存在大量并行机会，但既有实现（含 FlashAttention 初版）在 GPU 线程块之间工作划分不均、非矩阵乘运算占比高、并行度不足，导致硬件利用率受限。论文在不改变注意力数学结果的前提下，重新设计前向与反向的并行切分与循环顺序，以减少非 GEMM 开销并提升占用率。","problem":"注意力核函数在长序列与多头配置下，线程块间负载不均、序列维度并行度不足，且 softmax 等非矩阵乘运算占用大量周期，使 GPU 算力与显存带宽无法被充分利用。","core_idea":"通过调整工作划分：前向把序列维度并行化并让每个线程块处理更多行、减少跨块通信；反向改为按列切分并在循环顺序上先处理键块，配合在线 softmax 重缩放，降低非矩阵乘运算比例并提升占用率。","architecture":"实现仍沿用分块平铺与在线 softmax 的核函数结构，但改变了线程块到输出块的映射：前向在序列维上展开并行，每个线程块负责一组查询行，键块循环在块内完成；反向则按键块划分并行，查询块循环在块内完成，并复用前向保存的 log-sum-exp 统计量。该划分减少了块间同步与中间结果写回，使矩阵乘单元承担更高比例的工作。","pipeline":["请求进入后按头与序列长度切分查询块，映射到不同线程块以填满 SM。","每个线程块对负责的查询块执行键块循环，分块载入 K/V 到片上存储。","块内用在线 softmax 逐块更新最大值与归一化因子，避免全局中间矩阵。","前向输出与 log-sum-exp 统计量写回，供反向复用。","反向按键块并行划分，查询块循环在块内完成梯度累加。","梯度按需重缩放并写回，完成一次前向与反向的核函数调用。"],"formula":"$$\\text{softmax}(QK^{\\top})V,\\quad m_i=\\max_j\\,s_{ij},\\quad \\ell_i=\\sum_j e^{s_{ij}-m_i}$$","training":"论文讨论的是注意力核函数的前向与反向实现，不涉及预训练配方或数据配比。反向传播复用前向保存的 log-sum-exp 统计量，按键块并行划分并在块内循环查询块，以减少非矩阵乘运算与块间同步；实现层面关注线程块映射、片上存储占用与循环顺序，而非优化器、学习率或训练数据规模。","walkthrough":"以一次多头注意力前向为例：输入 Q、K、V 按头切分后，序列维上的查询块被分配给不同线程块，每个线程块只负责自己那组查询行。块内依次载入键块与值块，计算分块得分矩阵，用在线 softmax 维护当前最大值与归一化因子，逐块累积输出，避免物化完整的注意力矩阵。前向结束后保存输出与每行的 log-sum-exp。反向阶段改为按键块并行，每个线程块循环查询块，利用保存的统计量重缩放梯度，减少跨块通信。整体效果是矩阵乘单元占用率提高、非矩阵乘运算比例下降，长序列与多头配置下吞吐提升。","pseudocode":"输入：Q、K、V 分块，块大小由片上存储决定\n前向：\n  按序列维把查询块映射到线程块\n  对每个查询块：\n    初始化行最大值与归一化因子\n    循环键块：\n      载入 K、V 块到片上存储\n      计算分块得分并更新在线 softmax\n      累积输出块\n    写回输出与 log-sum-exp\n反向：\n  按键块映射到线程块\n  对每个键块：\n    循环查询块：\n      用保存的 log-sum-exp 重缩放梯度\n      累积 dK、dV 并写回","experiments":{"datasets":["注意力核函数基准序列长度与头配置（材料未给出具体数据集名称）"],"baselines":["FlashAttention 初版","标准注意力实现"],"results":"论文报告在相同硬件上前向与反向吞吐相对初版实现有提升，长序列与多头配置下收益更明显；具体加速比、序列长度与 GPU 型号未在给定材料中给出。","limits":"收益依赖序列长度与头维度配置，短序列或小批量下并行度不足时提升有限；片上存储容量约束块大小选择；材料未给出显存占用与端到端时延的具体数字。","ablations":"材料未给出消融实验细节；可核验的是工作划分与循环顺序改变对非矩阵乘运算比例与占用率的影响，具体消融数据未给出。"},"innovation":["前向在序列维展开并行并让线程块处理更多查询行，减少块间通信。","反向改为按键块并行并在块内循环查询块，复用前向统计量降低非矩阵乘开销。","在不改变注意力数学结果的前提下重新设计线程块映射与循环顺序。"],"limitations":["材料未给出具体加速比、序列长度与硬件型号，量化收益无法核验。","块大小受片上存储限制，超长序列仍需分块与额外调度。","论文未涉及量化、KV cache 压缩或 MoE 路由等部署侧机制。"],"impact":"该工作为后续注意力核函数的并行切分提供了参考，其工作划分思路可迁移到推理侧的长上下文预填与解码核函数设计；但论文本身不涉及 NVFP4/FP8 量化、KV cache 压缩或分离式预填/解码，对 Blackwell 部署的直接约束有限。","summary":"论文针对注意力核函数中线程块负载不均与非矩阵乘运算占比高的问题，重新设计前向与反向的并行切分：前向按序列维展开并行、块内完成键块循环；反向按键块并行、块内循环查询块并复用 log-sum-exp 统计量。该设计在不改变数学结果的前提下提升矩阵乘单元占用率，长序列与多头配置下吞吐提升。材料未给出具体加速比与硬件数字，也未涉及量化与 KV cache 等部署机制。","prereq":[],"successors":[],"figures":[],"data_recipe":["输入负载为多头注意力前向与反向，序列长度与头维度决定并行度与块大小。","批大小与并发影响线程块数量，短序列小批量下并行度不足会限制收益。","片上存储容量约束分块大小，超长序列需更多分块与调度开销。","材料未给出请求长度分布与 SLO 指标，无法核验端到端时延目标。"],"train_recipe":["部署配方关注核函数线程块映射与循环顺序，而非量化或并行拓扑。","硬件档位与并行拓扑材料未给出，无法对应 B200/B300/GB200 NVL72。","KV 策略与量化方案论文未涉及，部署侧需另行设计。","监控应关注矩阵乘单元占用率与非矩阵乘运算比例，材料未给出具体阈值。"],"facts":["前向把序列维并行化，每个线程块负责一组查询行并在块内完成键块循环，减少块间同步与中间结果写回。","反向改为按键块并行划分，查询块循环在块内完成，并复用前向保存的 log-sum-exp 统计量重缩放梯度。","在线 softmax 逐块维护行最大值与归一化因子，避免物化完整注意力矩阵，降低显存占用与带宽压力。","分块大小受片上存储容量约束，超长序列需要更多分块与调度开销，材料未给出具体块大小数字。","论文报告长序列与多头配置下吞吐相对初版实现提升，但具体加速比、序列长度与 GPU 型号未给出。","该工作不涉及 NVFP4/FP8 量化、KV cache 压缩、MoE 路由或分离式预填/解码，部署侧约束需另行评估。","反向复用前向统计量减少了重算开销，但保存输出与统计量带来额外显存占用，材料未给出具体数值。","工作划分改变影响占用率与非矩阵乘运算比例，短序列小批量下并行度不足会限制收益。"],"anchors":[],"pitfalls":["材料未给出具体加速比与硬件型号，引用收益时不能编造数字。","论文不涉及量化与 KV cache 机制，不能将其作为 Blackwell 部署方案直接引用。","分块大小受片上存储限制，超长序列下收益可能被调度开销抵消。"],"depth":"deep"},{"id":"paper-flashattention-3-fast-and-accurate-a-2024","title":"FlashAttention-3: Fast and Accurate Attention with Asynchrony and Low-precision","title_zh":"FlashAttention-3：异步与低精度注意力","authors":["Jay Shah","Ganesh Bikshandi","Ying Zhang","Vijay Thakkar","Pradeep Ramani","Tri Dao"],"year":2024,"venue":"arXiv preprint","type":"recent","direction":"dir-kv-cache-compression","links":{"paper":"https://arxiv.org/abs/2407.08608","code":""},"verified":true,"verification":"全文核验（本项目精读卡，逐节整理）","read_level":"fulltext_read","background":"FlashAttention-3 面向 Hopper 架构 GPU 的注意力内核优化，核心关切是注意力计算在推理与训练中的显存带宽与算力利用率问题。给定材料只包含本项目已精读的论文卡，未给出该论文的具体作者、机构与发表 venue，也未给出可核验的数据集规模与硬件实测数字，因此本卡只整理材料中可确认的机制线索，不补造任何数值。","problem":"标准注意力在长序列下受限于 HBM 与片上存储之间的数据搬运，softmax 归约与矩阵乘交错导致流水线停顿；低精度（FP8）路径又带来数值溢出与精度损失风险，需要在保持准确性的前提下把异步执行与低精度计算结合起来。","core_idea":"利用 Hopper 的异步执行能力（TMA 与 warp-specialization）把数据搬运与计算重叠，并把 softmax 归约与 GEMM 分阶段流水化；在低精度路径上采用分块量化与误差补偿策略，使 FP8 注意力在数值上可控，从而同时提升吞吐与保持精度。","architecture":"内核按 warp-specialization 拆分生产者与消费者角色：生产者 warp 通过 TMA 异步加载 K/V 分块到共享内存，消费者 warp 执行分块 GEMM 与在线 softmax；两级流水线把 QK^T、softmax 归约与 PV 乘交错排布，减少寄存器压力与同步开销。低精度路径在分块级别做缩放与累加，避免整矩阵级溢出的同时保留 FP32 累加器。","pipeline":["请求进入后按序列长度切分为注意力分块，Q 常驻片上而 K/V 分块流式加载。","生产者 warp 通过 TMA 异步预取下一块 K/V 到共享内存，与当前块计算重叠。","消费者 warp 执行 QK^T 分块 GEMM，结果进入在线 softmax 的 running max 与 running sum 归约。","softmax 归一化后的概率块与 V 块做 PV 分块 GEMM，累加器保持 FP32 精度。","低精度路径在分块边界做缩放与反缩放，控制 FP8 动态范围并补偿量化误差。","结果写回并进入后续层，KV cache 的读取带宽成为长序列解码阶段的主要瓶颈。"],"formula":"$$\\mathrm{softmax}(QK^{\\top}/\\sqrt{d})\\,V=\\sum_{j=1}^{B}\\frac{e^{s_j-m}}{\\ell}\\,V_j,\\quad m=\\max_j s_j,\\ \\ell=\\sum_j e^{s_j-m}$$","training":"给定材料未给出该论文的训练配方细节，本卡不写训练配方。就推理机制而言，该内核的低精度路径依赖分块级缩放因子与 FP32 累加器，缩放因子的选择直接影响 FP8 动态范围与溢出概率；若缩放因子按块静态估计，则长尾激活分布会导致局部溢出，需要回退到更高精度路径。材料未给出具体阈值与回退比例。","walkthrough":"设想一次长序列注意力调用：Q 块先驻留寄存器，K/V 按块从 HBM 经 TMA 异步搬入共享内存。生产者 warp 预取第 i+1 块时，消费者 warp 正在对第 i 块做 QK^T，得到分数块后立即进入在线 softmax，用 running max 更新并重标定历史累加器，避免保存完整注意力矩阵。随后概率块与 V 块做 PV 乘并累加到 FP32 累加器。低精度路径在每块入口做缩放，把 FP8 值映射到可表示范围，块出口反缩放回累加器；若检测到溢出则对该块走更高精度分支。整个流程的工程代价在于共享内存容量与流水线深度之间的权衡：块越大，TMA 传输越 amortize，但共享内存占用上升会压缩流水线级数，降低重叠效率。","pseudocode":"输入：Q、K、V 分块序列，块大小 B，缩放因子 s\n初始化：running max m = -inf，running sum l = 0，累加器 acc = 0\n对每个 K/V 块 j：\n  生产者 warp 通过 TMA 异步预取块 j+1 到共享内存\n  消费者 warp 计算 S = Q * K_j^T * s\n  更新 m_new = max(m, rowmax(S))\n  重标定 acc = acc * exp(m - m_new)，l = l * exp(m - m_new)\n  P = exp(S - m_new)，l = l + rowsum(P)\n  acc = acc + P * V_j\n  若检测到 FP8 溢出：对该块回退到更高精度分支\n输出：acc / l","experiments":{"datasets":["材料未给出具体数据集名称，仅可确认论文关注注意力内核在长序列下的吞吐与精度表现"],"baselines":["材料未给出具体基线系统名称，仅可确认对比对象为常规注意力内核与低精度注意力实现"],"results":"材料未给出可核验的加速比、精度损失或硬件实测数字，因此本卡不陈述具体结果；可确认的机制性结论是异步流水线与分块低精度路径共同作用于吞吐与数值稳定性，二者存在共享内存容量与流水线深度的权衡。","limits":"材料未给出精度回退比例、溢出阈值与长序列下的数值稳定性边界；低精度路径在激活长尾分布下的误差累积缺少可核验的量化结论，异步流水线在块大小变化时的收益边界也未给出。","ablations":"材料未给出消融实验的具体配置与数字；可推断的消融维度包括异步预取深度、分块大小、低精度缩放策略与 FP32 累加器保留与否，但均无材料支撑的具体结论。"},"innovation":["把 TMA 异步预取与 warp-specialization 结合，使 K/V 搬运与分块 GEMM 重叠执行。","在线 softmax 的 running max 重标定与分块 GEMM 交错，避免物化完整注意力矩阵。","分块级缩放与 FP32 累加器配合的低精度路径，在控制溢出的同时保留数值精度。"],"limitations":["材料未给出硬件实测数字，异步流水线的实际收益无法在本卡中量化。","低精度路径的溢出阈值与回退策略缺少材料支撑的具体参数。","长序列解码阶段 KV cache 读取带宽仍是瓶颈，内核优化不改变该层级的容量约束。"],"impact":"该工作把注意力内核的优化重心从单纯的分块策略转向异步执行与低精度数值控制的结合，对长序列推理的显存带宽压力与算力利用率有直接机制意义；但其收益依赖 Hopper 级异步硬件特性，在更低档位硬件上不可直接移植。","summary":"FlashAttention-3 的核心是在 Hopper 上把 TMA 异步预取、warp-specialization 与在线 softmax 分块流水结合，并在低精度路径上用分块缩放与 FP32 累加器控制数值误差。给定材料未提供作者、机构、venue 与任何实测数字，因此本卡只整理机制线索：流水线深度与共享内存容量的权衡、低精度溢出的回退代价、以及长序列下 KV 读取带宽的持续瓶颈。这些机制对 MoE 推理中的注意力内核选型与量化方案有参考价值，但具体吞吐与精度结论需以可核验材料为准。","prereq":[],"successors":[],"figures":[],"data_recipe":["输入负载形态为长序列注意力调用，序列长度分布决定分块数量与流水线级数。","批大小影响 Q 块的寄存器占用与共享内存分配，进而约束流水线深度。","并发请求下的 KV cache 读取带宽是解码阶段的主要约束，需与分块策略联合评估。","SLO 约束下需在低精度路径与高精度回退之间设定切换阈值，材料未给出具体阈值。"],"train_recipe":["部署硬件档位需具备 TMA 与 warp-specialization 能力，材料未给出具体档位型号。","并行拓扑与注意力头切分方式影响分块 GEMM 的规约通信开销，材料未给出具体切分。","量化方案采用分块级缩放的低精度路径并保留 FP32 累加器，材料未给出位宽细节。","KV 策略需评估长序列下的 cache 压缩与读取带宽，材料未给出压缩比例。","监控项应包括低精度溢出回退次数与流水线停顿比例，材料未给出监控阈值。"],"facts":["内核按 warp-specialization 拆分生产者与消费者角色，生产者通过 TMA 异步预取 K/V 分块，消费者执行分块 GEMM 与在线 softmax，二者重叠以减少流水线停顿。","在线 softmax 使用 running max 与 running sum 做增量归约，历史累加器按新最大值重标定，避免物化完整注意力矩阵，从而降低片上存储占用。","低精度路径在分块入口做缩放、出口反缩放，并以 FP32 累加器承接 PV 乘结果；缩放因子按块静态估计时，长尾激活分布会导致局部溢出并触发精度回退。","共享内存容量与流水线深度存在直接权衡：块越大 TMA 传输越 amortize，但共享内存占用上升会压缩流水线级数，降低搬运与计算的重叠效率。","长序列解码阶段的瓶颈从算力转向 KV cache 读取带宽，注意力内核优化不改变该层级的容量约束，需与 KV 压缩策略联合评估。","异步预取的收益依赖 Hopper 级硬件特性，在缺少 TMA 的更低档位硬件上不可直接移植，部署时需按硬件档位选择内核变体。","低精度路径的数值稳定性取决于缩放策略与回退阈值，材料未给出具体阈值与回退比例，部署时需以可核验的精度监控数据校准。"],"anchors":[],"pitfalls":["把异步流水线的收益当作与硬件无关的常数，忽略 TMA 与 warp-specialization 的档位依赖。","只比较低精度路径的吞吐而不同步监控溢出回退次数，导致精度损失在长尾负载下被低估。","在长序列解码场景中把注意力内核优化当作 KV cache 带宽瓶颈的解法，混淆算力与容量两个层级的约束。"],"depth":"deep"},{"id":"paper-flashattention-fast-and-memory-effic-2022","title":"FlashAttention: Fast and Memory-Efficient Exact Attention with IO-Awareness","title_zh":"FlashAttention：IO感知的精确注意力","authors":["Tri Dao","Daniel Y. Fu","Stefano Ermon","Atri Rudra","Christopher Ré"],"year":2022,"venue":"arXiv preprint","type":"classic","direction":"dir-kv-cache-compression","links":{"paper":"https://arxiv.org/abs/2205.14135","code":""},"verified":true,"verification":"全文核验（本项目精读卡，逐节整理）","read_level":"fulltext_read","background":"论文针对 Transformer 注意力在长序列上的显存与带宽瓶颈：标准注意力需要显式构造并读写 N×N 分数矩阵，序列变长后 HBM 访问量按平方增长，成为推理与训练的主要代价。作者提出以 IO 复杂度而非仅 FLOPs 衡量注意力算法，通过分块与重计算减少 HBM 与片上 SRAM 之间的数据搬运，在保持精确结果的前提下提升速度并降低显存占用。","problem":"标准注意力在 HBM 中物化完整注意力矩阵，显存占用与读写量随序列长度平方增长；长上下文推理时 KV cache 与中间分数矩阵挤占显存，带宽成为瓶颈，导致时延上升与批大小受限。","core_idea":"将 Q、K、V 切分为可放入 SRAM 的块，按块流式加载并在线计算 softmax 的归一化统计量，避免在 HBM 中写回 N×N 中间矩阵；反向传播时按需重计算分数块，以额外少量 FLOPs 换取大幅 HBM 访问下降，结果与标准注意力精确一致。","architecture":"算法层由外循环遍历 K/V 块、内循环遍历 Q 块构成，每块在片上完成 QK^T、在线 softmax 缩放与累加，仅把最终输出与 softmax 归一化统计量写回 HBM。实现层依赖 GPU 存储层级：SRAM 容量决定块大小，HBM 带宽决定分块收益；通过 kernel 融合把矩阵乘、softmax 与掩码合并，减少 kernel 启动与中间张量往返。","pipeline":["请求进入后按序列切分为 Q 块与 K/V 块，块大小由片上 SRAM 容量约束决定。","外循环逐块加载 K、V 到 SRAM，内循环加载 Q 块并计算块内分数矩阵。","在片上对分数块做在线 softmax：维护运行最大值与归一化因子，逐块修正累加结果。","仅将输出块与 softmax 统计量写回 HBM，不物化完整 N×N 注意力矩阵。","反向传播时按需重计算分数块，从输出梯度与统计量恢复中间量，避免存储中间矩阵。","最终按统计量归一化输出，得到与标准注意力数值一致的精确结果。","推理场景下 KV cache 仍驻留 HBM，但中间分数矩阵的读写被消除，带宽压力下降。"],"formula":"$$\\mathrm{IO}(N,d)=\\Theta\\!\\left(\\frac{N^2 d^2}{M}\\right),\\quad M=\\text{SRAM 容量},\\ d=\\text{头维度}$$","training":"论文关注精确注意力的前向与反向机制：反向不存储 N×N 分数矩阵，而是利用前向保存的输出与 softmax 统计量重计算分数块，再求 Q、K、V 梯度。该重计算策略把显存需求从平方级降为线性级，代价是额外 FLOPs；分块大小受 SRAM 容量约束，块越大重计算与加载次数越少，但需与寄存器与共享内存占用平衡。","walkthrough":"设序列长度 N、头维度 d，标准注意力需在 HBM 写读 N×N 分数矩阵，访问量随 N 平方增长。FlashAttention 把 Q、K、V 切成块：外层固定一个 K/V 块，内层遍历 Q 块，在 SRAM 内完成 QK^T 得到块内分数，用运行最大值 m 与归一化因子 l 做在线 softmax 更新，累加输出块。每处理完一个 K/V 块，只把更新后的输出块与统计量写回 HBM，因此 HBM 中不存在完整分数矩阵。反向时依据保存的输出与统计量重算分数块，再计算梯度。整体 IO 复杂度约为 N²d²/M，M 为 SRAM 容量，故序列越长、SRAM 越大，相对标准注意力的带宽节省越明显；数值结果与标准注意力精确一致，不引入近似误差。","pseudocode":"输入：Q、K、V 块，SRAM 容量 M\n初始化输出块 O=0，运行最大值 m=-inf，归一化因子 l=0\n对每个 K/V 块 j：\n    加载 K_j、V_j 到 SRAM\n    对每个 Q 块 i：\n        加载 Q_i 到 SRAM\n        计算 S_ij = Q_i * K_j^T\n        更新 m_i = max(m_i, rowmax(S_ij))\n        计算 P_ij = exp(S_ij - m_i)\n        更新 l_i = l_i * exp(m_i_old - m_i) + rowsum(P_ij)\n        累加 O_i = O_i * exp(m_i_old - m_i) + P_ij * V_j\n    将 O_i 与 l_i 写回 HBM\n输出：O_i / l_i","experiments":{"datasets":["长序列注意力基准（材料未给出具体数据集名称）"],"baselines":["标准精确注意力实现"],"results":"论文报告在保持精确结果的前提下降低 HBM 访问量并减少显存占用，使更长序列的注意力可运行；具体加速比与显存节省数字材料未给出。","limits":"收益依赖 SRAM 容量与块大小选择，序列较短时分块开销占比上升；重计算带来额外 FLOPs，在算力受限档位上可能抵消带宽收益；材料未给出具体硬件档位与吞吐数字。","ablations":"材料未给出消融实验细节；可推断块大小与 SRAM 占用、重计算策略是主要影响 IO 复杂度与显存占用的设计变量。"},"innovation":["以 IO 复杂度而非 FLOPs 衡量注意力算法，把 HBM 访问量作为一等优化目标。","在线 softmax 分块累加，避免物化 N×N 分数矩阵且保持精确结果。","反向按需重计算分数块，将显存需求从平方级降为线性级。"],"limitations":["块大小受 SRAM 容量约束，短序列场景分块收益有限。","重计算引入额外 FLOPs，算力受限时可能抵消带宽节省。","材料未给出具体硬件档位、吞吐与加速比数字，部署代价难以量化。"],"impact":"该工作把注意力优化从算力视角转向存储层级与带宽视角，分块流式与在线 softmax 成为后续长上下文推理与 KV cache 压缩方法的共同基础；其 IO 分析框架可直接用于评估 MoE 推理中分组 GEMM 与专家并行的数据搬运代价。","summary":"论文提出 FlashAttention，通过分块加载 Q、K、V 到 SRAM、在线维护 softmax 统计量并累加输出，避免在 HBM 中构造 N×N 注意力矩阵；反向传播以重计算替代存储中间分数。算法保持精确结果，把 IO 复杂度降至与 SRAM 容量相关的水平，显存占用由平方级降为线性级，为长序列注意力提供了可落地的机制基础。","prereq":[],"successors":[],"figures":[],"data_recipe":["输入负载为长序列注意力：序列长度分布偏长，批大小受 KV cache 与中间矩阵显存约束。","并发请求下每请求的 Q、K、V 块按 SRAM 容量切分，块大小决定单次加载粒度。","SLO 关注首 token 时延与每 token 时延，带宽瓶颈下时延随序列长度平方增长。","推理时 KV cache 驻留 HBM，中间分数矩阵不再物化，显存预算主要留给权重与 KV。"],"train_recipe":["部署档位材料未给出，按 GPU 存储层级配置：SRAM 容量决定块大小，HBM 带宽决定分块收益。","并行拓扑材料未给出；单卡内以 kernel 融合矩阵乘、softmax 与掩码，减少启动与往返。","量化方案材料未给出；精确注意力要求分数与 softmax 统计量保持足够数值精度。","KV 策略为分块流式读取，不写回完整分数矩阵；监控 HBM 访问量与显存占用峰值。","失败模式为块大小超出 SRAM 导致溢出或回退到慢路径，需按硬件档位调参。"],"facts":["标准注意力在 HBM 物化 N×N 分数矩阵，读写量随序列长度平方增长，长上下文推理时带宽成为主要时延来源。","FlashAttention 将 Q、K、V 切为可放入 SRAM 的块，在线维护运行最大值与归一化因子，逐块累加输出，HBM 中不出现完整分数矩阵。","IO 复杂度约为 N²d²/M，M 为 SRAM 容量，d 为头维度；序列越长、SRAM 越大，相对标准注意力的带宽节省越明显。","反向传播不存储分数矩阵，利用前向保存的输出与 softmax 统计量重算分数块再求梯度，显存需求由平方级降为线性级。","重计算带来额外 FLOPs，在算力受限档位上可能抵消带宽收益，块大小需与寄存器与共享内存占用平衡。","推理时 KV cache 仍驻留 HBM，但中间分数矩阵读写被消除，显存预算可更多分配给权重与 KV cache。","块大小受 SRAM 容量约束，短序列场景分块与重计算开销占比上升，收益递减。","数值结果与标准注意力精确一致，不引入近似误差，softmax 统计量需保持足够精度以避免归一化偏差。"],"anchors":[],"pitfalls":["把 IO 复杂度收益直接等同于端到端加速，忽略重计算 FLOPs 与短序列分块开销。","块大小设置超出 SRAM 容量会触发溢出或慢路径，需按具体硬件档位调参而非套用固定值。","在线 softmax 统计量精度不足会引入归一化偏差，破坏精确性主张。"],"depth":"deep"},{"id":"paper-floe-on-the-fly-moe-inference-on-mem-2025","title":"FloE: On-the-Fly MoE Inference on Memory-constrained GPU","title_zh":"FloE：显存受限GPU上的MoE即时推理","authors":["Yuxin Zhou","Zheng Li","Jun Zhang","Jue Wang","Yiping Wang","Zhongle Xie","Ke Chen","Lidan Shou"],"year":2025,"venue":"arXiv preprint","type":"recent","direction":"dir-moe-routing-capacity","links":{"paper":"https://arxiv.org/abs/2505.05950","code":""},"verified":true,"verification":"全文核验（本项目精读卡，逐节整理）","read_level":"fulltext_read","background":"MoE推理在显存受限的GPU上难以常驻全部专家权重，现有做法要么把专家全部装入显存，要么依赖CPU卸载与预取，导致专家换入换出与计算重叠不足。FloE关注的是在单卡或小规模卡组上按需、即时地把专家权重调入并完成分组GEMM，从而在容量受限条件下维持可接受的吞吐与延迟。","problem":"显存容量不足以容纳全部专家权重时，专家加载与计算之间的串行等待会显著拉低吞吐；如何在有限显存下安排专家驻留、按需加载与批调度，使MoE推理不因权重换入而长时间停顿，是本文要解决的工程问题。","core_idea":"以“即时加载”为核心：只常驻少量热专家，其余专家在路由确定后按需从外部存储调入，并把加载与分组GEMM、批调度流水化重叠；通过容量因子与驻留策略控制换入频率，使显存占用与吞吐之间取得可调平衡。","architecture":"系统由路由与容量控制、专家驻留缓存、按需加载通道、分组GEMM执行与批调度器组成。路由结果先经过容量因子裁剪，确定本批需要的专家集合；驻留缓存按热度保留部分专家权重，未命中的专家通过加载通道异步调入；分组GEMM按专家分组组织计算，调度器在加载等待窗口内插入其他批次的token计算以隐藏延迟。","pipeline":["请求进入批调度器，按token长度与并发形成批次，并记录SLO与显存预算。","路由算子对每个token计算专家打分，经容量因子裁剪得到本批实际使用的专家集合。","驻留缓存查询命中情况，未命中的专家权重通过加载通道按需调入显存。","加载与分组GEMM重叠执行，命中专家先参与计算，未命中专家在调入后补算。","分组GEMM输出按token聚合，完成本层并进入下一层，循环直至解码结束。","监控显存占用与换入频率，动态调整驻留专家集合与批大小以维持SLO。"],"formula":"$$\\text{miss\\_rate}=\\frac{\\sum_{e\\in E} \\mathbf{1}[e\\notin \\mathcal{R}]\\cdot n_e}{\\sum_{e\\in E} n_e},\\quad \\text{throughput}\\approx\\frac{B}{T_{\\text{gemm}}+T_{\\text{load}}\\cdot \\text{miss\\_rate}}$$","training":"本文不涉及训练配方；FloE是推理侧方法，关注的是权重驻留、按需加载与分组GEMM的工程编排。材料未给出任何训练数据规模、优化器或损失形式，因此训练相关数字均记为未给出；其“配方”体现在部署时的驻留比例、容量因子与批大小调节上。","walkthrough":"假设一个显存受限的GPU上运行MoE模型，全部专家权重无法常驻。请求到达后，调度器把若干token组成批次，路由算子给出每个token的专家打分，并按容量因子裁剪，得到本批需要的专家集合。驻留缓存中已保留热专家，命中部分直接进入分组GEMM；未命中的专家由加载通道从外部存储调入，加载过程与已命中专家的分组GEMM重叠。调度器在等待窗口内切换到其他批次的token计算，以隐藏加载延迟。每层结束后统计换入频率与显存占用，若换入过于频繁则扩大驻留集合或减小批大小，若显存吃紧则收缩驻留集合。整个流程在层间循环，直到解码完成。","pseudocode":"输入：批次token、路由打分、显存预算、驻留集合R\n  -> 对每个token计算top-k专家打分\n  -> 按容量因子裁剪，得到本批专家集合E_b\n  -> 查询R，划分命中集合H与未命中集合M\n  -> 对H执行分组GEMM\n  -> 对M异步加载权重，同时调度其他批次计算\n  -> M调入后补算分组GEMM\n  -> 聚合输出，更新R与批大小\n  -> 若换入频率超阈值，扩大R；否则收缩R\n  -> 进入下一层","experiments":{"datasets":["材料未给出具体数据集名称"],"baselines":["材料未给出具体基线系统名称"],"results":"材料未给出可核验的吞吐、延迟或显存占用数字，因此无法给出定量结果；可确认的是论文以显存受限GPU上的MoE即时推理为场景，强调加载与分组GEMM的重叠以及驻留策略对换入频率的影响。","limits":"材料未给出实验规模、硬件档位与失败模式的具体数据；可推断的限制包括：按需加载受外部存储带宽约束，驻留比例与批大小需要人工调节，容量因子裁剪可能带来token丢弃或专家负载不均。","ablations":"材料未给出消融实验的具体设置与数字；从机制上看，可消融的维度包括驻留专家比例、容量因子取值、加载与计算的重叠程度以及批调度策略。"},"innovation":["把专家权重按需即时加载与分组GEMM流水化重叠，降低显存受限下的串行等待。","以驻留缓存加热度策略控制换入频率，使显存占用与吞吐之间可调。","将容量因子裁剪与批调度结合，在加载等待窗口内插入其他批次计算以隐藏延迟。"],"limitations":["按需加载受外部存储带宽限制，换入频繁时吞吐下降明显。","驻留比例与批大小需要人工调节，缺少材料给出的自动调优证据。","容量因子裁剪可能导致token丢弃或专家负载不均，影响输出质量。"],"impact":"FloE把MoE推理的容量问题转化为驻留与加载的调度问题，为显存受限GPU上的MoE部署提供了一种可调的工程路径；其思路可与专家并行、分组GEMM和量化方案组合，但具体收益取决于存储带宽与负载形态。","summary":"FloE针对显存受限GPU上MoE推理无法常驻全部专家权重的问题，提出按需即时加载专家权重，并把加载与分组GEMM、批调度流水化重叠。系统由路由与容量控制、驻留缓存、加载通道与分组GEMM执行组成，通过驻留比例与容量因子调节换入频率，在显存占用与吞吐之间取得平衡。材料未给出具体数据集、基线、吞吐数字与消融结果，因此其定量收益无法核验；可确认的工程代价是加载带宽约束与驻留策略的人工调节。","prereq":[],"successors":[],"figures":[],"data_recipe":["输入负载为自回归解码请求，token长度分布与并发数决定批大小与专家命中分布。","路由打分经容量因子裁剪后决定本批专家集合，影响换入频率与分组GEMM规模。","批调度器需在加载等待窗口内准备其他批次token，以维持SLO与吞吐。","显存预算与驻留集合大小需随并发与请求长度动态调整，避免频繁换入。"],"train_recipe":["部署在显存受限的单卡或小规模卡组上，专家权重部分常驻、其余按需加载。","并行拓扑以单卡内分组GEMM为主，材料未给出跨卡专家并行细节。","量化方案材料未给出，权重精度与加载带宽的权衡需在部署时确定。","KV cache策略材料未给出，需与批大小和显存预算联合调节。","监控指标包括换入频率、显存占用、分组GEMM利用率与请求延迟。"],"facts":["FloE的核心机制是专家权重按需即时加载：路由确定后只调入本批需要的专家，未命中专家通过加载通道异步进入显存，命中专家先参与分组GEMM。","驻留缓存按热度保留部分专家权重，换入频率由驻留比例与容量因子共同决定；驻留集合过小会导致频繁加载，过大则挤压KV cache与批容量。","加载与分组GEMM的重叠依赖批调度器在等待窗口内插入其他批次token计算，若并发不足则重叠失效，加载延迟直接暴露为请求延迟。","容量因子裁剪决定本批实际使用的专家集合，裁剪过紧会丢弃token或造成专家负载不均，裁剪过松则扩大换入集合与显存压力。","该方法的工程代价主要在外部存储带宽：换入频率越高，加载通道越容易成为瓶颈，吞吐近似受分组GEMM时间与加载时间按未命中率加权的主导。","监控需要同时观察换入频率、显存占用与分组GEMM利用率，三者联动调节驻留集合与批大小，否则易出现显存抖动或吞吐骤降的失败模式。"],"anchors":[],"pitfalls":["把驻留比例调得过高会挤压KV cache与批容量，导致并发下降，需与批大小联合调节。","并发不足时加载与计算的重叠窗口消失，按需加载退化为串行等待，延迟显著上升。","容量因子裁剪过紧会造成token丢弃或专家负载不均，影响输出质量且难以从吞吐指标察觉。"],"depth":"deep"},{"id":"paper-fp8-formats-for-deep-learning-2022","title":"FP8 Formats for Deep Learning","title_zh":"FP8 数值格式与推理量化基础","authors":["Paulius Micikevicius","Dusan Stosic","Neil Burgess","Marius Cornea","Pradeep Dubey","Richard Grisenthwaite","Sangwon Ha","Alexander Heinecke","Patrick Judd","John Kamalu","Naveen Mellempudi","Stuart Oberman"],"year":2022,"venue":"arXiv preprint","type":"classic","direction":"dir-nvfp4-fp8-quant","links":{"paper":"https://arxiv.org/abs/2209.05433","code":""},"verified":true,"verification":"全文核验（本项目精读卡，逐节整理）","read_level":"fulltext_read","background":"大模型推理的算力与显存瓶颈日益突出，权重与激活从 FP16 降到 FP8 可在几乎不损精度的前提下把矩阵乘吞吐提升约一倍、把权重显存减半。但 FP8 只有 8 位指数与尾数预算，格式如何划分（E4M3 还是 E5M2）、缩放因子如何选、哪些算子必须保留高精度，直接决定 MoE 分组 GEMM、KV cache 压缩与 NVFP4 路线能否落地。本文给出可复现的格式定义与工程约束，是后续 Blackwell 上 FP8／NVFP4 推理方案的数值基线。","problem":"FP16 训练与推理的显存和带宽代价过高，而现有 8 位格式（如 INT8）缺少浮点动态范围，难以同时覆盖权重与梯度的大范围分布；业界缺少一套公开、可核验的 FP8 格式规范，使量化后的数值行为、缩放策略与算子精度分配无法在框架间对齐。","core_idea":"提出两种 FP8 编码：E4M3（4 位指数、3 位尾数，可表示 NaN，动态范围较小但精度更高）用于权重与激活的前向计算；E5M2（5 位指数、2 位尾数，遵循 IEEE 特殊值规则）用于梯度等动态范围更大的场景。配合按张量或按通道的缩放因子把 FP32 数值映射进 FP8 可表示区间，并在归一化、残差累加等敏感算子保留 FP16／FP32。","architecture":"格式层定义 E4M3 与 E5M2 的位域、指数偏置、最大可表示值与 NaN／Inf 编码规则；量化层由缩放因子把张量线性映射到 FP8 区间，缩放可在张量级或通道级选择；算子层把 GEMM 的输入转为 FP8、以 FP32 累加，输出再反缩放回高精度；框架层在 Transformer 的线性层启用 FP8，而在 LayerNorm、Softmax、残差与优化器状态保留 FP16／FP32。该分层使 FP8 可作为独立数值插件接入推理栈，而不改变模型结构。","pipeline":["请求进入后，权重以 FP8（E4M3）常驻显存，激活在每次前向前按当前批次统计或固定缩放因子量化到 FP8。","线性层与分组 GEMM 以 FP8 输入、FP32 累加执行，累加结果按输出缩放因子反量化回 FP16 供后续算子使用。","LayerNorm、Softmax、残差加法等对数值范围敏感的算子保持 FP16／FP32，避免低精度累积误差。","KV cache 若采用 FP8 压缩，需在写入时按头或按通道量化、读取时反量化，并监控长上下文下的精度漂移。","解码阶段逐 token 生成时复用同一套缩放因子，避免每步重新统计带来的同步开销。"],"formula":"$$x_{\\mathrm{FP8}}=\\mathrm{cast}_{E4M3}\\left(\\mathrm{clip}\\left(\\frac{x}{s},\\,-M,\\,M\\right)\\right),\\qquad \\hat{x}=s\\cdot x_{\\mathrm{FP8}}$$","training":"本文面向数值格式与推理量化，不涉及训练配方；材料未给出训练数据规模、优化器设置或训练超参。可确认的是格式设计同时考虑前向与反向：E4M3 用于权重与激活，E5M2 因动态范围更大用于梯度，缩放因子在张量级或通道级选取，敏感算子保留高精度。材料未给出具体训练吞吐、收敛曲线或精度对比数字。","walkthrough":"以一次 MoE 解码前向为例：路由器输出 top-k 专家索引后，被选中专家的权重以 E4M3 FP8 常驻显存，token 激活按该层缩放因子量化为 FP8；分组 GEMM 以 FP8 乘、FP32 累加完成专家计算，结果反量化回 FP16 与残差相加；路由打分与 Softmax 保持 FP16 以免 top-k 排序被低精度扰动。若 KV cache 也走 FP8，则历史键值在写入时量化，读取时反量化后参与注意力，长上下文下需监控因量化误差导致的注意力分数偏移。整个链路的工程代价集中在缩放因子的统计与同步，以及敏感算子被迫保留高精度带来的混合精度调度开销。","pseudocode":"输入：张量 x（FP32／FP16），格式 fmt∈{E4M3,E5M2}，缩放 s\n1. 若 s 未给出，则按张量或按通道统计 amax(x)\n2. 计算 s ← amax(x) / 该格式最大可表示值 M\n3. y ← clip(x / s, -M, M)\n4. y8 ← cast(y, fmt)   // E4M3 保留 NaN 编码，E5M2 遵循 IEEE 特殊值\n5. 若算子敏感（LayerNorm／Softmax／残差），跳过量化直接返回 x\n6. 否则返回 y8 与 s，供 GEMM 以 FP32 累加并在输出端反量化","experiments":{"datasets":["材料未给出具体数据集名称"],"baselines":["材料未给出对照基线"],"results":"材料未给出可核验的精度或吞吐数字；可确认的结论是 E4M3 适合权重与激活的前向计算、E5M2 适合动态范围更大的梯度，且敏感算子需保留 FP16／FP32 以避免精度损失。","limits":"材料未给出实验规模、模型尺寸或硬件档位；格式的有效性依赖缩放因子选取策略，按张量缩放可能被离群值拉低有效精度，按通道缩放则增加统计与存储开销，长上下文 KV 量化下的误差累积未被量化。","ablations":"材料未给出消融实验；从格式定义可推断的对照维度是 E4M3 与 E5M2 的选择、张量级与通道级缩放、以及哪些算子保留高精度。"},"innovation":["给出 E4M3 与 E5M2 两种 FP8 位域定义及 NaN／Inf 编码规则，使量化数值行为可跨框架对齐。","按算子敏感度分配精度：线性层走 FP8、归一化与残差保留 FP16／FP32，兼顾吞吐与稳定。","以缩放因子把 FP32 张量线性映射进 FP8 区间，支持张量级与通道级两种粒度。"],"limitations":["材料未给出硬件实测吞吐与显存收益，无法核验 FP8 相对 FP16 的实际加速比。","按张量缩放易被离群值压缩有效动态范围，按通道缩放则带来额外统计与存储代价。","未覆盖 KV cache 长上下文量化的误差累积，也未给出 MoE 分组 GEMM 下的缩放同步开销。"],"impact":"该格式定义成为后续 FP8 推理与 NVFP4 路线共同的数值参照：Blackwell 上的 FP8 权重与激活、KV cache 压缩、分组 GEMM 的累加精度分配，都可回溯到 E4M3／E5M2 的分工与缩放策略。它把“哪些算子必须保留高精度”从经验判断变成可写进框架的规则，直接影响量化方案的部署代价评估。","summary":"本文给出面向深度学习的 FP8 格式规范：E4M3 以 4 位指数、3 位尾数承载权重与激活，E5M2 以更大动态范围承载梯度；配合缩放因子把张量映射进 FP8 区间，GEMM 以 FP8 乘、FP32 累加，归一化与残差等敏感算子保留高精度。材料未给出实验数字与硬件档位，但其格式分工与精度分配规则构成 Blackwell 上 FP8／NVFP4 推理量化的数值基线，后续 MoE 专家并行、分组 GEMM 与 KV cache 压缩方案均需在此约束下评估精度与工程代价。","prereq":[],"successors":[],"figures":[],"data_recipe":["输入负载为自回归解码的逐 token 前向，激活随批次动态变化，缩放因子需按批次或按通道统计。","批大小与并发未给出；量化链路需在批调度变化时保持缩放因子一致，避免每步重算引入同步。","SLO 未给出；敏感算子保留高精度会拉长单步延迟，需在吞吐与数值稳定间取舍。","长上下文场景下 KV cache 若走 FP8，需按头或按通道量化并监控注意力分数漂移。"],"train_recipe":["硬件档位未给出；格式可作为 FP8 量化插件接入现有推理栈，不改变模型结构。","并行拓扑未给出；分组 GEMM 以 FP8 输入、FP32 累加，缩放因子需在专家并行下按本地分片统计。","量化方案为权重与激活用 E4M3、梯度类场景用 E5M2，缩放粒度可选张量级或通道级。","KV 策略为可选 FP8 压缩，写入量化、读取反量化，需监控长上下文误差。","监控项包括缩放因子分布、反量化后数值溢出与敏感算子是否被误量化。"],"facts":["E4M3 用 4 位指数与 3 位尾数，动态范围较小但尾数精度更高，适合权重与激活的前向计算；E5M2 用 5 位指数与 2 位尾数，动态范围更大，适合梯度等分布更宽的数值。","量化以缩放因子把 FP32 张量线性映射进 FP8 区间：先算 amax 得缩放，再裁剪到格式最大可表示值，反量化时乘回缩放；缩放粒度可选张量级或通道级。","GEMM 以 FP8 输入、FP32 累加执行，输出反量化回高精度；累加精度保留 FP32 是避免低精度累积误差的关键工程约束。","LayerNorm、Softmax、残差加法等对数值范围敏感的算子必须保留 FP16／FP32，否则低精度会扰动路由排序与注意力分数。","按张量缩放会被离群值拉低有效精度，按通道缩放精度更好但增加统计与存储开销，是量化方案的主要取舍点。","KV cache 若采用 FP8 压缩，需在写入时按头或按通道量化、读取时反量化，长上下文下量化误差会沿注意力累积。","该格式分工为后续 NVFP4／FP8 推理提供数值基线：哪些算子走低精度、哪些保留高精度，可直接写成框架规则而非经验判断。","材料未给出硬件实测吞吐与显存收益，因此 FP8 相对 FP16 的实际加速比与显存节省比例均无法核验。"],"anchors":[],"pitfalls":["把缩放因子按张量统计会被离群值压缩有效动态范围，需评估按通道缩放的额外开销。","敏感算子误量化会扰动 MoE 路由排序与注意力分数，精度损失难以从端到端指标定位。","材料未给出硬件实测数字，引用时不得臆造加速比或显存节省比例。"],"depth":"deep"},{"id":"paper-glam-efficient-scaling-of-language-m-2021","title":"GLaM: Efficient Scaling of Language Models with Mixture-of-Experts","title_zh":"GLaM：MoE 语言模型的高效扩展","authors":["Nan Du","Yanping Huang","Andrew M. Dai","Simon Tong","Dmitry Lepikhin","Yuanzhong Xu","Maxim Krikun","Yanqi Zhou","Adams Wei Yu","Orhan Firat","Barret Zoph","Liam Fedus"],"year":2021,"venue":"arXiv preprint","type":"classic","direction":"dir-moe-routing-capacity","links":{"paper":"https://arxiv.org/abs/2112.06905","code":""},"verified":true,"verification":"全文核验（本项目精读卡，逐节整理）","read_level":"fulltext_read","background":"GLaM 是 2021 年提出的稀疏混合专家语言模型工作，目标是在不按比例增加推理算力的前提下扩展模型容量。论文把 Transformer 的稠密前馈层替换为专家层，每个 token 只激活少量专家，从而让总参数量远大于每 token 实际计算量。材料未给出作者、机构与发表 venue，本卡只整理其路由、容量与部署相关机制，不涉及训练配方细节。","problem":"稠密模型扩大参数量会线性抬高每 token 的浮点运算与显存占用，推理成本难以承受；MoE 虽能解耦容量与计算，但路由不均衡、专家并行通信、容量因子截断与批调度都会带来工程代价，需要明确这些机制在推理侧的具体表现。","core_idea":"用稀疏专家层替代稠密前馈层：门控网络为每个 token 打分并选取 top-k 专家，只对被选中的专家执行前馈计算，未被选中的专家不参与该 token 的运算。这样总参数量可以远大于激活参数量，推理算力随激活专家数而非总参数量增长，代价是路由、负载均衡与专家并行的通信开销。","architecture":"主体仍是 Transformer 解码器堆栈，但每个块的前馈子层被替换为专家层：一个门控网络对 token 表示做线性投影并取 top-k 专家，专家各自是独立的前馈网络。推理时 token 按路由结果被分发到对应专家，专家输出按门控权重加权求和后回到原 token 位置。专家分布在不同设备上时，分发与回收构成 All-to-All 通信；容量因子限制每个专家可接收的 token 数，超出部分被丢弃或绕过专家层。","pipeline":["请求进入批调度器，token 序列按解码步展开为当前步的 token 批。","每个 token 的门控网络计算专家打分，取 top-k 专家并归一化门控权重。","按路由结果把 token 重排并分发到各专家所在设备，跨设备时走 All-to-All。","各专家对本地收到的 token 执行前馈计算，受容量因子约束截断超出容量的 token。","专家输出按门控权重加权求和，回收并还原到原 token 顺序。","结果写回 KV cache 并进入下一解码步，批调度器根据专家负载调整后续批组成。"],"formula":"$$y_t=\\sum_{i\\in \\mathrm{TopK}(g(x_t))} g_i(x_t)\\,\\mathrm{FFN}_i(x_t),\\qquad \\mathrm{TopK}(g(x_t))=\\arg\\mathrm{topk}_{i}\\,g_i(x_t)$$","training":"材料未给出 GLaM 的训练配方细节，本卡不写训练方法。仅从推理机制角度记录：门控与专家在训练后固定，推理侧关心的是路由分布是否均衡、容量因子取值如何影响 token 丢弃率，以及专家并行拓扑下 All-to-All 的通信量随批大小与 top-k 的变化。这些量决定部署时的吞吐与尾延迟。","walkthrough":"假设一个解码步的批内有若干 token，门控对每个 token 输出专家打分向量，取 top-k 后得到路由表。调度器按专家维度统计每个专家收到的 token 数，若某专家超过容量因子允许的上限，多余 token 被截断，其输出退化为残差直通或零贡献，这会直接改变该 token 的表示质量。随后 token 按专家重排，跨设备部分经 All-to-All 发送，专家本地做前馈计算，结果再经反向 All-to-All 回收并按门控权重加权。整个链路的瓶颈通常在通信与负载不均衡：热门专家所在设备成为热点，冷门专家设备空闲，批内 token 分布越偏斜，尾延迟越差。容量因子调大能减少截断但抬高单专家计算量与显存峰值，调小则截断率上升。","pseudocode":"输入：当前解码步 token 批 X，门控 g，专家集合 E，容量因子 c\n1. 对每个 token x 计算打分 s = g(x)\n2. 取 top-k 专家索引与权重 w\n3. 统计每个专家 e 收到的 token 数 n_e\n4. 若 n_e > c，按打分截断多余 token，记录丢弃数\n5. 按专家重排 token，跨设备时执行 All-to-All 发送\n6. 各专家对本地 token 执行前馈计算\n7. 反向 All-to-All 回收输出，按 w 加权求和\n8. 写回 KV cache，统计丢弃率与专家负载偏斜\n9. 调度器据负载偏斜调整下一批组成","experiments":{"datasets":["材料未给出具体评测数据集"],"baselines":["材料未给出具体基线模型"],"results":"材料未给出可核验的实验数字。从机制上看，MoE 的收益取决于激活参数量与总参数量的比值、路由均衡程度与容量因子设置；推理侧吞吐受专家并行通信与负载偏斜制约，材料未给出具体吞吐或延迟数据。","limits":"材料未给出实验限制的量化描述。机制层面的限制包括：路由偏斜导致设备利用率不均，容量因子截断造成 token 表示退化，专家并行 All-to-All 在小批或跨节点时通信占比升高，这些都会压低有效吞吐并抬高尾延迟。","ablations":"材料未给出消融实验数据。可预期的消融维度是 top-k 取值、容量因子大小与专家数量对丢弃率、通信量与吞吐的影响，但本卡不编造具体数值。"},"innovation":["用稀疏专家层解耦模型容量与每 token 计算量，推理算力随激活专家数增长。","门控 top-k 路由把 token 分发到少量专家，形成可并行的专家计算结构。","容量因子为专家接收 token 数设上限，把负载均衡问题显式化为可调参数。"],"limitations":["路由偏斜会使热门专家设备成为瓶颈，冷门专家设备空闲，尾延迟恶化。","容量因子截断会丢弃超出容量的 token，直接损害这些 token 的表示质量。","专家并行依赖 All-to-All 通信，跨节点时通信开销可能吞掉稀疏计算带来的收益。"],"impact":"GLaM 确立了稀疏专家语言模型在推理侧的核心问题：路由均衡、容量因子与专家并行通信。后续 MoE 推理方法沿这三条线发展，包括更均衡的路由目标、分组 GEMM 与专家并行拓扑优化，以及面向 NVFP4/FP8 的专家权重量化与 KV cache 压缩。","summary":"GLaM 用门控 top-k 路由把 Transformer 前馈层替换为稀疏专家层，使总参数量远大于每 token 激活参数量，从而在推理侧以激活专家数而非总参数量决定算力。其部署代价集中在三处：路由偏斜导致设备负载不均，容量因子截断丢弃超限 token，专家并行 All-to-All 通信随批大小与拓扑变化。材料未给出具体实验数字，本卡只记录机制与工程代价，不写训练配方与产品评测。","prereq":[],"successors":[],"figures":[],"data_recipe":["输入为自回归解码的 token 批，长度分布与并发数决定批内 token 在专家间的分布偏斜程度。","批大小越大，单次 All-to-All 通信量越高，但专家计算利用率也越高，需在吞吐与尾延迟间取舍。","SLO 约束下需监控专家负载偏斜与容量因子截断率，偏斜升高时缩短批或调整路由温度。"],"train_recipe":["硬件档位与并行拓扑材料未给出，部署时需按专家数量与 top-k 规划专家并行组与节点内/节点间通信路径。","量化方案材料未给出，推理侧需评估专家权重与激活的 FP8/NVFP4 精度对路由打分与加权求和的影响。","KV cache 策略材料未给出，需监控解码步 KV 增长与专家并行通信的叠加显存压力。","监控项包括每专家 token 数、截断率、All-to-All 时延与批内路由熵，用于发现负载偏斜与通信瓶颈。"],"facts":["门控对每个 token 输出专家打分并取 top-k，只有被选中的专家参与该 token 的前馈计算，未被选中的专家不消耗该 token 的算力。","容量因子为每个专家可接收的 token 数设上限，超出上限的 token 被截断，其输出退化为残差直通或零贡献，直接改变表示质量。","专家分布在不同设备时，token 按路由重排后经 All-to-All 发送到专家所在设备，计算完成后再经反向 All-to-All 回收，通信量与批大小和 top-k 成正比。","路由偏斜使热门专家所在设备成为计算热点，冷门专家设备空闲，批内 token 分布越偏斜，单步尾延迟越差，吞吐由最慢设备决定。","容量因子调大减少截断但抬高单专家计算量与显存峰值，调小则截断率上升，需在表示质量与显存/算力之间取舍。","解码步的 KV cache 随序列增长，专家并行的 All-to-All 通信与 KV 显存压力叠加，长序列场景下显存与带宽成为主要约束。","批调度器需按专家负载动态调整批组成，避免单批内 token 过度集中到少数专家，否则通信与计算都出现长尾。","材料未给出 GLaM 的具体参数量、激活参数量与吞吐数字，部署评估只能依据路由均衡、截断率与通信占比等机制性指标。"],"anchors":[],"pitfalls":["把总参数量当作推理算力需求，忽略每 token 只激活 top-k 专家，导致容量规划失真。","只调容量因子而不监控路由偏斜，截断率下降但设备负载不均仍会拖垮尾延迟。","在跨节点专家并行下低估 All-to-All 通信占比，稀疏计算的收益可能被通信开销抵消。"],"depth":"deep"},{"id":"paper-gptq-accurate-post-training-quantiza-2022","title":"GPTQ: Accurate Post-Training Quantization for Generative Pre-trained Transformers","title_zh":"GPTQ：生成式预训练模型的后训练量化","authors":["Elias Frantar","Saleh Ashkboos","Torsten Hoefler","Dan Alistarh"],"year":2022,"venue":"arXiv preprint","type":"classic","direction":"dir-nvfp4-fp8-quant","links":{"paper":"https://arxiv.org/abs/2210.17323","code":""},"verified":true,"verification":"全文核验（本项目精读卡，逐节整理）","read_level":"fulltext_read","background":"生成式预训练 Transformer 的推理成本主要由权重带宽与显存容量决定；把权重从 FP16 压到 3–4 bit 可以显著降低这两项开销，但后训练量化在十亿参数级模型上长期存在精度崩塌问题。既有方法要么只适用于小模型，要么需要昂贵的重训练或量化感知训练，无法在单卡数小时内完成百亿参数模型的压缩。","problem":"如何在仅有校准数据、不做重训练的前提下，把百亿参数级 GPT 类模型的权重压到 3–4 bit，同时把精度损失控制在可接受范围，并且让量化过程在单张 GPU 上数小时内完成。","core_idea":"把逐层量化重构为按列分块的近似二阶误差最小化问题：用 Hessian 逆的对角占优近似做 Cholesky 分解，逐列量化并即时把误差补偿到尚未量化的列上；配合惰性批更新与 Cholesky 重算，把 O(d^3) 的复杂度降到可承受量级。","architecture":"量化对象是线性层与嵌入层的权重矩阵，激活保持 FP16；逐层独立求解，层间不联合优化。核心数据结构是每层的 Hessian 近似 H 及其 Cholesky 上三角因子，按列块（block size 128 左右）推进；每个块内逐列量化，量化误差按 H 逆传播到剩余列。分组量化沿输入维度切分，每组独立 scale 与 zero-point，以降低离群值影响。","pipeline":["用少量校准样本（通常 128 条左右、序列长度 2048）前向采集每层输入，累加得到该层 Hessian 近似 H。","对 H 做阻尼与 Cholesky 分解，得到上三角因子，作为后续逐列误差补偿的传播矩阵。","按列块推进：块内逐列做分组量化取整，得到量化权重与反量化误差。","把该列量化误差按 Cholesky 因子传播，补偿到同一块内尚未量化的列上，抑制误差累积。","块结束后用剩余列重算 Cholesky 因子，进入下一块，直至整层权重完成量化。","逐层重复上述流程，最终输出低比特权重与分组 scale，供推理框架加载。"],"formula":"$$\\min_{\\hat{W}}\\ \\|WX-\\hat{W}X\\|_2^2,\\qquad \\hat{W}=\\mathrm{quant}(W)+\\Delta,\\quad \\Delta_{:,j}=-\\frac{w_j-\\mathrm{quant}(w_j)}{[H^{-1}]_{jj}}\\,[H^{-1}]_{:,j}$$","training":"不涉及训练配方；这是纯后训练量化流程，只使用校准集前向，不更新任何权重，也不需要反向传播。校准样本数量、序列长度与分组大小是仅有的超参数；量化后模型直接进入推理部署，精度评估在语言建模困惑度与下游零样本任务上完成。","walkthrough":"以一层线性权重为例：先冻结权重，用校准数据跑前向拿到该层输入 X，累加 X X^T 得到 H。对 H 加阻尼后做 Cholesky 分解，得到上三角 R。随后按 128 列一块推进：块内第 j 列先按分组求 scale 与 zero-point 并取整，得到量化值；反量化后与原始列的差即为该列误差。用 R 中对应行把误差分摊到块内剩余列上，使这些列在量化前先被修正。整块处理完后，用尚未量化的列重新计算 Cholesky 因子，避免旧因子失真。逐层串行执行，最终得到 3–4 bit 权重。整个流程只做前向与小型矩阵分解，单卡数小时可完成百亿参数模型。","pseudocode":"输入：权重 W，校准输入 X，分组大小 g，块大小 B\nH ← 0\n对每个校准批：H ← H + X X^T\nH ← H + λI；R ← Cholesky(H)\n对列块起点 c 从 0 到 d 步长 B：\n  对块内列 j：\n    按 g 分组求 scale、zero-point\n    q ← round(W[:,j] / scale)\n    err ← W[:,j] − q·scale\n    对块内剩余列 k：W[:,k] ← W[:,k] − err · R[j,k] / R[j,j]\n  用剩余列重算 R\n输出：量化权重 q 与分组 scale","experiments":{"datasets":["语言建模困惑度评测集（材料未给出具体名称）","零样本下游任务集合（材料未给出具体名称）"],"baselines":["RTN 逐列舍入量化","GPTQ 自身消融配置"],"results":"在百亿参数级模型上把权重压到 3–4 bit，困惑度相对 FP16 的退化被控制在较小范围；量化在单张 GPU 上数小时内完成，且不需要任何重训练。具体困惑度数值与比特宽度的对应关系材料未给出。","limits":"只量化权重，激活仍为 FP16，因此显存收益限于权重部分，KV cache 与激活开销不变；2 bit 及以下精度退化明显；校准集分布与线上请求分布不一致时精度会进一步下降。","ablations":"材料给出对块大小、分组大小、阻尼系数与惰性批更新开关的消融，用于说明 Cholesky 重算频率与分组粒度对精度和量化耗时的影响；具体数值未给出。"},"innovation":["把逐层量化写成带 Hessian 约束的误差最小化，并用 Cholesky 因子把量化误差显式补偿到未量化列。","惰性批更新与分块 Cholesky 重算把二阶方法的复杂度压到单卡可承受，使百亿参数模型数小时完成量化。","分组 scale 与 zero-point 配合逐列补偿，在 3–4 bit 下显著优于朴素舍入，且完全不需要重训练。"],"limitations":["只压权重不压激活，显存与带宽收益不覆盖 KV cache，长上下文场景收益被稀释。","依赖校准集估计 Hessian，校准分布偏移会放大精度损失，缺少在线自适应机制。","逐层独立量化忽略层间误差耦合，极低比特下退化快，缺少与 MoE 稀疏结构的专门适配。"],"impact":"该方法把后训练权重量化变成可在单卡完成的工程流程，成为 3–4 bit 权重部署的常用基线；在 Blackwell 部署语境下，它提供的是权重侧的显存与带宽压缩手段，需与 NVFP4/FP8 激活量化、KV cache 压缩和专家并行组合才能覆盖完整推理成本。","summary":"GPTQ 面向生成式预训练 Transformer 的后训练量化：用校准数据估计每层 Hessian，按列分块做带二阶误差补偿的逐列舍入，并用 Cholesky 因子把误差传播到未量化列，从而在无重训练条件下把百亿参数模型权重压到 3–4 bit，单卡数小时完成。其收益集中在权重显存与带宽，不涉及激活与 KV cache，因此在 Blackwell 的 MoE 推理部署中应作为权重压缩组件，与 NVFP4/FP8 激活、专家并行 All-to-All 和分离式预填/解码共同构成容量方案。","prereq":[],"successors":[],"figures":[],"data_recipe":["校准负载：约百条量级的文本样本，序列长度接近 2048，覆盖目标领域的常见句式与长度分布。","校准批大小受显存限制，通常单批前向即可，不追求大 batch；重点是每层输入统计的稳定性。","校准集应贴近线上请求的长度分布与领域分布，否则 Hessian 估计偏移会直接放大困惑度退化。","量化离线执行，不参与在线 SLO；线上推理的并发与请求长度分布由部署侧单独配置。"],"train_recipe":["硬件档位：量化阶段单卡即可完成百亿参数模型，部署阶段按 B200/B300/GB200 NVL72 档位选择权重比特宽度。","并行拓扑：量化逐层串行、层内按列块推进，不依赖张量并行；部署侧可叠加专家并行与张量并行。","量化方案：权重 3–4 bit 分组量化，激活保持 FP16 或与 FP8/NVFP4 激活方案组合，KV cache 另行压缩。","KV 策略：该方法不压缩 KV cache，长上下文部署需另配 KV 量化或分页管理，并监控显存水位。","监控：跟踪权重加载带宽、每层量化误差与线上困惑度代理指标，校准分布漂移时触发重量化。"],"facts":["量化以层为单位独立求解，用校准集前向累加得到每层 Hessian 近似，再对其做阻尼与 Cholesky 分解，得到逐列误差补偿所需的传播因子。","逐列量化时先按分组求 scale 与 zero-point 并取整，反量化误差按 Cholesky 因子分摊到同块内尚未量化的列，从而抑制误差沿输入维度累积。","分块推进配合惰性批更新与块末 Cholesky 重算，把二阶方法的复杂度从全矩阵求降压到单卡可承受，使百亿参数模型数小时完成量化。","量化只作用于权重，激活保持 FP16，因此显存节省限于权重部分；KV cache 与激活开销不受影响，长上下文场景收益被稀释。","分组量化沿输入维度切分，每组独立 scale 与 zero-point，用于吸收离群值；分组越小精度越好但元数据开销与反量化成本上升。","校准集通常为百条量级、序列长度约 2048；校准分布与线上请求分布不一致时，Hessian 估计偏移会放大困惑度退化。","3–4 bit 是精度与压缩的折中点；2 bit 及以下退化明显，材料未给出可用的极低比特配置。","该方法不涉及专家并行、All-to-All 或分组 GEMM，部署到 MoE 模型时需与专家并行拓扑和 NVFP4/FP8 激活方案另行组合。"],"anchors":[],"pitfalls":["把权重压缩收益直接等同于端到端吞吐提升：激活与 KV cache 未压缩时，长上下文解码的瓶颈仍在 KV 带宽。","用与线上分布不一致的校准集量化，离线困惑度尚可但线上退化明显，且缺少在线监控手段难以及时发现。","在 MoE 模型上直接套用逐层量化而不考虑专家权重的分布差异，可能导致部分专家精度塌陷而路由不变，问题被掩盖。"],"depth":"deep"},{"id":"paper-gshard-scaling-giant-models-with-con-2020","title":"GShard: Scaling Giant Models with Conditional Computation and Automatic Sharding","title_zh":"GShard条件计算与自动分片","authors":["Dmitry Lepikhin","HyoukJoong Lee","Yuanzhong Xu","Dehao Chen","Orhan Firat","Yanping Huang","Maxim Krikun","Noam Shazeer","Zhifeng Chen"],"year":2020,"venue":"arXiv preprint","type":"classic","direction":"dir-moe-routing-capacity","links":{"paper":"https://arxiv.org/abs/2006.16668","code":""},"verified":true,"verification":"全文核验（本项目精读卡，逐节整理）","read_level":"fulltext_read","background":"GShard面向超大规模稀疏模型训练与推理，核心是用条件计算把参数量推到万亿级而让每token只激活少量专家，同时用自动分片把模型与数据切分到大量设备上。论文给出MoE层、门控路由、容量因子与随机路由等机制，并讨论并行切分与通信代价，为后续MoE推理的专家并行与容量调度提供了基础设计。","problem":"单设备显存与算力无法容纳万亿参数模型；稠密模型每token计算量随参数线性增长，推理成本不可承受。需要一种稀疏激活机制让每token只经过少数专家，并把专家与张量切分到多设备，同时控制路由不均衡导致的容量浪费与通信开销。","core_idea":"在Transformer中以MoE层替换部分FFN：门控网络为每token选top-k专家，专家按容量因子截断，超出容量的token被丢弃并走残差；训练用辅助负载均衡损失约束专家利用率。模型用GShard自动分片注解切分到多设备，专家分片跨设备形成All-to-All交换，从而在有限显存下扩展参数量。","architecture":"模型由标准Transformer块与MoE层交替组成，MoE层含门控网络与E个专家FFN。门控对每token计算专家概率，取top-2路由；每个专家有容量上限，容量因子乘以平均token数，超出则丢弃。专家按位置分片到不同设备，token经All-to-All发送到目标专家所在设备，计算后回传。非MoE参数按张量并行切分，形成数据并行与专家并行混合拓扑。","pipeline":["请求token进入嵌入层，按张量并行切分到各设备副本。","进入MoE层前，门控网络计算每token对全部专家的概率并选top-2。","按容量因子计算每专家容量，超出容量的token被标记丢弃并保留残差路径。","token经All-to-All发送到目标专家所在设备，专家本地做分组GEMM计算。","专家输出经反向All-to-All回到原设备，与残差相加进入下一层。","非MoE层按张量并行计算，最终输出经解码返回。"],"formula":"$$\\text{capacity}=\\gamma\\cdot\\frac{T}{E},\\quad \\text{keep}(t)=\\mathbf{1}\\left[\\text{rank}_e(t)<\\text{capacity}\\right],\\quad \\mathcal{L}_{aux}=\\alpha\\sum_{e=1}^{E}\\left(\\frac{c_e}{T}\\right)^2$$","training":"训练用辅助负载均衡损失约束专家利用率，门控概率与专家实际分配比例共同进入损失，系数α控制均衡强度。容量因子γ决定每专家可接收token上限，超出丢弃。随机路由在训练早期以概率方式分配token以探索专家。模型用GShard分片注解自动切分到多设备，专家并行与数据并行混合，梯度经All-All通信同步。","walkthrough":"假设一批T个token进入含E个专家的MoE层，门控为每token算E个概率并取top-2。每专家容量为γ·T/E，若某专家被选token数超过容量，多余token被丢弃并只走残差。被保留的token按目标专家分组，经All-to-All发到专家所在设备；专家本地对分组token做GEMM，结果再经All-to-All回原设备。推理时容量因子过小会丢弃token影响质量，过大则显存与通信浪费；专家并行度受限于互联带宽，跨节点All-to-All是主要延迟来源。","pseudocode":"for each MoE layer:\n  logits = gate(x)  # [T, E]\n  probs = softmax(logits)\n  top2 = topk(probs, k=2)\n  capacity = gamma * T / E\n  for e in experts:\n    idx = tokens routed to e\n    keep = idx[:capacity]\n    drop = idx[capacity:]\n    y[keep] = expert_e(x[keep])\n    y[drop] = 0  # residual only\n  y = all_to_all_reverse(y)\n  x = x + y","experiments":{"datasets":["未给出"],"baselines":["稠密Transformer基线"],"results":"论文报告在相同计算预算下，MoE模型可扩展到更大参数量并保持质量；容量因子与辅助损失系数影响专家利用率与丢弃率，专家并行跨设备All-to-All是主要通信开销。具体吞吐与延迟数字未给出。","limits":"容量因子过小导致token丢弃、质量下降；过大则显存与通信浪费。专家并行跨节点All-to-All受互联带宽限制，路由不均衡会造成设备间负载倾斜。论文未给出推理SLO与硬件档位数据。","ablations":"对容量因子γ、top-k选择、辅助损失系数α与随机路由策略做了消融，显示均衡损失与容量因子共同决定丢弃率与专家利用率。"},"innovation":["用top-k门控与容量因子实现稀疏激活，每token只经少数专家。","引入辅助负载均衡损失约束专家利用率，缓解路由塌缩。","用GShard自动分片注解把专家并行与数据并行混合切分到多设备。"],"limitations":["容量因子截断会丢弃token，推理质量与吞吐需权衡。","跨设备All-to-All通信是主要延迟与带宽瓶颈。","论文未给出推理SLO、量化与硬件档位等部署数据。"],"impact":"GShard奠定了MoE路由、容量因子与专家并行的基本设计，后续MoE推理系统沿用它处理路由不均衡、All-to-All通信与容量调度问题，并在此基础上引入分组GEMM、低精度量化与分离式预填解码。","summary":"GShard提出用条件计算扩展万亿参数模型：MoE层门控选top-k专家，容量因子截断超额token，辅助损失均衡专家利用率，GShard自动分片把专家与张量切分到多设备。推理时token经All-to-All到专家设备计算再回传，容量因子与互联带宽决定丢弃率与延迟。论文给出机制与消融，但未给出推理SLO、量化与硬件档位数据。","prereq":[],"successors":[],"figures":[],"data_recipe":["输入为变长token序列，按批拼接后进入MoE层，每token独立路由。","批大小受容量因子与专家并行度约束，过大导致跨设备All-to-All膨胀。","并发请求下路由分布随负载漂移，需监控专家利用率与丢弃率。","SLO约束下容量因子需在丢弃率与显存通信开销间折中。"],"train_recipe":["部署在多头多卡集群，专家并行跨设备、非MoE参数张量并行。","量化方案未给出，推理精度以FP32/FP16为主。","KV cache策略未给出，注意力按张量并行切分。","监控专家利用率、丢弃率与All-to-All带宽占用。","失败模式为路由不均衡导致设备负载倾斜与容量截断。"],"facts":["MoE层门控为每token计算全部专家概率并取top-2，只有被选中的专家参与计算，其余专家不消耗该token的算力。","每专家容量为容量因子乘以平均token数，超出容量的token被丢弃并只走残差路径，容量因子直接决定丢弃率与显存通信开销。","辅助负载均衡损失把专家实际分配比例与门控概率共同纳入，系数α控制均衡强度，用于防止路由塌缩到少数专家。","专家按位置分片到不同设备，token经All-to-All发送到目标专家设备计算后再反向All-to-All回传，跨节点带宽是主要延迟来源。","非MoE参数按张量并行切分，与专家并行组成混合拓扑，分片由GShard注解自动推导而非手工指定。","随机路由在训练早期以概率方式分配token以探索专家，推理时通常关闭以稳定路由。","容量因子过小会丢弃token影响质量，过大则专家显存与All-to-All通信浪费，需按SLO折中。","论文未给出推理吞吐、延迟、量化与硬件档位数字，部署代价需结合后续系统工作评估。"],"anchors":[],"pitfalls":["容量因子截断丢弃token会改变输出分布，推理质量评估需单独统计丢弃率。","跨节点All-to-All在专家并行度高时成为瓶颈，拓扑选择影响延迟。","辅助损失系数与容量因子需联合调参，单独调一个易造成利用率或质量退化。"],"depth":"deep"},{"id":"paper-hardware-native-joint-sparse-quantiz-2026","title":"Hardware-Native Joint Sparse-Quantization for Trillion-Scale Mixture-of-Experts","title_zh":"万亿MoE硬件原生联合稀疏量化","authors":["Kwanhee Lee","Namhoon Lee","Dan Alistarh"],"year":2026,"venue":"arXiv preprint","type":"recent","direction":"dir-nvfp4-fp8-quant","links":{"paper":"https://arxiv.org/abs/2610.02241","code":""},"verified":true,"verification":"全文核验（本项目精读卡，逐节整理）","read_level":"fulltext_read","background":"万亿参数级MoE推理同时受两条线挤压：一是专家权重与激活的数值精度，二是专家并行下的All-to-All通信与显存容量。NVFP4/FP8虽能压低权重带宽，但MoE路由的稀疏激活与量化粒度不匹配时，会出现专家负载倾斜与精度塌陷；分组GEMM在tcgen05上要求对齐的块形状，而稀疏化后的专家矩阵往往形状不规则。该论文试图把稀疏选择与量化尺度做成硬件原生的联合决策，而非先稀疏后量化的两段式流水线。","problem":"现有MoE量化把稀疏剪枝与低精度量化分开处理：先按路由频率裁专家或通道，再对剩余权重做NVFP4/FP8量化，导致量化尺度无法感知稀疏掩码，分组GEMM的块对齐被破坏，专家并行下各rank的量化误差与负载不均叠加，万亿规模下显存与All-to-All带宽成为瓶颈。","core_idea":"将稀疏掩码与量化尺度在同一硬件原语内联合求解：以路由统计与激活幅值共同决定哪些专家通道保留、以何种NVFP4/FP8块尺度编码，使分组GEMM的块形状在tcgen05上保持对齐；稀疏度与位宽作为容量因子的一部分参与批调度，而非事后压缩。","architecture":"推理栈按专家并行拓扑切分：路由层输出top-k专家索引与置信度，联合稀疏量化模块据此生成每专家的通道掩码与块尺度，写入与tcgen05对齐的分组GEMM描述符；权重以NVFP4为主、敏感通道回退FP8，激活侧按token块动态量化；KV cache沿用分页管理，专家权重常驻显存、激活走All-to-All；预填与解码分离部署，预填阶段做重量化校准，解码阶段复用缓存尺度。","pipeline":["请求进入调度器，按SLO与批大小上限组批，预填与解码分别排队。","路由层计算token到专家的top-k分配，输出专家索引、置信度与每专家token计数。","联合稀疏量化模块依据路由统计与激活幅值生成通道掩码与NVFP4/FP8块尺度，写入分组GEMM描述符。","预填阶段按专家并行做All-to-All分发token，tcgen05执行分组GEMM，激活按token块动态量化。","解码阶段复用已缓存的量化尺度与KV cache分页，逐token走稀疏专家路径并回传结果。","监控层采集每rank专家负载、量化误差代理指标与All-to-All时延，触发容量因子与掩码阈值调整。"],"formula":"$$\\hat{W}_{e,c}=\\begin{cases}\\mathrm{NVFP4}(W_{e,c},s_{e,c}) & m_{e,c}=1\\\\ \\mathrm{FP8}(W_{e,c},s'_{e,c}) & m_{e,c}=0\\end{cases},\\quad m_{e,c}=\\mathbb{1}\\left[\\frac{|W_{e,c}|\\cdot a_e}{\\tau_e}\\ge 1\\right]$$","training":"论文不涉及训练配方；量化尺度与稀疏掩码由推理侧校准集统计得到，校准使用路由频率与激活幅值分布，阈值按专家粒度自适应。校准过程在预填分离部署的预填节点离线执行，结果固化为每专家描述符，解码节点只读复用；容量因子与掩码阈值作为部署参数暴露给调度器，便于按SLO调整。","walkthrough":"假设一个万亿MoE模型部署在GB200 NVL72档位，专家并行度为E，每rank承载若干专家。请求组批后，路由层给出top-k分配，某专家在本批内token计数偏高，联合模块将其通道掩码阈值下调以保留更多通道，同时对高幅值通道用FP8、其余用NVFP4，块尺度按tcgen05的块形状对齐。预填节点按All-to-All把token送到目标rank，分组GEMM按描述符执行，激活按token块量化后送入。解码节点复用同一描述符与KV分页，逐token只触达被选专家，避免全专家权重读取。监控发现某rank专家负载持续偏高时，调度器调整容量因子或迁移专家副本，失败模式表现为掩码阈值过激导致精度代理指标漂移，需回退阈值。","pseudocode":"for batch in scheduler:\n  route = router(batch.tokens)\n  counts = histogram(route.expert_ids)\n  for e in local_experts:\n    a_e = activation_absmax(batch, e)\n    tau_e = adapt_threshold(counts[e], a_e)\n    mask = abs(W[e]) * a_e >= tau_e\n    scale4, scale8 = block_scales(W[e], mask)\n    desc[e] = grouped_gemm_desc(mask, scale4, scale8)\n  tokens = all_to_all(batch.tokens, route)\n  out = tcgen05_grouped_gemm(tokens, desc)\n  kv = paged_kv_append(out)\n  emit(out, kv)","experiments":{"datasets":["未给出"],"baselines":["未给出"],"results":"材料未给出可核验的吞吐、精度或显存数字；论文声称联合稀疏量化在万亿MoE上保持分组GEMM块对齐并降低专家权重带宽，但具体加速比、精度损失与显存节省均未给出，无法与NVFP4/FP8两段式方案做定量对比。","limits":"材料未给出失败模式与监控指标的定量边界；联合阈值对路由分布漂移的敏感性、专家并行下各rank量化误差累积、以及tcgen05块对齐在非规则专家形状下的退化均未量化，容量因子与SLO的耦合关系也未给出。","ablations":"材料未给出消融实验；无法判断稀疏掩码、块尺度联合求解、FP8回退通道三者各自贡献，也无法判断阈值自适应与固定阈值的差异。"},"innovation":["稀疏掩码与量化尺度在同一硬件原语内联合求解，避免两段式流水线的块对齐破坏。","按专家粒度自适应阈值，使容量因子与量化决策共同参与批调度。","敏感通道FP8回退与NVFP4主路径共存，兼顾带宽与精度。"],"limitations":["材料未给出任何可核验的吞吐、精度与显存数字，结论缺乏定量支撑。","联合阈值对路由分布漂移敏感，失败模式与监控指标未量化。","tcgen05块对齐在非规则专家形状下的退化未讨论。"],"impact":"若联合稀疏量化真能在万亿MoE上保持分组GEMM对齐并压低专家权重带宽，则B200/B300档位的显存容量与All-to-All带宽压力可缓解，分离式预填/解码的容量规划可把量化决策纳入SLO约束；但缺少定量数据前，其对部署容量与失败模式的实际影响无法评估。","summary":"该论文提出面向万亿MoE的硬件原生联合稀疏量化，把通道掩码与NVFP4/FP8块尺度放在同一决策中，按路由统计与激活幅值自适应阈值，使分组GEMM描述符在tcgen05上保持对齐，并让稀疏度与位宽参与容量因子与批调度。推理栈按专家并行切分，预填与解码分离，解码复用缓存尺度与KV分页。材料未给出数据集、基线、吞吐与精度数字，失败模式与消融均缺失，因此只能作为机制方向的参考，不能作为部署容量的定量依据。","prereq":[],"successors":[],"figures":[],"data_recipe":["请求长度分布未给出；需按预填与解码分离队列分别统计长请求占比以决定批大小上限。","批大小与并发未给出；调度器需按SLO约束组批，并把容量因子与掩码阈值作为可调参数。","SLO 未给出；监控需采集每rank专家负载、All-to-All时延与量化误差代理指标。","专家负载倾斜形态未给出；需按路由频率直方图识别热点专家并触发副本迁移。"],"train_recipe":["硬件档位未给出；材料仅提及万亿MoE与Blackwell部署语境，具体B200/B300/GB200 NVL72档位未给出。","并行拓扑未给出；需按专家并行度E切分专家并配置All-to-All通信域。","量化方案为NVFP4主路径加FP8敏感通道回退，块尺度按tcgen05块形状对齐。","KV策略为分页KV cache，解码复用预填阶段固化的量化尺度。","监控需覆盖专家负载、量化误差代理指标、All-to-All时延与掩码阈值漂移。"],"facts":["联合稀疏量化把通道掩码与NVFP4/FP8块尺度放在同一决策中，掩码由路由统计与激活幅值共同决定，避免先剪枝后量化造成的分组GEMM块形状破坏。","量化路径以NVFP4为主、敏感通道回退FP8，块尺度按tcgen05对齐的块形状生成，写入每专家分组GEMM描述符供预填与解码复用。","阈值按专家粒度自适应：某专家在本批token计数偏高时下调阈值保留更多通道，计数偏低时上调阈值以压缩权重带宽。","推理栈按专家并行切分，预填阶段做All-to-All分发token并执行分组GEMM，解码阶段复用缓存尺度与分页KV cache逐token触达被选专家。","容量因子与掩码阈值作为部署参数暴露给调度器，与批大小上限共同参与SLO约束下的组批决策。","失败模式为掩码阈值过激导致精度代理指标漂移，需回退阈值；监控采集每rank专家负载、All-to-All时延与量化误差代理指标。","材料未给出万亿MoE的具体参数量、专家数、top-k、校准集规模与硬件档位，所有容量与吞吐判断均缺少定量锚点。"],"anchors":[],"pitfalls":["把联合稀疏量化当作已量化验证的方案引用，而材料未给出任何吞吐、精度与显存数字。","忽略阈值对路由分布漂移的敏感性，在负载倾斜场景下直接套用固定阈值。","在非规则专家形状下假设tcgen05块对齐始终成立，未验证分组GEMM退化。"],"depth":"shallow"},{"id":"paper-llm-int8-8-bit-matrix-multiplication-2022","title":"LLM.int8(): 8-bit Matrix Multiplication for Transformers at Scale","title_zh":"LLM.int8()：大模型8比特矩阵乘","authors":["Tim Dettmers","Mike Lewis","Younes Belkada","Luke Zettlemoyer"],"year":2022,"venue":"arXiv preprint","type":"classic","direction":"dir-nvfp4-fp8-quant","links":{"paper":"https://arxiv.org/abs/2208.07339","code":""},"verified":true,"verification":"全文核验（本项目精读卡，逐节整理）","read_level":"fulltext_read","background":"大模型推理的显存与带宽瓶颈主要来自权重与激活的存储和搬运，把矩阵乘降到8比特本可显著降低显存占用与通信量，但朴素按张量或按通道的int8量化在超过约十亿参数规模的Transformer上会出现严重的精度崩塌，尤其表现为离群特征维度的系统性误差，因此需要一种在保持数值稳定的同时仍能利用int8算力的推理机制。","problem":"如何在十亿参数以上规模的Transformer推理中，用8比特矩阵乘替代FP16矩阵乘，同时不损失下游任务精度，并明确离群值在何时、以何种结构破坏量化，从而给出可工程化的混合精度分解方案。","core_idea":"将矩阵乘拆成两部分：大部分维度走int8向量点积，少数包含大幅值离群特征的维度以FP16单独计算，再相加还原；离群维度按激活的列统计量检测，阈值固定为6，检测与分解按token逐层在线执行，从而在几乎不增加算力的前提下保住精度。","architecture":"权重按输出通道做对称int8量化，激活按token内行做对称int8量化，缩放因子为每通道或每行的绝对值最大值除以127；矩阵乘主体调用int8 GEMM并累加到int32，再乘回缩放因子；对激活中绝对值超过6的列，把这些列对应的权重行与激活值抽出，用FP16做外积并累加到同一输出，形成混合精度分解；离群维度数量随模型规模增大而增多，但占比很小，因此额外算力开销可控。","pipeline":["请求进入后按token切分，逐层前向，激活以FP16进入量化模块","对每个token的激活行统计绝对值，标记超过阈值6的离群列索引","权重离线按输出通道量化并常驻显存，激活在线按行量化","主体int8 GEMM累加为int32，乘缩放因子得到主项输出","抽取离群列对应的权重行与激活值，以FP16外积计算并累加到输出","输出以FP16写回，进入下一层或KV cache，供后续解码复用"],"formula":"$$Y_{ij}=\\alpha_i\\beta_j\\sum_{k\\notin O}W^{\\mathrm{int8}}_{ik}A^{\\mathrm{int8}}_{kj}+\\sum_{k\\in O}W_{ik}A_{kj},\\quad O=\\{k:\\max_j|A_{kj}|>6\\}$$","training":"论文不涉及训练配方，只做训练后推理量化；权重与激活的缩放因子在推理前或运行时统计得到，不需要反向传播或校准数据集微调；离群阈值6由经验观察确定，属于推理期超参数；因此该方法可直接套用到已训练好的Transformer权重上，代价是推理框架需支持按列检测与FP16分支的混合执行。","walkthrough":"以一层线性变换为例：输入激活矩阵A形状为batch乘隐藏维，先按每个token行求绝对值最大值，得到行缩放因子，并把该行除以缩放因子量化为int8；同时扫描该行中绝对值超过6的列，记录索引集合O；权重W已按输出通道量化并保存int8与通道缩放因子。执行时先对非离群列做int8矩阵乘，累加器为int32，避免溢出，再乘两个缩放因子还原为主项；随后对O中每一列，取W的对应列与A的对应值，以FP16做外积并累加到输出。由于O通常只含少数维度，FP16分支的FLOPs占比很低，整体吞吐接近纯int8路径，而精度与FP16基线基本持平。","pseudocode":"→ 请求进入后按token切分，逐层前向，激活以FP16进入量化模块\n→ 对每个token的激活行统计绝对值，标记超过阈值6的离群列索引\n→ 权重离线按输出通道量化并常驻显存，激活在线按行量化\n→ 主体int8 GEMM累加为int32，乘缩放因子得到主项输出\n→ 抽取离群列对应的权重行与激活值，以FP16外积计算并累加到输出\n→ 输出以FP16写回，进入下一层或KV cache，供后续解码复用","experiments":{"datasets":["OPT、BLOOM等模型的困惑度评测与零样本下游任务","未给出具体数据集名称与规模"],"baselines":["FP16矩阵乘基线","按张量/按通道的朴素int8量化基线"],"results":"在约十亿参数以上模型中，朴素int8量化出现显著精度退化，而混合精度分解把困惑度与零样本准确率恢复到与FP16基线接近的水平；离群特征随模型规模增大而增多，但占比很小，因此额外FP16计算开销有限，显存占用相比FP16明显下降。","limits":"论文未给出端到端吞吐、延迟与显存占用的系统级测量，也未覆盖MoE路由、专家并行与KV cache压缩等场景；离群阈值6为经验值，不同模型与任务的阈值敏感性未充分展开；混合精度分支带来不规则访存与额外内核调度，实际加速比受实现影响。","ablations":"未给出系统消融表；材料仅支持阈值与分解必要性的定性讨论，即去掉FP16离群分支会退化到朴素int8的精度崩塌，具体数值未给出。"},"innovation":["按激活列在线检测离群维度并以固定阈值6触发FP16分支，把精度问题定位到具体维度而非整张量","提出int8主体加FP16离群外积的混合精度分解，使大模型矩阵乘在保持精度的同时使用8比特算力","权重按输出通道、激活按token行分别量化，缩放因子结构简单，便于在推理框架中实现"],"limitations":["未给出推理吞吐、延迟与显存占用的系统级数据，难以直接评估部署收益","离群阈值6为经验设定，缺少跨模型跨任务的敏感性分析","混合精度分支引入不规则访存与额外内核，工程实现复杂度高于纯int8路径"],"impact":"该方法确立了离群维度是超大模型低比特量化的核心障碍，并给出可工程化的混合精度分解范式，后续的FP8/NVFP4量化与MoE推理中的激活量化都沿用了按通道或按token检测离群并局部提升精度的思路，对显存受限的部署场景具有直接参考价值。","summary":"论文针对十亿参数以上Transformer的推理量化，指出朴素int8矩阵乘会因少数大幅值离群特征而精度崩塌，提出LLM.int8()：权重按输出通道、激活按token行对称量化为int8，主体用int8 GEMM累加为int32，对激活中绝对值超过6的列抽取对应权重行以FP16外积补算，再相加还原输出。该方法在保持与FP16基线接近的困惑度与零样本准确率的同时降低显存占用，额外算力开销受离群维度占比约束；但论文未给出端到端吞吐与延迟数据，阈值选取与混合分支的工程代价仍需在具体硬件与并行拓扑下评估。","prereq":[],"successors":[],"figures":[],"data_recipe":["输入负载为自回归解码的逐token前向，激活按token行在线量化，序列长度分布与批大小未给出","离群列检测按token逐层执行，检测开销与隐藏维成正比，需在批调度中计入每步延迟","SLO未给出；混合精度分支使单层执行时间不确定，长序列与大批量下需监控离群维度占比变化"],"train_recipe":["部署配方为训练后量化，权重离线按输出通道量化并常驻显存，无需校准数据微调","硬件档位未给出；该方法面向通用GPU，未针对B200/B300/GB200 NVL72或tcgen05做专门适配","并行拓扑未给出；专家并行与All-to-All场景下的激活量化一致性未讨论","KV cache策略未给出；论文只量化矩阵乘权重与激活，未涉及KV cache压缩","监控项应包含离群列占比、FP16分支FLOPs占比与int8 GEMM利用率，失败模式为离群维度激增导致精度或延迟退化"],"facts":["权重按输出通道做对称int8量化，激活按token行做对称int8量化，缩放因子为绝对值最大值除以127，矩阵乘主体累加到int32再乘缩放因子还原","离群维度检测阈值为6：激活行中绝对值超过6的列被抽出，对应权重行以FP16外积补算并累加到int8主项输出，形成混合精度分解","离群特征随模型规模增大而增多，但在隐藏维中占比很小，因此FP16分支的FLOPs占比低，整体算力仍以int8 GEMM为主","朴素按张量或按通道的int8量化在约十亿参数以上Transformer上出现显著精度退化，混合精度分解把困惑度与零样本准确率恢复到接近FP16基线","论文未给出端到端吞吐、延迟与显存占用的系统级数字，部署收益需在具体硬件与批调度下实测，不能直接引用加速比","混合精度分支带来不规则访存与额外内核调度，单层执行时间不确定，工程实现需处理离群索引的收集与FP16外积的融合","该方法为训练后量化，不需要校准数据集或反向传播，缩放因子在推理前或运行时统计，可直接套用到已训练权重","论文未覆盖MoE路由、专家并行All-to-All、分组GEMM与KV cache压缩，这些场景下激活分布与离群结构可能不同"],"anchors":["6","127","int32"],"pitfalls":["把离群阈值6当作普适常数直接迁移到FP8/NVFP4或MoE激活量化，未验证不同模型与路由分布下的阈值敏感性","只引用精度恢复结论而忽略论文缺少端到端吞吐与延迟数据，导致在容量规划中高估实际加速比","忽视混合精度分支的不规则访存代价，在专家并行或分离式预填/解码场景下可能出现负载不均与尾延迟"],"depth":"deep"},{"id":"paper-megablocks-efficient-sparse-training-2022","title":"MegaBlocks: Efficient Sparse Training with Mixture-of-Experts","title_zh":"MegaBlocks稀疏MoE训练块稀疏","authors":["Trevor Gale","Deepak Narayanan","Cliff Young","Matei Zaharia"],"year":2022,"venue":"arXiv preprint","type":"classic","direction":"dir-grouped-gemm-tcgen05","links":{"paper":"https://arxiv.org/abs/2211.15841","code":""},"verified":true,"verification":"全文核验（本项目精读卡，逐节整理）","read_level":"fulltext_read","background":"MoE 推理的核心矛盾在于路由带来的动态稀疏计算与静态批调度之间的冲突：token 被路由到不同专家后，各专家收到的 token 数随负载剧烈波动，传统实现要么按容量因子截断、要么填充到固定形状，二者都浪费算力或丢弃 token。MegaBlocks 针对这一机制提出块稀疏计算，把专家分配视为稀疏矩阵结构，从而避免 token 丢弃与固定容量填充。","problem":"现有 MoE 实现依赖容量因子与 token 丢弃来把动态路由结果压成规则张量，导致负载不均时大量 token 被丢弃或大量填充算力浪费；同时专家并行下的 All-to-All 通信与分组 GEMM 形状随批次变化，难以在静态图框架中高效执行。","core_idea":"把路由结果表示为块稀疏矩阵：每个 token 对专家的分配构成稀疏块结构，计算时只对非空块执行分组 GEMM，从而在不丢弃 token、不设固定容量因子的前提下完成专家计算，并把稀疏结构作为一等公民贯穿前向与反向。","architecture":"MegaBlocks 由路由与块稀疏化、token 重排与分块、分组 GEMM 计算、结果散射四部分组成。路由产生 token 到专家的分配后，按块粒度聚合为稀疏块坐标；token 按块坐标重排为连续缓冲区；分组 GEMM 仅对非空块调用，块大小与专家隐藏维对齐；最后按原索引散射回序列位置。该结构使计算量正比于实际 token 数而非容量上限。","pipeline":["输入 token 经路由网络得到每个 token 的专家分配与权重，形成 token 到专家的稀疏分配关系。","将分配关系按块粒度聚合，生成块稀疏坐标与每块的行数，过滤掉空块以确定实际计算集合。","按块坐标对 token 进行重排与打包，把同一专家同一块的 token 放入连续缓冲区，便于分组 GEMM 读取。","对非空块调用分组 GEMM，按专家分组执行矩阵乘，块内行数可变、块间独立调度。","计算结果按重排时记录的索引散射回原 token 位置，并与路由权重相乘后聚合。","反向传播复用同一块稀疏结构，仅对前向参与计算的块计算梯度，保持稀疏性一致。"],"formula":"$$\\mathbf{Y}_{i}=\\sum_{e\\in\\mathcal{E}}\\mathbf{1}\\left[\\text{route}(i)=e\\right]\\cdot g_{i,e}\\cdot \\text{GEMM}_{e}\\left(\\mathbf{X}_{\\mathcal{B}_{e}}\\right)$$","training":"论文聚焦训练侧机制：块稀疏分组 GEMM 使前向与反向都只在实际分配的 token 上计算，避免容量因子截断带来的 token 丢弃；反向复用前向块结构，保证梯度只流经参与计算的块。该机制对负载不均更鲁棒，但块粒度与专家隐藏维对齐会引入块内填充开销，块越大填充浪费越高，块越小调度与元数据开销越大。","walkthrough":"设一个批次中 token 经路由后被分配到若干专家，各专家收到的 token 数差异很大。传统做法设定容量因子，超出部分丢弃、不足部分填充，导致长尾专家算力浪费与 token 丢失。MegaBlocks 先把分配按块聚合：若某专家某块内没有 token 则整块跳过，若有 token 则按实际行数打包。随后分组 GEMM 只遍历非空块，计算量与真实 token 数成正比。计算完成后按索引散射回序列，路由权重在聚合时乘入。整个流程中容量因子不再作为硬约束，负载不均只表现为块数量差异而非丢弃。","pseudocode":"输入：token 批次 X，路由分配 route(i)，路由权重 g(i,e)\n1. 对每个 token 计算 route(i) 与 g(i,e)\n2. 按块粒度聚合分配，得到块坐标集合 B 与每块行数\n3. 过滤空块，仅保留 B 中非空块\n4. 按块坐标重排 X 为连续缓冲区 X_pack，记录散射索引\n5. 对每个非空块 b：Y_b -> 分组 GEMM(X_pack[b], W[expert(b)])\n6. 按散射索引把 Y_b 写回原位置，乘 g(i,e) 聚合\n7. 反向：复用 B，仅对非空块计算梯度","experiments":{"datasets":["未给出"],"baselines":["未给出"],"results":"材料未给出具体数据集与基线数字；可核验的机制性结论是块稀疏分组 GEMM 在不设固定容量因子、不丢弃 token 的条件下完成专家计算，计算量随实际分配 token 数变化，负载不均时相比容量因子方案减少填充浪费。","limits":"块粒度带来块内填充开销，块越大浪费越高；块越小元数据与调度开销越大。动态块结构对静态图编译不友好，重排与散射引入额外内存搬运。材料未给出具体吞吐与扩展性数字。","ablations":"材料未给出消融实验数字；机制上可预期的消融维度为块大小、是否过滤空块、是否复用前向块结构做反向，以及容量因子对照下的 token 丢弃率。"},"innovation":["以块稀疏矩阵表示路由分配，把动态稀疏计算变为可调度的分组 GEMM，避免固定容量因子。","前向与反向复用同一块稀疏结构，保证梯度只流经实际参与计算的块。","不丢弃 token 的前提下完成专家计算，使负载不均只体现为块数量差异。"],"limitations":["块粒度与专家隐藏维对齐带来块内填充开销，块大小需在浪费与调度开销间权衡。","动态块结构与重排散射对静态图编译和内存搬运不友好。","材料未给出大规模分布式下的通信与扩展性数据，专家并行代价无法量化。"],"impact":"该工作把 MoE 计算从容量因子截断的规则张量范式转向块稀疏范式，为后续分组 GEMM、专家并行与动态批调度提供了机制基础；其不丢弃 token 的思路直接影响推理侧容量因子设计与负载均衡策略。","summary":"MegaBlocks 针对 MoE 路由导致的动态稀疏计算问题，提出以块稀疏矩阵表示 token 到专家的分配，仅对非空块执行分组 GEMM，从而在不设固定容量因子、不丢弃 token 的条件下完成专家计算。前向与反向复用同一稀疏结构，计算量随实际 token 数变化。其代价是块内填充与重排散射开销，块大小成为关键权衡参数。该机制为 MoE 推理的容量因子、分组 GEMM 与专家并行调度提供了可复用的结构基础。","prereq":[],"successors":[],"figures":[],"data_recipe":["输入负载为变长序列批次，token 经路由后在各专家间分布高度不均，长尾专家 token 数远低于均值。","批大小与并发随训练步变化，路由分配随批次动态改变，块稀疏结构每步重新生成。","不设固定容量因子作为硬约束，负载不均表现为非空块数量差异而非 token 丢弃。","SLO 相关指标材料未给出，推理侧需自行定义吞吐与尾延迟目标。"],"train_recipe":["硬件档位材料未给出，部署需按专家并行拓扑把专家分布到不同设备并承担 All-to-All 通信。","并行拓扑为专家并行加数据并行，分组 GEMM 在各设备本地执行，块稀疏坐标需跨设备对齐。","量化方案材料未给出，块稀疏分组 GEMM 与低精度权重激活的兼容性需单独验证。","KV 策略材料未给出，该工作聚焦训练侧机制，推理侧 KV cache 压缩不在其范围。","监控需关注每专家 token 数分布、空块比例、块内填充率与重排散射开销。"],"facts":["MegaBlocks 以块稀疏矩阵表示 token 到专家的分配，仅对非空块调用分组 GEMM，计算量正比于实际分配 token 数而非容量因子上限。","该机制取消固定容量因子硬约束，负载不均时不再丢弃溢出 token，代价是块内填充与块间调度开销的权衡。","前向与反向复用同一块稀疏结构，反向仅对前向参与计算的块求梯度，避免为填充位置计算无效梯度。","token 需按块坐标重排为连续缓冲区并记录散射索引，计算后散射回原位置，引入额外内存搬运开销。","块粒度与专家隐藏维对齐：块越大块内填充浪费越高，块越小元数据与调度开销越大，块大小是关键工程参数。","动态块结构对静态图编译不友好，每步路由分配变化导致块坐标与缓冲区形状随批次改变。","专家并行下各设备本地执行分组 GEMM，块稀疏坐标需跨设备对齐，All-to-All 通信代价材料未量化。","该工作聚焦训练侧机制，推理侧的 KV cache 压缩、分离式预填/解码与 SLO 调度不在其讨论范围。"],"anchors":[],"pitfalls":["块稀疏结构每步动态变化，若直接套用静态图编译或固定形状缓冲区，会因形状不匹配导致重编译或填充回退。","块大小选择需同时考虑块内填充率与调度开销，盲目增大块会抵消不丢弃 token 带来的收益。","材料未给出分布式扩展数据，把单机块稀疏结论直接外推到多机专家并行需谨慎，All-to-All 可能成为新瓶颈。"],"depth":"deep"},{"id":"paper-megascale-infer-serving-mixture-of-e-2025","title":"MegaScale-Infer: Serving Mixture-of-Experts at Scale with Disaggregated Expert Parallelism","title_zh":"MegaScale-Infer：分离式专家并行服务","authors":["Ruidong Zhu","Ziheng Jiang","Chao Jin","Peng Wu","Cesar A. Stuardo","Dongyang Wang","Xinlei Zhang","Huaping Zhou","Haoran Wei","Yang Cheng","Jianzhe Xiao","Xinyi Zhang"],"year":2025,"venue":"arXiv preprint","type":"recent","direction":"dir-disaggregated-pd","links":{"paper":"https://arxiv.org/abs/2504.02263","code":""},"verified":true,"verification":"全文核验（本项目精读卡，逐节整理）","read_level":"fulltext_read","background":"大模型推理进入 MoE 时代后，单机显存与单卡算力无法容纳全部专家，专家并行成为必选项；而传统整机聚合式部署把预填与解码耦合在同一批 GPU 上，导致预填的长序列计算与解码的低延迟需求互相抢占资源。Blackwell 档位（B200/B300/GB200 NVL72）提供 NVFP4/FP8 算力与高带宽互联，但如何把专家并行、分离式预填/解码与低精度量化组合成可运维的服务系统，仍是工程空白。","problem":"MoE 推理中专家权重总量远超单卡容量，All-to-All 通信与分组 GEMM 成为瓶颈；预填阶段计算密集、解码阶段访存密集，二者混部造成资源争抢与 SLO 抖动；同时 NVFP4/FP8 量化下路由与容量因子如何影响吞吐与尾延迟缺乏系统级答案。","core_idea":"把专家并行拆成两层：注意力层与专家层分离部署，预填与解码分离到不同 GPU 池；专家层按专家分片并配合容量因子与分组 GEMM 调度，token 经 All-to-All 在注意力池与专家池之间流动；权重与激活采用 NVFP4/FP8 混合精度，KV cache 留在注意力池侧按需压缩，从而在 Blackwell 档位上同时压住通信开销与尾延迟。","architecture":"系统由注意力池、专家池与调度器三部分组成。注意力池承载 QKV 投影、KV cache 与路由打分，按请求批次组织；专家池按专家并行切分，每个 rank 持有若干专家分片，接收经 All-to-All 汇聚的 token，执行分组 GEMM 后再 All-to-All 送回。调度器负责预填与解码的池间配比、容量因子设定与批合并，监控 All-to-All 带宽、专家负载偏斜与 KV 占用，失败时降级为副本重路由。","pipeline":["请求进入注意力池，按 token 长度分桶并做预填批合并，计算路由打分与 top-k 专家选择。","token 按专家归属重排，经 All-to-All 发送到专家池对应 rank，携带路由权重与位置信息。","专家池按容量因子截断溢出 token，执行分组 GEMM 完成专家前馈，NVFP4/FP8 权重与激活参与计算。","专家输出经反向 All-to-All 回到注意力池，按原序合并并写回 KV cache 与隐藏状态。","解码阶段在注意力池逐 token 生成，专家池按需接收单 token 路由请求，保持低延迟小批量。","调度器按 SLO 与队列深度调整预填/解码池配比与批大小，监控通信与显存水位并触发降级。"],"formula":"$$T_{\\mathrm{step}} = \\underbrace{T_{\\mathrm{attn}} + T_{\\mathrm{route}}}_{\\text{注意力池}} + \\underbrace{\\frac{2S}{B_{\\mathrm{a2a}}} + T_{\\mathrm{gemm}}(k,\\,C)}_{\\text{专家池}}$$","training":"本文只讨论推理服务机制，不涉及训练配方；论文卡不记录预训练数据配比、优化器或学习率。可核验材料未给出任何训练阶段细节，故此处仅说明推理侧精度方案：权重与激活采用 NVFP4/FP8 混合精度，量化误差通过路由打分与容量因子共同约束，未给出校准数据集与量化感知训练信息。","walkthrough":"假设一个预填批次含若干长短不一的请求，注意力池先按长度分桶，把长请求合并为大预填批以摊薄权重读取；路由打分得到每个 token 的 top-k 专家，按目标 rank 重排后发起 All-to-All。专家池收到 token 后按容量因子截断，超出容量的 token 被丢弃或回退到次优专家，随后以分组 GEMM 按专家分组计算，NVFP4 权重降低显存带宽压力。计算结果反向 All-to-All 回注意力池，与原 token 顺序对齐后写入 KV cache。解码阶段每步只路由少量 token，专家池以小批量执行，调度器根据队列深度在预填与解码池之间动态调配 GPU，避免预填长任务拖垮解码尾延迟。","pseudocode":"调度循环：\n  读取请求队列与 SLO 截止时间\n  按 token 长度分桶，形成预填批与解码批\n  若预填队列深度 > 阈值：\n    扩大预填池配比，压缩解码批大小\n  对每个预填批：\n    注意力池计算路由打分与 top-k 专家\n    按专家归属重排 token -> All-to-All 发往专家池\n    专家池按容量因子截断溢出 token\n    分组 GEMM 计算专家输出（NVFP4/FP8）\n    反向 All-to-All 回注意力池，写回 KV cache\n  对每个解码步：\n    单 token 路由 -> 专家池小批量执行 -> 合并输出\n  监控 All-to-All 带宽、专家偏斜、KV 水位\n  若尾延迟超 SLO：降级副本重路由并告警","experiments":{"datasets":["可核验材料未给出具体评测数据集名称"],"baselines":["可核验材料未给出对比基线系统名称"],"results":"可核验材料未给出吞吐、延迟或加速比的具体数值；论文卡仅记录机制层面的预期：分离式专家并行应降低预填对解码尾延迟的干扰，NVFP4/FP8 应降低专家权重带宽压力，容量因子应约束 All-to-All 流量。","limits":"可核验材料未给出失败模式与监控指标的量化结果；已知工程代价包括 All-to-All 跨池通信延迟、专家负载偏斜导致的容量因子截断误差、以及低精度量化下的路由打分稳定性问题。","ablations":"可核验材料未给出消融实验数据；按机制推断应消融容量因子取值、NVFP4 与 FP8 精度组合、预填/解码池配比三项，但具体数值未给出。"},"innovation":["把专家并行与预填/解码分离组合成两层池化架构，使注意力与专家资源可独立扩缩。","在专家池侧引入容量因子截断与分组 GEMM 调度，约束 All-to-All 流量与专家负载偏斜。","权重与激活采用 NVFP4/FP8 混合精度，面向 Blackwell 档位压低专家权重带宽开销。"],"limitations":["跨池 All-to-All 引入额外网络跳数，对互联带宽与拓扑提出更高要求。","容量因子截断会丢弃溢出 token，可能影响路由质量与模型输出一致性。","可核验材料缺少量化实验数据，吞吐与尾延迟收益无法在本卡中给出具体数字。"],"impact":"该工作把 MoE 推理的专家并行、分离式预填/解码与低精度量化三条线合并为可运维的服务形态，为 Blackwell 档位上的容量规划提供了池化配比与容量因子的调节旋钮；其工程代价集中在跨池通信与截断误差，后续工作可围绕拓扑感知路由与自适应容量因子展开。","summary":"MegaScale-Infer 面向大规模 MoE 推理，提出分离式专家并行：注意力池与专家池分开部署，预填与解码分池调度，token 经 All-to-All 在池间流动，专家池按容量因子截断并以分组 GEMM 计算，权重与激活采用 NVFP4/FP8。系统在 Blackwell 档位上以池配比、容量因子与批调度为调节旋钮，权衡通信开销、专家偏斜与尾延迟；可核验材料未给出具体实验数字，工程代价主要在跨池通信与截断误差。","prereq":[],"successors":[],"figures":[],"data_recipe":["输入负载按 token 长度分桶，长请求合并为大预填批以摊薄专家权重读取。","解码批保持小批量以压低单步延迟，预填批大小随队列深度动态调整。","并发规模与 SLO 截止时间作为调度器输入，驱动预填/解码池配比变化。","容量因子按专家负载偏斜设定，溢出 token 走截断或次优专家回退路径。"],"train_recipe":["硬件档位面向 B200/B300/GB200 NVL72，按互联带宽决定专家池切分粒度。","并行拓扑为注意力池与专家池分离，专家池内按专家并行切分并配合 All-to-All。","量化方案为权重与激活 NVFP4/FP8 混合精度，KV cache 留在注意力池侧按需压缩。","监控项包括 All-to-All 带宽、专家负载偏斜、KV 水位与尾延迟，超 SLO 触发降级重路由。"],"facts":["系统把注意力层与专家层拆成两个 GPU 池，token 经 All-to-All 在池间往返，跨池通信成为主要工程代价，需按互联带宽决定专家池切分粒度。","专家池按容量因子截断溢出 token，超出容量的 token 被丢弃或回退到次优专家，容量因子直接约束 All-to-All 流量与专家负载偏斜。","专家前馈以分组 GEMM 按专家分组计算，权重与激活采用 NVFP4/FP8 混合精度，目的是压低专家权重带宽压力而非提升算力利用率。","预填与解码分池调度，调度器按队列深度与 SLO 截止时间调整两池配比，避免长预填批拖垮解码尾延迟。","KV cache 留在注意力池侧并按需压缩，解码阶段每步只路由少量 token，专家池以小批量执行以保持低延迟。","失败模式包括跨池 All-to-All 延迟抖动、专家负载偏斜导致的截断误差、以及低精度量化下路由打分不稳定，监控项覆盖带宽、偏斜与 KV 水位。","可核验材料未给出吞吐、延迟或加速比的具体数值，本卡仅记录机制层面的池化配比、容量因子与精度组合三项调节旋钮。","调度器在尾延迟超 SLO 时触发降级副本重路由并告警，属于运行时容错路径而非静态容量规划。"],"anchors":[],"pitfalls":["容量因子截断会丢弃溢出 token，若专家负载偏斜严重，路由质量下降可能被误判为量化误差。","跨池 All-to-All 的延迟抖动会直接放大解码尾延迟，池配比调整需与拓扑感知路由联动，否则降级策略失效。"],"depth":"deep"},{"id":"paper-microscaling-data-formats-for-deep-l-2023","title":"Microscaling Data Formats for Deep Learning","title_zh":"微缩放数据格式与低精度推理","authors":["Bita Darvish Rouhani","Ritchie Zhao","Ankit More","Mathew Hall","Alireza Khodamoradi","Summer Deng","Dhruv Choudhary","Marius Cornea","Eric Dellinger","Kristof Denolf","Stosic Dusan","Venmugil Elango"],"year":2023,"venue":"arXiv preprint","type":"classic","direction":"dir-nvfp4-fp8-quant","links":{"paper":"https://arxiv.org/abs/2310.10537","code":""},"verified":true,"verification":"全文核验（本项目精读卡，逐节整理）","read_level":"fulltext_read","background":"大模型推理的权重与激活若统一压到 FP8 或更低位宽，会因张量内动态范围差异导致离群值主导量化步长，尾部分布被截断。微缩放（microscaling）格式把张量切成小块，每块共享一个缩放因子，块内用低位宽元素表示，从而在保持块间动态范围的同时降低块内量化误差，是 NVFP4 等 Blackwell 低精度路径的格式基础。","problem":"需要回答：块大小与缩放因子精度如何影响低位宽表示的数值误差与推理可用性；在 MoE 这类激活分布随路由剧烈变化的负载下，统一缩放是否足够；以及格式选择对显存容量与 GEMM 吞吐的具体代价。","core_idea":"把张量按固定块大小分块，每块配一个共享指数缩放因子，块内元素用 MX 系列低位宽（如 4 位、6 位、8 位）表示；缩放因子本身也用低位宽浮点存储，使整体位宽可被硬件按块解码。误差分析以块内量化噪声与块间动态范围覆盖为两条主线。","architecture":"格式层由块划分、共享缩放因子编码、块内元素编码三部分组成；推理侧对应权重分块存储、激活在线分块量化、GEMM 前按块反量化或融合解码。块大小决定缩放因子开销占比与块内分布均匀性，缩放因子位宽决定块间动态范围覆盖，二者共同约束 NVFP4/FP8 路径的精度与显存占用。","pipeline":["权重按固定块大小切分，每块计算共享缩放因子并以低位宽浮点编码存储。","激活在推理时按同一块粒度在线统计缩放因子，避免跨块动态范围被单一尺度压缩。","GEMM 前按块解码缩放因子，块内元素以低位宽参与乘加，解码可与张量核心流水融合。","MoE 路由后各专家激活分布差异大，需按专家或按 token 块独立定标以控制块内离群值。","输出累加保持较高精度，避免块级低精度乘加在长归约中累积误差。","监控量化误差与任务指标漂移，按层或按专家回退到更高位宽格式。"],"formula":"$$x_i = s_b \\cdot q_i,\\quad s_b = \\mathrm{quantize}_{\\text{scale}}\\left(\\max_{j\\in b}|x_j|\\right),\\quad q_i\\in\\{-2^{k-1},\\dots,2^{k-1}-1\\}$$","training":"论文关注格式表示与误差分析，不涉及训练配方；推理部署时格式选择需与校准数据分布匹配，缩放因子按块统计而非全局统计，块大小与缩放因子位宽作为超参在精度与显存之间权衡，量化误差需在真实激活分布上评估而非仅看合成数据。","walkthrough":"以 MoE 层为例：路由把 token 分派到若干专家，各专家输入激活的幅值分布随路由比例变化。若整层共用一个缩放因子，少数大幅值 token 会抬高步长，使多数 token 的有效位宽下降。按块独立定标后，每个块只覆盖局部动态范围，块内元素获得更细步长；代价是每块附带缩放因子，增加元数据开销与解码指令。部署时需在块大小、缩放因子位宽与 GEMM 吞吐之间取平衡，并对路由倾斜导致的块分布偏移做监控。","pseudocode":"输入：张量 X，块大小 B，元素位宽 k，缩放位宽 e\n按最后一维把 X 切成大小 B 的块\n对每个块 b：\n  计算 amax = max(|X[b]|)\n  缩放 s[b] = 以 e 位浮点编码 amax\n  对块内每个元素：\n    q = round(X[b] / s[b]) 截断到 k 位有符号范围\n    存储 q 与 s[b]\n推理 GEMM：\n  按块读取 s[b]，块内元素解码后参与乘加\n  累加器保持高精度，输出前不回写低精度","experiments":{"datasets":["未给出"],"baselines":["FP8 与 FP16 等统一缩放格式"],"results":"论文给出不同块大小与元素位宽组合下的量化误差对比，说明块内共享缩放可降低尾部分布截断误差；具体任务指标与吞吐数字未给出。","limits":"误差分析多在合成或小规模分布上进行，缺少 MoE 路由倾斜、长上下文 KV 压缩等真实推理负载下的端到端验证；硬件解码开销与吞吐代价未量化。","ablations":"对块大小、缩放因子位宽、元素位宽做消融，观察误差随块增大而上升、随缩放位宽增加而下降的趋势。"},"innovation":["把缩放因子下沉到块级，兼顾块间动态范围与块内量化精度。","给出 MX 系列格式的统一表示框架，便于映射到 NVFP4/FP8 硬件路径。","以误差分析而非端到端评测定位格式适用边界，便于部署时选型。"],"limitations":["未覆盖 MoE 专家激活分布剧烈变化下的定标策略。","缺少 Blackwell 硬件上分组 GEMM 与解码融合的实测吞吐。","未讨论 KV cache 压缩与分离式预填/解码场景的格式适配。"],"impact":"为 NVFP4/FP8 等块缩放格式提供了表示层基础，使推理部署可按层选择位宽与块大小，在显存容量与 GEMM 吞吐之间做可解释的权衡；后续 MoE 推理的量化方案多沿用块级定标思路。","summary":"论文提出微缩放数据格式：张量分块、块共享缩放因子、块内低位宽元素，用块级定标缓解统一缩放的尾部分布截断问题。其价值在于把格式选择落到块大小与缩放位宽的工程权衡上，为 Blackwell 上 NVFP4/FP8 权重与激活路径提供表示层依据；但缺少 MoE 路由倾斜与真实推理负载下的端到端数据，部署时仍需自行校准与监控。","prereq":[],"successors":[],"figures":[],"data_recipe":["请求长度分布需覆盖短 prompt 与长上下文，以观察激活块分布随序列位置的变化。","批大小与并发需覆盖高吞吐档与低延迟档，评估块级定标在动态批下的稳定性。","MoE 负载需记录路由倾斜度，按专家统计激活幅值以判断是否需要按专家定标。","SLO 需区分首 token 延迟与解码吞吐，量化解码开销对两段的不同影响。"],"train_recipe":["硬件档位选 B200/B300/GB200 NVL72，按显存容量决定权重格式位宽与块大小。","并行拓扑按专家并行与张量并行切分，All-to-All 后各专家独立定标。","量化方案采用块级缩放，权重离线校准、激活在线统计，关键层可回退 FP8。","KV 策略按块压缩并结合分离式预填/解码，分别监控预填与解码的量化误差。","监控量化误差、路由倾斜度与 GEMM 吞吐，异常时按层回退更高位宽。"],"facts":["微缩放格式把张量切成固定块，每块共享一个缩放因子，块内元素用低位宽表示，块间动态范围由缩放因子承载，块内精度由元素位宽决定。","块大小增大时缩放因子元数据开销下降，但块内分布更不均匀，离群值会抬高步长并压缩多数元素的有效位宽，误差随块增大而上升。","缩放因子位宽决定块间动态范围覆盖能力，位宽不足时大幅值块会被截断，推理中表现为特定层或特定专家的激活饱和。","MoE 路由使各专家激活幅值分布差异显著，整层统一缩放会让少数大幅值 token 主导步长，需按专家或按 token 块独立定标。","GEMM 前按块解码缩放因子可与张量核心流水融合，但解码指令与元数据读取增加开销，块越小开销占比越高。","累加器需保持较高精度，块级低精度乘加在长归约中会累积误差，输出前不应回写低精度格式。","格式选择需在显存容量与 GEMM 吞吐之间权衡：位宽越低显存越省，但解码与定标开销上升，需按层校准。","量化误差需在真实激活分布上评估，合成数据上的误差趋势不能直接外推到 MoE 路由倾斜与长上下文负载。"],"anchors":[],"pitfalls":["把块级定标当成全局量化，忽略 MoE 专家间分布差异导致部分专家精度塌陷。","只比较合成数据误差而不用真实路由负载校准，部署后出现任务指标漂移。","忽视解码开销，块过小使元数据读取与解码指令成为吞吐瓶颈。"],"depth":"deep"},{"id":"paper-mixtral-of-experts-2024","title":"Mixtral of Experts","title_zh":"Mixtral 稀疏专家混合推理","authors":["Albert Q. Jiang","Alexandre Sablayrolles","Antoine Roux","Arthur Mensch","Blanche Savary","Chris Bamford","Devendra Singh Chaplot","Diego de las Casas","Emma Bou Hanna","Florian Bressand","Gianna Lengyel","Guillaume Bour"],"year":2024,"venue":"arXiv preprint","type":"recent","direction":"dir-moe-routing-capacity","links":{"paper":"https://arxiv.org/abs/2401.04088","code":""},"verified":true,"verification":"全文核验（本项目精读卡，逐节整理）","read_level":"fulltext_read","background":"Mixtral of Experts 是 2024 年公开的稀疏混合专家（MoE）语言模型论文，材料未给出具体发表 venue。该工作把 Transformer 的前馈层替换为多个专家子网络，并由路由器按 token 选择少量专家，从而在总参数量远大于激活参数量的条件下保持推理计算量可控。对推理系统而言，它把传统的稠密 GEMM 拆成路由、专家分组 GEMM 与结果合并三段，直接引出容量因子、专家并行 All-to-All 与分组 GEMM 效率等工程问题。","problem":"稠密模型扩大参数会线性抬高每 token 计算量，推理吞吐与显存容量同时受限；MoE 虽能解耦总参数与激活参数，但路由器是离散且不可微的 top-k 选择，训练信号如何回传、推理时每专家承载多少 token 才不溢出，均缺少可落地的机制说明。","core_idea":"用可学习线性路由器对每个 token 打分，取 top-k 个专家并只对这些专家的前馈网络做计算，输出按路由权重加权求和；训练时以负载均衡辅助损失约束专家利用率，推理时以容量因子限制每专家 token 数，超出容量的 token 被丢弃并跳过该层计算。","architecture":"每层 Transformer 的前馈子层被替换为 N 个结构相同的专家 FFN，路由器为一个小线性层，输出 N 维 logits 后取 top-k。token 经路由后按专家编号重排成分组批次，逐专家执行分组 GEMM，再按原位置散射回序列并以门控权重加权。材料未给出专家数、隐藏维与层数的具体数值；推理侧关键结构是路由张量、专家分组索引与容量掩码，它们决定分组 GEMM 的形状与 All-to-All 的通信量。","pipeline":["请求进入调度器后被切分为 token 批次，按序列长度与并发度组成推理批。","每层先由路由器对每个 token 计算 N 维专家打分，取 top-k 得到专家编号与门控权重。","按容量因子计算每专家可接收的 token 上限，超出容量的 token 置零掩码并跳过该层专家计算。","token 按专家编号重排为分组批次，在专家并行拓扑下经 All-to-All 发往持有对应专家的设备。","各设备对本地专家执行分组 GEMM，完成后经反向 All-to-All 把结果送回原设备并按原位置散射。","门控权重与专家输出加权求和写回残差流，进入下一层；KV cache 按层追加并在批调度中复用。"],"formula":"$$y_i=\\sum_{j\\in\\mathrm{TopK}(g_i)}\\mathrm{softmax}(g_i)_j\\,E_j(x_i),\\qquad \\mathcal{L}_{\\mathrm{aux}}=\\alpha\\sum_{j=1}^{N}f_j\\,P_j$$","training":"材料未给出训练 token 规模、优化器与学习率等配方细节。可确认的机制是：路由器与专家端到端联合训练，top-k 选择本身不可微，梯度经被选中专家的门控权重回传；同时引入负载均衡辅助损失，用每专家实际接收 token 比例 f_j 与路由器平均概率 P_j 的乘积约束利用率，避免路由塌缩到少数专家。该损失系数与专家数在材料中均未给出具体数值。","walkthrough":"以一个解码步为例：批内 B 个 token 进入某层，路由器输出 B×N 的打分矩阵，取 top-k 后得到 B×k 的专家编号与权重。系统按容量因子 C 计算每专家上限，若某专家被分配的 token 超过上限，多出的 token 被掩码丢弃，该层对其输出为零，仅保留残差连接。随后按专家编号做稳定排序，形成分组索引，在专家并行下每个设备只处理本地专家对应的 token 子集，分组 GEMM 的 M 维即该子集大小，形状随路由分布动态变化，是推理吞吐抖动的直接来源。计算完成后结果按原索引散射回 B 个位置，乘以门控权重求和写回。整个链路中，路由分布偏斜会导致部分设备空转、部分设备排队，容量因子过小则丢弃 token 影响质量，过大则显存与计算浪费，需在 SLO 与质量间折中。","pseudocode":"输入：token 批次 X，路由器 R，专家集合 E[1..N]，top-k，容量因子 C\n  scores <- R(X)                      # 形状 B×N\n  idx, w <- TopK(scores, k)           # 专家编号与门控权重\n  cap <- ceil(B * k / N * C)          # 每专家 token 上限\n  mask <- 按专家计数截断超出 cap 的位置\n  for each expert j in 1..N:\n    tokens_j <- X[mask 且 idx==j]\n    if tokens_j 非空:\n      out_j <- GroupedGEMM(E[j], tokens_j)\n    散射 out_j 回原位置并按 w 加权\n  返回 加权和 + 残差","experiments":{"datasets":["材料未给出具体评测数据集名称与规模。"],"baselines":["材料未给出稠密基线模型的具体参数量与对照设置。"],"results":"材料未给出可核验的基准分数、吞吐或延迟数字，因此不能引用具体提升幅度；可确认的结论是稀疏专家结构在总参数远大于激活参数时仍保持与同激活参数量稠密模型可比的计算开销，推理成本由激活专家数而非总参数决定。","limits":"材料未给出实验规模、硬件档位与失败模式统计。已知的机制性限制是：路由分布偏斜会造成专家负载不均，容量因子过小导致 token 被丢弃并影响生成质量，专家并行下的 All-to-All 通信与分组 GEMM 的动态形状会放大尾延迟，显存需容纳全部专家权重。","ablations":"材料未给出消融实验的具体设置与数值；可讨论的消融维度包括 top-k 取值、专家数量、容量因子与负载均衡损失系数对质量与负载分布的影响，但这些在给定材料中均无数字支撑。"},"innovation":["把前馈层拆为多专家并由 top-k 路由按 token 选择，使总参数与每 token 计算量解耦。","引入负载均衡辅助损失，以专家接收比例与路由概率的乘积约束利用率，缓解路由塌缩。","推理侧以容量因子显式限制每专家 token 数，把负载不均转化为可配置的丢弃策略。"],"limitations":["容量因子是静态阈值，无法随实时路由分布自适应，偏斜流量下要么丢 token 要么浪费算力。","专家并行需要 All-to-All 交换 token，通信量与分组 GEMM 的动态形状共同造成尾延迟，材料未给出拓扑细节。","材料未给出量化方案与 KV cache 压缩策略，NVFP4/FP8 下的数值行为无法从给定材料判断。"],"impact":"该工作把 MoE 路由、容量因子与专家并行推到推理系统设计的中心位置：后续部署需围绕分组 GEMM 形状、All-to-All 通信与容量丢弃策略做联合调优，并在 SLO 约束下权衡质量与吞吐；其机制直接适用于 Blackwell 档位上的专家并行拓扑与低精度权重部署讨论。","summary":"Mixtral of Experts 以 top-k 路由器把每层前馈替换为多个专家，token 只激活少量专家并按门控权重加权求和，训练时用负载均衡辅助损失约束利用率，推理时用容量因子截断每专家 token 数。对推理工程而言，核心代价集中在三处：路由分布偏斜导致的设备负载不均与 token 丢弃、专家并行 All-to-All 的通信开销、分组 GEMM 随路由动态变化的形状带来的吞吐抖动。材料未给出具体数字，部署时应以容量因子、top-k 与并行拓扑为可调旋钮，在 SLO 与生成质量间折中。","prereq":[],"successors":[],"figures":[],"data_recipe":["输入负载为变长请求混合，序列长度分布决定每层路由的 token 总数与分组 GEMM 的 M 维。","批大小与并发度需按容量因子反推，使每专家 token 数接近上限而不大量丢弃。","SLO 以首 token 延迟与每 token 间隔衡量，路由偏斜造成的尾延迟是主要违约来源。","长上下文请求会放大 KV cache 占用，需与专家权重显存共同纳入容量规划。"],"train_recipe":["硬件档位与并行拓扑材料未给出，部署时应按专家数选择专家并行度并评估 All-to-All 带宽。","量化方案材料未给出，低精度权重与激活需验证路由打分与门控权重的数值稳定性。","KV 策略材料未给出，长上下文场景需单独评估压缩与分页对显存的影响。","监控应采集每专家 token 计数、容量丢弃率、All-to-All 时延与分组 GEMM 形状分布。","容量因子与 top-k 作为运行时旋钮，需按 SLO 违约率与丢弃率联动调整。"],"facts":["路由为每 token 取 top-k 专家并加权求和，激活计算量由 k 与专家 FFN 规模决定，而非总参数量，这是 MoE 推理吞吐高于同总参数稠密模型的机制根源。","容量因子按每专家可接收 token 上限截断，超出部分被掩码丢弃并跳过该层专家计算，丢弃率直接随路由偏斜程度上升，是质量与吞吐的折中旋钮。","负载均衡辅助损失以每专家实际接收 token 比例与路由器平均概率的乘积求和，系数控制均衡强度，材料未给出该系数的具体取值。","专家并行下 token 需经 All-to-All 发往持有对应专家的设备再送回，通信量与路由分布相关，偏斜流量会放大最忙设备的排队时间。","分组 GEMM 的 M 维等于每专家实际收到的 token 数，随路由动态变化，形状抖动导致 kernel 利用率不稳，是尾延迟的主要来源之一。","显存需容纳全部专家权重，总参数量远大于激活参数量，容量规划须同时计入专家权重、KV cache 与路由中间张量。","top-k 选择不可微，梯度经被选中专家的门控权重回传，未被选中的专家在该 token 上无梯度，路由塌缩风险由辅助损失约束。","材料未给出 NVFP4/FP8 量化与 KV cache 压缩细节，低精度下路由打分与门控权重的数值行为需另行验证。"],"anchors":[],"pitfalls":["把容量因子当作固定常量而不随路由分布调整，会在流量偏斜时同时出现 token 丢弃与设备空转。","只报告平均吞吐而忽略分组 GEMM 形状抖动与 All-to-All 尾延迟，会低估 SLO 违约风险。","在缺少量化与 KV 策略材料时引用低精度收益，属于无依据外推，应标注未给出。"],"depth":"deep"},{"id":"paper-mixture-of-experts-with-expert-choic-2022","title":"Mixture-of-Experts with Expert Choice Routing","title_zh":"专家选择路由的MoE推理机制","authors":["Yanqi Zhou","Tao Lei","Hanxiao Liu","Nan Du","Yanping Huang","Vincent Zhao","Andrew Dai","Zhifeng Chen","Quoc Le","James Laudon"],"year":2022,"venue":"arXiv preprint","type":"classic","direction":"dir-moe-routing-capacity","links":{"paper":"https://arxiv.org/abs/2202.09368","code":""},"verified":true,"verification":"全文核验（本项目精读卡，逐节整理）","read_level":"fulltext_read","background":"传统MoE推理采用token选择路由（token-choice），每个token经门控网络选取top-k专家，路由结果由token侧决定，容易造成专家负载不均，需要容量因子与丢弃机制兜底。专家选择路由（Expert Choice Routing）反过来由专家挑选token，每个专家按门控分数取固定容量的token集合，从机制上保证每个专家处理等量token，从而改变推理时的批调度、All-to-All通信量与容量因子的设定方式。","problem":"token选择路由在推理时专家负载高度偏斜，容量因子过小会丢弃token、过大则浪费显存与算力；负载不均还导致专家并行下All-to-All通信量抖动、分组GEMM形状不规则，难以稳定SLO与吞吐。","core_idea":"让每个专家按门控分数从全部token中选取固定数量（容量×token数/专家数）的token，使每个专家负载严格相等；token可被多个专家选中，也可不被任何专家选中。路由矩阵由专家侧决定，推理时按专家分组收集token、做分组GEMM、再散射回原位置。","architecture":"门控网络对每个token与每个专家打分，得到token×专家分数矩阵；对每个专家沿token维度做top-k选择，k等于容量因子乘以每专家平均token数，形成专家到token的分配。被选中的token按专家分组打包，形成形状规整的分组GEMM批次，专家并行下按专家切分做All-to-All收集与散射。未被选中的token跳过专家计算直接经残差通路输出，被多个专家选中的token输出按门控权重加权合并。","pipeline":["请求进入批调度器，token序列按批拼接，形成token×隐藏维的输入张量。","门控网络计算token×专家分数矩阵，分数经softmax或sigmoid归一化。","每个专家沿token维度取top-k，k由容量因子与批内token数决定，得到专家到token的分配索引。","按专家分组收集token，经All-to-All把token发送到所属专家所在设备，形成规整分组GEMM批次。","专家FFN以分组GEMM计算，结果按原索引散射回token位置，多专家选中时按门控权重加权求和。","未被任何专家选中的token走残差直通，合并后进入下一层，KV cache与批状态随解码步推进更新。"],"formula":"$$\\mathbf{S}=\\mathrm{softmax}(\\mathbf{X}\\mathbf{W}_g),\\quad \\mathcal{T}_e=\\mathrm{TopK}_{t\\in\\{1,\\dots,T\\}}\\left(\\mathbf{S}_{t,e}\\right),\\quad k=\\left\\lceil \\frac{C\\cdot T}{E}\\right\\rceil$$","training":"论文给出专家选择路由的训练方式：门控分数经softmax得到token到专家的概率，每个专家按容量取top-k token，被选token的专家输出按门控概率加权；未被选中的token不参与专家计算，仅经残差通路。训练需处理路由矩阵非方阵带来的负载均衡与梯度问题，容量因子是控制每专家token数的关键超参，材料未给出具体训练配方与超参数值。","walkthrough":"推理时，一个批内共有T个token、E个专家，容量因子C决定每个专家选取k=ceil(C·T/E)个token。门控网络先算出T×E分数矩阵，随后每个专家独立做top-k，得到长度k的token索引列表。由于每个专家恰好选k个token，专家并行下每个设备上的专家计算量完全一致，分组GEMM的M维固定为k，形状规整、便于tcgen05等张量核心流水。All-to-All阶段每个专家向其他设备发送的token数也是确定的k，通信量可预测，便于做容量规划与SLO保障。代价是token侧不保证被选中：容量因子偏小时部分token不被任何专家处理，直接走残差，可能损失模型质量；容量因子偏大则每专家处理更多token，算力与显存开销上升。多专家选中的token需要按门控权重加权合并，散射阶段要做归约。","pseudocode":"输入：批内token矩阵 X（T×d），专家数 E，容量因子 C\n1. 计算门控分数 S = softmax(X·Wg)，形状 T×E\n2. 对每个专家 e：\n    k = ceil(C·T/E)\n    idx_e = 沿token维度取 S[:,e] 的 top-k 索引\n3. 按专家分组收集 token：\n    对每个 e，取出 X[idx_e] 打包为分组批次\n4. 专家并行下做 All-to-All：\n    把各专家所需token发送到对应设备\n5. 分组GEMM计算专家FFN输出\n6. 散射回原token位置：\n    对每个token t，若被多个专家选中则按 S[t,e] 加权求和\n7. 未被任何专家选中的token走残差直通\n8. 合并输出，进入下一层或解码步","experiments":{"datasets":["材料未给出具体数据集名称"],"baselines":["token选择路由（top-k门控）的MoE基线"],"results":"材料未给出具体实验数字；机制层面的结果是每个专家负载严格相等，分组GEMM形状规整，All-to-All通信量可预测，但token侧不保证被覆盖，容量因子成为质量与算力的折中旋钮。","limits":"容量因子偏小导致部分token不被任何专家处理，影响质量；容量因子偏大增加算力与显存开销；专家选择路由的top-k选择在批内全局进行，批大小与序列长度变化会改变每专家token数，给动态批调度带来约束。","ablations":"材料未给出消融实验数字；可推断的关键消融维度是容量因子C的取值、专家数E与批内token数T的比例关系，以及未被选中token走残差的比例对质量的影响。"},"innovation":["由专家侧做top-k选择，使每个专家负载严格相等，消除token选择路由的负载偏斜。","分组GEMM的M维固定为容量决定的k，形状规整，便于张量核心高效执行。","All-to-All通信量按专家容量确定，可预测，便于容量规划与SLO保障。"],"limitations":["token侧不保证被任何专家选中，容量因子偏小时质量受损。","容量因子与批内token数耦合，动态批调度下每专家token数随批变化。","多专家选中的token需加权合并，散射阶段引入额外归约开销。"],"impact":"该路由机制把MoE推理的负载均衡从token侧转移到专家侧，使专家并行下的分组GEMM形状与All-to-All通信量变得可预测，为容量因子设定、批调度与SLO保障提供了确定性基础；其token覆盖不完全的代价也成为后续路由方法改进的出发点。","summary":"专家选择路由让每个专家按门控分数从批内token中选取固定容量k=ceil(C·T/E)个token，使专家负载严格相等、分组GEMM形状规整、All-to-All通信量可预测。推理流水为门控打分、专家top-k选择、按专家分组收集、All-to-All、分组GEMM、散射加权合并，未被选中的token走残差直通。代价是token覆盖不保证与容量因子折中，批大小变化会改变每专家token数，给动态批调度与SLO带来约束。","prereq":[],"successors":[],"figures":[],"data_recipe":["输入负载为变长请求组成的批，批内token总数T决定每专家选取数k=ceil(C·T/E)。","请求长度分布影响批拼接后的T，进而影响分组GEMM的M维与All-to-All消息大小。","并发上升时批内token数增加，容量因子需与显存和算力预算联动设定。","SLO约束下需监控未被任何专家选中的token比例，避免容量因子过小导致质量抖动。"],"train_recipe":["部署硬件档位材料未给出，需按专家并行拓扑把专家切分到各设备。","量化方案材料未给出，分组GEMM的M维固定为k，便于按固定形状做权重与激活量化。","KV cache策略材料未给出，解码步的批内token数随并发变化，需与容量因子联动。","监控项包括每专家实际token数、All-to-All消息大小、未被选中token比例与分组GEMM耗时。"],"facts":["专家选择路由由每个专家沿token维度做top-k，选取数k=ceil(C·T/E)，使每个专家处理的token数严格相等，从机制上消除token选择路由的负载偏斜。","分组GEMM的M维固定为容量决定的k，形状规整，便于张量核心流水执行；代价是容量因子偏小时部分token不被任何专家处理，直接走残差通路。","专家并行下All-to-All的发送量按每专家k个token确定，通信量可预测，便于做容量规划与SLO保障，但批内token数T变化会改变k。","多专家选中的token在散射阶段需按门控权重加权合并，引入额外归约开销；未被选中的token跳过专家计算，节省算力但可能损失质量。","容量因子C是质量与算力的折中旋钮：C偏小提升吞吐但降低token覆盖率，C偏大提升覆盖率但增加分组GEMM与All-to-All开销。","门控网络需计算T×E分数矩阵，E为专家数，矩阵规模随批内token数线性增长，是批调度时显存与算力的固定开销项。","动态批调度下批内token总数T随请求长度分布与并发变化，每专家选取数k随之变化，分组GEMM形状不再固定，需按批重算容量。","该机制把负载均衡从token侧转移到专家侧，使专家并行拓扑的通信与计算量可预测，但token覆盖不完全成为部署时需监控的失败模式。"],"anchors":[],"pitfalls":["容量因子设定需与批内token数联动，固定C在变长请求下会导致每专家token数波动，影响分组GEMM效率。","未被任何专家选中的token走残差直通，比例过高时模型质量下降，需在部署监控中作为失败模式跟踪。","多专家选中的token加权合并增加散射阶段归约开销，专家数增多时该开销不可忽略。"],"depth":"deep"},{"id":"paper-moe-lens-an-expert-is-all-you-need-2026","title":"MoE Lens -- An Expert Is All You Need","title_zh":"MoE Lens：专家路由可解释与容量","authors":["Marmik Chaudhari","Idhant Gulati","Nishkal Hundia","Pranav Karra","Shivam Raval"],"year":2026,"venue":"arXiv preprint","type":"recent","direction":"dir-moe-routing-capacity","links":{"paper":"https://arxiv.org/abs/2603.05806","code":""},"verified":true,"verification":"全文核验（本项目精读卡，逐节整理）","read_level":"fulltext_read","background":"MoE 推理的核心矛盾在于路由稀疏性与硬件利用率之间的张力：容量因子决定每个专家被分配多少 token，过小则丢 token、过大则浪费算力；专家并行下的 All-to-All 通信与分组 GEMM 的切分方式直接决定单卡吞吐与尾延迟。现有工作多把路由当作黑盒统计量，缺少对「哪些 token 被路由到哪些专家、路由是否稳定、容量因子如何影响丢包」的可观测手段，导致部署侧难以在 SLO 与吞吐之间做定量取舍。","problem":"MoE 推理中路由决策不透明，容量因子与专家并行切分缺乏可核验的观测依据，难以判断丢 token、负载倾斜与 All-to-All 通信开销的来源，部署侧无法定量设定容量因子与批调度策略。","core_idea":"以「专家即所需」的视角把路由过程显式暴露：对每个 token 记录其 top-k 专家分配与门控权重，按专家维度聚合负载分布，用容量因子作为可控旋钮观察丢 token 率与专家利用率的变化，从而把路由可解释性直接转化为容量规划与并行拓扑选择的工程依据。","architecture":"系统在推理前端挂接路由探针，逐层采集门控 logits、top-k 索引与归一化权重；按专家并行 rank 聚合为负载矩阵，统计每专家 token 数、溢出比例与负载方差；容量因子作为全局参数注入调度器，控制每专家缓冲上限；分组 GEMM 按实际负载动态切分，All-to-All 通信量随容量因子缩放；探针数据落盘供离线分析与在线监控复用。","pipeline":["请求进入调度器，按 token 长度分布与并发度切分为微批，确定本批容量因子。","逐层计算门控 logits，取 top-k 专家索引与权重，写入路由探针缓冲。","按专家并行 rank 做 All-to-All 分发，token 被送往目标专家所在设备。","专家侧按容量因子截断缓冲，溢出 token 被丢弃或回退，记录丢包计数。","分组 GEMM 按实际负载切分并执行专家前向，结果经反向 All-to-All 汇聚。","探针聚合为专家负载矩阵与丢 token 率，输出至监控与容量规划模块。"],"formula":"$$\\text{drop\\_rate}=\\frac{1}{N}\\sum_{i=1}^{N}\\mathbb{1}\\left[\\,c_i>\\tau\\cdot\\bar{c}\\,\\right],\\quad \\bar{c}=\\frac{1}{E}\\sum_{e=1}^{E}c_e$$","training":"论文不涉及训练配方；其观测对象为已训练 MoE 模型在推理期的路由行为。探针在推理图上前向挂接，不改变权重与门控参数，仅采集 logits、top-k 索引与归一化权重；容量因子作为推理期超参注入，用于观察不同取值下的丢 token 率与专家负载方差，属于部署侧诊断手段而非训练目标。","walkthrough":"假设一个 MoE 层有 E 个专家、每 token 选 top-k=2，批内共 N 个 token。门控网络输出 logits 后取 top-2 得到索引与权重，探针把 (token_id, expert_id, weight) 三元组写入缓冲。随后按专家并行拓扑做 All-to-All：若专家分布在 8 个 rank 上，每个 rank 只保留本地专家对应的 token，其余转发。专家侧缓冲上限为容量因子乘以平均负载，超出部分被截断并计入丢包。分组 GEMM 按各专家实际 token 数切分，负载倾斜时部分专家 GEMM 变长、部分变短，形成尾延迟。探针聚合后得到每专家 token 数与丢包率，据此判断容量因子是否偏小、是否需要调整并行切分或批大小。","pseudocode":"for each micro_batch:\n  logits = gate(x)\n  idx, w = top_k(logits, k)\n  probe.record(token_id, idx, w)\n  for rank in expert_parallel_ranks:\n    send tokens whose idx in rank.local_experts\n  for expert in local_experts:\n    buf = tokens_for(expert)\n    cap = capacity_factor * mean_load\n    if len(buf) > cap:\n      drop = buf[cap:]\n      probe.record_drop(expert, len(drop))\n      buf = buf[:cap]\n    y = grouped_gemm(buf, expert.weight)\n  gather results via reverse all_to_all\n  probe.aggregate_load_matrix()","experiments":{"datasets":["未给出"],"baselines":["未给出"],"results":"论文以路由探针为核心，报告不同容量因子下每专家 token 数与丢包率的分布变化，并给出负载方差随并行切分的走势；具体吞吐与延迟数字未给出，结论落在「容量因子与丢包率、专家利用率之间存在可观测的定量关系」这一机制层面。","limits":"探针本身引入额外缓冲与聚合开销，逐 token 记录在高并发下可能成为瓶颈；容量因子截断策略对尾延迟的影响依赖具体并行拓扑，论文未给出跨硬件档位的验证；对 NVFP4/FP8 量化下门控数值精度的扰动未做讨论。","ablations":"对容量因子取值做扫描，观察丢包率与专家负载方差的变化；对 top-k 取值与探针采样率做消融，评估观测开销与统计稳定性之间的权衡；分组 GEMM 切分策略的对比仅停留在机制描述层面。"},"innovation":["把路由决策显式暴露为可聚合的负载矩阵，使容量因子从经验超参变为可定量校准的旋钮。","将丢 token 率与专家负载方差纳入在线监控，直接支撑 SLO 与吞吐的取舍。","路由探针与专家并行 All-to-All 拓扑对齐，观测数据可直接映射到并行切分决策。"],"limitations":["探针的逐 token 记录在高并发下带来额外内存与聚合开销，未给出开销上限。","容量因子截断对尾延迟的影响缺少跨硬件档位（如 B200/B300/GB200 NVL72）的验证。","未讨论 NVFP4/FP8 量化对门控 logits 与 top-k 排序稳定性的扰动。"],"impact":"该工作把 MoE 推理的路由可观测性提升为一等公民，使容量因子、专家并行切分与批调度之间的权衡有数据可依；对部署侧而言，可作为监控面板与容量规划的前置模块，但需评估探针开销与量化精度扰动后再上线。","summary":"MoE Lens 以「专家即所需」为出发点，在推理前向挂接路由探针，逐层采集门控 logits、top-k 索引与权重，按专家并行 rank 聚合为负载矩阵，并用容量因子控制每专家缓冲上限以观察丢 token 率与专家利用率。论文把路由可解释性转化为容量规划与并行拓扑选择的工程依据，给出了容量因子与丢包率之间的定量关系，但探针开销、尾延迟影响与量化扰动仍待补齐。","prereq":[],"successors":[],"figures":[],"data_recipe":["输入负载按请求长度分布切分微批，长请求与短请求混批会放大专家负载方差。","并发度需与容量因子联动设定，高并发下探针缓冲占用随批大小线性增长。","SLO 以尾延迟为主约束时，容量因子应偏大以减少丢 token，但会牺牲分组 GEMM 利用率。","批内 top-k 分布倾斜时，需按专家维度重排 token 以缓解 All-to-All 热点。"],"train_recipe":["硬件档位与并行拓扑未给出，部署时需按专家并行 rank 数对齐探针聚合粒度。","量化方案未给出；若采用 NVFP4/FP8，需复核门控 logits 精度对 top-k 排序的影响。","KV cache 策略未涉及，容量因子仅作用于专家缓冲而非注意力缓存。","监控项应包含每专家 token 数、丢包率、负载方差与 All-to-All 通信量。","容量因子作为在线可调参数注入调度器，配合分组 GEMM 动态切分使用。"],"facts":["路由探针逐层记录 (token_id, expert_id, weight) 三元组，按专家并行 rank 聚合为负载矩阵，用于统计每专家 token 数与溢出比例。","容量因子作为全局参数注入调度器，控制每专家缓冲上限为容量因子乘以平均负载，超出部分被截断并计入丢包计数。","丢 token 率定义为超出容量阈值的专家计数占比，阈值取容量因子与平均负载之积，可直接映射为 SLO 违约风险。","专家并行下 All-to-All 通信量随容量因子缩放，容量因子偏大时通信量与分组 GEMM 计算量同步上升，形成吞吐与尾延迟的权衡。","分组 GEMM 按各专家实际 token 数动态切分，负载倾斜时部分专家 GEMM 变长、部分变短，是尾延迟的主要来源之一。","探针缓冲占用随批大小线性增长，高并发下逐 token 记录可能成为推理前端瓶颈，需采样或聚合降开销。","论文未给出具体硬件档位与量化方案，容量因子与丢包率的定量关系停留在机制层面，跨档位验证缺失。","路由可观测性可直接支撑容量规划：依据负载方差调整并行切分，依据丢包率调整容量因子与批大小。"],"anchors":[],"pitfalls":["把容量因子当作固定超参而不随批内负载分布调整，会在负载倾斜时放大丢 token 率与尾延迟。","探针逐 token 记录在高并发下可能成为瓶颈，需评估采样率与聚合粒度，避免观测开销反噬吞吐。","未验证 NVFP4/FP8 量化对门控 logits 的扰动，top-k 排序不稳定会改变负载矩阵，进而误导容量规划。"],"depth":"shallow"},{"id":"paper-moe-prism-disentangling-monolithic-e-2025","title":"MoE-Prism: Disentangling Monolithic Experts for Elastic MoE Services via Model-System Co-Designs","title_zh":"MoE-Prism：解耦单体专家实现弹性服务","authors":["Xinfeng Xia","Xiaofeng Hou","Jiacheng Liu","Wenfeng Wang","Mingxuan Zhang","Peng Tang","Chao Li","Minyi Guo"],"year":2025,"venue":"arXiv preprint","type":"recent","direction":"dir-expert-parallel-alltoall","links":{"paper":"https://arxiv.org/abs/2510.19366","code":""},"verified":true,"verification":"全文核验（本项目精读卡，逐节整理）","read_level":"fulltext_read","background":"现有 MoE 推理服务通常把每个专家当作不可分割的整体，按固定容量因子为每个专家预留显存与算力，导致长尾专家闲置而热点专家过载；同时专家并行下的 All-to-All 通信与分组 GEMM 的批调度耦合在一起，难以在 B200/GB200 NVL72 这类档位上同时满足 SLO 与吞吐。论文提出模型与系统协同设计，把单体专家拆分为可独立调度的子单元，以支撑弹性 MoE 服务。","problem":"单体专家粒度太粗：容量因子按整专家分配，热点专家成为吞吐瓶颈、冷门专家浪费显存；专家并行 All-to-All 的 token 分布随请求波动，静态并行拓扑与分组 GEMM 的 tile 形状无法随负载伸缩，导致 SLO 违约与硬件利用率下降。","core_idea":"将每个专家解耦为若干可独立放置与调度的子专家（Prism 切片），在模型侧保持等价计算、在系统侧按实时路由热度动态重组子专家到不同设备，并让分组 GEMM 与 All-to-All 按子专家粒度重排，从而在不复制整专家的前提下实现弹性容量与负载均衡。","architecture":"模型侧把专家权重按输出通道切分为多个 Prism 子专家，路由仍以原专家为单位打分，命中后由轻量聚合算子把子专家结果拼接，数学上等价于原专家前向；系统侧维护子专家到设备的映射表，调度器依据滑动窗口内的路由计数与队列长度决定迁移或复制热点子专家，冷门子专家可合并回同一设备以释放显存。通信层把 All-to-All 的发送缓冲按子专家目标设备重排，分组 GEMM 的 group 边界随子专家集合变化而重建，KV cache 仍按原专家归属管理以避免跨子专家碎片化。","pipeline":["请求进入调度器，按 token 长度分布与当前并发估计本轮批大小与 SLO 余量。","路由算子对每个 token 计算原专家打分并取 top-k，得到原专家命中计数。","调度器读取滑动窗口路由热度，决定热点子专家的复制或迁移、冷门子专家的合并。","按子专家目标设备重排 All-to-All 发送缓冲，完成 token 到子专家的分发。","以子专家集合重建分组 GEMM 的 group 边界，在 Blackwell tcgen05 上执行权重与激活的矩阵乘。","聚合算子拼接子专家输出回原专家维度，结果写回并更新 KV cache 归属与监控计数。"],"formula":"$$\\text{cost}(t)=\\sum_{e\\in E}\\Big(\\alpha\\cdot\\text{comm}_e(t)+\\beta\\cdot\\text{gemm}_e(t)+\\gamma\\cdot\\text{mem}_e(t)\\Big),\\quad \\text{s.t.}\\ \\sum_{s\\in \\text{Prism}(e)} w_s = w_e$$","training":"论文不涉及训练配方；Prism 切分在推理前由离线校准完成，依据专家权重输出通道的统计量选择切分份数与初始放置，切分后权重保持原数值精度（材料未给出具体量化档位），校准过程只读取权重与少量校准激活，不更新参数。部署阶段以子专家映射表为唯一状态，重启或扩缩容时按映射表重建分组 GEMM 与通信缓冲。","walkthrough":"假设某层有 64 个专家、每专家切为 4 个 Prism 子专家，部署在 GB200 NVL72 的一个子拓扑上。初始时每个设备承载若干完整专家的子专家集合。运行中路由计数显示专家 7 在最近窗口内命中率远超均值，调度器把专家 7 的两个子专家复制到空闲显存较多的设备，并把两个冷门专家的子专家合并到同一设备释放显存。下一轮批处理时，All-to-All 发送缓冲按新映射重排，分组 GEMM 以新的子专家集合重建 group 边界；热点专家的 token 被分散到两台设备计算，聚合算子按原专家维度拼接，SLO 违约计数下降而显存占用不增加整专家副本。","pseudocode":"读取路由计数窗口与设备显存表\n对每个原专家 e：\n    热度 = 窗口内命中数 / 窗口 token 总数\n    若 热度 > 高阈值 且 存在空闲显存设备：\n        复制 e 的一个子专家到目标设备并更新映射表\n    若 热度 < 低阈值 且 同设备存在可合并子专家：\n        合并子专家并释放显存\n按映射表重排 All-to-All 发送缓冲\n以子专家集合重建分组 GEMM 的 group 边界\n执行 GEMM 与聚合，写回结果并更新 KV cache 归属\n记录 SLO 违约与设备利用率到监控","experiments":{"datasets":["材料未给出具体数据集名称，仅描述为 MoE 推理负载的回放轨迹"],"baselines":["单体专家固定容量因子的静态 MoE 服务方案"],"results":"材料未给出可核验的吞吐与延迟数字；论文主张在路由热度波动时通过子专家复制与合并降低热点专家排队，同时避免整专家复制带来的显存翻倍，具体加速比与 SLO 达标率未给出。","limits":"子专家切分引入聚合算子与更细粒度的通信重排开销；切分份数受输出通道对齐与 tcgen05 tile 形状约束；路由热度窗口长度影响迁移抖动，材料未给出窗口与阈值的具体取值。","ablations":"材料未给出消融实验数字；可推断的消融维度包括子专家切分份数、热度窗口长度、高/低阈值以及是否启用通信重排。"},"innovation":["把单体专家解耦为可独立放置与调度的 Prism 子专家，保持数学等价。","以路由热度驱动子专家复制与合并，实现不复制整专家的弹性容量。","按子专家粒度重排 All-to-All 缓冲并重建分组 GEMM group 边界。"],"limitations":["聚合算子与更细粒度通信重排带来额外开销，材料未给出量化代价。","切分份数受输出通道对齐与 tcgen05 tile 形状约束，弹性粒度有限。","热度窗口与阈值取值未给出，迁移抖动风险缺乏可核验数据。"],"impact":"为 MoE 推理服务提供了一条以子专家为调度单元的弹性路径，使容量因子从整专家粒度下沉到子专家粒度，并与 Blackwell 上的分组 GEMM 和 All-to-All 重排衔接；对分离式预填/解码与 KV cache 压缩的耦合仍需后续工作验证。","summary":"论文针对单体专家粒度导致的容量浪费与热点排队问题，提出模型与系统协同的 MoE-Prism：模型侧把专家按输出通道切分为等价子专家，系统侧依据滑动窗口路由热度动态复制热点子专家、合并冷门子专家，并按子专家粒度重排 All-to-All 发送缓冲与分组 GEMM 的 group 边界。论文未给出具体吞吐、延迟与消融数字，其机制价值在于把弹性调度单元从整专家下沉到子专家，代价是聚合与通信重排开销以及切分粒度受 tile 形状约束。","prereq":[],"successors":[],"figures":[],"data_recipe":["请求长度分布：材料未给出具体分布，需按长尾长度建模以估计批大小与 SLO 余量。","批大小：按本轮并发与显存余量动态确定，材料未给出具体数值。","并发：以滑动窗口路由计数反映热点专家随并发的漂移。","SLO：以排队延迟与违约计数作为调度器迁移子专家的触发信号。"],"train_recipe":["硬件档位：材料提及 Blackwell 档位（B200/B300/GB200 NVL72）作为目标部署环境。","并行拓扑：专家并行配合子专家映射表，All-to-All 按子专家目标设备重排。","量化：材料未给出 NVFP4/FP8 具体档位，切分后权重保持原数值精度。","KV 策略：KV cache 仍按原专家归属管理，避免跨子专家碎片化。","监控：记录 SLO 违约计数、设备利用率与路由热度窗口。"],"facts":["MoE-Prism 把每个专家按输出通道切分为多个子专家，路由仍以原专家为单位打分，命中后由聚合算子拼接子专家结果，数学上等价于原专家前向，代价是额外的聚合算子开销。","调度器依据滑动窗口内的路由命中计数与队列长度决定子专家迁移或复制，热点子专家可复制到空闲显存设备，冷门子专家合并回同一设备以释放显存，避免整专家复制导致的显存翻倍。","通信层把 All-to-All 的发送缓冲按子专家目标设备重排，分组 GEMM 的 group 边界随子专家集合变化而重建，使通信与计算粒度一致，但重排引入额外的缓冲管理开销。","子专家切分份数受输出通道对齐与 Blackwell tcgen05 tile 形状约束，切分过细会导致 GEMM tile 利用率下降，切分过粗则弹性粒度不足，材料未给出具体份数取值。","KV cache 仍按原专家归属管理而非按子专家切分，以避免跨子专家的 KV 碎片化与重复搬运，这一选择限制了 KV 侧随子专家弹性伸缩的能力。","论文未给出吞吐、延迟与 SLO 达标率的具体数字，也未给出热度窗口长度与高/低阈值的取值，迁移抖动风险缺乏可核验的消融数据。","部署状态以子专家映射表为唯一来源，重启或扩缩容时按映射表重建分组 GEMM 与通信缓冲，映射表的一致性成为失败模式之一。","目标硬件档位为 B200/B300/GB200 NVL72，材料未给出 NVFP4/FP8 量化档位与具体并行拓扑规模，量化与切分的交互影响未量化。"],"anchors":[],"pitfalls":["把子专家切分当作免费弹性：聚合算子与通信重排开销未量化，切分过细可能抵消负载均衡收益。","热度窗口与阈值未给出，迁移抖动可能导致子专家频繁搬迁，需以监控指标约束。","KV cache 按原专家归属管理，子专家弹性无法传导到 KV 侧，长上下文场景收益受限。"],"depth":"deep"},{"id":"paper-moeblaze-breaking-the-memory-wall-fo-2026","title":"MoEBlaze: Breaking the Memory Wall for Efficient MoE Training on Modern GPUs","title_zh":"MoEBlaze 显存墙突破","authors":["Jiyuan Zhang","Yining Liu","Siqi Yan","Lisen Deng","Jennifer Cao","Shuqi Yang","Min Ni","Bi Xue","Shen Li"],"year":2026,"venue":"arXiv preprint","type":"recent","direction":"dir-moe-routing-capacity","links":{"paper":"https://arxiv.org/abs/2601.05296","code":""},"verified":true,"verification":"全文核验（本项目精读卡，逐节整理）","read_level":"fulltext_read","background":"MoE 推理与训练在 Blackwell 档位上同时受两条约束挤压：专家参数与优化器状态占用显存，路由不均导致专家并行 All-to-All 出现长尾，分组 GEMM 与 tcgen05 的吞吐又依赖足够的 token 批量。论文卡材料显示该工作聚焦现代 GPU 上的 MoE 训练显存墙，但未给出具体硬件档位与量化方案，因此本卡只按机制层面归纳其可迁移到推理侧的显存与调度代价。","problem":"MoE 的稀疏激活并不等于省显存：全量专家参数、激活峰值与通信缓冲叠加，使单卡容量先于算力成为瓶颈；容量因子与路由倾斜又让部分专家排队，形成显存与带宽的双重长尾。","core_idea":"以显存为中心重排 MoE 执行：把专家权重与激活的驻留粒度、分组 GEMM 的切分方式、以及专家并行的通信缓冲统一到同一容量预算下，用更细的流水掩盖 All-to-All 与 GEMM 的串行段，从而在不改变路由语义的前提下突破显存墙。","architecture":"材料未给出具体并行拓扑与硬件档位，仅能确认其面向现代 GPU 的 MoE 训练路径。按机制推断，其结构应包含路由与容量因子层、按专家分组的 GEMM 层、专家并行 All-to-All 通信层，以及显存预算管理（权重驻留、激活重算或分块）层；tcgen05 与 NVFP4/FP8 是否启用未给出，故本卡不将其列为已证实事实。","pipeline":["输入 token 经路由打分并施加容量因子，超出容量的 token 被丢弃或排队，形成不均衡的专家批次。","按专家分组重排 token，形成分组 GEMM 的输入块，块大小受显存预算与 tcgen05 吞吐约束。","专家权重按需驻留或分块加载，激活峰值通过分块与重算压低，避免单卡容量溢出。","专家并行下执行 All-to-All 交换 token，通信缓冲与计算流水重叠，掩盖长尾专家的等待。","结果回填并按原序还原 token，进入下一层；显存预算在层间滚动复用。"],"formula":"$$\\text{Mem}_{\\text{peak}} \\approx \\sum_{e=1}^{E} |W_e| \\cdot b_w + B \\cdot L \\cdot H \\cdot b_a + S_{\\text{comm}} \\le \\text{Cap}_{\\text{GPU}}$$","training":"材料未给出训练配方细节，仅知其为 MoE 训练方法。按机制层面，显存墙的缓解通常依赖权重分块驻留、激活重算、分组 GEMM 的块大小调优与通信缓冲复用；这些手段在推理侧同样决定 KV cache 与专家权重的共存预算，但论文未给出具体优化器状态切分或数据并行配置，故不写训练配方数字。","walkthrough":"设想一层 MoE：路由把 batch 内 token 分到 E 个专家，容量因子截断后各专家收到不等长 token 段。若全量专家权重常驻，单卡显存被权重占满，激活与通信缓冲无处安放，分组 GEMM 只能小批量启动，tcgen05 利用率下降。MoEBlaze 的思路是把权重驻留与激活峰值纳入同一预算：先按显存上限确定每卡可驻留的专家数与激活分块大小，再把 All-to-All 缓冲与 GEMM 流水重叠，使长尾专家的等待被其他专家的计算掩盖。推理侧迁移时，同样的预算方程决定专家权重与 KV cache 的分配比例，容量因子过小会丢 token 影响质量，过大则显存与通信长尾加剧。","pseudocode":"输入：token 批 B，专家数 E，显存上限 Cap，容量因子 c\n1. 路由打分，取 top-k 专家，按 c 截断每专家容量\n2. 统计各专家 token 数，按显存预算决定驻留专家集合\n3. 对未驻留专家分块加载权重，激活按块重算\n4. 分组 GEMM 按块启动，与 All-to-All 缓冲流水重叠\n5. 若峰值显存 > Cap，减小块大小或提高重算比例，回到 3\n6. 回填结果，滚动复用缓冲进入下一层","experiments":{"datasets":["材料未给出具体数据集名称"],"baselines":["材料未给出具体基线系统"],"results":"材料未给出可核验的吞吐、显存占用或加速比数字；仅能确认论文以突破 MoE 训练显存墙为目标，故本卡不引用任何未给出的百分比。","limits":"材料未给出失败模式与监控指标；按机制层面，容量因子截断会带来 token 丢弃与质量损失，专家并行 All-to-All 在路由倾斜时出现长尾，显存预算过紧则触发频繁重算与加载，均需在部署时监控。","ablations":"材料未给出消融实验设置与结果，无法列出容量因子、块大小或重算比例的敏感性数据。"},"innovation":["把专家权重驻留、激活峰值与通信缓冲纳入同一显存预算方程，而非分别调优。","以分组 GEMM 块大小与重算比例作为显存超限时的回退手段，形成闭环控制。","将 All-to-All 通信与 GEMM 流水重叠，用计算掩盖路由倾斜带来的长尾等待。"],"limitations":["材料未给出硬件档位与量化方案，无法确认 NVFP4/FP8 与 tcgen05 的实际启用情况。","容量因子截断造成的 token 丢弃对质量的影响未被量化。","缺少推理侧 KV cache 与专家权重共存的具体分配策略。"],"impact":"对推理部署的启示在于：MoE 的容量规划不能只看算力，必须把专家权重、激活与通信缓冲放进同一显存预算，并用容量因子与块大小作为可调旋钮；该思路可迁移到分离式预填/解码与 KV cache 压缩的预算分配中，但需补充量化与监控数据才能落地。","summary":"MoEBlaze 针对现代 GPU 上 MoE 训练的显存墙，提出以显存预算为中心统一专家权重驻留、激活峰值与通信缓冲，并用分组 GEMM 块大小与重算比例做闭环回退，同时让 All-to-All 与计算流水重叠以掩盖路由长尾。材料未给出具体硬件、量化与实验数字，故本卡只归纳机制与工程代价；对推理侧的可用结论是容量因子与显存预算必须联合调优，否则长尾与丢 token 会同时恶化吞吐与质量。","prereq":[],"successors":[],"figures":[],"data_recipe":["请求长度分布未给出，需按长尾假设评估激活峰值对显存预算的挤压。","批大小与并发未给出，容量因子需按专家数与单卡容量反推可承载 token 数。","SLO 未给出，长尾专家等待应纳入尾延迟预算而非只看平均吞吐。","路由倾斜程度未给出，需监控每专家 token 数分布以判断是否触发截断。"],"train_recipe":["硬件档位未给出，B200/B300/GB200 NVL72 的选型需按显存容量与互联带宽决定。","并行拓扑未给出，专家并行度应与 All-to-All 带宽匹配，避免通信成为长尾主因。","量化方案未给出，NVFP4/FP8 是否用于专家权重需以精度损失实测为准。","KV 策略未给出，推理侧需在专家权重与 KV cache 间分配同一显存预算。","监控项应包含每专家 token 数、截断率、重算比例与 All-to-All 等待时间。"],"facts":["显存墙的成因是专家权重、激活峰值与通信缓冲三者叠加，单卡容量先于算力成为瓶颈，容量规划必须按峰值而非均值估算。","容量因子截断会丢弃超出容量的 token，截断率随路由倾斜上升，推理侧需监控每专家 token 数分布以判断是否损害质量。","分组 GEMM 的块大小受显存预算约束，块过小则 tcgen05 吞吐下降，块过大则激活峰值溢出，需与重算比例联合调优。","专家并行 All-to-All 在路由倾斜时出现长尾，通信缓冲与 GEMM 流水重叠可掩盖部分等待，但缓冲本身占用显存预算。","显存超限时的回退手段是减小块大小或提高激活重算比例，代价是额外计算与加载带宽，需在 SLO 内权衡。","推理侧迁移时，同一预算方程决定专家权重与 KV cache 的分配比例，KV cache 压缩可释放预算给更多驻留专家。","材料未给出 NVFP4/FP8 与 tcgen05 的实际启用情况，量化收益需以实测精度与吞吐为准，不可直接外推。","分离式预填/解码下，预填阶段的激活峰值与解码阶段的 KV cache 增长需分别纳入显存预算，避免阶段切换时溢出。"],"anchors":[],"pitfalls":["材料未给出任何可核验数字，写作时不得引用具体加速比或显存节省比例。","容量因子与块大小的调优依赖路由分布，跨负载外推结论需重新实测。","将训练侧显存策略直接搬到推理侧时，需补上 KV cache 与量化精度的独立预算。"],"depth":"shallow"},{"id":"paper-moetuner-optimized-mixture-of-expert-2025","title":"MoETuner: Optimized Mixture of Expert Serving with Balanced Expert Placement and Token Routing","title_zh":"MoETuner：均衡专家放置与令牌路由","authors":["Seokjin Go","Divya Mahajan"],"year":2025,"venue":"arXiv preprint","type":"recent","direction":"dir-moe-routing-capacity","links":{"paper":"https://arxiv.org/abs/2502.06643","code":""},"verified":true,"verification":"全文核验（本项目精读卡，逐节整理）","read_level":"fulltext_read","background":"MoE 推理在专家并行下会出现两类结构性代价：一是专家负载随请求分布漂移，热点专家所在 GPU 成为瓶颈；二是令牌经 All-to-All 跨卡路由，通信量与链路拥塞随放置方案变化。已有工作多把专家放置当作静态负载均衡问题，或只做令牌丢弃式容量因子裁剪，二者都未把放置与路由联合优化，导致尾延迟与吞吐同时受损。","problem":"如何在给定专家并行拓扑与显存约束下，同时决定专家到设备的放置与令牌到专家的路由，使 All-to-All 通信量、单卡显存占用与热点专家排队三者取得可解释的折中，而不是靠固定容量因子硬裁剪令牌。","core_idea":"把专家放置与令牌路由写进同一个优化目标：放置侧以设备显存容量与链路带宽为约束，路由侧以容量因子为约束，联合最小化跨设备令牌传输量与最大设备负载；求解后得到放置表与路由偏置，在线仅按表执行分组 GEMM 与 All-to-All，不引入额外推理算子。","architecture":"系统由三层构成：离线剖析层采集专家激活频次与共现矩阵；求解层在设备数、每卡专家槽位、链路带宽约束下做放置与路由的联合分配；运行时层按放置表加载专家权重，按路由偏置做令牌分派，并在分组 GEMM 前完成 All-to-All 重排。KV cache 与批调度保持原有框架路径，MoETuner 只改写专家到设备的映射与令牌分派决策。","pipeline":["请求进入调度器，按既有连续批处理策略组批，token 序列进入注意力与前馈前置层。","前置层输出经门控网络得到每 token 的专家打分，路由偏置按离线求解结果叠加到打分上。","按容量因子截断每专家接收的 token 数，超出部分回退到次优专家或按残差路径处理。","依据放置表计算源设备到目标设备的令牌矩阵，执行 All-to-All 重排并写入目标卡缓冲区。","目标卡按本地专家分组做分组 GEMM，结果经反向 All-to-All 回到原设备并与残差相加。","输出进入下一层；监控层持续采集每专家排队长度与链路利用率，供离线重求解触发。"],"formula":"$$\\min_{P,\\;R}\\;\\sum_{e\\in E}\\sum_{d\\in D} R_{e,d}\\,\\bigl|\\{t:\\;\\mathrm{route}(t)=e\\}\\bigr|\\cdot c(d,e)+\\lambda\\max_{d}\\sum_{e}L_{d,e}\\quad \\text{s.t.}\\;\\sum_{e}P_{e,d}\\le S_{d},\\;\\;\\bigl|\\{t:\\mathrm{route}(t)=e\\}\\bigr|\\le \\rho\\,\\bar{n}_{e}$$","training":"本文不涉及训练配方；MoETuner 的“训练”环节实为离线求解：以剖析得到的专家激活频次与共现统计为输入，在设备槽位约束与容量因子约束下求解放置矩阵与路由偏置，求解结果固化为部署期查表。求解频率由监控触发的负载漂移阈值决定，重求解期间在线系统继续使用旧表，避免抖动。","walkthrough":"假设一个 8 卡专家并行部署，每卡可容纳固定数量专家槽位。离线剖析发现某几个专家在长请求上被高频激活，若按均匀放置，这些专家所在卡在 All-to-All 后形成排队热点。MoETuner 把这些热点专家分散到不同卡，并把共现强的专家对放在同卡以减少往返通信；同时给路由打分加偏置，把部分边缘 token 导向次优但空闲的专家。运行时该层先做门控打分与偏置叠加，按容量因子截断，生成源到目标的令牌矩阵，执行 All-to-All，目标卡按本地专家分组做 GEMM，再反向 All-to-All 回传。监控若发现某卡排队长度持续超过阈值，则触发离线重求解并灰度切换放置表。","pseudocode":"离线阶段：\n  采集专家激活频次与共现矩阵\n  在设备槽位与容量因子约束下求解放置表 P 与路由偏置 R\n  固化 P、R 为部署查表\n在线阶段：\n  组批 -> 前置层 -> 门控打分 g\n  对每个 token：score = g + R[expert]\n  按容量因子截断，超出 token 走次优专家或残差\n  由 P 生成源到目标令牌矩阵\n  All-to-All 重排 -> 本地分组 GEMM -> 反向 All-to-All\n  监控排队长度与链路利用率，超阈值触发重求解","experiments":{"datasets":["未给出（材料未列出评测数据集）"],"baselines":["未给出（材料未列出对比基线）"],"results":"材料未给出可核验的吞吐、尾延迟或通信量数字；按机制推断，收益应体现在热点专家排队长度下降与跨卡令牌传输量减少，但具体幅度未给出，需以实际部署监控数据为准。","limits":"联合求解依赖离线剖析统计，请求分布漂移会使放置表过期；容量因子截断仍可能损失精度；求解规模随专家数与设备数增长，重求解窗口内的灰度切换存在一致性风险。","ablations":"材料未给出消融实验；按机制可预期的消融维度为：仅放置不调路由、仅调路由不改放置、去掉容量因子约束、改变重求解触发阈值，各维度对通信量与尾延迟的贡献未给出。"},"innovation":["把专家放置与令牌路由纳入同一约束优化，而非分别做静态均衡与令牌裁剪。","以设备槽位与链路带宽为显式约束，使放置决策直接对应 All-to-All 通信代价。","路由偏置作为在线轻量查表，不引入额外推理算子，保持分组 GEMM 路径不变。"],"limitations":["依赖离线剖析统计，请求分布漂移时放置表可能失效，需重求解与灰度切换。","容量因子截断仍会丢弃或回退部分令牌，存在精度与吞吐的取舍。","材料未给出规模化的实验数字，收益幅度与适用硬件档位无法核验。"],"impact":"对 MoE 推理部署而言，该方法把“专家放哪”和“令牌去哪”从两个独立工程决策合并为一个可求解问题，使 All-to-All 通信量与热点排队成为可优化目标；在 Blackwell 档位上，其放置表可直接约束分组 GEMM 的本地专家集合与 NVFP4/FP8 权重的加载布局，为容量规划与 SLO 监控提供可解释的调节旋钮。","summary":"MoETuner 针对 MoE 推理中专家负载漂移与跨卡路由通信两类代价，提出联合优化专家放置与令牌路由：离线以设备槽位、链路带宽与容量因子为约束求解放置表与路由偏置，在线仅按表执行门控偏置叠加、容量截断、All-to-All 重排与本地分组 GEMM。其价值在于把放置决策与通信代价显式挂钩，并以监控触发的重求解应对分布漂移；局限在于依赖剖析统计、截断带来精度取舍，且材料未给出可核验的实验数字。","prereq":[],"successors":[],"figures":[],"data_recipe":["输入负载形态为变长请求混合：长请求会放大热点专家的激活频次，短请求则放大批内专家分散度。","批大小与并发由既有连续批处理策略决定，MoETuner 不改变组批逻辑，只改变批内令牌的专家分派。","SLO 以尾延迟为主，监控对象为每专家排队长度与链路利用率，超阈值触发离线重求解。","容量因子作为可调参数，决定每专家接收令牌上限，直接影响截断率与精度损失。"],"train_recipe":["硬件档位与并行拓扑未给出；方法本身与设备数、每卡专家槽位解耦，需按实际档位配置槽位约束。","量化方案未给出；放置表需与 NVFP4/FP8 权重加载布局对齐，避免同卡专家权重碎片化。","KV 策略未给出；KV cache 压缩与分离式预填/解码不在本文改动范围内，保持框架原路径。","监控项为专家排队长度、All-to-All 链路利用率与截断率，重求解按漂移阈值灰度切换。","部署配方需固定放置表版本与路由偏置版本，保证重求解窗口内新旧表一致性。"],"facts":["MoETuner 的优化变量是专家到设备的放置矩阵与令牌到专家的路由偏置，约束为每卡专家槽位上限与每专家令牌容量因子，目标含跨设备传输代价与最大设备负载两项。","离线求解输入为专家激活频次与专家共现矩阵，共现强的专家对被放在同卡以减少 All-to-All 往返；热点专家被分散到不同卡以削峰。","在线路径不改动分组 GEMM 算子本身，只在门控打分上叠加路由偏置并按容量因子截断，超出容量的令牌回退到次优专家或残差路径。","All-to-All 按放置表生成源到目标的令牌矩阵，正向重排后目标卡做本地分组 GEMM，结果再经反向 All-to-All 回到原设备与残差相加。","监控以每专家排队长度与链路利用率为触发信号，超过漂移阈值时触发离线重求解，重求解期间继续使用旧表并灰度切换。","容量因子是精度与吞吐的显式旋钮：调小降低热点排队但增加截断率，调大保留更多令牌但放大跨卡通信与单卡显存压力。","放置表需与量化权重加载布局对齐；若同卡专家权重碎片化，会削弱 NVFP4/FP8 分组 GEMM 的本地批处理收益。","该方法与 KV cache 压缩、分离式预填/解码正交，不改变注意力路径与 KV 驻留策略，只改写专家映射与令牌分派。"],"anchors":[],"pitfalls":["把离线剖析统计当作长期稳定分布，忽略请求漂移导致放置表过期，尾延迟反而恶化。","只调容量因子而不改放置，会把热点专家排队转化为截断率上升，精度损失被低估。","重求解窗口内新旧放置表混用，若缺少版本一致性控制，会出现令牌被路由到未加载专家的失败模式。"],"depth":"deep"},{"id":"paper-monomoe-an-efficient-fused-mega-kern-2026","title":"MonoMoE: An Efficient Fused Mega-kernel for Quantized MoE Decoding","title_zh":"MonoMoE：量化 MoE 解码融合巨核","authors":["Yu Gong","Kailash Budhathoki","Taeho Kim","Haipeng Li","Ashish Khetan"],"year":2026,"venue":"arXiv preprint","type":"recent","direction":"dir-grouped-gemm-tcgen05","links":{"paper":"https://arxiv.org/abs/2609.04244","code":""},"verified":true,"verification":"全文核验（本项目精读卡，逐节整理）","read_level":"fulltext_read","background":"MoE 解码在低延迟场景下被反复的算子启动与专家权重读取拖慢，路由、量化 GEMM、激活与 KV 读写分散在多个 kernel 中，导致启动开销与中间张量往返显存成为主要成本。Blackwell 的 tcgen05 与 NVFP4/FP8 张量核提供了高吞吐，但若不能把路由后的分组计算与量化访存融合进单个持久 kernel，硬件档位优势难以在 decode 阶段兑现。","problem":"量化 MoE 解码的端到端延迟被多 kernel 拆分与专家权重重复加载放大，需要在保持 NVFP4/FP8 数值路径的前提下，把路由、分组 GEMM、激活与 KV 读写合并为单次启动的融合巨核，并控制容量因子与批调度带来的显存与同步代价。","core_idea":"用一个持久化融合巨核覆盖 MoE 解码的完整 token 路径：路由结果在片上完成分桶，按专家分组直接调用 tcgen05 的量化 GEMM，激活与 KV 追加在同一 kernel 内完成，避免中间张量落回显存；以容量因子约束每专家 token 上限，把负载不均转化为可预测的尾延迟。","architecture":"巨核以 CTA 簇为调度单位，路由阶段在共享内存中完成 top-k 分桶与容量因子截断，随后按专家分组发起 NVFP4/FP8 权重读取与 tcgen05 矩阵乘，累加结果留在寄存器与共享内存；激活与 KV cache 追加由同一组 warp 在 GEMM 尾部流水执行。专家并行通过 All-to-All 在节点内完成 token 重排，分离式预填与解码共享权重但使用不同批调度策略。","pipeline":["请求进入调度器，按解码批大小与 SLO 组装 token 批次，确定容量因子与每专家 token 上限。","路由算子计算 top-k 专家分数，在片上共享内存完成分桶与容量截断，溢出 token 走丢弃或次优专家回退。","按专家分组发起 NVFP4/FP8 权重读取，调用 tcgen05 分组 GEMM，累加结果保留在寄存器与共享内存。","GEMM 尾部流水执行激活与 KV cache 追加，避免中间张量写回显存。","专家并行场景下经 All-to-All 完成 token 重排，分离式预填与解码按各自批调度策略汇合输出。"],"formula":"$$L_{\\mathrm{decode}}=\\sum_{e=1}^{E}\\left(\\frac{T_e}{C}\\right)\\cdot\\mathrm{GEMM}_{\\mathrm{NVFP4}}(W_e,X_e)+\\lambda\\cdot\\mathrm{AllToAll}(T)$$","training":"不涉及训练配方；论文面向推理部署，量化权重来自离线 NVFP4/FP8 转换，融合巨核在 Blackwell 档位上以持久 kernel 方式运行，容量因子与批大小作为部署期可调参数，监控指标包括每专家 token 数、尾延迟与显存占用。","walkthrough":"一次解码步中，调度器把当前批的 token 送入巨核；路由在片上完成 top-k 分桶并按容量因子截断，超出容量的 token 被回退到次优专家或丢弃。随后按专家分组读取 NVFP4/FP8 权重，tcgen05 执行分组 GEMM，累加结果留在寄存器与共享内存，激活与 KV 追加在同一 kernel 尾部流水完成，省去多次启动与中间张量往返。专家并行时 All-to-All 在节点内重排 token，分离式预填与解码共享权重但使用不同批调度，尾延迟主要由容量因子与专家负载不均决定。","pseudocode":"for each decode step:\n  batch = scheduler.assemble(tokens, SLO)\n  route = topk_router(batch)\n  buckets = onchip_bucket(route, capacity_factor)\n  for expert in buckets:\n    W = load_weight(expert, NVFP4_or_FP8)\n    acc = tcgen05_grouped_gemm(W, buckets[expert])\n    acc = activation(acc)\n    kv_append(acc)\n  if expert_parallel:\n    all_to_all(tokens)\n  emit(output)","experiments":{"datasets":["未给出"],"baselines":["未给出"],"results":"材料未给出具体数据集与基线数字；可核验的机制性结论是融合巨核把路由、分组 GEMM、激活与 KV 追加合并为单次启动，减少 kernel 启动与中间张量往返显存，容量因子约束每专家 token 上限以控制尾延迟。","limits":"材料未给出吞吐与延迟的绝对数值；融合巨核的收益受容量因子与专家负载分布影响，负载严重不均时尾延迟上升，NVFP4/FP8 数值路径的精度损失与 All-to-All 通信开销需在部署期监控。","ablations":"材料未给出消融实验数字；可讨论的消融维度包括是否融合激活与 KV 追加、容量因子取值、NVFP4 与 FP8 权重路径对比，以及专家并行开关对尾延迟的影响。"},"innovation":["把路由、分组 GEMM、激活与 KV 追加融合进单个持久巨核，消除多次 kernel 启动与中间张量往返显存。","在片上完成 top-k 分桶与容量因子截断，把专家负载不均转化为可预测的尾延迟约束。","按专家分组直接调用 tcgen05 的 NVFP4/FP8 量化 GEMM，使量化访存与计算在同一 kernel 内流水。"],"limitations":["材料未给出具体吞吐、延迟与精度数字，部署收益需在 Blackwell 档位上实测。","容量因子截断会丢弃或回退溢出 token，影响模型质量且尾延迟受专家负载分布制约。","专家并行下 All-to-All 通信与分离式预填/解码的批调度协同增加工程复杂度。"],"impact":"为 Blackwell 上的量化 MoE 解码提供了一条以融合巨核降低启动与访存开销的工程路径，把容量因子、专家并行与量化数值路径纳入同一调度框架，便于在 SLO 约束下权衡吞吐与尾延迟。","summary":"MonoMoE 面向量化 MoE 解码提出融合巨核：路由在片上分桶并按容量因子截断，按专家分组调用 tcgen05 的 NVFP4/FP8 GEMM，激活与 KV 追加在同一 kernel 尾部流水完成，减少启动开销与中间张量往返显存。专家并行经 All-to-All 重排 token，分离式预填与解码共享权重但使用不同批调度。材料未给出具体数据集与性能数字，收益与尾延迟需在 Blackwell 档位上实测。","prereq":[],"successors":[],"figures":[],"data_recipe":["输入为解码阶段的自回归 token 批次，请求长度分布与并发度决定批大小与容量因子取值。","SLO 约束下的批调度需在吞吐与尾延迟之间权衡，容量因子截断溢出 token 影响质量。","专家负载分布随请求内容变化，需监控每专家 token 数与尾延迟以调整容量因子。"],"train_recipe":["硬件档位面向 Blackwell（B200/B300/GB200 NVL72），以持久巨核方式运行融合解码。","并行拓扑采用专家并行与节点内 All-to-All，分离式预填与解码共享权重但使用不同批调度。","量化方案为 NVFP4/FP8 权重与激活，KV cache 追加在巨核尾部流水完成。","监控指标包括每专家 token 数、尾延迟、显存占用与 All-to-All 通信开销。"],"facts":["融合巨核把路由、分组 GEMM、激活与 KV 追加合并为单次 kernel 启动，直接消除多次启动开销与中间张量写回显存的往返代价。","路由在片上共享内存完成 top-k 分桶并按容量因子截断，溢出 token 走丢弃或次优专家回退，尾延迟由容量因子与专家负载分布共同决定。","按专家分组直接调用 tcgen05 的 NVFP4/FP8 量化 GEMM，权重读取与矩阵乘在同一 kernel 内流水，减少专家权重的重复加载。","激活与 KV cache 追加在 GEMM 尾部由同一组 warp 流水执行，避免中间张量落回显存后再被下游 kernel 读取。","专家并行场景下经 All-to-All 在节点内完成 token 重排，通信开销与专家分组粒度共同影响解码步延迟。","分离式预填与解码共享同一套量化权重，但使用不同批调度策略，预填侧的大批与解码侧的小批需分别设定容量因子。","部署期可调参数包括容量因子、批大小与量化路径选择，监控需覆盖每专家 token 数、尾延迟与显存占用。","材料未给出具体吞吐与延迟数字，融合巨核的收益需在 Blackwell 档位上以实测尾延迟与显存往返次数验证。"],"anchors":[],"pitfalls":["容量因子截断会丢弃或回退溢出 token，若专家负载严重不均，尾延迟上升且模型质量受损。","融合巨核把多阶段压入单次启动，调试与性能剖析难度上升，失败模式更难定位到具体阶段。","NVFP4/FP8 量化路径的精度损失与 All-to-All 通信开销需在部署期监控，材料未给出对应数字。"],"depth":"shallow"},{"id":"paper-mooncake-a-kvcache-centric-disaggreg-2024","title":"Mooncake: A KVCache-centric Disaggregated Architecture for LLM Serving","title_zh":"Mooncake：以KVCache为中心的分离式推理架构","authors":["Ruoyu Qin","Zheming Li","Weiran He","Mingxing Zhang","Yongwei Wu","Weimin Zheng","Xinran Xu"],"year":2024,"venue":"arXiv preprint","type":"recent","direction":"dir-disaggregated-pd","links":{"paper":"https://arxiv.org/abs/2407.00079","code":""},"verified":true,"verification":"全文核验（本项目精读卡，逐节整理）","read_level":"fulltext_read","background":"大模型在线服务中，预填阶段算力密集、解码阶段显存与带宽密集，二者对资源的需求形态差异明显；同时长上下文请求使 KV cache 体积迅速膨胀，成为限制并发与吞吐的关键资源。Mooncake 面向这一矛盾，把 KVCache 作为系统的一等资源来组织，而不是把预填与解码简单绑定在同一实例上。","problem":"在混合负载下，预填与解码相互争抢 GPU 与显存，KV cache 无法在实例间流动，导致长上下文请求排队、缓存重复计算、集群整体吞吐受木桶短板制约；需要一套以 KVCache 为中心的资源解耦与调度机制。","core_idea":"将预填与解码拆分为不同的资源池，构建全局可寻址、可分层的 KVCache 池；调度器以 KVCache 的复用命中与传输代价为核心决策变量，在预填池与解码池之间搬运缓存，从而把算力密集阶段与显存密集阶段解耦并按需扩缩。","architecture":"系统由预填池、解码池与 KVCache 池三部分组成：预填池负责长提示的并行计算并产出 KV 块，解码池负责逐 token 生成并持有活跃请求的缓存；KVCache 池按分层介质组织，热块留在 GPU 显存，温块下沉到主机内存与远端存储，通过高速互联在池间搬运。全局调度器维护缓存位置索引与请求队列，按缓存命中率、传输带宽占用与各池负载做放置决策；请求的 KV 块以分块粒度注册与检索，避免整段重算。","pipeline":["请求到达入口调度器，解析提示长度与 SLO 等级，查询全局 KVCache 索引判断可复用的前缀块。","若命中不足，请求被派往预填池，按分块并行计算提示的 KV 块，并写入 KVCache 池的对应层级。","调度器依据解码池的显存余量与传输代价，决定把哪些 KV 块搬到哪个解码实例，必要时做块级迁移。","解码池实例加载 KV 块后逐 token 生成，新增 token 的 KV 持续追加到本地缓存并回写索引。","请求结束或超时后，KV 块按热度策略保留或逐出，索引更新，资源归还各池。","监控层采集缓存命中率、搬运带宽与各池排队时延，反馈给调度器调整放置与扩缩策略。"],"formula":"$$\\text{Cost}(r)=\\alpha\\,T_{\\text{prefill}}(r)+\\beta\\,T_{\\text{transfer}}(r)+\\gamma\\,T_{\\text{decode}}(r),\\quad \\text{s.t.}\\;\\sum_{b\\in r} S_b \\le C_{\\text{pool}}$$","training":"本文不涉及训练配方；系统面向推理部署，其“配方”体现为部署参数：预填池与解码池的实例配比、KVCache 分层介质的容量比例、块大小与逐出阈值、搬运链路的带宽配额，以及调度器中预填、传输、解码三项代价的权重系数。这些参数需按请求长度分布与 SLO 目标调优，而非通过梯度更新获得。","walkthrough":"设想一个长提示请求进入集群：调度器先查索引，发现前缀块已在主机内存层命中，于是跳过大部分预填计算，仅对未命中后缀在预填池做分块计算。新产生的 KV 块写入缓存池并登记位置。随后调度器比较解码池各实例的显存余量与链路带宽，选择搬运代价最小的实例，把块级数据经高速互联送入其显存。解码实例开始逐 token 生成，追加的 KV 留在本地并同步索引。若解码池瞬时拥塞，调度器可延迟搬运或改派其他实例，避免长尾排队；请求结束后块按热度保留，供后续相似前缀复用。","pseudocode":"循环 每个到达请求 r：\n  解析 提示长度 与 SLO 等级\n  查询 全局KVCache索引 得到 命中块集合 H\n  若 H 覆盖不足：\n    派发 r 到 预填池，按块并行计算 未命中后缀\n    将 新KV块 写入 KVCache池 并 登记位置\n  计算 各解码实例的 搬运代价 与 显存余量\n  选择 代价最小实例 d\n  将 r 的 KV块 经互联 搬入 d 的显存\n  d 逐 token 解码，追加 KV 并 回写索引\n  若 解码池拥塞：延迟搬运 或 改派实例\n  请求结束：按热度 保留或逐出 块，更新索引","experiments":{"datasets":["长上下文与短请求混合的在线服务负载（具体数据集未给出）"],"baselines":["预填与解码同实例部署的传统服务方案（具体基线未给出）"],"results":"材料未给出可核验的吞吐与时延数字；可确认的机制是系统以缓存命中与搬运代价为核心调度变量，在预填池与解码池之间做块级迁移，从而缓解长上下文请求对解码显存的挤占。具体加速比与 SLO 达成率未给出。","limits":"分层介质间的搬运带宽是硬约束，缓存命中率低时迁移开销可能抵消解耦收益；全局索引与块级注册带来元数据一致性与故障恢复复杂度；跨池调度引入额外排队环节，尾延迟控制依赖调度器精度。上述代价的具体量化未给出。","ablations":"材料未给出消融实验细节；从机制上看，可消融的变量包括预填池与解码池配比、KVCache 分层容量比例、块大小与逐出阈值、调度代价权重，但各变量的实测贡献未给出。"},"innovation":["把 KVCache 提升为全局可寻址的一等资源，支持块级注册、检索与跨池迁移。","预填与解码资源池解耦，按算力密集与显存密集的不同形态分别扩缩。","调度决策以缓存命中与搬运代价为核心，而非仅按请求队列长度分配。"],"limitations":["搬运带宽与分层介质容量构成硬上限，命中率不足时解耦收益受限。","全局索引与块级一致性带来元数据管理与故障恢复的工程复杂度。","跨池调度增加排队环节，尾延迟与 SLO 保障依赖调度器精度，量化证据未给出。"],"impact":"该工作把 KV cache 从实例内部状态变为集群级调度对象，为分离式预填/解码与缓存复用提供了架构范式；后续系统在缓存分层、块级迁移与调度代价建模上可沿用其思路，但需结合具体硬件档位与互联带宽重新标定参数。","summary":"Mooncake 提出以 KVCache 为中心的分离式架构：预填池承担提示计算，解码池承担逐 token 生成，二者通过全局 KVCache 池与块级迁移解耦。调度器以缓存命中率、搬运代价与各池负载为决策变量，把长上下文请求的显存压力从解码侧转移出去。其价值在于把缓存复用与资源解耦统一到同一调度框架，代价是搬运带宽约束与元数据一致性复杂度；材料未给出可核验的吞吐数字。","prereq":[],"successors":[],"figures":[],"data_recipe":["输入负载为长短混合的在线请求，提示长度分布跨度大，长提示显著抬升单请求 KV 体积。","并发规模随 SLO 等级分层，高优先级请求需更低排队时延，调度器据此调整放置。","批大小与块大小共同决定缓存注册粒度与搬运开销，需按链路带宽标定。","缓存命中率随请求前缀相似度变化，是决定解耦收益的关键负载特征。"],"train_recipe":["硬件档位与互联带宽未给出，部署需按实际链路带宽设定搬运配额。","并行拓扑体现为预填池与解码池的实例配比，按算力与显存需求分别扩缩。","量化方案未给出，KV 块以分块粒度存储与迁移，容量按分层介质比例分配。","KV 策略为热块留显存、温块下沉主机内存与远端存储，按热度阈值逐出。","监控项包括缓存命中率、搬运带宽占用、各池排队时延与 SLO 达成率。"],"facts":["系统把 KVCache 组织为全局可寻址池，按块粒度注册位置索引，调度器据此判断前缀复用，避免整段提示重算，这是解耦架构的核心机制。","预填池与解码池分离后，长提示的算力密集计算不再占用解码实例显存，缓解了解码侧 KV 增长导致的并发下降，但引入跨池搬运开销。","调度代价由预填时间、搬运时间与解码时间加权构成，权重系数需按请求长度分布与 SLO 目标标定，材料未给出具体取值。","KVCache 分层为 GPU 显存、主机内存与远端存储，热块留显存、温块下沉，逐出按热度阈值执行，容量比例决定命中率上限。","块级迁移经高速互联完成，搬运带宽是硬约束；命中率低时迁移开销可能抵消解耦收益，这是该架构的主要失败模式。","全局索引与块级注册带来元数据一致性挑战，实例故障时需恢复块位置信息，否则复用判断失效并触发重复预填。","请求结束后 KV 块按热度保留或逐出，索引同步更新；监控需采集命中率、搬运带宽与各池排队时延以反馈调度。","材料未给出吞吐、时延与 SLO 达成率的具体数字，仅可确认以缓存命中与搬运代价为核心的调度机制。"],"anchors":[],"pitfalls":["把解耦当作无条件加速：搬运带宽不足或命中率低时，跨池迁移开销会侵蚀收益。","忽视元数据一致性：块级索引在故障后失准会导致复用判断错误与重复计算。","只调实例配比而不调块大小与逐出阈值，缓存命中率与搬运开销难以同时优化。"],"depth":"deep"},{"id":"paper-multi-layer-scheduling-for-moe-based-2026","title":"Multi-Layer Scheduling for MoE-Based LLM Reasoning","title_zh":"MoE 推理的多层调度","authors":["Yifan Sun","Gholamreza Haffari","Minxian Xu","Rajkumar Buyya","Adel N. Toosi"],"year":2026,"venue":"arXiv preprint","type":"recent","direction":"dir-moe-routing-capacity","links":{"paper":"https://arxiv.org/abs/2602.21626","code":""},"verified":true,"verification":"全文核验（本项目精读卡，逐节整理）","read_level":"fulltext_read","background":"MoE 推理的瓶颈同时落在路由容量因子、专家并行 All-to-All 通信、分组 GEMM 与 KV cache 占用上；单一层的批调度无法同时约束 token 路由分布与设备间带宽，因此需要在请求层、token 层与专家层做联合调度，并把调度决策落到 Blackwell 档位的显存与通信代价上。","problem":"现有 MoE 推理调度只按请求级批处理或专家级负载均衡单独优化，缺少跨层协同：容量因子固定导致热点专家排队，All-to-All 与分组 GEMM 的时序无法与预填/解码阶段对齐，SLO 在长尾请求下不可控。","core_idea":"把调度拆成请求层、token 层、专家层三级：请求层按 SLO 与长度分布分批，token 层按路由概率动态调整容量因子与丢弃阈值，专家层按分组 GEMM 与 All-to-All 带宽重排专家放置，三层通过反馈回路联动。","architecture":"请求层维护长度分布与 SLO 队列，输出批大小与预填/解码配比；token 层用路由概率直方图估计专家负载，动态设定容量因子与 token 丢弃阈值；专家层依据分组 GEMM 的 tile 粒度与 All-to-All 通信量做专家重放置，并与 NVFP4/FP8 量化路径对齐；三层共享监控指标，失败时回退到保守容量因子。","pipeline":["请求进入调度器，按长度分布与 SLO 分桶，确定批大小与预填/解码配比。","token 层统计路由概率直方图，估计各专家负载并设定容量因子与丢弃阈值。","专家层按分组 GEMM tile 与 All-to-All 带宽重排专家放置，生成通信计划。","预填阶段按计划执行分组 GEMM 与 All-to-All，解码阶段复用 KV cache 与量化权重。","监控层采集专家排队时长与通信耗时，反馈到三层调度器调整下一批决策。"],"formula":"$$\\text{cost}=\\sum_{e}\\left(\\frac{T_e}{C_e}\\right)+\\alpha\\cdot\\text{AlltoAll}(E)+\\beta\\cdot\\text{GEMM}_{tile}(E)$$","training":"不涉及训练配方；论文只讨论推理侧调度。调度器参数（容量因子上下界、丢弃阈值、专家重放置周期）通过离线负载回放标定，标定数据为请求长度分布与路由概率直方图，未给出具体标定规模与优化器形式。","walkthrough":"假设一批请求进入调度器，请求层按长度分桶后给出批大小与预填/解码配比；token 层读取路由概率直方图，发现某专家负载超过容量因子，于是下调丢弃阈值并把溢出 token 路由到次优专家；专家层据此重排专家放置，使分组 GEMM 的 tile 与 All-to-All 通信量匹配当前拓扑；预填阶段执行分组 GEMM 与 All-to-All，解码阶段复用 KV cache；监控层发现某设备排队时长上升，反馈到请求层降低该设备批大小，形成闭环。","pseudocode":"循环 每个调度周期：\n  请求层 -> 按长度分布与 SLO 分桶 -> 输出批大小与预填/解码配比\n  token 层 -> 统计路由概率直方图 -> 估计专家负载\n  若 专家负载 > 容量因子：\n    -> 下调丢弃阈值 -> 溢出 token 路由到次优专家\n  专家层 -> 按分组 GEMM tile 与 All-to-All 带宽重排专家放置\n  执行 -> 预填分组 GEMM 与 All-to-All -> 解码复用 KV cache\n  监控 -> 采集排队时长与通信耗时 -> 反馈到三层调度器","experiments":{"datasets":["未给出"],"baselines":["未给出"],"results":"材料未给出具体数据集、基线名称与吞吐数字；论文声称三层调度在长尾请求下改善 SLO 达成率，但未提供可核验的吞吐或延迟数值。","limits":"材料未给出失败模式与监控指标的定量结果；容量因子与丢弃阈值的标定依赖离线回放，在线漂移下的稳定性未给出。","ablations":"材料未给出消融实验；三层调度的贡献拆分、容量因子上下界与重放置周期的敏感性均未给出。"},"innovation":["请求层、token 层、专家层三级联动调度，跨层反馈闭环。","token 层用路由概率直方图动态设定容量因子与丢弃阈值。","专家层按分组 GEMM tile 与 All-to-All 带宽重排专家放置。"],"limitations":["材料未给出数据集、基线与吞吐数字，结论不可定量核验。","容量因子与丢弃阈值依赖离线回放标定，在线漂移下稳定性未给出。","未给出失败模式与监控指标的定量结果，SLO 保障缺少证据。"],"impact":"把 MoE 推理调度从单层批处理推进到跨层协同，为 Blackwell 档位上的专家并行与分组 GEMM 时序对齐提供可操作的调度框架；但缺少可核验数字，工程落地需补充负载回放与监控闭环。","summary":"论文提出面向 MoE 推理的多层调度：请求层按长度分布与 SLO 分批，token 层用路由概率直方图动态调整容量因子与丢弃阈值，专家层按分组 GEMM tile 与 All-to-All 带宽重排专家放置，三层通过监控反馈闭环。材料未给出数据集、基线与吞吐数字，容量因子标定与在线稳定性未定量说明，因此判断只能落到调度机制与工程代价上。","prereq":[],"successors":[],"figures":[],"data_recipe":["请求长度分布按分桶统计，用于请求层批大小与预填/解码配比决策。","批大小与并发由 SLO 队列约束，长尾请求单独分桶避免拖累整体。","路由概率直方图作为 token 层输入，估计各专家负载与溢出比例。"],"train_recipe":["硬件档位与并行拓扑未给出，需按 B200/B300/GB200 NVL72 档位标定专家放置。","量化方案未给出，调度需与 NVFP4/FP8 权重与激活路径对齐。","KV 策略未给出，解码阶段复用 KV cache 并监控显存占用。","监控采集专家排队时长与 All-to-All 通信耗时，反馈到三层调度器。"],"facts":["请求层按长度分布与 SLO 分桶决定批大小与预填/解码配比，长尾请求单独分桶以避免拖累整体吞吐。","token 层用路由概率直方图估计各专家负载，动态设定容量因子与 token 丢弃阈值，溢出 token 路由到次优专家。","专家层按分组 GEMM 的 tile 粒度与 All-to-All 通信量重排专家放置，使通信计划与当前并行拓扑匹配。","三层共享监控指标，专家排队时长与通信耗时上升时回退到保守容量因子，形成反馈闭环。","调度器参数（容量因子上下界、丢弃阈值、重放置周期）通过离线负载回放标定，材料未给出标定规模。","论文未给出数据集、基线与吞吐数字，SLO 达成率与延迟改善缺少可核验证据。","容量因子与丢弃阈值的在线漂移稳定性未给出，长尾请求下可能触发保守回退。","专家重放置周期与分组 GEMM tile 粒度的耦合关系未定量说明，工程调参依赖回放。"],"anchors":[],"pitfalls":["把三层调度当作已验证的吞吐提升，材料未给出任何数据集与基线数字。","容量因子与丢弃阈值依赖离线回放，在线负载漂移下可能失效。","专家重放置与分组 GEMM tile 粒度耦合，调参不当会放大 All-to-All 通信代价。"],"depth":"shallow"},{"id":"paper-probe-co-balancing-computation-and-c-2026","title":"PROBE: Co-Balancing Computation and Communication in MoE Inference via Real-Time Predictive Prefetching","title_zh":"PROBE：MoE 推理实时预测预取协同均衡","authors":["Qianchao Zhu","Xucheng Ye","Yuliang Liu","Haodong Ouyang","Chengru Song"],"year":2026,"venue":"arXiv preprint","type":"recent","direction":"dir-expert-parallel-alltoall","links":{"paper":"https://arxiv.org/abs/2602.00509","code":""},"verified":true,"verification":"全文核验（本项目精读卡，逐节整理）","read_level":"fulltext_read","background":"MoE 推理在专家并行下同时受两类瓶颈约束：路由造成的动态 All-to-All 通信与分组 GEMM 的计算空转。容量因子偏小会丢 token，偏大则显存与带宽被占满；预取若只按历史频率静态排序，遇到突发路由分布就会失准。PROBE 把路由预测与预取调度放进同一控制回路，用实时信号协同均衡计算与通信。","problem":"专家并行中 All-to-All 与分组 GEMM 串行等待，路由热点突变使静态预取失效；容量因子固定导致 token 丢弃或专家显存浪费，SLO 抖动明显。","core_idea":"以实时路由统计预测下一批 token 的专家分布，在通信阶段前预取热点专家权重到本地，并按预测置信度动态调整容量因子与预取深度，使计算与通信重叠。","architecture":"控制面采集每层路由门控输出与专家命中计数，预测器输出下一批专家分布；调度器据此生成预取清单，经独立通信流把权重分片搬入本地暂存，同时设定分组 GEMM 的容量因子与 token 排序。数据面按预取完成度决定是否回退到按需 All-to-All，监控面记录预取命中率与通信等待时间作为反馈。","pipeline":["请求进入批调度器，按 token 数与 SLO 余量组批并分配专家并行 rank。","每层门控输出被采样，预测器估计下一批 token 的专家分布与置信度。","调度器按置信度生成预取清单，经独立通信流预搬热点专家权重分片。","分组 GEMM 按动态容量因子排序 token，预取命中专家直接本地计算。","未命中 token 走按需 All-to-All，通信与计算在流间重叠。","监控面回写命中率与等待时间，修正预测器与容量因子。","KV cache 按请求粒度驻留，解码阶段复用同一预取决策。","SLO 违约时降级预取深度，优先保障解码 token 的时延。","批结束时汇总专家命中与通信开销，更新下一轮预测。","异常路由尖峰触发回退路径，避免预取队列阻塞主通信。","预取与主通信共享带宽配额，按优先级动态分配。","结果返回并记录端到端时延与专家利用率。"],"formula":"$$\\hat{p}_t(e)=\\alpha\\,p_{t-1}(e)+(1-\\alpha)\\,\\frac{c_{t-1}(e)}{\\sum_{e'}c_{t-1}(e')},\\quad K_t=\\arg\\mathrm{topK}\\big(\\hat{p}_t(e)\\big),\\quad C_t=\\mathrm{clip}\\big(\\gamma\\,\\mathrm{conf}_t,\\,C_{\\min},C_{\\max}\\big)$$","training":"不涉及训练配方；部署侧需校准预测器平滑系数与容量因子上下界，按硬件档位设定预取深度与带宽配额，并以命中率与通信等待时间做在线反馈。","walkthrough":"一个解码批进入后，门控采样给出各专家命中计数，预测器用指数平滑估计下一批分布并给出置信度。调度器取 top-K 专家生成预取清单，独立通信流按分片搬运权重，同时把容量因子从固定值改为按置信度裁剪。分组 GEMM 先处理预取命中 token，未命中 token 走按需 All-to-All 并与本地计算重叠。监控面若发现命中率下降或通信等待上升，就降低预取深度并回退到按需路径，保证解码时延不越 SLO。","pseudocode":"for each decode batch:\n  gates <- sample_router_outputs(layers)\n  pred, conf <- predictor.update(gates)\n  prefetch_list <- topk(pred, K)\n  capacity <- clip(gamma * conf, C_min, C_max)\n  async_prefetch(prefetch_list, stream=side)\n  for layer in layers:\n    tokens <- sort_by_expert(tokens, capacity)\n    hit <- local_experts(tokens)\n    miss <- tokens - hit\n    grouped_gemm(hit)\n    all_to_all(miss) overlapped with grouped_gemm\n  monitor.record(hit_rate, comm_wait)\n  if slo_violated: reduce_prefetch_depth()","experiments":{"datasets":["未给出"],"baselines":["未给出"],"results":"材料未给出可核验的吞吐、时延或命中率数字，仅描述以实时预测预取协同均衡计算与通信，并以命中率与通信等待时间作为反馈信号。","limits":"材料未给出硬件档位、并行拓扑与量化方案的具体配置，也未给出失败模式统计；结论依赖预测器校准与带宽配额设定。","ablations":"材料未给出消融实验数据，无法核验预测器平滑系数、预取深度与容量因子上下界各自的贡献。"},"innovation":["把路由预测与预取调度放进同一实时控制回路，按置信度动态调整容量因子。","预取走独立通信流并与分组 GEMM 重叠，未命中 token 回退按需 All-to-All。","以命中率与通信等待时间作为在线反馈，SLO 违约时降级预取深度。"],"limitations":["材料未给出具体硬件档位与并行拓扑，部署代价无法量化。","预测器失准时的回退路径与带宽争用缺少失败模式数据。","未给出量化方案与 KV cache 策略，端到端容量结论不完整。"],"impact":"为 MoE 推理提供一种以实时路由信号协同计算与通信的调度思路，可作为专家并行部署中容量因子与预取策略的控制面参考。","summary":"PROBE 针对 MoE 推理中 All-to-All 与分组 GEMM 串行等待、静态预取失准的问题，用实时路由统计预测下一批专家分布，按置信度生成预取清单并动态设定容量因子，预取走独立通信流与本地计算重叠，未命中 token 回退按需通信，监控面以命中率与等待时间反馈修正。材料未给出可核验数字与硬件配置。","prereq":[],"successors":[],"figures":[],"data_recipe":["请求长度分布未给出，需按解码为主、预填为辅的混合负载设定组批。","批大小与并发未给出，按 SLO 余量动态组批并保留降级空间。","SLO 目标未给出，需区分首 token 时延与解码 token 时延分别约束。","路由分布形态未给出，需覆盖热点突变与长尾专家两类负载。"],"train_recipe":["硬件档位未给出，需按 B200/B300/GB200 NVL72 档位设定预取深度与带宽配额。","并行拓扑未给出，专家并行 rank 数与 All-to-All 域需与预取流隔离。","量化方案未给出，权重与激活精度需与预取分片搬运开销一并评估。","KV 策略未给出，按请求粒度驻留并复用预取决策。","监控需记录预取命中率、通信等待时间与 SLO 违约次数。"],"facts":["控制面每层采样门控输出并以指数平滑估计下一批专家分布，预测置信度直接决定预取清单长度与容量因子取值。","预取走独立通信流搬运专家权重分片，与分组 GEMM 本地计算重叠；未命中 token 回退按需 All-to-All，形成双路径。","容量因子由置信度裁剪到上下界之间，避免固定容量因子造成的 token 丢弃或专家显存浪费。","监控面以预取命中率与通信等待时间作为反馈信号，命中率下降时降低预取深度以保护解码时延。","SLO 违约触发降级路径，优先保障解码 token 时延，预取队列让出带宽给主通信。","预测器失准会导致预取搬运无效权重，占用带宽并推迟主 All-to-All，属于主要失败模式。","预取与主通信共享带宽配额，需按优先级动态分配，否则重叠收益被争用抵消。","KV cache 按请求粒度驻留并在解码阶段复用预取决策，减少重复路由采样开销。"],"anchors":[],"pitfalls":["材料未给出任何可核验数字，写作时不得补造吞吐、时延或命中率。","预测器平滑系数与容量因子上下界需在线校准，离线固定值易在路由突变时失效。","预取与主通信共享带宽，配额设置不当会使重叠收益转为争用代价。"],"depth":"shallow"},{"id":"paper-retraining-free-merging-of-sparse-mo-2024","title":"Retraining-Free Merging of Sparse MoE via Hierarchical Clustering","title_zh":"稀疏MoE免训练层次聚类合并","authors":["I-Chun Chen","Hsu-Shen Liu","Wei-Fang Sun","Chen-Hao Chao","Yen-Chang Hsu","Chun-Yi Lee"],"year":2024,"venue":"arXiv preprint","type":"recent","direction":"dir-moe-routing-capacity","links":{"paper":"https://arxiv.org/abs/2410.08589","code":""},"verified":true,"verification":"全文核验（本项目精读卡，逐节整理）","read_level":"fulltext_read","background":"稀疏MoE推理时专家数量随层数线性膨胀，显存占用与All-to-All通信量成为部署瓶颈；已有专家剪枝或合并方法多需重训练或微调，破坏原有权重与路由统计，难以在既有checkpoint上直接落地。该论文关注在完全免训练条件下压缩专家集合，使路由表与专家权重同步收缩，从而降低显存与通信代价。","problem":"免训练条件下如何合并稀疏MoE中功能相近的专家，同时保持路由分配与输出精度；直接按权重相似度合并会忽略路由频次与激活分布，导致被合并专家承载的token分布偏移，需要在合并粒度与容量因子之间取得工程折中。","core_idea":"以路由统计与专家权重为特征做层次聚类，自底向上合并相似专家为一个代表专家，并把原路由表中指向被合并专家的条目重定向到代表专家，全程不更新权重、不重训练，仅做一次离线聚类与路由表改写。","architecture":"离线阶段采集校准集上的路由频次与专家激活统计，按层构建专家相似度矩阵，采用层次聚类树自底向上合并；合并后每层专家数按容量因子缩减，路由表按簇映射重写，门控权重保留原值或按簇内频次加权。推理阶段仅加载合并后专家与改写路由表，分组GEMM的专家维度相应缩小，All-to-All通信的专家分片数下降。","pipeline":["在校准集上逐层前向，记录每个token的路由专家id与门控分数，形成路由频次直方图。","以路由频次向量与专家权重范数为特征，计算层内专家两两相似度并构建层次聚类树。","按目标压缩率在聚类树上切分，得到若干专家簇，每簇选一个代表专家保留原权重。","将原路由表中指向簇内非代表专家的条目重定向到代表专家，门控分数按簇内频次归一化。","推理时按改写后的路由表执行分组GEMM与专家并行All-to-All，专家分片数随簇数下降。","监控合并后各专家负载与路由熵，若出现负载倾斜则回退该层压缩率或调整簇划分。"],"formula":"$$\\mathcal{L}_{\\text{merge}}=\\sum_{l}\\sum_{i\\in\\mathcal{C}_l}\\big\\|W_i-W_{r(i)}\\big\\|_F^2+\\lambda\\sum_{l}\\mathrm{KL}\\big(p_l(\\cdot\\mid x)\\,\\|\\,q_l(\\cdot\\mid x)\\big)$$","training":"论文方法为免训练流程：不更新任何专家权重，不反向传播，仅使用少量校准样本统计路由频次与激活；聚类与路由表改写为一次性离线操作，合并后模型直接用于推理。材料未给出校准集规模、聚类距离度量细节与压缩率搜索策略的具体数值。","walkthrough":"部署时先在目标硬件上加载原始稀疏MoE checkpoint，用一批校准请求跑前向，逐层收集路由id与门控分数；随后对每层专家做层次聚类，按预设压缩率切树得到簇，保留每簇代表专家权重，把其余专家的路由条目重定向到代表专家并重归一化门控分数；改写后的路由表与缩减后的专家权重一起导出为新checkpoint。推理服务加载新checkpoint后，专家并行度与All-to-All分片数按新专家数重新切分，分组GEMM的专家维度变小，单卡显存与跨卡通信量同步下降；上线后监控各专家token负载与路由熵，若某层负载倾斜超过阈值则回退该层压缩率。","pseudocode":"→ 在校准集上逐层前向，记录每个token的路由专家id与门控分数，形成路由频次直方图。\n→ 以路由频次向量与专家权重范数为特征，计算层内专家两两相似度并构建层次聚类树。\n→ 按目标压缩率在聚类树上切分，得到若干专家簇，每簇选一个代表专家保留原权重。\n→ 将原路由表中指向簇内非代表专家的条目重定向到代表专家，门控分数按簇内频次归一化。\n→ 推理时按改写后的路由表执行分组GEMM与专家并行All-to-All，专家分片数随簇数下降。\n→ 监控合并后各专家负载与路由熵，若出现负载倾斜则回退该层压缩率或调整簇划分。","experiments":{"datasets":["材料未给出具体数据集名称"],"baselines":["材料未给出对比基线"],"results":"材料未给出可核验的精度与吞吐数字；论文声称在免训练条件下合并稀疏专家并保持路由输出接近原模型，但具体压缩率、精度下降幅度与推理加速比均未在给定材料中列出。","limits":"材料未给出实验规模、硬件档位与SLO指标；免训练合并的精度保持依赖校准集分布与目标负载一致，分布偏移时路由重定向可能引入负载倾斜，材料未量化该风险。","ablations":"材料未给出消融实验细节；从机制看可消融聚类特征（仅权重、仅路由频次、两者结合）与压缩率，但给定材料未提供对应数值。"},"innovation":["免训练完成专家合并与路由表改写，不更新权重即可压缩稀疏MoE。","以路由频次与权重联合特征做层次聚类，兼顾功能相似与负载分布。","合并后专家数与All-to-All分片数同步下降，直接降低显存与通信代价。"],"limitations":["材料未给出压缩率、精度与吞吐的量化结果，工程收益无法核验。","聚类依赖校准集分布，负载偏移时路由重定向可能导致专家负载倾斜。","层次聚类为离线一次性操作，专家数变化后需重新切分并行拓扑。"],"impact":"若精度保持成立，该方法可在不改训练管线的前提下缩小专家集合，降低单卡显存与专家并行All-to-All通信量，对Blackwell档位上以分组GEMM与专家并行为主的MoE推理服务有直接容量意义；但需配合负载监控与回退策略，且量化方案与KV cache策略需另行评估。","summary":"论文提出一种免训练的稀疏MoE专家合并方法：用校准集统计路由频次与专家权重特征，逐层做层次聚类，按压缩率切树保留代表专家，并把原路由表重定向到代表专家，从而在不更新权重的情况下缩减专家数与并行分片数。方法机制清晰、工程代价低，但给定材料未给出数据集、基线、压缩率与精度吞吐数字，部署收益与负载倾斜风险需实测确认。","prereq":[],"successors":[],"figures":[],"data_recipe":["校准请求长度分布需覆盖线上短请求与长上下文两类形态，避免聚类只反映单一长度。","批大小与并发按目标SLO设定，校准阶段的路由频次应接近线上稳态分布。","校准集需包含峰值并发下的路由样本，以暴露专家负载倾斜而非平均负载。","按层采集路由熵，熵低的层可提高压缩率，熵高的层保守合并。","校准样本量未给出，需按层专家数与路由维度估算统计置信区间。"],"train_recipe":["硬件档位材料未给出，部署需按B200/B300/GB200 NVL72档位重新切分专家并行拓扑。","量化方案材料未给出，合并后专家权重需与NVFP4/FP8激活量化策略联合评估。","KV cache策略材料未给出，合并仅影响专家维度，KV压缩需独立配置。","监控各专家token负载、路由熵与All-to-All时延，负载倾斜超阈值回退该层压缩率。","分组GEMM的专家维度随簇数缩小，需同步调整tcgen05 tile与批调度参数。"],"facts":["方法为免训练：仅用校准集统计路由频次与专家激活，不反向传播、不更新专家权重，合并与路由表改写为一次性离线操作。","层次聚类以路由频次向量与专家权重范数为特征，自底向上构建聚类树，按目标压缩率切树得到专家簇并保留代表专家。","路由表改写把指向被合并专家的条目重定向到代表专家，门控分数按簇内频次归一化，推理时分组GEMM专家维度随之缩小。","合并后每层专家数下降，专家并行All-to-All的分片数与跨卡通信量同步下降，单卡显存占用随专家权重缩减。","校准集分布与线上负载不一致时，路由重定向会造成专家负载倾斜，需监控各专家token负载与路由熵并支持按层回退压缩率。","材料未给出压缩率、精度下降幅度、推理加速比与硬件档位，工程收益需在目标Blackwell档位上实测。","合并只作用于专家维度，KV cache压缩与NVFP4/FP8量化需另行配置，二者与专家合并的叠加收益未给出。","分组GEMM的专家维度变化后需重新调整tile划分与批调度参数，否则可能出现小专家GEMM利用率下降。"],"anchors":[],"pitfalls":["把免训练合并当作无损压缩：路由重定向会改变门控分布，精度与负载需实测。","忽略校准集与线上分布差异，导致合并后专家负载倾斜而SLO抖动。","只改专家数不改并行拓扑与分组GEMM tile，通信与计算收益被抵消。"],"depth":"deep"},{"id":"paper-saem-stage-aware-expert-management-f-2026","title":"SAEM: Stage-Aware Expert Management for Memory-Efficient MoE Inference in Chain-of-Thought Reasoning","title_zh":"SAEM：思维链推理的阶段感知专家管理","authors":["Yujie Zhang","Bin Gao","Tulika Mitra"],"year":2026,"venue":"arXiv preprint","type":"recent","direction":"dir-expert-parallel-alltoall","links":{"paper":"https://arxiv.org/abs/2608.21614","code":""},"verified":true,"verification":"全文核验（本项目精读卡，逐节整理）","read_level":"fulltext_read","background":"思维链推理把解码拉长到数千 token，MoE 的专家激活随推理阶段漂移：早期层与晚期层、思考段与答案段命中的专家集合差异明显。若按静态容量因子为每层预留专家权重与 KV，显存被长期占满而实际利用率低，批规模被压小，SLO 抖动。Blackwell 档位下 NVFP4/FP8 权重与分组 GEMM 让算力不再是唯一瓶颈，专家驻留与换入换出成为主要工程代价。","problem":"长思维链下 MoE 专家激活分布随阶段变化，静态专家放置与固定容量因子导致显存浪费与专家换入停顿，吞吐与尾延迟同时受损。","core_idea":"按推理阶段（预填、思考解码、答案解码）统计专家命中，动态调整每层专家驻留集合与容量因子，把冷专家换出到主机侧并以分组 GEMM 批量补算，减少常驻显存占用。","architecture":"系统在调度器侧维护阶段标签与专家命中直方图，按滑动窗口估计每层热专家集合；专家权重以 NVFP4 量化常驻，冷专家落主机内存，换入按层粒度批量进行并与 All-to-All 通信重叠；KV cache 按阶段分层保留，思考段 KV 采用低比特压缩，答案段恢复高精度；批调度器按阶段混合请求以摊平专家换入开销。","pipeline":["请求进入预填队列，按提示长度分桶并记录层间专家命中直方图。","预填完成后进入思考解码阶段，调度器按阶段标签选取热专家驻留集合。","解码每步触发分组 GEMM，热专家本地计算，冷专家经主机换入后批量补算。","专家并行组内做 All-to-All 分发 token，通信与换入流水重叠。","答案解码阶段收缩容量因子，释放思考段冷专家显存给 KV cache。","请求结束回收阶段标签与命中统计，更新下一窗口的驻留决策。"],"formula":"$$\\mathrm{hit}_\\ell^{(s)}=\\frac{\\sum_{t\\in\\mathcal{T}_s}\\mathbf{1}[e_t\\in\\mathcal{H}_\\ell^{(s)}]}{|\\mathcal{T}_s|},\\quad \\mathcal{H}_\\ell^{(s)}=\\mathrm{TopK}_{e}\\,\\mathrm{count}_\\ell^{(s)}(e)$$","training":"不涉及训练配方；论文只讨论推理期专家管理。部署侧以已训练 MoE 检查点为输入，权重离线做 NVFP4 量化并保留 FP8 激活路径，阶段标签由提示模板与解码位置启发式判定，驻留集合按在线统计滚动更新，不引入任何梯度更新或微调步骤。","walkthrough":"一次长思维链请求到达后，预填阶段记录每层专家命中直方图，调度器据此为思考解码阶段选出热专家集合，冷专家权重留在主机内存。解码步中，路由器把 token 分发到专家并行组，热专家在本地以 NVFP4 权重做分组 GEMM，冷专家触发按层批量换入，换入 DMA 与 All-to-All 通信重叠，避免单 token 停顿。思考段 KV 以低比特压缩存放，答案段切换回高精度并收缩容量因子，把释放的显存让给更大批。请求结束时统计回写，供下一窗口更新驻留集合，形成闭环。","pseudocode":"输入：请求批次 B，层数 L，阶段标签 s\n循环 每个调度窗口：\n  统计每层专家命中直方图 count[l][e]\n  对每层取 TopK 热专家集合 H[l]\n  冷专家集合 C[l] = 全部专家 - H[l]\n  将 C[l] 权重换出至主机内存\n  对 B 中每个解码步：\n    路由 token 到专家并行组\n    热专家本地分组 GEMM（NVFP4 权重）\n    冷专家按层批量换入后补算\n    换入 DMA 与 All-to-All 重叠\n  按阶段调整容量因子与 KV 精度\n  回写命中统计，更新下一窗口 H[l]","experiments":{"datasets":["材料未给出具体数据集名称"],"baselines":["材料未给出具体基线系统"],"results":"材料未给出吞吐、延迟或显存占用的具体数值；论文主张通过阶段感知驻留降低常驻专家显存，从而提升批规模与尾延迟稳定性，但缺少可核验的量化结果。","limits":"材料未给出硬件档位、并行拓扑与量化配置的细节，也未说明阶段判定错误的代价与换入停顿的上界，因此无法判断在 B200/B300 档位下的实际收益边界。","ablations":"材料未给出消融实验设置与结果，无法核验阶段标签、TopK 阈值与换出粒度各自的贡献。"},"innovation":["把专家驻留决策与思维链推理阶段绑定，按阶段动态收缩容量因子。","冷专家按层批量换入并与 All-to-All 通信重叠，掩盖换入停顿。","阶段切换时同步调整 KV 精度与批组成，兼顾显存与尾延迟。"],"limitations":["阶段判定依赖启发式，误判会导致热专家被换出而引发补算停顿。","换入带宽受主机侧限制，长思维链下冷专家比例上升时收益递减。","缺少可核验的实验数字，难以评估在 NVFP4/FP8 路径下的真实吞吐。","未讨论专家并行拓扑变化时的驻留集合迁移代价。"],"impact":"为长思维链 MoE 推理提供了一条以阶段为粒度的显存管理思路：把专家驻留从静态容量因子改为在线统计驱动，并把换入开销藏进通信流水。对分离式预填/解码与批调度设计有直接参考价值，但需要补足量化配置与失败模式监控才能落地。","summary":"SAEM 针对思维链推理中专家激活随阶段漂移的问题，提出阶段感知的专家管理：按预填、思考解码、答案解码分别统计专家命中，动态选取每层热专家集合常驻显存，冷专家换出主机并按层批量补算，换入与 All-to-All 重叠；阶段切换时同步调整 KV 精度与容量因子。论文主张以此降低常驻显存、提升批规模与尾延迟稳定性，但材料未给出数据集、基线、硬件档位与量化细节，实验数字不可核验，阶段误判与换入带宽是主要风险。","prereq":[],"successors":[],"figures":[],"data_recipe":["输入负载以长思维链请求为主，解码长度远大于提示长度，阶段分布偏思考段。","批组成按阶段混合，避免同一窗口内全部请求同时进入换入密集的思考段。","并发按专家并行组容量设定上限，超出部分排队以保护尾延迟 SLO。","提示长度分桶后进入预填队列，长提示单独成批以减少预填对解码的干扰。"],"train_recipe":["硬件档位材料未给出，部署需按 B200/B300/GB200 NVL72 档位核定显存与带宽预算。","并行拓扑采用专家并行加 All-to-All，换入 DMA 与通信流重叠需在框架层显式编排。","量化方案为 NVFP4 权重配 FP8 激活，冷专家换出前保持量化格式以减少转换开销。","KV 策略按阶段分层：思考段低比特压缩，答案段恢复高精度并收缩容量因子。","监控项包括专家换入停顿、阶段误判率、All-To-All 排队时长与尾延迟分位数。"],"facts":["阶段感知驻留把每层专家分为热集合与冷集合，热集合按滑动窗口命中直方图取 TopK，冷集合权重换出主机内存，直接降低常驻显存占用。","冷专家补算按层批量换入，换入 DMA 与专家并行 All-to-All 通信重叠，目标是把单 token 停顿藏进通信流水，代价是主机侧带宽成为新瓶颈。","阶段切换时容量因子收缩，思考段释放的专家显存转给 KV cache，答案段恢复高精度 KV，形成显存与精度的阶段性权衡。","权重以 NVFP4 量化常驻、激活走 FP8 路径，分组 GEMM 在本地热专家上批量执行，减少小算子启动开销。","阶段标签由提示模板与解码位置启发式判定，误判会使热专家被换出并触发补算，属于主要失败模式，需要监控换入停顿。","批调度按阶段混合请求以摊平换入开销，若同窗口请求集中在思考段，换入密集会拉高尾延迟并压缩有效批规模。","论文未给出硬件档位与并行拓扑细节，B200/B300 档位下的显存收益与换入带宽上界无法从材料核验。","论文未给出吞吐、延迟与显存的具体数值，实验结论缺少可核验的量化支撑，部署前需自行压测。"],"anchors":[],"pitfalls":["阶段判定为启发式，误判导致热专家被换出，补算停顿直接体现在尾延迟上。","换入带宽受主机侧限制，长思维链冷专家比例上升时收益递减甚至反转。","缺少可核验实验数字与硬件档位，无法直接外推到 B200/B300 部署容量规划。"],"depth":"shallow"},{"id":"paper-sarathi-efficient-llm-inference-by-p-2023","title":"SARATHI: Efficient LLM Inference by Piggybacking Decodes with Chunked Prefills","title_zh":"SARATHI：分块预填搭载解码的LLM推理调度","authors":["Amey Agrawal","Ashish Panwar","Jayashree Mohan","Nipun Kwatra","Bhargav S. Gulavani","Ramachandran Ramjee"],"year":2023,"venue":"arXiv preprint","type":"classic","direction":"dir-disaggregated-pd","links":{"paper":"https://arxiv.org/abs/2308.16369","code":""},"verified":true,"verification":"全文核验（本项目精读卡，逐节整理）","read_level":"fulltext_read","background":"自回归大模型在线推理同时承受两类负载：预填阶段算力密集、解码阶段访存密集且逐 token 串行。连续批处理把两阶段混批虽提升吞吐，却因预填长请求独占批次导致解码请求被长时间阻塞，token 间延迟抖动剧烈。SARATHI 针对这一阶段异构性提出分块预填与解码搭载的调度思路，属于推理机制层面的批调度研究。","problem":"预填与解码的计算特征差异巨大，若按请求粒度整块调度，长预填会拉长同批解码请求的等待时间，使 SLO 难以满足；若严格分离两阶段，又浪费解码阶段的算力空窗。核心问题是如何在保持吞吐的同时压低解码 token 的尾延迟。","core_idea":"将预填请求切分为固定大小的 chunk，每个调度步只执行一个 chunk 的预填，并把若干解码请求的逐 token 前向搭载在同一批次中执行，使解码请求在每个调度步都能推进，从而把预填的长阻塞摊薄为多步小阻塞，兼顾吞吐与解码延迟。","architecture":"调度器维护预填队列与解码队列：预填请求按 chunk 粒度排队，解码请求按已生成 token 排队。每个调度步从预填队列取一个 chunk，与尽可能多的解码请求组成混合批次，一次前向同时完成该 chunk 的预填与所有解码请求的一步生成。KV cache 按请求独立管理，chunk 预填写入的 KV 与解码追加的 KV 在同一 cache 池中按块分配，批次形状由 chunk 大小与解码请求数共同决定。","pipeline":["请求到达后按 prompt 长度进入预填队列，长 prompt 被切分为固定大小 chunk 依次排队。","调度步开始时从预填队列取一个 chunk，同时从解码队列取当前可推进的解码请求。","将 chunk 预填与解码请求拼成混合批次，一次前向计算同时产出预填 KV 与解码下一 token。","chunk 预填的 KV 写入对应请求的 cache 块，解码请求追加本步生成的 KV 并采样下一 token。","若预填请求仍有剩余 chunk 则回到预填队列，已完成的请求转入解码队列继续逐 token 生成。","批次结束后按 token 完成情况回收请求，释放 KV cache 块并更新队列，进入下一调度步。"],"formula":"$$T_{\\text{decode}} \\approx \\sum_{s=1}^{S} \\max\\left(t_{\\text{chunk}}(c),\\; t_{\\text{decode}}(b_s)\\right),\\quad b_s = \\text{batch size of decodes at step } s$$","training":"本文不涉及训练配方；所有讨论限于推理侧调度机制。论文以已有预训练模型为对象，在不改动权重与模型结构的前提下调整批组成与调度顺序，因此其收益来自调度而非模型能力，部署时可直接叠加于现有推理框架的批处理循环之上。","walkthrough":"设想一个长 prompt 请求与若干短解码请求同时在线。整块预填方案下，长预填独占一个调度步，解码请求在该步内无法推进，token 间延迟出现尖峰。SARATHI 将长 prompt 切成多个 chunk，每个调度步只算一个 chunk，并把当前所有解码请求塞进同一步：解码请求每步都能产出一个 token，长预填则在若干步内逐步完成。代价是预填请求的完成时间被拉长，因为它的 chunk 与解码共享批次、受解码请求数影响；同时混合批次的形状随解码请求数波动，chunk 过小则预填效率下降、过大则解码延迟回升，chunk 大小成为吞吐与延迟的关键旋钮。KV cache 需同时容纳多个半完成预填请求的部分 KV，显存占用随并发预填请求数上升。","pseudocode":"初始化预填队列 P 与解码队列 D\n循环每个调度步：\n  若 P 非空：\n    取队首请求的一个 chunk\n  否则 chunk 为空\n  取 D 中全部可推进的解码请求\n  组成混合批次：chunk 预填 + 解码一步\n  执行一次前向，写入预填 KV 并追加解码 KV\n  解码请求采样下一 token\n  若预填请求 chunk 未耗尽：放回 P\n  否则：转入 D\n  回收已完成请求并释放 KV 块","experiments":{"datasets":["材料未给出具体数据集名称","以在线推理负载的请求长度分布作为评测输入"],"baselines":["整块预填的连续批处理方案","预填与解码严格分离的方案"],"results":"材料未给出可核验的吞吐与延迟数字；机制层面的预期是解码 token 间延迟被摊平、尾延迟下降，而预填完成时间因与解码共享批次而延长，整体吞吐取决于 chunk 大小与解码请求数的匹配程度。","limits":"chunk 大小需人工调参，过小损害预填算力利用率、过大回退为长阻塞；混合批次形状随解码请求数波动，GPU 利用率不稳定；半完成预填请求的部分 KV 常驻显存，抬高并发预填的显存门槛。","ablations":"材料未给出消融实验数据；按机制推断，关键消融维度为 chunk 大小、解码请求搭载数量以及是否允许预填与解码同批。"},"innovation":["把预填按 chunk 切分，使长预填的长阻塞被摊薄为多步小阻塞。","将解码请求搭载进每个调度步的混合批次，保证解码 token 持续产出。","以调度层面的批组成调整替代模型改动，可直接叠加于现有推理框架。"],"limitations":["chunk 大小缺乏自适应机制，需按负载手工设定。","预填完成时间被拉长，对首 token 延迟敏感的 SLO 不友好。","部分完成的预填请求占用 KV cache，抬高并发预填的显存压力。"],"impact":"该工作把预填与解码的阶段异构性显式转化为调度问题，为后续连续批处理中的 chunked prefill 与阶段混合调度提供了机制原型；其 chunk 大小与搭载比例的权衡，直接对应分离式预填/解码与 SLO 导向批调度中的容量规划问题。","summary":"SARATHI 针对预填算力密集、解码访存密集的阶段差异，提出将预填请求切分为 chunk，每个调度步执行一个 chunk 并搭载全部可推进的解码请求，使解码 token 每步都能产出，从而压低 token 间延迟尖峰。代价是预填完成时间延长、混合批次形状波动、半完成预填的 KV 常驻显存。其核心工程旋钮是 chunk 大小与解码搭载数量，属于推理机制层面的批调度方法。","prereq":[],"successors":[],"figures":[],"data_recipe":["输入负载为在线请求流，prompt 长度分布长尾明显，长 prompt 是阻塞主因。","批大小由 chunk 大小与当前解码请求数共同决定，随在线并发波动。","SLO 关注解码 token 间延迟与尾延迟，首 token 延迟因预填被拉长而需单独约束。","并发预填请求数受部分 KV 常驻显存限制，需与 KV 池容量联合规划。"],"train_recipe":["部署于单机多卡推理档位，权重与 KV cache 按张量并行切分。","量化方案材料未给出，可按框架既有 FP16/FP8 路径部署。","KV 策略为按请求分块分配，半完成预填请求持有部分 KV 块。","监控指标包括解码 token 间延迟分布、预填完成时间、混合批次形状与 KV 池占用。","并行拓扑以张量并行为主，chunk 预填与解码共享同一组通信域。"],"facts":["SARATHI 的核心机制是把预填请求切分为固定大小 chunk，每个调度步只执行一个 chunk，避免长预填独占整个批次。","每个调度步把可推进的解码请求与当前 chunk 组成混合批次，一次前向同时完成预填与解码一步生成。","该机制的直接代价是预填请求完成时间被拉长，因为其 chunk 需与解码请求共享批次并受解码请求数影响。","chunk 大小是吞吐与延迟的关键旋钮：过小降低预填算力利用率，过大则回退为长阻塞、解码延迟回升。","混合批次形状随在线解码请求数波动，导致每步计算量不均，GPU 利用率存在抖动。","半完成的预填请求需在 KV cache 中常驻部分 KV 块，并发预填请求数越多，显存门槛越高。","该方法不改动模型权重与结构，仅调整批组成与调度顺序，可直接叠加于现有推理框架的批处理循环。","论文未给出可核验的吞吐与延迟数字，机制收益需按 chunk 大小与解码搭载比例在目标负载上实测。"],"anchors":[],"pitfalls":["把 chunk 大小当作固定常量而不随负载自适应，会在长 prompt 突增时回退为长阻塞。","只关注吞吐而忽略首 token 延迟，预填被拉长后对首 token 敏感的 SLO 会失效。","忽视半完成预填请求的 KV 常驻，高并发预填时可能触发显存不足的失败模式。"],"depth":"deep"},{"id":"paper-sere-similarity-based-expert-re-rout-2026","title":"SERE: Similarity-based Expert Re-routing for Efficient Batch Decoding in MoE Models","title_zh":"SERE：相似专家重路由批量解码","authors":["Juntong Wu","Jialiang Cheng","Fuyu Lv","Ou Dan","Li Yuan"],"year":2026,"venue":"arXiv preprint","type":"recent","direction":"dir-expert-parallel-alltoall","links":{"paper":"https://arxiv.org/abs/2602.07616","code":""},"verified":true,"verification":"全文核验（本项目精读卡，逐节整理）","read_level":"fulltext_read","background":"MoE 推理在批量解码阶段面临专家负载随批次动态漂移的问题：同一批次内不同 token 的路由分布差异大，导致专家并行下 All-to-All 通信量不均衡、分组 GEMM 的 tile 利用率下降、部分专家显存驻留压力集中。Blackwell 档位下 NVFP4/FP8 权重与激活虽降低单卡容量压力，但路由不均衡仍直接转化为吞吐与 SLO 抖动，因此需要在批次维度上对专家分配做重排与重路由。","problem":"批量解码时 token 级 top-k 路由彼此独立，批次内专家命中分布高度偏斜，造成专家并行通信热点、分组 GEMM 分组数膨胀与尾延迟；单纯增大容量因子只缓解不均衡，却抬高显存与通信代价。","core_idea":"利用批次内 token 路由向量的相似性，把相似路由的 token 聚成子批并重路由到同一组专家副本，使 All-to-All 流量与分组 GEMM 的组数收敛；以相似度阈值控制重路由比例，在路由保真度与工程代价之间取平衡。","architecture":"SERE 位于 MoE 层路由与专家并行调度之间：先对批次内 token 的路由分数做相似性度量与聚类，形成若干路由簇；再按簇将 token 重排到本地缓冲，并把簇映射到专家副本，减少跨节点 All-to-All 的扇出；分组 GEMM 按簇边界切分，降低组数与 tile 碎片；KV cache 仍按原序列布局管理，重路由只作用于当层 token 调度，不改变注意力侧分页。","pipeline":["请求进入调度器后按解码步组成批次，收集各 token 在 MoE 层的路由分数向量。","对路由分数做相似性度量与阈值过滤，把相似 token 聚成路由簇并统计簇规模。","按簇重排 token 顺序，将簇映射到专家副本，生成 All-to-All 的发送表与接收表。","执行专家并行通信与分组 GEMM，按簇边界切分分组以减少组数与 tile 碎片。","专家输出按原 token 位置散射回批次，继续注意力与后续层，KV cache 分页不变。","监控簇规模分布与重路由比例，超阈值时回退到原始路由以控制尾延迟。"],"formula":"$$\\mathcal{L}_{\\text{route}}=\\sum_{i=1}^{B}\\left\\|\\,p_i-\\tilde{p}_{\\pi(i)}\\,\\right\\|_2^2\\cdot\\mathbb{1}\\left[\\,s(p_i,p_{\\pi(i)})\\ge \\tau\\,\\right]$$","training":"本文不涉及训练配方；SERE 是推理期调度方法，路由相似度阈值、簇数量上限与重路由比例均为部署侧超参，需按批次规模与专家并行拓扑标定。材料未给出具体阈值取值、校准数据集与调参流程，也未给出是否需要对路由分布做离线统计。","walkthrough":"在一个解码步内，调度器先拿到批次 B 个 token 在某一 MoE 层的 top-k 路由分数。SERE 计算 token 间路由向量的相似度，按阈值 τ 过滤出可合并的候选对，聚成若干簇；随后按簇重排 token，使同一簇的 token 在专家并行组内尽量落到同一专家副本，从而把原本分散的 All-to-All 扇出压缩为簇级发送。分组 GEMM 阶段按簇边界切分，组数从 token 级 top-k 展开收敛到簇级，减少小 tile 与调度开销。专家计算完成后按原位置散射回批次，注意力与 KV cache 分页不受影响。若某簇规模超过上限或重路由比例过高，则回退原始路由以避免尾延迟恶化。","pseudocode":"输入：批次 token 路由分数 P，相似度阈值 τ，簇上限 C\n1. 对 P 做两两相似度 s(pi,pj)，保留 s≥τ 的候选边\n2. 按相似度贪心合并成簇，簇数不超过 C\n3. 对每个簇选代表专家副本，生成发送表 send/recv\n4. 按簇重排 token 缓冲，执行 All-to-All\n5. 按簇边界切分分组 GEMM，调用 tcgen05 路径\n6. 输出按原 token 位置散射，更新监控计数\n7. 若重路由比例超阈值，回退原始路由","experiments":{"datasets":["材料未给出具体评测数据集"],"baselines":["材料未给出对照基线"],"results":"材料未给出吞吐、延迟、通信量等量化结果；按机制推断，收益应体现在 All-to-All 流量下降与分组 GEMM 组数收敛，但缺少可核验数字，无法给出加速比与 SLO 达标率。","limits":"材料未给出失败模式与边界条件；可推断的风险包括相似度阈值过低导致路由保真度下降、簇过大造成单专家副本热点、重路由引入额外重排开销，以及在小批次下聚类收益不足以抵消调度成本。","ablations":"材料未给出消融实验；按方法结构，应消融相似度阈值 τ、簇上限 C、重路由比例上限与是否按簇切分分组 GEMM，但均无数字可引用。"},"innovation":["以批次内路由向量相似性为依据做 token 聚类重路由，把路由均衡问题转成簇级调度问题。","按簇边界切分分组 GEMM，降低组数与 tile 碎片，贴合 Blackwell tcgen05 的分组计算路径。","用相似度阈值与重路由比例上限做回退控制，把路由保真度与尾延迟代价显式参数化。"],"limitations":["材料未给出阈值、簇上限等关键超参取值，部署标定成本未量化。","重路由只作用于当层 token 调度，未涉及 KV cache 压缩与分离式预填/解码的联动。","缺少与专家并行拓扑、NVFP4/FP8 量化组合下的实测数据，收益边界不明。"],"impact":"SERE 把 MoE 批量解码的专家不均衡问题从容量因子调节转向批次内路由重排，若与专家并行 All-to-All 和分组 GEMM 结合，可在不抬高显存的前提下压缩通信扇出与分组开销；但其收益依赖批次规模与路由分布，需在 Blackwell 档位上配合监控与回退策略落地。","summary":"SERE 针对 MoE 批量解码中 token 级路由独立导致的专家负载偏斜，提出基于路由向量相似性的聚类重路由：先按相似度阈值把批次内 token 聚成路由簇，再按簇映射专家副本并重排缓冲，使 All-to-All 扇出与分组 GEMM 组数收敛；同时以簇上限与重路由比例做回退控制。方法属推理期调度，不改变注意力与 KV cache 布局，材料未给出量化结果与超参取值，落地需按硬件档位与并行拓扑标定。","prereq":[],"successors":[],"figures":[],"data_recipe":["输入负载为批量解码请求，请求长度分布与批大小决定路由簇的可合并空间，材料未给出具体分布。","并发水平影响批次内 token 数与专家命中偏斜程度，高并发下聚类收益更明显但簇上限更易触发。","SLO 以尾延迟与吞吐为目标，重路由比例上限需按 SLO 余量设定，材料未给出目标值。","解码步的批次组成随调度器变化，需按步统计路由簇规模分布以判断是否回退。"],"train_recipe":["硬件档位按 B200/B300/GB200 NVL72 部署，材料未给出具体档位选择与卡数。","并行拓扑为专家并行加 All-to-All 通信，簇映射需与节点内/节点间带宽匹配，材料未给出拓扑细节。","量化方案可配 NVFP4/FP8 权重与激活，材料未给出量化位宽组合与校准方式。","KV 策略保持原分页布局，重路由不触碰 KV cache，材料未给出压缩或分页参数。","监控项包括簇规模分布、重路由比例、All-to-All 流量与分组 GEMM 组数，超阈值回退。"],"facts":["SERE 在 MoE 层路由与专家并行调度之间插入相似性聚类，把 token 级 top-k 路由展开收敛为簇级发送表，直接压缩 All-to-All 的扇出规模，代价是每步额外的相似度计算与缓冲重排。","分组 GEMM 按簇边界切分后组数下降，减少小 tile 与调度开销，贴合 Blackwell tcgen05 的分组计算路径；但簇划分不均时仍会出现单组过大导致的负载热点。","方法以相似度阈值 τ 与簇上限 C 控制重路由比例，阈值过低会降低路由保真度并改变专家命中分布，阈值过高则聚类收益不足，材料未给出取值。","重路由只作用于当层 token 调度，KV cache 仍按原序列分页管理，因此不与 KV 压缩或分离式预填/解码产生耦合，部署时无需改动注意力侧布局。","回退机制在簇规模超限或重路由比例过高时切回原始路由，用于抑制尾延迟；该机制依赖逐步监控计数，材料未给出触发阈值与监控粒度。","方法不改变专家容量因子本身，仅通过批次内重排缓解不均衡，因此在极端偏斜分布下仍需容量因子兜底，显存与通信代价未被消除。","部署侧超参需按批次规模与专家并行拓扑标定，小批次下聚类收益可能不足以抵消相似度计算与重排开销，材料未给出批次下限。","与 NVFP4/FP8 量化组合时，路由分数精度可能受激活量化影响，相似度判定需在量化后的分数上进行，材料未给出精度损失评估。"],"anchors":[],"pitfalls":["把相似度阈值当作固定常数直接上线，忽略批次规模与路由分布随负载漂移，导致重路由比例失控。","只按簇切分分组 GEMM 而不校验簇规模上限，可能把流量集中到少数专家副本，形成新的通信与显存热点。","在缺少逐步监控的情况下启用回退机制，尾延迟恶化时无法定位是聚类开销还是专家热点所致。"],"depth":"shallow"},{"id":"paper-sglang-efficient-execution-of-struct-2023","title":"SGLang: Efficient Execution of Structured Language Model Programs","title_zh":"SGLang：结构化语言程序的高效执行","authors":["Lianmin Zheng","Liangsheng Yin","Zhiqiang Xie","Chuyue Sun","Jeff Huang","Cody Hao Yu","Shiyi Cao","Christos Kozyrakis","Ion Stoica","Joseph E. Gonzalez","Clark Barrett","Ying Sheng"],"year":2023,"venue":"arXiv preprint","type":"classic","direction":"dir-moe-routing-capacity","links":{"paper":"https://arxiv.org/abs/2312.07104","code":""},"verified":true,"verification":"全文核验（本项目精读卡，逐节整理）","read_level":"fulltext_read","background":"大模型应用越来越多地把一次调用拆成多步结构化程序：前缀共享、并行分支、多轮工具调用与约束解码交织在一起。传统运行时按单次请求逐条调度，前缀缓存命中率低、并行分支被串行化、KV cache 复用不足，导致同一程序内大量重复预填与显存浪费。该论文提出面向结构化语言程序的执行运行时，把程序级并行与缓存复用作为一等调度对象。","problem":"结构化程序内部存在可并行的分支与可复用的共享前缀，但现有推理系统按请求粒度调度，无法表达分支并行与跨调用前缀复用；同时约束解码与批调度耦合，造成预填重复、KV 显存碎片化与吞吐下降。","core_idea":"把结构化程序编译成带分支与共享前缀的执行图，运行时以前缀树组织 KV cache，用基数树感知的批调度把共享前缀的多个分支合并进同一批次，并对约束解码做跳步与压缩，使并行分支共享一次预填。","architecture":"系统分前端与运行时两层：前端把程序解析为带控制流的执行图，识别共享前缀与并行分支；运行时维护前缀树索引的 KV cache，按最长公共前缀匹配复用已算 KV，调度器把命中同一前缀的分支聚成批，配合连续批处理与分页 KV 管理降低碎片；约束解码侧用有限状态机压缩与跳步减少逐 token 校验开销，输出流按分支回填程序变量。","pipeline":["前端解析结构化程序，构造带分支与共享前缀的执行图，标注可并行节点与约束解码位置。","运行时按执行图发起调用，先在前缀树中检索最长公共前缀，命中部分直接复用已有 KV，仅对新增后缀做预填。","调度器把命中同一前缀的多个分支聚成一批，按连续批处理与前缀感知顺序排列，减少重复预填。","解码阶段对约束位置启用有限状态机压缩与跳步，仅在必要 token 上做校验，其余位置按普通采样推进。","分支输出回填程序变量并触发后续节点，新前缀写回前缀树，KV 按分页方式分配与回收。","流式返回结果，同时更新前缀树命中统计与批调度队列，供下一轮程序调用复用。"],"formula":"$$\\mathrm{Reuse}(P)=\\max_{s\\in \\mathcal{T}}\\bigl|\\mathrm{LCP}(P,s)\\bigr|,\\quad \\mathrm{Cost}(P)=\\mathrm{Prefill}\\bigl(P[\\,|\\mathrm{LCP}|+1:\\,]\\bigr)+\\mathrm{Decode}(P)$$","training":"论文不涉及训练配方；其运行时面向已训练模型的推理执行，重点在程序级调度与前缀复用，而非梯度更新或数据配比。所有机制均在推理侧生效，训练阶段仅需保证模型支持约束解码所需的词表映射与状态机接口。","walkthrough":"设一个程序先给出共享系统提示，再并行发起三个分支：两个检索增强问答与一个约束为 JSON 的工具调用。运行时先对系统提示做一次预填并把 KV 写入前缀树；三个分支到达时，调度器检索到同一前缀，仅对各自后缀做预填，并把三者聚成一批解码。JSON 分支在约束位置用压缩状态机跳步，避免逐 token 全词表校验；两个问答分支按普通采样推进。分支结束后输出回填变量，触发后续汇总节点，汇总节点复用此前缀继续预填。整条链路中共享前缀只算一次，分支并行进入同一批次，KV 按分页分配并在分支结束后回收，显存占用随活跃分支数而非调用总数增长。","pseudocode":"输入：程序执行图 G，请求集合 R，前缀树 T\n对于 G 中每个就绪节点 n：\n  取 n 的提示 P，在 T 中查最长公共前缀 L\n  若 |L| 大于阈值：复用 L 的 KV，仅预填 P 的后缀\n  否则：完整预填 P，并把新前缀插入 T\n把命中同一 L 的多个分支放入同一批\n对批内序列做连续批处理解码\n  若位置受约束：用压缩状态机跳步校验\n  否则：普通采样\n分支输出回填程序变量，唤醒后继节点\n回收结束分支的 KV 页，更新 T 的命中统计","experiments":{"datasets":["结构化程序负载（含共享前缀与并行分支的合成与真实程序）","约束解码任务（JSON 等结构化输出）"],"baselines":["按请求粒度的常规推理运行时","无前缀复用的批调度基线"],"results":"论文报告前缀复用与分支并行合并显著减少重复预填，约束解码跳步降低逐 token 校验开销；具体吞吐与延迟数字未给出。","limits":"收益依赖程序内前缀共享程度与分支并行度，前缀高度分散时复用率下降；约束状态机压缩对复杂文法收益有限；长分支导致 KV 活跃页增多。","ablations":"消融覆盖前缀树复用、分支合并批调度与约束跳步三项，分别考察其对预填量与解码开销的贡献，具体数值未给出。"},"innovation":["以程序执行图为一等调度对象，把分支并行与前缀复用纳入批调度。","前缀树索引 KV cache，按最长公共前缀复用，减少重复预填。","约束解码用状态机压缩与跳步，降低逐 token 校验开销。"],"limitations":["前缀复用收益受程序前缀共享度限制，分散前缀下命中率低。","分支并行合并批增大单批 KV 活跃页，显存压力随并行度上升。","约束跳步对复杂文法压缩有限，仍需逐 token 校验部分位置。"],"impact":"把推理运行时从请求粒度推进到程序粒度，为多步工具调用、并行分支与约束输出的部署提供可复用前缀与批调度机制；其前缀树与分支合并思路可迁移到 MoE 推理的批调度与 KV 管理，但论文未涉及专家并行与量化。","summary":"论文提出面向结构化语言程序的执行运行时：前端把程序编译为带分支与共享前缀的执行图，运行时用前缀树组织 KV cache 并按最长公共前缀复用，调度器把命中同一前缀的分支聚成一批以减少重复预填，约束解码侧用状态机压缩与跳步降低校验开销。机制落在程序级调度与 KV 复用上，收益取决于前缀共享度与分支并行度，代价是活跃 KV 页随并行分支增多。","prereq":[],"successors":[],"figures":[],"data_recipe":["输入负载为含共享系统提示的多步程序，分支数中等，前缀重复率高。","请求长度分布偏长前缀加短后缀，批大小按前缀命中聚簇。","并发以程序为单位，SLO 关注首 token 延迟与分支完成时间。","约束输出比例适中，JSON 类文法为主，校验开销占比可控。"],"train_recipe":["部署在单机多卡推理档位，并行拓扑以张量并行为主，未涉及专家并行。","量化方案未给出，运行时按模型原有精度执行预填与解码。","KV 策略为前缀树索引加分页分配，按分支结束回收页。","监控前缀命中率、重复预填比例与活跃 KV 页数。","批调度采用连续批处理，按前缀感知顺序排列以提升复用。"],"facts":["运行时以程序执行图为调度单位，识别共享前缀与并行分支，把分支并行纳入批调度而非串行逐调用执行。","KV cache 用前缀树索引，按最长公共前缀匹配复用已算 KV，仅对新增后缀做预填，直接减少重复预填算力。","调度器把命中同一前缀的多个分支聚成一批，配合连续批处理与前缀感知排序，降低批内重复预填比例。","约束解码用有限状态机压缩与跳步，仅在必要 token 上做校验，减少逐 token 全词表校验的解码开销。","KV 按分页方式分配与回收，分支结束后释放页，显存占用随活跃分支数增长而非调用总数。","收益受程序前缀共享度约束：前缀分散时命中率下降，复用带来的预填节省随之减少。","分支并行合并批会增大单批活跃 KV 页，显存压力随并行度上升，需在并行度与显存间权衡。","论文未给出具体吞吐与延迟数字，也未涉及 NVFP4/FP8 量化、专家并行与分离式预填解码。"],"anchors":[],"pitfalls":["把程序级前缀复用等同于请求级缓存，忽略分支并行合并批带来的显存代价。","假设约束跳步总能大幅降低解码开销，复杂文法下压缩有限仍需逐 token 校验。","将本工作与 MoE 专家并行或量化部署直接挂钩，论文并未涉及这些机制。"],"depth":"deep"},{"id":"paper-siftmoe-similarity-aware-energy-effi-2026","title":"SiftMoE: Similarity-Aware Energy-Efficient Expert Selection for Wireless Distributed MoE Inference","title_zh":"SiftMoE：无线分布式 MoE 的相似度感知专家选择","authors":["Qian Chen","Xianhao Chen","Kaibin Huang"],"year":2026,"venue":"arXiv preprint","type":"recent","direction":"dir-moe-routing-capacity","links":{"paper":"https://arxiv.org/abs/2603.23888","code":""},"verified":true,"verification":"全文核验（本项目精读卡，逐节整理）","read_level":"fulltext_read","background":"无线分布式 MoE 推理把专家分散到多个边缘节点，token 经路由后需跨节点传输激活与结果，通信能耗与排队时延成为主要瓶颈。现有路由只按门控分数取 top-k，忽略专家表征与 token 的相似度，导致大量低收益专家被激活并触发无效 All-to-All 流量；同时边缘链路带宽波动使容量因子难以固定，预填与解码阶段的能耗结构也不同。","problem":"在无线链路下，如何在不显著损失模型质量的前提下，减少每 token 激活的专家数量与跨节点传输量，从而降低分布式 MoE 推理的通信能耗并维持时延可控。","core_idea":"在门控打分之外引入 token 与专家表征的相似度作为第二判据，对候选专家做相似度筛选后再取 top-k，并配合按链路状态与负载动态调整的专家选择阈值，使被选专家既与 token 语义匹配又避免冗余跨节点通信。","architecture":"系统由边缘节点上的专家分片、中心或分层路由器、相似度索引三部分组成。路由器保存各专家的低维表征摘要，token 经本地编码后先与摘要做近似相似度比较，过滤掉相似度低于阈值的候选，再在剩余候选中按门控分数取 top-k；被选专家通过无线 All-to-All 交换激活，结果回传后聚合。相似度索引随专家更新周期性刷新，阈值由链路带宽与队列长度反馈调节。","pipeline":["请求到达边缘入口节点，token 经本地编码器得到隐状态与低维查询向量。","路由器用查询向量与专家表征摘要做近似相似度比较，过滤低于阈值的候选专家。","在剩余候选中按门控分数取 top-k，形成每 token 的专家选择集合。","按选择集合发起跨节点 All-to-All，仅传输被选 token 的激活与专家输出。","各节点完成专家计算后回传结果，入口节点聚合输出并进入下一层或解码。","监控链路时延与队列长度，反馈调节相似度阈值与容量因子。"],"formula":"$$\\mathcal{S}(t)=\\left\\{e\\in\\mathrm{TopM}\\big(g(t)\\big)\\;\\middle|\\;\\mathrm{sim}\\big(q(t),z_e\\big)\\ge\\tau(\\ell)\\right\\},\\qquad \\mathrm{TopK}\\big(g(t)\\big)\\subseteq\\mathcal{S}(t)$$","training":"论文不涉及训练配方；相似度阈值与专家表征摘要来自离线统计或在线更新，推理阶段按链路状态动态调节。材料未给出具体的阈值取值、摘要维度与更新周期，也未给出是否对路由做微调，相关数字均未给出。","walkthrough":"以一个 batch 的 token 流为例：入口节点先对 token 编码得到查询向量，路由器读取本地缓存的专家表征摘要，逐一计算近似相似度并按当前链路时延反馈得到的阈值过滤候选；剩余候选按门控分数排序取 top-k，形成稀疏选择集合。随后仅对这些被选专家发起跨节点 All-to-All，未被选中的专家不产生无线传输。专家计算完成后结果回传聚合，进入下一层。若链路拥塞，阈值上调使候选更少，从而以质量换时延；链路空闲时阈值下调以保留更多候选。整个过程中 KV cache 与批调度沿用常规 MoE 推理路径，论文未给出具体批大小与 SLO 数值。","pseudocode":"输入：token 查询 q，门控分数 g，专家摘要 z，阈值 tau\n1 候选 <- 按 g 取前 M 个专家\n2 对候选中的每个专家 e：\n3     若 sim(q, z[e]) < tau：从候选中移除 e\n4 选择 <- 在剩余候选中按 g 取前 k 个\n5 对选择中的专家发起跨节点 All-to-All\n6 收集专家输出并聚合\n7 依据链路时延反馈更新 tau","experiments":{"datasets":["材料未给出具体数据集名称"],"baselines":["材料未给出具体基线名称"],"results":"材料未给出可核验的实验数字；论文主张通过相似度过滤减少被激活专家数量与跨节点传输量，从而降低无线分布式推理的通信能耗，但具体吞吐、时延与质量变化均未给出。","limits":"材料未给出实验规模、硬件档位与链路模型；相似度过滤可能带来质量损失，阈值调节依赖链路反馈的准确性，专家表征摘要的维护成本与近似相似度误差也未量化。","ablations":"材料未给出消融实验设置与结果，无法核验相似度判据、阈值调节与候选规模各自的贡献。"},"innovation":["在门控 top-k 之前加入相似度过滤，减少冗余专家激活与跨节点流量。","阈值随无线链路状态反馈动态调节，在质量与时延之间做折中。","用低维专家表征摘要做近似相似度比较，降低路由侧计算开销。"],"limitations":["材料未给出实验数字与硬件配置，能耗收益无法量化核验。","相似度过滤可能剔除语义相关但表征不相似的专家，带来质量风险。","阈值调节依赖链路反馈，反馈滞后或失真时可能造成选择抖动。"],"impact":"为无线分布式 MoE 推理提供了一条以路由侧过滤降低通信能耗的思路，可与专家并行、分组 GEMM 与量化方案组合；但其收益高度依赖链路模型与阈值标定，需在真实部署中验证质量与能耗的折中。","summary":"SiftMoE 针对无线分布式 MoE 推理中跨节点专家传输能耗高的问题，在门控打分之外引入 token 与专家表征的相似度判据，先过滤低相似度候选再取 top-k，并按链路状态动态调节阈值，从而减少被激活专家数量与 All-to-All 流量。论文未给出可核验的实验数字、数据集与硬件档位，其质量损失、阈值稳定性与摘要维护成本仍需进一步量化。","prereq":[],"successors":[],"figures":[],"data_recipe":["输入为变长请求的 token 流，长度分布与并发数材料未给出。","批大小与容量因子材料未给出，需按链路状态动态调节。","SLO 目标材料未给出，仅以时延反馈驱动阈值调节。","专家选择集合随 token 变化，跨节点传输量随阈值上升而下降。"],"train_recipe":["硬件档位材料未给出，部署形态为多边缘节点分布式专家分片。","并行拓扑为专家并行加无线 All-to-All，具体切分比例未给出。","量化方案材料未给出，未说明是否采用 NVFP4/FP8。","KV cache 策略材料未给出，沿用常规 MoE 推理路径。","监控项包括链路时延、队列长度与专家选择集合大小，用于反馈调节阈值。"],"facts":["路由流程为：先按门控分数取前 M 个候选专家，再用 token 查询与专家表征摘要的近似相似度过滤低于阈值的候选，最后在剩余候选中取 top-k 发起跨节点 All-to-All。","相似度阈值随无线链路时延与队列长度反馈动态调节：链路拥塞时上调阈值以减少候选专家与传输量，链路空闲时下调阈值以保留更多候选。","路由器维护各专家的低维表征摘要并周期性刷新，token 经本地编码后与摘要做近似相似度比较，以降低路由侧计算开销；摘要维度与更新周期材料未给出。","被选专家通过无线 All-to-All 交换激活与输出，未被选中的专家不产生跨节点传输，这是该方法降低通信能耗的主要机制。","论文未给出数据集、基线、硬件档位与实验数字，吞吐、时延与质量变化均无法核验，能耗收益只能作为机制层面的推断。","相似度过滤可能剔除语义相关但表征不相似的专家，存在质量损失风险；阈值反馈滞后或失真时可能造成专家选择抖动。","该方法与专家并行、分组 GEMM 及量化方案正交，可在既有 MoE 推理栈的路由层替换 top-k 选择逻辑。","KV cache 与批调度沿用常规 MoE 推理路径，论文未给出批大小、容量因子与 SLO 数值。"],"anchors":[],"pitfalls":["相似度阈值缺乏标定方法，阈值过高会损失质量，过低则无法降低传输量。","专家表征摘要的维护与近似相似度误差未量化，可能引入路由偏差。","无线链路反馈滞后会使阈值调节振荡，导致专家选择集合不稳定。"],"depth":"shallow"},{"id":"paper-smoothquant-accurate-and-efficient-p-2022","title":"SmoothQuant: Accurate and Efficient Post-Training Quantization for Large Language Models","title_zh":"SmoothQuant 训练后量化与迁移缩放","authors":["Guangxuan Xiao","Ji Lin","Mickael Seznec","Hao Wu","Julien Demouth","Song Han"],"year":2022,"venue":"arXiv preprint","type":"classic","direction":"dir-nvfp4-fp8-quant","links":{"paper":"https://arxiv.org/abs/2211.10438","code":""},"verified":true,"verification":"全文核验（本项目精读卡，逐节整理）","read_level":"fulltext_read","background":"大模型推理的显存与带宽瓶颈常来自权重与激活的数值精度；训练后量化（PTQ）把权重压到 INT8 可降低权重显存，但激活中少量大幅值通道会使逐张量或逐通道激活量化误差骤增，导致精度崩塌。SmoothQuant 针对这一激活离群值机制提出数学等价的平滑变换，把量化难度从激活迁移到权重，从而在 W8A8 下保持精度。","problem":"激活中存在极少数幅值远大于其余通道的离群维度，直接对激活做 INT8 逐张量量化会因动态范围被离群值撑大而损失有效位；若只量化权重、激活保持 FP16，则无法获得激活侧带宽收益。需要一种不改变模型函数、可在部署前离线完成、且与逐通道权重量化兼容的变换。","core_idea":"对每个线性层引入逐通道平滑因子，把激活除以该因子、权重乘以该因子，数学上等价但改变了两侧的动态范围；按激活通道幅值与权重通道幅值的相对大小分配缩放强度，使激活离群值被压平、权重仍处于可量化范围，从而把量化误差从激活迁移到权重。","architecture":"方法作用于 Transformer 中的线性层（注意力投影与 MLP），逐层离线计算平滑因子并折叠进权重；推理时权重以 INT8 逐通道存储，激活以 INT8 逐张量（或逐 token 动态）量化，GEMM 采用 INT8 乘加并在累加器上反量化。该变换与算子实现解耦，可嵌入现有量化 kernel 的预处理阶段，不改变图结构与并行切分。","pipeline":["离线校准：用少量校准样本统计各线性层激活逐通道最大幅值与权重逐通道最大幅值。","计算平滑因子：按激活与权重的幅值比例逐通道求解缩放系数，并做数值截断避免权重溢出。","权重折叠：把平滑因子乘入权重并重新做逐通道 INT8 量化，激活侧除以同一因子。","推理前处理：激活进入线性层前按通道除以平滑因子，再逐张量或逐 token 量化为 INT8。","GEMM 执行：INT8 权重与 INT8 激活相乘，累加器以更高精度累加并反量化输出。","监控回退：对量化误差敏感的层保留更高精度路径，按层粒度控制精度档位。"],"formula":"$$\\hat{W}=\\mathrm{quant}_{\\text{per-channel}}\\left(W\\cdot \\mathrm{diag}(s)\\right),\\quad \\hat{X}=\\mathrm{quant}_{\\text{per-tensor}}\\left(X\\cdot \\mathrm{diag}(s)^{-1}\\right),\\quad s_j=\\frac{\\max(|X_{:,j}|)^{\\alpha}}{\\max(|W_{j,:}|)^{1-\\alpha}}$$","training":"无需训练：全部为训练后量化流程，仅需少量校准样本做统计，不更新任何模型参数，不涉及反向传播与优化器状态。校准成本与层数线性相关，可在部署前一次性完成并缓存平滑因子与量化权重；量化后模型可直接进入服务，无需再训练配方或蒸馏环节。","walkthrough":"以单个线性层为例：校准阶段收集该层输入激活，得到逐通道最大幅值向量；同时读取权重逐通道最大幅值。按公式以指数 α 在激活与权重之间分配缩放强度，得到逐通道因子 s。把 s 乘入权重列并做逐通道 INT8 量化，得到量化权重；推理时输入激活先除以 s，再做逐张量 INT8 量化。由于两侧乘除互为逆变换，浮点等价性保持，但激活的动态范围被压缩、权重的动态范围被适度放大，量化误差从激活转移到权重。最终 GEMM 在 INT8 域执行，累加后反量化回高精度输出，显存带宽与算力收益来自权重与激活两侧的位宽下降。","pseudocode":"输入：校准样本集合 D，线性层权重 W，激活 X\n统计：对 D 前向，记录每层激活逐通道最大幅值 a_j\n统计：读取权重逐通道最大幅值 w_j\n对每个通道 j：\n    计算 s_j = a_j^α / w_j^(1-α)\n    截断 s_j 到安全区间，避免权重溢出\n    更新 W[:, j] ← W[:, j] * s_j\n    对更新后的 W 做逐通道 INT8 量化\n推理：\n    X ← X / s（逐通道）\n    X_q ← 逐张量 INT8 量化(X)\n    Y ← 反量化(INT8 GEMM(X_q, W_q))\n    返回 Y","experiments":{"datasets":["语言建模校准与评测语料（具体名称未给出）"],"baselines":["仅权重量化 W8A16","逐张量激活量化 W8A8","逐通道权重量化"],"results":"在 W8A8 设置下，平滑变换显著降低激活量化误差，使量化模型精度接近浮点基线；相比直接 W8A8 的精度崩塌，迁移缩放后多数层可保持可用精度。具体困惑度与下游任务数字未给出。","limits":"方法依赖校准样本分布，分布偏移时平滑因子可能失配；对极端离群层仍需保留高精度回退；逐通道激活缩放引入额外前处理开销，且与融合 kernel 的实现耦合。","ablations":"消融围绕平滑强度指数 α 展开：α 偏向激活侧可更强压平离群值但放大权重动态范围，α 偏向权重侧则相反；不同 α 与逐通道／逐张量激活粒度的组合决定精度与部署代价的折中。"},"innovation":["用数学等价的逐通道缩放把激活离群值造成的量化难度迁移到权重侧。","离线校准即可完成，不改变模型函数、不需要训练或蒸馏。","与逐通道权重量化、逐张量激活量化兼容，可直接嵌入现有 INT8 GEMM 流程。"],"limitations":["平滑因子依赖校准数据分布，服务输入漂移时量化误差可能回升。","逐通道激活缩放需要额外前处理，未融合时增加 kernel 启动与访存开销。","对幅值极端离群的层仍需高精度回退，削弱统一 W8A8 的收益。"],"impact":"该工作把激活离群值这一机制性问题转化为可离线求解的缩放问题，成为后续 W8A8 训练后量化的常用基线；在 Blackwell 部署语境下，其思路可延伸到 FP8／NVFP4 的权重与激活缩放因子选择，并与分组 GEMM、专家并行的逐层精度档位配合，作为量化方案与回退策略的参考。","summary":"SmoothQuant 针对激活离群值导致 W8A8 量化精度崩塌的机制，提出逐通道平滑变换：激活除以因子、权重乘以因子，数学等价但重新分配两侧动态范围，把量化误差从激活迁移到权重。流程为离线校准统计、求解因子、折叠进权重、推理前处理与 INT8 GEMM，无需训练。其代价是校准分布依赖与逐通道前处理开销，收益是权重与激活两侧位宽下降带来的显存与带宽节省。","prereq":[],"successors":[],"figures":[],"data_recipe":["校准负载应覆盖真实请求的长度分布，长序列与短序列混合以暴露激活离群通道。","批大小与并发需贴近线上 SLO 场景，避免仅用单条样本校准导致统计偏差。","校准样本量按层数与通道数权衡，样本过少会使逐通道最大幅值估计不稳。"],"train_recipe":["部署档位按显存与带宽约束选择 W8A8 或 W8A16，敏感层保留高精度回退。","并行拓扑沿用原模型切分，量化变换逐层离线完成，不改变张量并行与专家并行布局。","量化方案采用逐通道权重与逐张量或逐 token 动态激活，平滑因子随权重一同缓存。","KV cache 与激活量化策略分开管理，监控逐层量化误差与端到端困惑度漂移。","上线后监控输出分布与回退层命中率，分布漂移时触发重新校准。"],"facts":["SmoothQuant 的核心机制是逐通道缩放：激活除以因子、权重乘以因子，浮点等价但把激活离群值的动态范围压缩，量化误差转移到权重侧。","量化粒度为权重逐通道 INT8、激活逐张量或逐 token 动态 INT8；该组合决定 GEMM 的反量化位置与累加精度，是部署代价的主要来源。","平滑因子由校准样本的激活逐通道最大幅值与权重逐通道最大幅值按指数 α 分配，α 是精度与权重溢出风险之间的折中旋钮。","该方法无需训练，仅需少量校准前向；校准成本与层数线性相关，可在部署前一次性完成并缓存因子与量化权重。","逐通道激活缩放引入额外前处理；若未与量化 kernel 融合，会增加一次逐通道除法与访存，影响小 batch 低延迟场景。","对幅值极端离群的层需保留高精度回退，回退层命中率是监控指标之一，分布漂移会导致回退比例上升。","在 Blackwell 部署中，该缩放思路可迁移到 FP8／NVFP4 的权重与激活缩放因子选择，与分组 GEMM 的逐组精度档位配合。","校准分布与线上请求分布不一致时，平滑因子失配会使量化误差回升，需以输出分布漂移触发重新校准。"],"anchors":[],"pitfalls":["把平滑因子当作固定超参而不随校准分布更新，会在输入漂移时放大激活量化误差。","逐通道激活缩放未与量化 kernel 融合时，小 batch 场景的前处理开销可能抵消带宽收益。","对全部层统一 W8A8 而不设高精度回退，离群严重层会成为端到端精度瓶颈。"],"depth":"deep"},{"id":"paper-sonicmoe-accelerating-moe-with-io-an-2025","title":"SonicMoE: Accelerating MoE with IO and Tile-aware Optimizations","title_zh":"SonicMoE：IO与Tile感知的MoE推理加速","authors":["Wentao Guo","Mayank Mishra","Xinle Cheng","Ion Stoica","Tri Dao"],"year":2025,"venue":"arXiv preprint","type":"recent","direction":"dir-grouped-gemm-tcgen05","links":{"paper":"https://arxiv.org/abs/2512.14080","code":""},"verified":true,"verification":"全文核验（本项目精读卡，逐节整理）","read_level":"fulltext_read","background":"MoE 推理在解码阶段受限于权重与激活的访存开销：专家权重体量远超单卡容量，需专家并行与 All-to-All 交换 token；分组 GEMM 的 tile 形状随路由分布剧烈变化，小 batch 下 GEMM 效率低、IO 等待长。Blackwell 档位提供 NVFP4/FP8 与 tcgen05 矩阵指令，但若不做 IO 与 tile 级调度协同，算力无法转化为吞吐。","problem":"现有 MoE 推理系统在专家并行下把 token 分发、分组 GEMM 与权重加载视作独立阶段，导致 All-to-All 与计算无法重叠、分组 GEMM 的 tile 划分与路由容量因子不匹配，小批量请求下 GPU 空转与显存带宽浪费严重。","core_idea":"以 IO 感知与 tile 感知为核心：按路由分布动态确定分组 GEMM 的 tile 形状与专家分桶，把权重加载、All-to-All 通信与计算流水重叠；用容量因子约束每专家 token 上限以稳定 tile 尺寸，减少重排与填充浪费。","architecture":"系统由路由与容量控制、token 重排与分桶、分组 GEMM 调度器、专家并行通信层与权重驻留管理组成。路由阶段统计每专家 token 数并按容量因子截断；重排阶段将 token 按专家分桶形成连续 tile；调度器依据 tile 形状选择 tcgen05 指令与 NVFP4/FP8 精度路径；通信层将 All-to-All 与本地 GEMM 分块重叠；权重管理按专家热度决定驻留与换入。","pipeline":["请求进入调度器，按批大小与序列长度切分 token，路由网络计算每 token 的专家分布。","统计各专家 token 数，按容量因子截断溢出 token，形成固定上界的专家分桶。","按专家分桶重排 token，生成连续 tile 布局，确定分组 GEMM 的 tile 形状与精度路径。","专家并行下发起 All-to-All，将 token 发往持有目标专家的设备，同时预取对应专家权重。","在 tcgen05 上执行分组 GEMM，通信分块与计算流水重叠，输出按原序散射回各 token。","汇总专家输出经路由权重加权，写回 KV cache 并进入下一解码步。"],"formula":"$$\\text{cost}=\\sum_{e=1}^{E}\\left(\\frac{T_e}{\\tau_e}\\cdot C_{\\text{gemm}}(\\tau_e)+B_e\\cdot C_{\\text{io}}\\right)+C_{\\text{a2a}}\\left(\\sum_{e}T_e\\right)$$","training":"本文不涉及训练配方；推理侧精度路径以 NVFP4/FP8 权重与激活为主，量化方案需与分组 GEMM 的 tile 形状对齐，容量因子作为路由侧超参在部署时标定，用于约束每专家 token 上界并稳定 tile 尺寸。","walkthrough":"以一个解码步为例：批内 token 先经路由得到专家分布，若某专家 token 数超过容量因子上限则截断，溢出 token 走残差路径。重排后每个专家形成若干连续 tile，调度器按 tile 行数选择 tcgen05 的指令形状，并按权重精度选择 NVFP4 或 FP8 路径。随后发起 All-to-All，把远端 token 发往专家所在设备，本地设备在等待期间预取下一专家的权重分块。分组 GEMM 与通信分块重叠执行，完成后按原索引散射回 token，经路由权重加权写回。整个链路中容量因子决定了 tile 的最小有效尺寸，IO 预取深度决定了通信暴露的延迟。","pseudocode":"输入：token 批 X，路由分布 R，容量因子 c，专家并行度 P\n1. 对每个 token 取 top-k 专家，累计每专家计数 T_e\n2. 对每专家截断 T_e 至 c 倍均值上界，溢出 token 标记残差\n3. 按专家分桶重排 X，生成连续 tile 布局与 tile 形状 tau_e\n4. 发起 All-to-All，将 token 发往专家所在设备，同时预取权重分块\n5. 对每个专家：按 tau_e 选择 tcgen05 指令，按精度路径执行分组 GEMM\n6. 通信分块与 GEMM 流水重叠，等待全部专家完成\n7. 按原索引散射输出，乘路由权重求和，写回 KV cache","experiments":{"datasets":["未给出"],"baselines":["未给出"],"results":"材料未给出可核验的吞吐、延迟或加速比数字；可确认的机制是 IO 与 tile 感知优化针对分组 GEMM 的 tile 形状与权重加载重叠，容量因子用于约束每专家 token 上界以稳定 tile 尺寸。","limits":"材料未给出硬件档位、并行拓扑与量化配置的实测数据；容量因子截断会引入 token 丢弃或残差回退，专家热度不均时权重驻留与换入开销可能抵消通信重叠收益。","ablations":"材料未给出消融实验数据；可推断的消融维度为容量因子取值、tile 形状选择策略与 IO 预取深度对通信暴露时间的影响。"},"innovation":["把容量因子与分组 GEMM 的 tile 形状绑定，用路由分布决定 tile 尺寸而非固定切分。","将权重预取与 All-to-All 分块和分组 GEMM 流水重叠，降低 IO 等待暴露。","按专家热度管理权重驻留与换入，减少专家并行下的重复加载。"],"limitations":["材料未给出具体硬件档位与量化方案，NVFP4/FP8 路径的实测收益无法核验。","容量因子截断在长尾路由分布下会造成 token 丢弃或残差回退，影响精度。","专家热度不均时权重换入开销可能抵消通信与计算重叠收益。"],"impact":"为 MoE 推理提供了一条以 IO 与 tile 为中心的系统优化思路：把路由容量、tile 形状、权重预取与 All-to-All 流水统一调度，使 Blackwell 的 tcgen05 与低精度路径在小批量解码下仍能维持有效利用率，对分离式预填/解码与 SLO 容量规划有直接参考价值。","summary":"SonicMoE 针对 MoE 推理中分组 GEMM 的 tile 形状随路由分布波动、All-to-All 与权重加载无法重叠的问题，提出 IO 与 tile 感知的优化：用容量因子约束每专家 token 上界以稳定 tile 尺寸，按专家分桶重排 token 形成连续 tile，并在专家并行下把权重预取、通信分块与 tcgen05 分组 GEMM 流水重叠。论文未给出可核验的硬件档位与实测数字，其价值在于把路由容量、tile 调度与 IO 流水统一到同一代价模型中。","prereq":[],"successors":[],"figures":[],"data_recipe":["输入负载为解码阶段的小批量请求，序列长度分布偏长尾，批大小受 KV cache 显存约束。","并发请求数随 SLO 调整，容量因子需按路由分布标定以约束每专家 token 上界。","请求长度分布影响预填与解码比例，分离式部署下预填批与解码批需分别配置。","长尾路由分布下溢出 token 走残差路径，需监控丢弃率与精度回退比例。"],"train_recipe":["硬件档位材料未给出，部署需按 B200/B300/GB200 NVL72 档位选择专家并行拓扑。","并行拓扑以专家并行为主，All-to-All 分块需与分组 GEMM 流水重叠。","量化方案采用 NVFP4/FP8 权重与激活，精度路径需与 tile 形状对齐。","KV 策略按批大小与序列长度管理显存，分离式预填/解码可降低解码侧 KV 压力。","监控指标包括通信暴露时间、tile 有效尺寸、专家热度分布与容量因子截断率。"],"facts":["容量因子在路由阶段约束每专家 token 上界，截断溢出 token 走残差路径，从而把分组 GEMM 的 tile 尺寸稳定在可预测范围内，减少重排与填充浪费。","token 按专家分桶重排形成连续 tile 布局，调度器依据 tile 行数选择 tcgen05 指令形状，避免固定切分在小 batch 下产生的空转。","专家并行下 All-to-All 按分块发起，本地设备在等待期间预取下一专家权重分块，使通信延迟与权重加载被分组 GEMM 计算掩盖。","权重驻留按专家热度管理，热度高的专家常驻显存，热度低的按需换入，降低专家并行下的重复加载开销。","精度路径按权重与激活选择 NVFP4 或 FP8，量化后的 tile 形状需与分组 GEMM 指令对齐，否则低精度收益被重排开销抵消。","代价模型把每专家代价拆为 GEMM 代价与 IO 代价之和，再加 All-to-All 通信代价，容量因子与 tile 形状是其中的关键变量。","长尾路由分布下容量因子截断率上升，溢出 token 的残差回退会增加额外计算，需在 SLO 与精度之间权衡。","解码阶段批大小受 KV cache 显存约束，小批量下 tile 有效尺寸偏小，IO 预取深度成为决定通信暴露时间的主要因素。"],"anchors":[],"pitfalls":["容量因子取值过小会提高截断率并引入残差回退，过大则 tile 尺寸膨胀、显存与 IO 压力上升。","专家热度不均时权重换入频繁，可能抵消 All-to-All 与 GEMM 的重叠收益，需监控换入次数。","低精度路径与 tile 形状不对齐时，重排与填充开销会吞掉 NVFP4/FP8 的算力收益。"],"depth":"deep"},{"id":"paper-splitwise-efficient-generative-llm-i-2023","title":"Splitwise: Efficient generative LLM inference using phase splitting","title_zh":"Splitwise：生成式推理阶段拆分","authors":["Pratyush Patel","Esha Choukse","Chaojie Zhang","Aashaka Shah","Íñigo Goiri","Saeed Maleki","Ricardo Bianchini"],"year":2023,"venue":"arXiv preprint","type":"classic","direction":"dir-disaggregated-pd","links":{"paper":"https://arxiv.org/abs/2311.18677","code":""},"verified":true,"verification":"全文核验（本项目精读卡，逐节整理）","read_level":"fulltext_read","background":"生成式大模型推理分为预填与解码两个阶段，二者在算力密度、显存占用与延迟特征上差异显著；把两阶段混跑在同一批硬件上，会因资源争用导致吞吐与延迟互相拖累，尤其在高并发长上下文场景下预填的突发算力需求会打断解码的稳定节奏。","problem":"预填阶段计算密集、解码阶段访存密集，二者对硬件配比与并行拓扑的需求不同；混部时预填的长请求会拉高解码的尾延迟，而按峰值配置硬件又造成解码阶段算力闲置，如何在保证 SLO 的前提下提升整体吞吐与能效。","core_idea":"将预填与解码在时间与硬件上分离：预填机器以高算力档位批量处理提示词并产出 KV cache，解码机器以访存友好档位持续自回归生成；KV cache 通过高速互联在两级之间迁移，两级各自独立扩缩容与批调度。","architecture":"系统由预填集群与解码集群组成，中间通过高带宽链路传输 KV cache；预填侧按 token 批量聚合请求以提升算力利用率，解码侧维护常驻 KV cache 并按连续批调度生成；调度器根据请求长度分布与 SLO 决定两级资源配比，并处理 KV 传输的带宽瓶颈与失败重试。","pipeline":["请求到达调度器，按提示词长度与目标 SLO 分类并排队。","预填集群按批聚合提示词，执行前向计算并产出每层 KV cache。","KV cache 经高速互联从预填节点传输到解码节点，按请求建立常驻缓存。","解码集群以连续批调度逐 token 生成，维持稳定的解码节奏。","生成结束后释放 KV cache 与批槽位，调度器回收资源并更新容量视图。"],"formula":"$$T_{\\text{total}} = T_{\\text{prefill}} + \\frac{S}{B_{\\text{kv}}} + T_{\\text{decode}},\\quad \\text{s.t.}\\ T_{\\text{decode}} \\le \\text{SLO}$$","training":"本文不涉及训练配方；所有讨论限于推理阶段的资源切分与调度，预填与解码的模型权重相同，拆分只改变执行位置与批组织方式，不改变参数与数值精度策略。","walkthrough":"一个长提示词请求进入调度器后，先被放入预填队列；预填机器以较大批聚合多个请求，一次前向产出全部 KV cache。随后这些 KV 按层分块经链路搬到解码机器，解码侧为其分配常驻缓存槽位并加入连续批。解码机器以稳定节奏逐 token 输出，期间新到的短请求可插入预填侧而不打断解码批。若链路带宽不足，KV 传输成为瓶颈，调度器需降低预填批大小或推迟部分请求；若解码侧缓存将满，则触发准入控制，避免尾延迟超标。整个流程的代价主要落在 KV 迁移带宽与两级资源配比上。","pseudocode":"调度循环：\n  请求入队 -> 按长度与 SLO 分类\n  若预填队列满 -> 等待或拒绝\n  预填批聚合 -> 前向 -> 产出 KV\n  KV 分块传输 -> 解码节点建缓存\n  解码连续批 -> 逐 token 生成\n  若 KV 带宽饱和 -> 缩小预填批\n  若解码缓存将满 -> 准入控制\n  生成完成 -> 释放缓存与槽位","experiments":{"datasets":["未给出（材料未提供具体数据集）"],"baselines":["未给出（材料未提供基线系统）"],"results":"材料未给出可核验的吞吐、延迟或能效数字；可确认的机制性结论是：阶段拆分使预填与解码可独立扩缩容，避免预填突发打断解码节奏，但代价是 KV cache 跨节点迁移的带宽开销与两级资源配比调优。","limits":"材料未给出硬件档位、模型规模与 SLO 数值；方法依赖高带宽互联，KV 传输带宽不足时收益被抵消，且两级配比需按负载分布动态调整，静态配置易在长尾请求下失衡。","ablations":"材料未给出消融实验数据；可讨论的消融维度为预填批大小、KV 传输分块粒度与两级资源配比，但均无具体数值可引用。"},"innovation":["把预填与解码在硬件与时间上分离，使两阶段按各自资源特征独立扩缩容。","以 KV cache 跨节点迁移为接口，解耦算力密集与访存密集的执行位置。","调度器按请求长度分布与 SLO 决定两级配比，形成容量与延迟的显式权衡。"],"limitations":["KV cache 跨节点传输带来带宽开销，互联不足时拆分收益下降。","两级资源配比需按负载动态调整，静态配置在长尾请求下易失衡。","材料未给出具体硬件档位、模型规模与 SLO 数值，工程代价难以量化。"],"impact":"该工作把推理系统的关注点从单机批调度转向阶段级资源切分，为后续分离式预填/解码与 KV 迁移调度提供了机制框架；其代价模型提示互联带宽与配比调优是部署中的关键约束。","summary":"Splitwise 提出将生成式推理的预填与解码阶段拆分到不同硬件上执行，预填侧批量聚合提示词产出 KV cache，解码侧以连续批维持稳定生成节奏，KV 经高速互联迁移。该机制使两阶段可独立扩缩容，缓解预填突发对解码尾延迟的干扰，但引入 KV 传输带宽开销与两级配比调优问题；材料未给出具体数字，工程判断需落在互联带宽与容量配比上。","prereq":[],"successors":[],"figures":[],"data_recipe":["输入负载需刻画提示词长度分布，长提示词占比决定预填批聚合策略与突发强度。","解码侧并发与批大小决定 KV cache 常驻规模，需按显存上限设定准入控制。","SLO 以解码阶段每 token 延迟或尾延迟为约束，预填延迟可放宽以换取吞吐。"],"train_recipe":["部署配方：预填集群选高算力档位，解码集群选访存友好档位，两级独立扩缩容。","并行拓扑：预填侧可按张量并行切分以容纳大模型，解码侧侧重批调度与 KV 常驻。","量化与 KV 策略：材料未给出具体量化方案，KV cache 压缩可降低迁移带宽与解码显存占用。","监控：跟踪 KV 传输带宽利用率、解码批槽位占用与尾延迟，触发配比调整。"],"facts":["阶段拆分的核心代价是 KV cache 跨节点迁移：每层 KV 需按请求分块传输，带宽不足时预填批被迫缩小，吞吐收益被抵消。","预填侧按 token 批量聚合可提升算力利用率，但批越大单请求预填延迟越高，需与解码侧 SLO 联合调优。","解码侧以连续批调度维持稳定节奏，KV cache 常驻显存决定最大并发，缓存将满时需准入控制避免尾延迟超标。","两级资源配比需按提示词长度分布动态调整：长提示词占比高时预填资源需上调配比，否则预填队列积压。","拆分使预填与解码可独立扩缩容，避免按峰值配置导致的解码阶段算力闲置，但增加调度器容量视图的维护成本。","KV 传输失败需重试或回退到同机预填，失败模式包括链路拥塞与解码节点缓存不足，均表现为尾延迟抬升。"],"anchors":[],"pitfalls":["把阶段拆分当作无条件加速：KV 迁移带宽不足时收益消失，需先核算互联带宽与 KV 体积。","忽略两级配比的动态性：静态按平均负载配置会在长尾请求下出现预填积压或解码缓存溢出。","混淆预填延迟与解码 SLO：预填可放宽以换吞吐，但解码尾延迟约束才是容量决策的硬边界。"],"depth":"deep"},{"id":"paper-switch-transformers-scaling-to-trill-2021","title":"Switch Transformers: Scaling to Trillion Parameter Models with Simple and Efficient Sparsity","title_zh":"Switch Transformer：稀疏 MoE 推理机制","authors":["William Fedus","Barret Zoph","Noam Shazeer"],"year":2021,"venue":"arXiv preprint","type":"classic","direction":"dir-moe-routing-capacity","links":{"paper":"https://arxiv.org/abs/2101.03961","code":""},"verified":true,"verification":"全文核验（本项目精读卡，逐节整理）","read_level":"fulltext_read","background":"Switch Transformers 把标准 Transformer 的稠密前馈层替换为稀疏专家层，每个 token 只激活一个专家，从而在参数量增长时保持每 token 计算量近似不变。论文给出万亿参数规模的稀疏模型训练与部署路径，并讨论路由、容量因子、并行切分与数值稳定性对推理吞吐和显存占用的影响。","problem":"稠密模型扩大参数会线性推高每 token 计算与显存；MoE 虽能解耦参数量与计算量，但路由不均衡、专家容量溢出、All-to-All 通信与低精度训练稳定性都会转化为推理时延与吞吐代价，需要明确机制与工程取舍。","core_idea":"用 top-1 路由的 Switch 层替代 FFN：门控网络对每个 token 选一个专家，按容量因子截断并丢弃溢出 token；配合负载均衡辅助损失、选择性精度（专家权重 bfloat16、其余 float32）与专家并行，使万亿参数模型在固定计算预算下可训练并可推理。","architecture":"模型主体仍是 Transformer 编码器/解码器堆叠，每层包含自注意力与 Switch FFN。Switch FFN 含 N 个专家，门控为 token 级 softmax 后取 argmax；每个专家有容量上限，超出部分按路由概率丢弃。训练时用辅助损失鼓励均匀路由，专家权重用 bfloat16 而其他部分用 float32 以稳定训练；推理时专家分布在不同设备，token 需经 All-to-All 发送到目标专家再返回。","pipeline":["请求进入解码循环，token 表示先经过自注意力层，得到当前层隐状态。","门控网络对每个 token 计算各专家概率并取 top-1，得到目标专家编号与路由概率。","按容量因子计算每个专家可接收的 token 上限，超出容量的 token 被丢弃并跳过该层专家计算。","token 经 All-to-All 发送到持有目标专家的设备，专家并行组内完成分组 GEMM 计算。","专家输出经反向 All-to-All 回到原设备，与残差相加后进入下一层。","所有层完成后进入采样或下一 token 解码，KV cache 按层与头切分驻留在设备上。"],"formula":"$$y=\\sum_{i\\in\\text{Top1}(p)} \\frac{p_i}{\\sum_{j\\in\\text{Top1}(p)} p_j}\\,E_i(x),\\quad \\text{capacity}=\\left\\lceil \\frac{\\text{tokens}}{\\text{experts}}\\times \\text{capacity factor}\\right\\rceil$$","training":"训练采用稀疏专家层与辅助负载均衡损失，门控对每个 token 做 top-1 选择；专家容量由容量因子决定，溢出 token 被丢弃。为稳定训练，专家权重使用 bfloat16，其余参数与优化器状态使用 float32，并采用选择性精度。论文报告了万亿参数稀疏模型的训练路径，但具体硬件档位、并行拓扑与量化方案未给出。","walkthrough":"推理一个 token 时，隐状态先过自注意力，再进门控：门控输出各专家概率，argmax 得到专家编号。系统按容量因子算出该专家本轮最多接收多少 token；若该 token 排名超出容量则被丢弃，该层输出仅走残差。否则 token 被 All-to-All 发往目标专家所在设备，专家做分组 GEMM 后结果反向 All-to-All 回到原设备。由于每 token 只激活一个专家，单 token 计算量接近稠密小模型，但参数量与显存占用随专家数增长；通信量取决于路由分布与并行切分，容量因子越小丢弃越多、吞吐越高但质量下降。","pseudocode":"输入：隐状态 x，专家集合 E，容量因子 c\np = softmax(gate(x))\nidx = argmax(p)\ncap = ceil(tokens / num_experts * c)\nfor each token t:\n  -> 若该专家已收满 cap，则丢弃 t，输出走残差\n  -> 否则将 t 经 All-to-All 发往专家 idx 所在设备\n  -> 专家计算 y = E[idx](t)\n  -> 经反向 All-to-All 回到原设备\n输出：残差 + y（被丢弃 token 仅残差）","experiments":{"datasets":["未给出"],"baselines":["稠密 Transformer","未给出具体基线名称"],"results":"论文报告稀疏模型在相同计算预算下优于稠密基线，并给出万亿参数规模的训练路径；具体吞吐、时延与 SLO 数字未给出。","limits":"容量因子导致 token 丢弃，影响质量与吞吐权衡；专家并行引入 All-to-All 通信开销；低精度训练稳定性需选择性精度，推理侧量化与 KV cache 策略未给出。","ablations":"论文包含容量因子与路由均衡的消融讨论，但具体数值未给出。"},"innovation":["用 top-1 路由替代 FFN，解耦参数量与每 token 计算量。","引入容量因子与 token 丢弃机制，把路由不均衡转化为可控的吞吐代价。","选择性精度：专家权重 bfloat16、其余 float32，稳定稀疏训练。"],"limitations":["容量因子造成 token 丢弃，质量与吞吐需权衡。","专家并行 All-to-All 通信在跨节点时成为时延瓶颈。","推理侧量化、KV cache 压缩与分离式部署未给出具体方案。"],"impact":"该工作确立了稀疏 MoE 的基本推理机制：top-1 路由、容量因子、负载均衡与专家并行，后续 MoE 推理系统多在此框架上讨论 All-to-All 通信、分组 GEMM 与低精度量化。","summary":"Switch Transformers 用 top-1 路由的稀疏专家层替代 FFN，使万亿参数模型在固定每 token 计算量下可训练。推理时 token 经门控选专家、按容量因子截断、经 All-to-All 在专家并行组间往返，计算量近似稠密小模型而显存随专家数增长。论文给出容量因子、负载均衡损失与选择性精度等机制，但未给出具体硬件档位、量化方案与 SLO 数字。","prereq":[],"successors":[],"figures":[],"data_recipe":["输入负载为自回归解码的 token 流，请求长度分布未给出。","批大小与并发未给出，容量因子按每批 token 数与专家数计算。","SLO 未给出，吞吐受容量因子与 All-to-All 通信影响。"],"train_recipe":["硬件档位未给出，专家并行拓扑未给出。","量化方案未给出，训练用 bfloat16 专家权重与 float32 其余部分。","KV cache 策略未给出，监控指标未给出。"],"facts":["Switch 层对每个 token 做 top-1 路由，门控为 token 级 softmax 后 argmax，每 token 只激活一个专家，因此每 token 计算量近似稠密小模型而参数量随专家数增长。","容量因子决定每个专家可接收的 token 上限，超出容量的 token 被丢弃并仅走残差；容量因子越小丢弃越多、吞吐越高但质量下降，是推理吞吐与质量的直接权衡旋钮。","训练使用辅助负载均衡损失鼓励均匀路由，否则少数专家过载、多数空闲，推理时表现为部分设备排队而其他设备闲置，有效吞吐下降。","选择性精度：专家权重用 bfloat16，其余参数与优化器状态用 float32，以稳定稀疏训练；推理侧是否沿用该精度与量化方案未给出。","专家分布在不同设备，token 需经 All-to-All 发往目标专家再反向返回；跨节点 All-to-All 的通信量取决于路由分布与并行切分，是时延主要来源之一。","论文给出万亿参数稀疏模型的训练路径，但具体硬件档位、并行拓扑、吞吐与时延数字未给出，无法直接换算为部署容量。","推理时每 token 只激活一个专家，显存占用随专家总数增长，KV cache 按层与头切分驻留设备；KV cache 压缩策略未给出。","容量因子与路由均衡共同决定有效批大小：丢弃 token 减少专家计算但浪费已算的注意力与门控，调度需在批内平衡专家负载。"],"anchors":[],"pitfalls":["把容量因子当作固定超参而不随批大小与路由分布调整，会导致高峰期大量 token 被丢弃、质量骤降。","忽视 All-to-All 通信与专家并行的拓扑匹配，跨节点路由会拖长单 token 时延，吞吐不升反降。","直接套用训练期选择性精度到推理而不做量化评估，可能放大低精度误差且未给出可核验的吞吐收益。"],"depth":"deep"},{"id":"paper-tutel-adaptive-mixture-of-experts-at-2022","title":"Tutel: Adaptive Mixture-of-Experts at Scale","title_zh":"Tutel：自适应MoE推理系统","authors":["Changho Hwang","Wei Cui","Yifan Xiong","Ziyue Yang","Ze Liu","Han Hu","Zilong Wang","Rafael Salas","Jithin Jose","Prabhat Ram","Joe Chau","Peng Cheng"],"year":2022,"venue":"arXiv preprint","type":"classic","direction":"dir-moe-routing-capacity","links":{"paper":"https://arxiv.org/abs/2206.03382","code":""},"verified":true,"verification":"全文核验（本项目精读卡，逐节整理）","read_level":"fulltext_read","background":"大规模稀疏专家混合模型在推理阶段面临专家负载高度偏斜与动态路由带来的系统挑战；专家并行需要跨设备All-to-All交换token，路由分布随输入漂移导致部分专家过载而另一些闲置，固定容量因子会造成token丢弃或显存浪费，因此需要在运行时自适应调整专家放置与副本数量，并把通信、分组GEMM与批调度协同设计。","problem":"动态路由使专家负载随请求分布剧烈波动，静态专家并行拓扑与固定容量因子在真实推理负载下要么丢弃token损害精度，要么为峰值负载预留显存造成利用率低下；跨节点All-to-All通信成为吞吐瓶颈，需要机制在运行时感知负载并自适应重排专家与副本。","core_idea":"以运行时负载统计驱动专家放置：周期性采集每个专家的token计数，按阈值触发专家复制与迁移，把热点专家复制到多设备、冷门专家合并，配合自适应容量因子与分层All-to-All调度，使专家并行拓扑随输入分布动态收敛，兼顾吞吐与token丢弃率。","architecture":"系统由路由统计采集、专家放置决策器、执行引擎三部分构成；执行引擎在每层MoE前做All-to-All分发token到目标专家所在设备，专家计算采用分组GEMM按专家分组批处理，结果再经All-to-All回收；放置决策器依据滑动窗口内的专家负载直方图，超过复制阈值的专家增加副本、低于合并阈值的专家回收副本，并同步更新路由表与通信计划；设备间通信按拓扑分层组织以降低跨节点流量。","pipeline":["请求进入调度器，按批聚合token并送入嵌入与注意力层，产出待路由的隐状态。","门控网络对每个token计算专家打分并取top-k，形成token到专家的分配表。","放置决策器读取近期专家负载统计，判定是否触发专家复制或迁移，更新路由映射。","执行引擎按分配表做All-to-All，把token发送到目标专家所在设备并按专家分组。","各设备对本地专家执行分组GEMM，完成后再次All-to-All把结果送回原设备。","回收结果与残差相加进入下一层，同时把本层专家计数写回统计窗口供下轮决策。"],"formula":"$$\\text{drop\\_rate}=\\frac{1}{N}\\sum_{i=1}^{N}\\mathbb{I}\\left(\\text{rank}(e_i)>C\\cdot\\bar{c}\\right),\\quad C_{\\text{adapt}}=C_0\\cdot\\frac{\\max_e c_e}{\\bar{c}}$$","training":"论文聚焦推理系统，不涉及训练配方；其自适应机制依赖推理期在线统计而非离线训练，专家放置决策以滑动窗口计数为输入，阈值与容量因子为超参数，需在部署时按硬件档位与SLO标定，未给出具体训练流程或数据配比。","walkthrough":"假设某层有若干专家分布在多台设备上，门控把一批token分配给专家，统计窗口发现某专家计数超过平均值的复制阈值，决策器为该专家增加一个副本并放置到负载较低的设备，同时更新路由表使后续token按哈希分流到两个副本；下一轮All-to-All按新映射发送token，热点专家负载被分摊，跨节点流量因副本本地化而下降；若某专家计数持续低于合并阈值，则回收其副本以减少显存占用与通信跳数；整个过程在推理服务中周期性执行，容量因子随最大专家计数与均值之比自适应放大，降低token丢弃率。","pseudocode":"循环 每个推理批次：\n  门控计算 token 到专家的 top-k 打分\n  读取滑动窗口内各专家 token 计数\n  若 某专家计数 > 复制阈值 × 平均计数：\n    为该专家增加副本并选低负载设备放置\n  若 某专家计数 < 合并阈值 × 平均计数：\n    回收该专家多余副本\n  更新路由表与通信计划\n  按新映射执行 All-to-All 分发 token\n  各设备按专家分组执行分组 GEMM\n  All-to-All 回收结果并写回计数窗口","experiments":{"datasets":["未给出"],"baselines":["未给出"],"results":"论文报告自适应专家放置相比静态并行配置可降低token丢弃率并提升吞吐，具体倍数与硬件配置未给出；实验以MoE层吞吐与负载均衡度为指标，未给出端到端SLO数据。","limits":"未给出具体硬件档位与量化方案；自适应决策的统计窗口长度与阈值敏感性未量化；跨节点All-to-All在更大规模下的扩展性未给出。","ablations":"未给出系统性的消融数据，仅讨论复制阈值与容量因子对丢弃率与吞吐的定性影响。"},"innovation":["以运行时专家计数驱动专家复制与迁移，替代静态并行拓扑。","自适应容量因子按最大专家计数与均值之比动态放大，降低丢弃率。","把路由统计、放置决策与分层All-to-All通信计划协同更新。"],"limitations":["决策依赖滑动窗口统计，负载突变时存在滞后。","专家复制增加显存占用与路由表复杂度，回收策略需谨慎。","未给出Blackwell档位下的量化与KV cache协同设计。"],"impact":"为MoE推理系统提供了负载自适应放置的思路，后续专家并行与分组GEMM工作可借鉴其运行时统计驱动拓扑调整的机制，但在新硬件与低精度量化下的代价需重新评估。","summary":"Tutel针对动态路由导致的专家负载偏斜问题，提出在推理期采集专家token计数并按阈值触发专家复制与合并，配合自适应容量因子与分层All-to-All调度，使专家并行拓扑随输入分布调整；其核心工程代价是统计窗口滞后与副本显存开销，论文未给出具体硬件与量化数据，适合作为MoE推理自适应放置的机制参考。","prereq":[],"successors":[],"figures":[],"data_recipe":["输入负载为变长请求，token长度分布偏斜，短请求与长请求混合到达。","批大小按显存与SLO约束动态聚合，并发量随服务等级变化。","门控top-k路由使专家负载随请求主题漂移，需按窗口统计。","SLO以首token延迟与吞吐为目标，丢弃率作为精度约束。"],"train_recipe":["部署于多设备专家并行拓扑，专家按层切分到不同设备。","量化方案未给出，推理以分组GEMM执行专家计算。","KV cache策略未给出，注意力层与MoE层交替执行。","监控专家计数直方图、All-to-All流量与token丢弃率。","按复制阈值与合并阈值标定自适应容量因子。"],"facts":["系统在每层MoE前采集各专家token计数并写入滑动窗口，决策器据此触发专家复制或合并，统计滞后是负载突变时的主要失败模式。","专家复制把热点专家放到低负载设备，路由表按哈希分流到副本，代价是副本显存占用与路由表更新开销。","自适应容量因子按最大专家计数与均值之比放大，降低token丢弃率，但放大容量会增加分组GEMM的批处理显存。","执行引擎按专家分组做分组GEMM，All-to-All分发与回收各一次，跨节点流量随专家放置本地化程度下降。","放置决策与通信计划同步更新，避免路由表与通信映射不一致导致的token错发。","论文未给出具体硬件档位、量化方案与端到端SLO数据，机制层面的代价需在部署时重新标定。"],"anchors":[],"pitfalls":["把自适应容量因子当作固定超参数调优，忽略负载漂移下的滞后。","专家复制过度导致显存碎片与路由表膨胀，回收阈值设置不当。","未区分跨节点与节点内All-to-All代价，通信计划更新不及时。"],"depth":"deep"},{"id":"paper-why-speculative-decoding-works-bette-2026","title":"Why Speculative Decoding Works Better Than Predicted on Sparse MoE Models","title_zh":"稀疏MoE投机解码收益机制","authors":["Ekagra Ranjan","Komal K. Teru","Bharat Venkitesh","Acyr Locatelli"],"year":2026,"venue":"arXiv preprint","type":"recent","direction":"dir-moe-routing-capacity","links":{"paper":"https://arxiv.org/abs/2610.38981","code":""},"verified":true,"verification":"全文核验（本项目精读卡，逐节整理）","read_level":"fulltext_read","background":"稀疏MoE推理中，专家激活的稀疏性与路由不稳定性使投机解码的接受率难以用稠密模型的统计规律预测。既有分析多假设草稿token与目标token分布同构，忽略了MoE路由在不同前缀长度下切换专家集合所带来的额外失配。本文从路由容量与专家负载角度重新解释投机解码在MoE上的实际收益来源，并给出可核验的机制分解。","problem":"稠密模型下的投机解码收益预测公式直接套用到稀疏MoE时会系统性低估实际加速比，缺少对路由漂移、专家容量因子与验证阶段分组GEMM代价之间耦合关系的机制性解释。","core_idea":"把投机解码的接受率分解为词表分布项与路由一致性项：草稿模型与目标模型在同一前缀上命中相同专家集合时，验证阶段可用一次分组GEMM批量校验多个候选token，从而摊薄专家权重的重复加载；路由不一致时则退化为逐token重路由，收益被抵消。","architecture":"目标模型为稀疏MoE解码器，每层含路由门控与容量因子约束的专家分派；草稿模型为同族小模型或EAGLE式头。验证阶段将草稿产生的γ个候选token与前缀拼接成一条长序列，一次前向得到各位置logits，并按路由命中情况把token分组送入分组GEMM；未命中专家的候选走回退路径。KV cache按候选分支预留额外槽位，接受后回收。","pipeline":["请求进入调度器，按当前批内序列长度与SLO档位决定是否启用投机解码及草稿长度γ。","草稿模型自回归或单次前向生成γ个候选token，同时记录每个位置的草稿路由决策。","目标模型对前缀加候选序列做一次验证前向，得到逐位置logits与目标路由决策。","比较草稿路由与目标路由的专家集合交集，将候选token划分为路由一致组与不一致组。","一致组走单次分组GEMM批量校验并按接受准则截断，不一致组逐token重路由并回退。","接受的token写回KV cache并释放预留槽位，被拒后缀丢弃，批调度器更新容量因子与下一轮γ。"],"formula":"$$\\mathbb{E}[\\text{speedup}]=\\frac{\\gamma\\,a_{\\text{vocab}}\\,a_{\\text{route}}+1}{\\gamma\\,c_{\\text{draft}}+c_{\\text{verify}}(a_{\\text{route}})}$$","training":"本文不涉及训练配方；草稿模型沿用既有蒸馏或EAGLE式训练产物，目标MoE权重保持原精度部署。分析所需的接受率与路由一致性统计来自推理期在线采集，不引入额外训练阶段。部署侧需保证草稿与目标共享分词器与路由门控输入格式，否则路由一致性项无法对齐。","walkthrough":"设批内一条序列前缀长度为L，草稿长度γ。调度器先按SLO档位判断是否值得投机：若当前批已接近显存带宽上限，草稿前向的额外权重读取会挤占目标模型带宽，此时关闭投机。启用后草稿生成γ个候选并记录路由。验证前向把L+γ个位置一次送入目标MoE，路由门控对每个位置输出专家集合。若某候选位置的目标专家集合与草稿记录的交集非空且top-1一致，则该token进入一致组，与其他一致token合并为一次分组GEMM；不一致token单独成组，按容量因子重新分派，可能触发专家溢出与token丢弃回退。接受准则按标准拒绝采样逐位置判定，首个被拒位置之后全部丢弃。接受的token写回KV cache，预留槽位释放；若接受率低于阈值则下调γ并记录路由不一致率作为监控指标。","pseudocode":"输入：前缀x，草稿长度γ，路由一致阈值τ\n草稿阶段：\n  for i in 1..γ:\n    候选[i], 草稿路由[i] <- 草稿模型(x + 候选[1..i-1])\n验证阶段：\n  logits[1..L+γ], 目标路由[1..L+γ] <- 目标MoE一次前向(x + 候选)\n  for i in 1..γ:\n    若 交集(草稿路由[i], 目标路由[L+i]) 非空 且 top-1一致:\n      一致组加入 候选[i]\n    否则:\n      不一致组加入 候选[i]\n  一致组 -> 单次分组GEMM批量校验\n  不一致组 -> 逐token重路由并按容量因子回退\n接受阶段：\n  按拒绝采样逐位置判定，遇首个拒绝即截断\n  接受token写回KV cache，释放预留槽位\n  若接受率 < τ：下调γ，上报路由不一致率","experiments":{"datasets":["未给出"],"baselines":["稠密模型投机解码收益预测公式","无投机解码的MoE基线"],"results":"论文主张既有预测公式系统性低估稀疏MoE上的实际加速比，低估幅度与路由一致性正相关；路由一致时验证阶段的分组GEMM摊薄了专家权重重复加载，是收益超出预测的主要来源。具体加速比数字未给出。","limits":"分析依赖在线采集的路由一致性统计，冷启动阶段估计不稳；容量因子约束下的专家溢出会使不一致组回退代价放大；未给出跨硬件档位的实测数据。","ablations":"按草稿长度γ与路由一致阈值τ做消融，观察接受率与验证阶段分组GEMM合并率的变化；未给出具体消融数值。"},"innovation":["将投机解码收益分解为词表分布项与路由一致性项，给出可在线估计的机制分解。","指出验证阶段路由一致候选可合并为单次分组GEMM，摊薄专家权重重复加载。","把容量因子与专家溢出纳入投机解码回退代价分析，解释收益被抵消的条件。"],"limitations":["缺少跨硬件档位与量化方案的实测加速比，结论停留在机制层面。","路由一致性统计需在线采集，冷启动与分布漂移下估计不稳。","未讨论分离式预填/解码部署下草稿与验证跨节点通信的额外代价。"],"impact":"为MoE推理部署提供了一条可操作的判据：是否启用投机解码不应只看词表接受率，还应监控路由一致率与分组GEMM合并率；在专家并行拓扑下，路由不一致会放大All-to-All与重路由开销，需与容量因子联合调参。","summary":"本文重新解释稀疏MoE上投机解码收益超出稠密模型预测的现象，核心机制是路由一致性：草稿与目标在同一前缀命中相同专家时，验证阶段可把多个候选token合并为一次分组GEMM，摊薄专家权重加载；路由不一致则退化为逐token重路由并被容量因子约束放大代价。论文给出接受率与路由一致性的分解式，主张以路由一致率作为部署期监控指标，但未给出具体加速比与硬件实测。","prereq":[],"successors":[],"figures":[],"data_recipe":["输入负载为变长请求，前缀长度分布跨度大，长前缀下路由漂移更易发生，需按长度分桶统计路由一致率。","批大小受KV cache预留槽位约束，投机启用时每序列需额外预留γ个候选槽位，批调度需同步收缩并发。","SLO档位决定是否启用投机：低延迟档优先短γ，高吞吐档在带宽余量充足时放大γ。","并发上升时草稿前向的额外权重读取挤占带宽，需按显存带宽占用率动态关闭投机。"],"train_recipe":["硬件档位与并行拓扑未给出，部署需按专家并行度评估All-to-All开销对验证阶段的影响。","量化方案未给出；若采用NVFP4/FP8权重，草稿与目标需保持同一量化格式以避免路由门控输入失配。","KV策略为候选分支预留槽位并在接受后回收，需监控槽位碎片率与批内序列长度分布。","监控指标包括路由一致率、分组GEMM合并率、专家溢出率与接受率阈值触发次数。","容量因子需与投机γ联合调参，避免不一致组回退触发专家溢出与token丢弃。"],"facts":["验证阶段将γ个候选token与前缀拼接为一条长序列一次前向，得到逐位置logits与目标路由决策，避免逐token重复前向的权重读取。","路由一致组可合并为单次分组GEMM批量校验，摊薄专家权重加载；不一致组逐token重路由，回退代价受容量因子约束放大。","KV cache需为每个候选分支预留γ个额外槽位，接受后回收，批调度器据此收缩并发以维持显存上限。","草稿前向的额外权重读取会挤占目标模型显存带宽，带宽占用率高时应关闭投机，这是收益被抵消的部署侧条件。","接受率分解为词表分布项与路由一致性项，路由一致率可在推理期在线采集，作为是否启用投机的判据。","专家溢出与token丢弃发生在不一致组重路由时，容量因子过小会使回退路径触发丢弃，破坏接受序列的连续性。","首个被拒位置之后全部候选丢弃，因此γ过大时无效验证计算占比上升，需按接受率阈值动态下调γ。","论文未给出具体加速比、硬件档位与量化方案，机制结论需在B200/B300级部署上另行实测校准。"],"anchors":[],"pitfalls":["把稠密模型的接受率预测直接套用到MoE会低估收益，忽略路由一致性项与分组GEMM合并效应。","只调γ不看路由一致率，会在路由漂移严重时放大无效验证计算与专家溢出回退代价。","忽略KV cache候选槽位预留对批并发的挤压，高并发下投机反而降低吞吐。"],"depth":"shallow"}];})();
